#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for network event notifications
typedef struct {
    int id;
    long timestamp;
    int status;
} Event;

// Define the list of events as a hash table (using a combination of arrays and linked lists)
#define MAX_EVENTS 1000
#define HASH_TABLE_SIZE 128

typedef struct _EventList {
    Event *events[MAX_EVENTS];
    pthread_mutex_t mutex;
    int size;
} EventList;

EventList event_list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

// Initialize the event list
void init_event_list() {
    for (int i = 0; i < MAX_EVENTS; i++) {
        event_list.events[i] = NULL;
    }
}

// Add an event to the list
void add_event(int id, long timestamp, int status) {
    pthread_mutex_lock(&event_list.mutex);

    // Check if the event list is full and need to resize
    if (event_list.size >= MAX_EVENTS) {
        // Reallocate memory for the events array
        Event **new_events = realloc(event_list.events, sizeof(Event *) * (MAX_EVENTS * 2));
        if (!new_events) {
            pthread_mutex_unlock(&event_list.mutex);
            return;
        }

        event_list.events = new_events;
    }

    // Find an empty slot in the hash table
    int index = id % HASH_TABLE_SIZE;
    while (event_list.events[index]) {
        index++;
        if (index >= HASH_TABLE_SIZE) {
            index = 0;
        }
    }

    Event *new_event = malloc(sizeof(Event));
    new_event->id = id;
    new_event->timestamp = timestamp;
    new_event->status = status;
    event_list.events[index] = new_event;
    event_list.size++;

    pthread_mutex_unlock(&event_list.mutex);
}

// Update an event in the list
void update_event(int id, int status) {
    pthread_mutex_lock(&event_list.mutex);

    // Find the event with the given ID
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (event_list.events[i] && event_list.events[i]->id == id) {
            event_list.events[i]->status = status;
            break;
        }
    }

    pthread_mutex_unlock(&event_list.mutex);
}

// Retrieve an event from the list
Event *get_event(int id) {
    pthread_mutex_lock(&event_list.mutex);

    // Find the event with the given ID
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (event_list.events[i] && event_list.events[i]->id == id) {
            Event *event = event_list.events[i];
            pthread_mutex_unlock(&event_list.mutex);
            return event;
        }
    }

    pthread_mutex_unlock(&event_list.mutex);
    return NULL;
}

// Print the event list
void print_event_list() {
    pthread_mutex_lock(&event_list.mutex);

    for (int i = 0; i < MAX_EVENTS; i++) {
        if (event_list.events[i]) {
            printf("Event ID: %d, Timestamp: %ld, Status: %d\n", event_list.events[i]->id, event_list.events[i]->timestamp, event_list.events[i]->status);
        }
    }

    pthread_mutex_unlock(&event_list.mutex);
}
