typedef struct {
    int key;
    long offset;
    int value;
} record;

record* allocate_records(int num_records, size_t total_limit) {
    // Calculate the total memory needed
    size_t total_size = sizeof(record) * num_records + sizeof(long) * 2; // two arrays of offsets and keys

    if (total_size > total_limit) {
        printf("Memory limit exceeded\n");
        return NULL;
    }

    record* records = (record*)malloc(total_size);
    long* offsets = (long*)malloc(sizeof(long) * num_records);
    int* keys = (int*)malloc(sizeof(int) * num_records);

    if (!records || !offsets || !keys) {
        printf("Memory allocation failed\n");
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * 100 + rand() % 1000000L;
        keys[i] = i;
    }

    // Set random values in records
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }

    return records;
}

void update_record(record* records, int index, int key, int value) {
    // Check if the record exists
    if (index >= 0 && index < sizeof(records) / sizeof(record)) {
        for (int i = 0; i < sizeof(records) / sizeof(record); i++) {
            if (records[i].key == key) {
                records[index].value = value;
                return;
            }
        }
    }

    printf("Record not found\n");
}

