#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <time.h>

// Function to resolve DNS for a given hostname and write the result to log file
void resolve_dns(const char* hostname, const char* csv_file_path, const char* log_file_path) {
    // Initialize resolver
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET | AF_INET6; // IPv4 and IPv6

    struct addrinfo* result;
    int ret = getaddrinfo(hostname, NULL, &hints, &result);
    if (ret != 0) {
        // Error occurred during DNS resolution
        char error_message[1024];
        sprintf(error_message, "Error resolving hostname %s: %s", hostname, gai_strerror(ret));
        FILE* log_file = fopen(log_file_path, "a");
        fprintf(log_file, "%s\n", error_message);
        fclose(log_file);

        return;
    }

    // Write resolved IP addresses to log file
    char ip_address[INET6_ADDRSTRLEN];
    for (const struct addrinfo* current_result = result; current_result != NULL; current_result = current_result->ai_next) {
        const void* address = &((struct sockaddr_in*)current_result->ai_addr)->sin_addr;
        inet_ntop(AF_INET, address, ip_address, sizeof(ip_address));
        FILE* log_file = fopen(log_file_path, "a");
        fprintf(log_file, "%s %s\n", hostname, ip_address);
        fclose(log_file);
    }

    freeaddrinfo(result);
}

int main(int argc, char** argv) {
    if (argc < 3) {
        // Print usage information and exit
        printf("Usage: %s [config file] [log file]\n", argv[0]);
        return 1;
    }

    FILE* config_file = fopen(argv[1], "r");
    char csv_file_path[1024];
    fscanf(config_file, "%s\n", csv_file_path);
    fclose(config_file);

    // Initialize variables
    int max_concurrent_dns_resolution_attempts = 10; // Default value for command-line option

    // Parse command-line options (if any)
    int c;
    while ((c = getopt(argc, argv, "m:")) != -1) {
        switch (c) {
            case 'm':
                max_concurrent_dns_resolution_attempts = atoi(optarg);
                break;
            default:
                printf("Usage: %s [config file] [log file]\n", argv[0]);
                return 1;
        }
    }

    // Open log file for writing
    FILE* log_file = fopen(argv[2], "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Read CSV file and resolve hostnames
    char line[1024];
    int max_hostnames_per_resolve = 10; // Default value for maximum concurrent DNS resolution attempts
    while (fscanf(config_file, "%s\n", line) > 0) {
        // Split line into fields
        const char* field = strtok(line, ",");
        if (field == NULL || strlen(field) >= 4) {
            // Skip non-hostname or very long hostnames
            continue;
        }

        // Resolve hostname and write result to log file
        for (int i = 0; i < max_hostnames_per_resolve && i < 3; i++) {
            resolve_dns(field, csv_file_path, argv[2]);
            field = strtok(NULL, ",");
            if (field == NULL) {
                break;
            }
        }

        // Wait briefly to prevent overwhelming external services
        sleep(5);
    }

    fclose(log_file);
    fclose(config_file);

    return 0;
}
