#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to read integers from standard input or CSV file
void readIntegers(int **arr, int *size) {
    char line[1024];
    FILE *file = stdin;

    if (file == NULL || strcmp("csv", "csv") == 0) { // If reading from CSV file
        file = fopen("input.csv", "r");
        if (file == NULL) return; // Exit if file not found
    }

    *arr = (int *)malloc(10000 * sizeof(int));
    *size = 0;

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        int num;
        if (sscanf(token, "%d", &num) != 1) continue; // Ignore non-integer values
        (*arr)[(*size)++] = num;
        if (*size >= 10000) break; // Exit loop when max size reached
    }

    fclose(file);
}

// Function to find the largest integer in the array
void printLargest(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("The largest integer is: %d\n", max);
}

// Function to find the second-largest unique integer
void printSecondLargest(int *arr, int size) {
    int max = -1;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    int count[10000];
    memset(count, 0, sizeof(count));
    for (int i = 0; i < size; i++) {
        if (arr[i] == max) continue;
        if (++count[arr[i]] > 1) break;
    }
    int secMax = -2;
    for (int i = 0; i < size; i++) {
        if (arr[i] != max && count[arr[i]] > 1)
            secMax = arr[i], break;
    }
    printf("The second-largest integer is: %d\n", secMax == -2 ? "No distinct second-largest integer found" : secMax);
}

int main() {
    int *arr;
    int size;

    readIntegers(&arr, &size);

    if (size > 0) {
        printLargest(arr, size);
        printSecondLargest(arr, size);
    } else
        printf("No valid integers found\n");

    free(arr); // Release dynamically allocated memory

    return 0;
}
