void* initializeConfiguration(cfg_type_t type, ...) {
    va_list args;
    va_start(args, type);

    struct configuration *cfg = (struct configuration *)malloc(sizeof(struct configuration));
    if (!cfg) {
        // Handle memory allocation failure
        char error_msg[256];
        snprintf(error_msg, sizeof(error_msg), "Failed to allocate memory for configuration of type %d", type);
        va_end(args);
        return NULL;
    }

    cfg->type = type;

    switch (type) {
        case CFG_TYPE_A:
            // Initialize fields specific to CFG_TYPE_A
            cfg->size = 1024; // Adjust this based on the actual size required
            break;
        case CFG_TYPE_B:
            // Initialize fields specific to CFG_TYPE_B
            cfg->size = 2048; // Adjust this based on the actual size required
            break;
        case CFG_TYPE_C:
            // Initialize fields specific to CFG_TYPE_C
            cfg->size = 4096; // Adjust this based on the actual size required
            break;
        default:
            // Handle unknown configuration type
            free(cfg);
            return NULL;
    }

    va_end(args);
    return (void *)cfg;
}

void finalizeConfiguration(void *cfg) {
    if (!cfg) {
        return;
    }

    struct configuration *cfg_ptr = (struct configuration *)cfg;
    free(cfg);
}
