        Map<ElementType, Double> effectiveness = calculateEffectiveness(typeChart, pokemon);

        // Generate report sections for weaknesses and resistances
        StringBuilder weaknessesSection = new StringBuilder();
        for (Map.Entry<ElementType, Double> entry : effectiveness.entrySet()) {
            if (entry.getValue() < 0) {
                weaknessesSection.append(entry.getKey().getName()).append(": ").append(Math.abs(entry.getValue())).append("\n");
            }
        }

        report.append("Weaknesses:\n").append(weaknessesSection);

        StringBuilder resistancesSection = new StringBuilder();
        for (Map.Entry<ElementType, Double> entry : effectiveness.entrySet()) {
            if (entry.getValue() > 0) {
                resistancesSection.append(entry.getKey().getName()).append(": ").append(entry.getValue()).append("\n");
            }
        }

        report.append("Resistances:\n").append(resistancesSection);

        return report.toString();
