#include <semaphore.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_SEMAPHORES 100
#define SEMAPHORE_INITIAL_VALUE 1

typedef struct {
    sem_t *semaphores;
    int count;
} semaphore_collection;

void* semaphore_collection_init() {
    semaphore_collection *collection = (semaphore_collection*)malloc(sizeof(semaphore_collection));
    collection->semaphores = (sem_t*)calloc(MAX_SEMAPHORES, sizeof(sem_t));
    for(int i = 0; i < MAX_SEMAPHORES; i++) {
        sem_init(&collection->semaphores[i], 1, SEMAPHORE_INITIAL_VALUE);
    }
    collection->count = 0;
    return (void*)collection;
}

void semaphore_collection_free(void* ptr) {
    semaphore_collection *collection = (semaphore_collection*)ptr;
    for(int i = 0; i < MAX_SEMAPHORES; i++) {
        sem_destroy(&collection->semaphores[i]);
    }
    free(collection->semaphores);
    free(ptr);
}

int add_semaphore(semaphore_collection* collection, int value) {
    if(collection->count >= MAX_SEMAPHORES) {
        // Handle error: insufficient system resources
        return -1;
    }
    sem_init(&collection->semaphores[collection->count], 1, value);
    collection->count++;
    return 0;
}

int remove_semaphore(semaphore_collection* collection, int index) {
    if(index >= collection->count || index < 0) {
        // Handle error: invalid semaphore index
        return -2;
    }
    sem_destroy(&collection->semaphores[index]);
    for(int i = index; i < collection->count - 1; i++) {
        sem_overwrite(&collection->semaphores[i], &collection->semaphores[i+1]);
    }
    collection->count--;
    return 0;
}

void reset_semaphores(semaphore_collection* collection, int operations) {
    for(int i = 0; i < collection->count; i++) {
        sem_overwrite(&collection->semaphores[i], (sem_t*)SEMAphORE_INITIAL_VALUE);
    }
}

int get_semaphore_value(semaphore_collection* collection, int index) {
    if(index >= collection->count || index < 0) {
        // Handle error: invalid semaphore index
        return -2;
    }
    return sem_getvalue(&collection->semaphores[index]);
}
