#include <chrono>
#include <mutex>

bool modifyIntegerCollection(std::vector<std::shared_ptr<int>>& collection,
                             int targetValue, int defaultValue,
                             std::chrono::milliseconds timeout) {
    bool result = false;
    auto start = std::chrono::high_resolution_clock::now();

    for (auto& ptr : collection) {
        if (*ptr == targetValue) {
            if (std::this_thread::sleep_until(start + timeout) != 
                std::cv_status::timeout) {
                *ptr += 1;
                result = true;
                break;
            }
        } else if (!*ptr && std::chrono::high_resolution_clock::now() - start >= timeout) {
            return false;
        }
    }

    if (!result) {
        for (auto& ptr : collection) {
            if (!*ptr) {
                *ptr = defaultValue + 1;
                result = true;
                break;
            } else if (std::chrono::high_resolution_clock::now() - start >= timeout) {
                return false;
            }
        }
    }

    return result;
}

