from flask_sqlalchemy import SQLAlchemy
import json

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///inventory.db"
db = SQLAlchemy(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    category_id = db.Column(db.Integer, db.ForeignKey("category.id"))
    name = db.Column(db.String(100), nullable=False)
    attributes = db.Column(db.PickleType(), default={})

class Category(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), unique=True)

@app.route("/resources/<int:resource_id>", methods=["PUT"])
def update_resource(resource_id):
    resource = Resource.query.get(resource_id)
    if request.is_json:
        data = json.loads(request.data.decode("utf-8"))
        for key, value in data.items():
            if hasattr(resource, key) and isinstance(value, dict):
                setattr(resource, key, value)
    else:
        app.logger.error(f"Invalid JSON: {request.get_data()}")

@app.route("/resources/<int:resource_id>", methods=["DELETE"])
def delete_resource(resource_id):
    resource = Resource.query.get(resource_id)
    if resource is None:
        return jsonify({"error": "Resource not found"}), 404
    db.session.delete(resource)
    db.session.commit()
    return jsonify({"message": "Resource deleted successfully"})

@app.route("/categories/<int:category_id>/resources", methods=["GET"])
def get_resources(category_id):
    resources = Resource.query.filter_by(category_id=category_id).all()
    return jsonify([{"id": r.id, "name": r.name} for r in resources])

if __name__ == "__main__":
    app.run(debug=True)
