using System;
using System.Xml.XPath;
using System.IO;
using Microsoft.Win32;
using Serilog;

public class XmlProcessor
{
    public void ProcessXml(string xmlString)
    {
        var doc = new XPathDocument(new StringReader(xmlString));
        var nsmgr = new XmlNamespaceManager(doc.NameTable);
        var node = doc.CreateNavigator().SelectSingleNode("//element[@name='desiredName']", nsmgr);

        if (node == null || !IsValidDirectoryName(node.Value))
        {
            LogError("No matching element found or invalid directory name.");
            return;
        }

        try
        {
            var dirPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, node.Value);
            Directory.CreateDirectory(dirPath).SetAccessControl(new FileSystemRights(FileSystemRights.Read | FileSystemRights.Write));
        }
        catch (IOException ex)
        {
            LogError("Failed to create directory: " + ex.Message);
            return;
        }

        try
        {
            Environment.SetEnvironmentVariable("XML_CONFIG_PATH", dirPath);
        }
        catch (Exception ex)
        {
            LogError("Failed to set environment variable: " + ex.Message);
            return;
        }

        LogInfo("Directory created and XML_CONFIG_PATH set.");
    }

    private bool IsValidDirectoryName(string directoryName)
    {
        // implement your custom validation logic here
        // for example:
        if (!directoryName.All(char.IsLetterOrDigit))
        {
            return false;
        }
        if (directoryName.Length > 255)
        {
            return false;
        }
        return true;
    }

    private void LogInfo(string message)
    {
        try
        {
            // implement your logging logic here, for example:
            var logger = Serilog.Log.ForContext();
            logger.Information(message);
        }
        catch (Exception ex)
        {
            LogError("Failed to log info: " + ex.Message);
        }
    }

    private void LogError(string message)
    {
        try
        {
            // implement your logging logic here, for example:
            var logger = Serilog.Log.ForContext();
            logger.Error(message);
        }
        catch (Exception ex)
        {
            // handle the error gracefully
        }
    }
}
