import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class MD5HashProcessor {

    private static final int MAX_CONCURRENT_THREADS = 10;
    private static final int DEFAULT_CACHE_TTL = 3600; // 1 hour in seconds

    public void processBatch(String[] batch, DistributedCache cache) {
        ExecutorService executor = new ThreadPoolExecutor(
                MAX_CONCURRENT_THREADS,
                MAX_CONCURRENT_THREADS,
                0L,
                TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<Runnable>()
        );

        for (String s : batch) {
            if (s == null || s.isEmpty()) {
                continue; // skip empty strings
            }

            executor.submit(() -> processString(s, cache));
        }

        executor.shutdown();
    }

    private void processString(String s, DistributedCache cache) {
        try {
            String md5Hash = org.apache.commons.codec.digest.DigestUtils.md5Hex(s);
            cache.put(md5Hash, s);
        } catch (Exception e) {
            // handle errors gracefully
        }
    }
}
