<?php
function manageUserAccountRequests($requestData) {
    $rateLimit = 5; // requests per minute
    $timeWindow = 60; // in seconds (1 minute)
    $allowedRequests = 0;
    $lastRequestTime = time();

    if ($requestData['sub_action'] === 'create') {
        $userExists = false;
        foreach ($_SESSION['users'] as $user) {
            if ($user['email'] === $requestData['email']) {
                $userExists = true;
                break;
            }
        }

        if (!$userExists) {
            // Add new user account
            $_SESSION['users'][] = array(
                'id' => uniqid(),
                'name' => $requestData['name'],
                'email' => $requestData['email'],
                'password' => password_hash($requestData['password'], PASSWORD_BCRYPT),
            );

            // Query external API for authentication token
            $authToken = apiCall('create', array(
                'email' => $requestData['email'],
                'password' => $requestData['password'],
            ));

            if ($authToken) {
                $_SESSION['users'][][][] = array(
                    'id' => uniqid(),
                    'token' => $authToken,
                );
            }
        } else {
            return json_encode(array('message' => 'error', 'data' => 'User already exists'));
        }

    } elseif ($requestData['sub_action'] === 'update') {
        // Update user account
        foreach ($_SESSION['users'] as &$user) {
            if ($user['id'] === $requestData['id']) {
                $user['name'] = $requestData['name'];
                $user['email'] = $requestData['email'];
                $user['password'] = password_hash($requestData['password'], PASSWORD_BCRYPT);
                break;
            }
        }

    } elseif ($requestData['sub_action'] === 'delete') {
        // Delete user account
        foreach ($_SESSION['users'] as $key => &$user) {
            if ($user['id'] === $requestData['id']) {
                unset($_SESSION['users'][$key]);
                break;
            }
        }

    } elseif ($requestData['sub_action'] === 'retrieve') {
        // Retrieve user account details
        foreach ($_SESSION['users'] as $user) {
            if ($user['id'] === $requestData['id']) {
                return json_encode(array('message' => 'success', 'data' => $user));
            }
        }

    } else {
        return json_encode(array('message' => 'error', 'data' => 'Invalid sub_action'));
    }

    // Rate limiting
    if (time() - $lastRequestTime < $timeWindow) {
        $allowedRequests++;

        if ($allowedRequests > $rateLimit) {
            return json_encode(array('message' => 'error', 'data' => 'Rate limit exceeded'));
        }
    } else {
        $allowedRequests = 1;
        $lastRequestTime = time();
    }

    // Event bus logging
    eventBusPublish($requestData['sub_action'], $requestData);

    return json_encode(array('message' => 'success', 'data' => array()));
}

function apiCall($action, $params) {
    try {
        $response = json_decode(file_get_contents('https://external-api.com/' . $action), true);
        if ($response['status'] === 'error') {
            return null;
        } else {
            return $response['data'];
        }
    } catch (Exception $e) {
        return null;
