    public MoSTState loadStateFromFile(String filePath) throws IOException {
        try (ObjectInputStream objectInputStream = new ObjectInputStream(new FileInputStream(filePath))) {
            return (MoSTState) objectInputStream.readObject();
        } catch (ClassNotFoundException e) {
            return null;
        } finally {
            closeInputStream(objectInputStream);
        }
    }

    public Bitmap getTheme(String themeName) throws IOException {
        Bitmap bitmap = themeCache.get(themeName);
        if (bitmap != null) {
            return bitmap;
        }
        String filePath = themeDir + "/" + themeName + ".png";
        try (FileInputStream fileInputStream = new FileInputStream(filePath)) {
            bitmap = BitmapFactory.decodeStream(fileInputStream);
            themeCache.put(themeName, bitmap);
            return bitmap;
        } catch (FileNotFoundException e) {
            return null;
        } finally {
            closeInputStream(fileInputStream);
        }
    }

    public void setThemeDir(String themeDir) {
        this.themeDir = themeDir;
    }

    private void closeInputStream(Closeable closeable) {
        try {
            closeable.close();
        } catch (IOException e) {
            // Handle exception
        }
    }
}
