    public class AuthenticationHandler : AuthenticationHandler<AuthenticationTicket>
    {
        private readonly UserManager<IdentityUser> _userManager;
        private readonly SignInManager<IdentityUser> _signInManager;
        private readonly IPasswordValidator<IdentityUser> _passwordValidator;
        private readonly ICustomizableValidator _customizableValidator;

        public AuthenticationHandler(UserManager<IdentityUser> userManager, SignInManager<IdentityUser> signInManager, IPasswordValidator<IdentityUser> passwordValidator, ICustomizableValidator customizableValidator)
        {
            _userManager = userManager;
            _signInManager = signInManager;
            _passwordValidator = passwordValidator;
            _customizableValidator = customizableValidator;
        }

        protected override async Task HandleAuthenticationRequestAsync(AuthorizationRequest request)
        {
            var authenticationProperties = new AuthenticationProperties { StoreData = true };

            try
            {
                var result = await _signInManager.PasswordSignInAsync(request.UserName, request.Password, false, true);

                if (result != SignInResult.Success)
                {
                    await ForbidAsync(context: Context, properties: authenticationProperties);
                    return;
                }

                var user = await _userManager.FindByNameAsync(request.UserName);

                if (!await _passwordValidator.ValidateAsync(user, request.Password))
                {
                    await ForbidAsync(Context, authenticationProperties);
                    return;
                }

                var customizedValidationResult = await _customizableValidator.ValidateAsync(user, request);

                if (!customizedValidationResult)
                {
                    await ForbidAsync(Context, authenticationProperties);
                    return;
                }

                var ticket = await _signInManager.CreateAuthenticationTicketAsync(request.UserName, user.Email, user.Id);

                await StartAuthentication(ticket);
            }
            catch (Exception ex)
            {
                // Handle exceptions
            }
        }
    }
}
