function runTests(label, f, envConfig) {
  const require = typeof require !== 'undefined' ? require : () => { throw new Error("Cannot find module"); };
  const blueslip = require('blueslip');

  async function runTestInEnv(env, test) {
    try {
      await blueslip.reset();
      await f(test);
    } catch (err) {
      console.error(`Error running ${test} in env ${env}:`, err);
    }
  }

  async function runTestsInEnvs(label, tests, envConfig) {
    const concurrencyLevel = 5; // adjust this based on available resources and test requirements
    const numTestsFailed = [];

    for (const [envName, env] of Object.entries(envConfig)) {
      console.log(`Running tests in environment ${envName}...`);

      const promises = [];
      for (const test of tests) {
        promises.push(runTestInEnv(envName, test));
      }

      try {
        await Promise.all(promises.slice(0, concurrencyLevel).map(p => p.catch(err => numTestsFailed.push({ test, env: envName, error: err }))));

        for (let i = concurrencyLevel; i < promises.length; i++) {
          const promise = promises[i];
          setTimeout(() => promise().catch(err => numTestsFailed.push({ test, env: envName, error: err })), 0);
        }
      } catch (err) {
        console.error(`Error running tests in environment ${envName}:`, err);
      }
    }

    if (numTestsFailed.length > 0) {
      const failedTests = numTestsFailed.reduce((acc, { test }) => acc + `  - ${test}\n`, `Failed tests:\n`);
      console.error(failedTests);
    } else {
      console.log(`All tests passed!`);
    }
  }

  runTestsInEnvs(label, ['test1', 'test2'], envConfig);
