const { Worker } = require('worker_threads');
const fs = require('fs');
const zlib = require('zlib');

function processStreamingData(options) {
  const storageDir = options.storageDir;
  const streamingSource = options.streamingSource;
  const monitoringSystem = options.monitoringSystem;
  const delay = options.delay || 1000;

  async function worker() {
    let buffer = '';
    for await (const chunk of streamingSource()) {
      buffer += chunk.toString();
      if (buffer.length >= 1024 * 1024) { // 1MB
        writeBufferToStorage(buffer);
        buffer = '';
      }
    }
    if (buffer.length > 0) {
      writeBufferToStorage(buffer);
    }
  }

  async function writeBufferToStorage(buffer) {
    const storageFile = `${storageDir}/data.json`;
    try {
      await fs.promises.writeFile(storageFile, Buffer.from(zlib.compress(JSON.stringify({ data: buffer })), 'binary'));
    } catch (err) {
      console.error(err);
    }
  }

  async function startService() {
    return new Promise((resolve, reject) => {
      const worker = new Worker(`worker.js`);
      worker.on('message', message => {
        if (message === 'stop') {
          stopService().then(() => resolve()).catch(reject);
        } else if (message === 'resume') {
          resumeService().then(() => resolve()).catch(reject);
        }
      });
      worker.on('error', err => reject(err));
      setTimeout(() => {
        worker.postMessage('start');
      }, delay);
    });
  }

  async function stopService() {
    return new Promise((resolve, reject) => {
      try {
        await fs.promises.writeFile(`${storageDir}/stop.json`, JSON.stringify({ stopped: true }));
        monitoringSystem.sendNotification('service_stopped');
        resolve();
      } catch (err) {
        reject(err);
      }
    });
  }

  async function resumeService() {
    return new Promise((resolve, reject) => {
      try {
        await fs.promises.writeFile(`${storageDir}/resume.json`, JSON.stringify({ resumed: true }));
        monitoringSystem.sendNotification('service_resumed');
        resolve();
      } catch (err) {
        reject(err);
      }
    });
  }

  async function start() {
    await startService().then(() => worker()).catch(console.error);
  }

  return { start };
}

module.exports = processStreamingData;
