function traverseDOM(root, selectors, timeout = 5000) {
    const results = [];
    const queue = [root];
    let started = Date.now();

    while (queue.length && (Date.now() - started < timeout)) {
        const node = queue.shift();
        if (!node) continue;

        for (const selector of selectors) {
            const parts = selector.split('.');
            const classRegex = new RegExp(`\\.${parts[1]}$`);
            const idRegex = new RegExp(`#${parts[0]}`);
            if (!classRegex.test(node.className) && !idRegex.test(node.id)) continue;

            results.push(node);
        }

        for (const child of node.childNodes) {
            queue.push(child);
        }
    }

    return results;
}
