#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void rename_files(char *dir) {
    DIR *dp;
    struct dirent *entry;
    int i = 0;

    dp = opendir(dir);
    if (dp == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        char *filename = entry->d_name;
        size_t len = strlen(filename);

        // Check if file extension is present
        size_t pos = strrchr(filename, '.');
        if (pos == NULL || pos == filename + len - 1) {
            continue; // Skip files without extensions
        }

        char *new_filename = malloc(len + 5);
        sprintf(new_filename, "%d.%s", i++, pos);

        rename(fullfile(dir, entry->d_name), fullfile(dir, new_filename));

        free(new_filename);
    }

    closedir(dp);
}

char *fullfile(char *dir, char *file) {
    size_t len = strlen(dir);
    return malloc(len + 2 + strlen(file));
}
