class FileManager {
    constructor(directory) {
        this.directory = directory;
        this.fileList = [];
        this.loadCount = 0;
        this.onloadCallback = null;
    }

    async loadFiles() {
        return new Promise((resolve, reject) => {
            this.readdir(this.directory).then(files => {
                files.forEach(file => {
                    if (file.endsWith('.js')) {
                        this.fileList.push(file);
                    }
                });
                resolve();
            }).catch(error => {
                reject(error);
            });
        });
    }

    async readdir(directory) {
        return new Promise((resolve, reject) => {
            fs.readdir(directory, (err, files) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(files);
                }
            });
        });
    }

    async executeFiles() {
        await this.loadFiles();
        for (const file of this.fileList) {
            this.loadFile(file);
        }
    }

    async loadFile(file) {
        return new Promise((resolve, reject) => {
            fs.readFile(`${this.directory}/${file}`, 'utf8', (err, data) => {
                if (err) {
                    reject(err);
                } else {
                    eval(data);
                    this.loadCount++;
                    if (this.loadCount === this.fileList.length) {
                        resolve();
                    }
                }
            });
        });
    }

    setOnloadCallback(callback) {
        this.onloadCallback = callback;
    }

    async onload() {
        await this.executeFiles();
        if (this.onloadCallback) {
            this.onloadCallback();
        }
    }
}
