import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;

public class LogProcessor {
    private final int WINDOW_SIZE = 60;
    private final long MAX_MEMORY_USAGE = 1024 * 1024 * 500; // 500 MB
    private final Map<String, Long> sequenceCounts = new HashMap<>();
    private final ConcurrentLinkedQueue<LogEvent> logEvents = new ConcurrentLinkedQueue<>();

    public void processLogFile(String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            long startProcessingTime = System.currentTimeMillis();
            LogEvent currentWindowStart = null;
            int sequenceCount = 0;

            String line;
            while ((line = reader.readLine()) != null) {
                LogEvent logEvent = LogEvent.parse(line);
                if (logEvents.size() >= WINDOW_SIZE && logEvent.getTimestamp() > currentWindowStart.getTimestamp() + 60 * 1000) {
                    processCurrentWindow();
                    sequenceCount = 0;
                    currentWindowStart = logEvent;
                }

                logEvents.add(logEvent);
                if (logEvents.size() > MAX_MEMORY_USAGE / 4) {
                    processCurrentWindow();
                    sequenceCount = 0;
                    currentWindowStart = null;
                }

                if (sequenceCount++ % 10000 == 0) {
                    recordProcessingTime(startProcessingTime, "Processing events...");
                }
            }

            processCurrentWindow();
        }
    }

    private void processCurrentWindow() {
        long startProcessingTime = System.currentTimeMillis();
        Map<String, Long> sequenceCountsCopy = new HashMap<>(sequenceCounts);
        for (LogEvent logEvent : new ArrayList<>(logEvents)) {
            if (!sequenceCountsCopy.containsKey(logEvent.getSequence())) {
                sequenceCounts.put(logEvent.getSequence(), 1L);
            } else {
                long count = sequenceCounts.get(logEvent.getSequence());
                sequenceCounts.put(logEvent.getSequence(), ++count);
            }
        }

        logEvents.clear();
        recordProcessingTime(startProcessingTime, "Processing window...");
    }

    private void recordProcessingTime(long startTime, String message) {
        try {
            Thread.sleep(1000); // Allow the logging thread to process
        } catch (InterruptedException e) {}

        Thread backgroundThread = new Thread(() -> System.out.println(message + ": " + (System.currentTimeMillis() - startTime) + " ms"));
        backgroundThread.setDaemon(true);
        backgroundThread.start();
    }
}

class LogEvent {
    private long timestamp;
    private String sequence;

    static LogEvent parse(String line) {
        // Implement parsing logic here
        return null;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public String getSequence() {
        return sequence;
    }
}
