import java.io.IOException;
import java.net.SocketOption;
import java.nio.channels.SelectionKey;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionManager {
    private final Map<String, ConnectionPool> connectionPools = new ConcurrentHashMap<>();
    private final Map<String, SelectionKey> selectionKeys = new ConcurrentHashMap<>();
    private final AtomicInteger activeConnections = new AtomicInteger(0);
    private final int maxConnectionsPerService;
    private final long timeoutMs;
    private final int reconnectionAttempts;
    private final long reconnectDelayMs;

    public ConnectionManager(int maxConnectionsPerService, long timeoutMs, int reconnectionAttempts, long reconnectDelayMs) {
        this.maxConnectionsPerService = maxConnectionsPerService;
        this.timeoutMs = timeoutMs;
        this.reconnectionAttempts = reconnectionAttempts;
        this.reconnectDelayMs = reconnectDelayMs;
    }

    public void addService(String serviceId) {
        connectionPools.putIfAbsent(serviceId, new ConnectionPool(maxConnectionsPerService));
    }

    public void removeService(String serviceId) {
        connectionPools.remove(serviceId);
    }

    public void start() throws IOException {
        // Initialize selection keys for each service
        for (Map.Entry<String, ConnectionPool> entry : connectionPools.entrySet()) {
            SelectionKey key = selectionKeys.putIfAbsent(entry.getKey(), entry.getValue().initialize());
            if (key == null) throw new IOException("Failed to initialize selection key for " + entry.getKey());
        }
    }

    public void stop() {
        // Close all channels and cancel all selection keys
        connectionPools.forEach((serviceId, pool) -> pool.close());
        selectionKeys.forEach(SelectionKey::cancel);
    }

    public void run() throws IOException {
        while (true) {
            // Perform health checks for each service
            connectionPools.forEach((serviceId, pool) -> {
                try {
                    if (!pool.isHealthy()) {
                        // Reconnect to the service if it's not healthy
                        pool.reconnect();
                    }
                } catch (IOException e) {
                    // Log error and reattempt after reconnect delay
                    logError(serviceId, e);
                    Thread.sleep(reconnectDelayMs);
                }
            });

            // Perform read operations on all channels
            connectionPools.forEach((serviceId, pool) -> pool.read());

            // Update active connection count
            activeConnections.set(connectionPools.values().stream()
                    .mapToInt(ConnectionPool::getActiveConnectionCount)
                    .sum());
        }
    }

    private void logError(String serviceId, IOException e) {
        // Log error and send alert if necessary
    }
}

class ConnectionPool {
    private final int maxConnections;
    private final AtomicInteger activeConnectionCount = new AtomicInteger(0);
    private final java.nio.channels.Selector selector;

    public ConnectionPool(int maxConnectionsPerService) {
        this.maxConnections = maxConnectionsPerService;
        this.selector = Selector.open();
