    public Bitmap getTheme(String themeName) {
        lock.lock();
        try {
            if (cache.containsKey(themeName)) {
                return cache.get(themeName);
            } else {
                // Handle cache miss...
                lock.unlock();
                return null;
            }
        } finally {
            lock.unlock();
        }
    }

    public void putTheme(String themeName, Bitmap bitmap) {
        lock.lock();
        try {
            if (cache.size() >= maxCacheSize) {
                // Evict least recently used theme when cache is full...
            }
            cache.put(themeName, bitmap);
        } finally {
            lock.unlock();
        }
    }

    public void clearCache() {
        lock.lock();
        try {
            cache.clear();
        } finally {
            lock.unlock();
        }
