    private static final int MAX_INSTANCES = 1000;
    private static final int MIN_DELAY = 5000; // 5 seconds
    private static final int MAX_DELAY = 15000; // 15 seconds

    private ScheduledExecutorService executor;
    private Map<String, ServiceInstance> instances;
    private Configuration config;

    public ScalableServiceManager(Configuration config) {
        this.config = config;
        this.executor = Executors.newScheduledThreadPool(10);
        this.instances = new ConcurrentHashMap<>();
    }

    public void start() {
        for (int i = 0; i < MAX_INSTANCES; i++) {
            ServiceInstance instance = new ServiceInstance();
            instances.put(instance.getId(), instance);
            executor.schedule(() -> instance.start(), Math.random() * (MAX_DELAY - MIN_DELAY) + MIN_DELAY, TimeUnit.MILLISECONDS);
        }
    }

    public void stop(String serviceId) {
        ServiceInstance instance = instances.get(serviceId);
        if (instance != null) {
            executor.execute(() -> instance.stop());
            executor.schedule(() -> sendNotification(instance), 1000, TimeUnit.MILLISECONDS);
        }
    }

