use reqwest;
use std::default;
use std::env;

struct HttpClient {
    request_builder: reqwest::blocking::RequestBuilder,
}

impl HttpClient {
    fn new() -> Self {
        let request_builder = reqwest::blocking::RequestBuilder::new();
        HttpClient { request_builder }
    }

    fn set_url(&mut self, url: &str) {
        self.request_builder = self.request_builder.url(url);
    }

    fn add_certificate_validation(&mut self, validate: bool) {
        if validate {
            self.request_builder = self.request_builder.ca_cert_path("path_to_ca_file");
        }
    }

    fn set_request_timeout(&mut self, timeout: u64) {
        self.request_builder = self.request_builder.timeout(std::time::Duration::from_millis(timeout as u128));
    }

    fn add_custom_headers(&mut self, headers: Vec<(&str, &str)>) {
        for (key, value) in headers {
            self.request_builder = self.request_builder.header(key.to_string(), value.to_string());
        }
    }

    async fn send_request(&self) -> Result<String, reqwest::Error> {
        let response = self.request_builder.send().await?;
        Ok(response.text().await?)
    }
}

async fn main() {
    let mut client = HttpClient::new();
    client.set_url("https://example.com");
    client.add_certificate_validation(true);
    client.set_request_timeout(5000);
    client.add_custom_headers(vec![("header1", "value1"), ("header2", "value2")]);

    match client.send_request().await {
        Ok(response) => println!("Response: {}", response),
        Err(err) => println!("Error: {}", err),
    }
}

fn main() {
    env::set_var("RUST_BACKTRACE", "1");
    tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(main());
}
