const fs = require('fs');
const crypto = require('crypto');

async function processFileAndHash(filePath, desiredStringLength, characterSet, passwordToHash) {
    try {
        const fileContent = await new Promise((resolve, reject) => {
            fs.readFile(filePath, (err, data) => {
                if (err) reject(err);
                else resolve(data.toString());
            });
        });

        const randomString = crypto.randomBytes(desiredStringLength).toString(characterSet);

        const hashedPassword = crypto.createHash('sha256').update(passwordToHash).digest().toString('hex');

        return { fileContent, randomString, hashedPassword };
    } catch (error) {
        throw error;
    }
}
