#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct State {
    int id;
    struct State* next;
} State;

typedef struct FSA {
    int numStates;
    int currentState;
    State** states;
    pthread_mutex_t lock;
} FSA;

FSA* fsaCreate(int numStates, int currentState) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    fsa->numStates = numStates;
    fsa->currentState = currentState;
    fsa->states = (State**)calloc(numStates, sizeof(State*));
    pthread_mutex_init(&fsa->lock, NULL);
    return fsa;
}

void fsaFree(FSA* fsa) {
    for (int i = 0; i < fsa->numStates; i++) {
        free(fsa->states[i]);
    }
    free(fsa->states);
    pthread_mutex_destroy(&fsa->lock);
    free(fsa);
}

State* createState(int id, State* next) {
    State* state = (State*)malloc(sizeof(State));
    state->id = id;
    state->next = next;
    return state;
}

void fsaUpdate(FSA* fsa, int lastStateId) {
    pthread_mutex_lock(&fsa->lock);

    // Validate the FSA for consistency
    for (int i = 0; i < fsa->numStates; i++) {
        // Check all transitions are defined
        // Check reachable states are considered
    }

    State* newStateList = createState(lastStateId, NULL);
    for (int i = 0; i < fsa->numStates; i++) {
        fsa->states[i]->next = &newStateList;
    }

    pthread_mutex_unlock(&fsa->lock);
}
