typedef struct {
    int count;
    double mean;
    double stdDev;
    double* values;
} StatisticalMetrics;

SensorReading* process_data_stream(int num_sensors, SensorReading** sensor_readings, int window_size) {
    StatisticalMetrics* metrics = (StatisticalMetrics*)malloc(num_sensors * sizeof(StatisticalMetrics));
    for (int i = 0; i < num_sensors; i++) {
        metrics[i].count = 1;
        metrics[i].mean = sensor_readings[i]->value;
        metrics[i].values = (double*)malloc(window_size * sizeof(double));
        metrics[i].values[0] = sensor_readings[i]->value;
    }

    int max_deviation = 0;
    long max_deviation_timestamp = 0;

    for (int i = 0; i < num_sensors; i++) {
        for (int j = 1; j <= window_size; j++) {
            if (j >= metrics[i].count) {
                metrics[i].mean -= metrics[i].values[j - 1];
                metrics[i].values[metrics[i].count++] = sensor_readings[i][j].value;
                metrics[i].mean += sensor_readings[i][j].value;
                metrics[i].values[j - 1] = sensor_readings[i][j].value;
            }
        }

        double variance = 0;
        for (int j = 0; j < metrics[i].count; j++) {
            variance += pow(metrics[i].values[j] - metrics[i].mean, 2);
        }
        variance /= (metrics[i].count - 1);

        double std_dev = sqrt(variance);

        if (abs(sensor_readings[i]->value - metrics[i].mean) > 3 * std_dev && i == 0) {
            max_deviation = abs(sensor_readings[i]->value - metrics[i].mean);
            max_deviation_timestamp = sensor_readings[i]->timestamp;
        }
    }

    return (SensorReading*)malloc(sizeof(SensorReading));
}

