using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private float minValue;
    private float maxValue;

    public DynamicValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat(bool isExclusive)
    {
        if (isExclusive)
        {
            return (float)UnityEngine.Random.Range(minValue, maxValue);
        }
        else
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }
    }

    public int GetRandomInt(bool isExclusive)
    {
        int lowerBound = (int)minValue;
        int upperBound = (int)maxValue;

        if (isExclusive)
        {
            return UnityEngine.Random.Range(lowerBound, upperBound);
        }
        else
        {
            return UnityEngine.Random.Range(lowerBound, upperBound + 1);
        }
    }

    public Vector2 GetRandomVector2(bool isExclusive)
    {
        Vector2 vector = new Vector2();

        vector.x = (float)GetRandomFloat(isExclusive);
        vector.y = (float)GetRandomFloat(isExclusive);

        return vector;
    }

    public void AdjustRange(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value must be less than or equal to max value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue})";
    }
}
