const { performance } = require('perf_hooks');
const { setTimeout } = require('timers');

function asyncReduce(transactions, callback) {
  let totalAmount = 0;
  let timeoutCount = 0;

  transactions.forEach((transaction) => {
    if (!transaction.timestamp || !transaction.amount || !transaction.status) {
      throw new Error('Invalid transaction format');
    }

    const now = Date.now();
    const windowStart = now - (24 * 60 * 60 * 1000); // last 24 hours

    if (transaction.timestamp < windowStart || transaction.status !== 'COMPLETED') {
      return; // skip transaction
    }

    setTimeout(() => {
      try {
        callback(transaction);
      } catch (error) {
        if (error.name === 'TimeoutError') {
          timeoutCount++;
        }
      } finally {
        performance.clearMarks();
      }
    }, 500); // processing time limit

    totalAmount += transaction.amount;
  });

  return { totalAmount, timeoutCount };
}

module.exports = asyncReduce;
