function processDOMElements(node, sizeLimit, selector, fetchData) {
  const results = [];

  (function traverse(node) {
    if (!node) return;

    try {
      const text = node.textContent;
      const matched = node.matches(selector);

      if (matched && text.length <= sizeLimit) {
        const metadata = fetchData(node);
        results.push(metadata ? metadata : text);
      } else if (text.length > sizeLimit) {
        results.push('TOO_LONG');
      }

      Array.from(node.children).forEach(traverse);
    } catch (error) {
      console.error(error);
    }
  })(node);

  return results;
}
