['Here is the C code block that implements the `extractTIFFInfo` function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <md5.h>

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
} SampleInfo;

typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamplesCount;
    SampleInfo* extraSamples;
} TIFFImageInfo;

TIFFImageInfo extractTIFFInfo(const char* filePath) {
    TIFFImageInfo info;
    SampleInfo sample;

    // Open the file
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        // Handle error: File not found or unable to open
        return (TIFFImageInfo){0};
    }

    // Read the TIFF header
    unsigned short byteOrder;
    unsigned short tiffHeaderSize;
    fread(&byteOrder, sizeof(byteOrder), 1, file);
    fread(&tiffHeaderSize, sizeof(tiffHeaderSize), 1, file);

    // Parse sample and bits per sample information
    unsigned short samplesPerPixel;
    fread(&samplesPerPixel, sizeof(samplesPerPixel), 1, file);

    int bitsPerSample;
    fread(&bitsPerSample, sizeof(bitsPerSample), 1, file);

    if (bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16) {
        // Validate the bit depth
        info.bitsPerSample = bitsPerSample;

        // Read extra samples count and information
        int extraSamplesCount;
        fread(&extraSamplesCount, sizeof(extraSamplesCount), 1, file);

        if (extraSamplesCount > 0) {
            info.extraSamplesCount = extraSamplesCount;
            sample.bitsPerSample = bitsPerSample;
            info.extraSamples = malloc(extraSamplesCount * sizeof(SampleInfo));

            for (int i = 0; i < extraSamplesCount; i++) {
                fread(&sample, sizeof(sample), 1, file);
                info.extraSamples[i] = sample;
            }
        } else {
            info.extraSamples = NULL;
        }

        // Calculate the MD5 hash of the extracted image metadata
        unsigned char md5Hash[MD5_DIGEST_LENGTH];
        MD5_CTX ctx;
        MD5_Init(&ctx);

        char* buffer = (char*) &info;
        size_t bufferSize = sizeof(TIFFImageInfo);

        MD5_Update(&ctx, buffer, bufferSize);
        MD5_Final(md5Hash, &ctx);

        // Return the extracted information and the MD5 hash string
        return info;
    } else {
        // Handle error: Unsupported bit depth
        return (TIFFImageInfo){0};
    }
}
