char* generate_new_filename(char* input_filename) {
    char *token = strtok(input_filename, ".");
    if (token == NULL || strlen(token) == 0) {
        token = strtok(NULL, ".");
        return realloc(strcat("unknown", "."), strlen("unknown") + 2);
    }

    int base_name_length = 0;
    for (char* p = token; *p; p++) {
        if (*p >= 'A' && *p <= 'Z' || *p >= 'a' && *p <= 'z' || *p >= '0' && *p <= '9') {
            base_name_length++;
        } else break;
    }

    char* new_extension = malloc(strlen(token) + 2);
    sprintf(new_extension, ".%d", base_name_length);

    if (strcat(strcpy(new_extension, token), new_extension)) {
        free(new_extension);
        return NULL;
    }

    size_t len = strlen(input_filename);
    for (size_t i = len - 1; i > 0; --i) {
        if (input_filename[i] == '/') {
            len = i;
            break;
        }
    }

    char* new_filename = malloc(len + strlen(new_extension) + 2);
    sprintf(new_filename, "%.*s%s", (int)len, input_filename, new_extension);

    free(new_extension);
    return new_filename;
}
