#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define MAX_JOBS 100
#define MAX_QUEUED_JOBS 50
#define LOG_FILE "job_log.txt"

int job_queue_size = 0;
int total_jobs_ran = 0;
int jobs_succeeded = 0;

void sig_handler(int signal) {
    // Terminate all running jobs when the program exits
    while (kill(getpid(), SIGTERM) && wait(NULL) > 0);
}

void handle_job_failure(pid_t job_pid, int status) {
    // Log failure details and increment failure count
    FILE *log_file = fopen(LOG_FILE, "a");
    fprintf(log_file, "Job %d failed with status %d\n", job_pid, status);
    fclose(log_file);

    total_jobs_ran++;
}

int manage_job_pool() {
    pid_t jobs[MAX_JOBS];
    int job_index = 0;
    int job_queue[50];

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Wait for a new job request
        sleep(1);  // Simulate some processing time

        if (job_queue_size >= MAX_QUEUED_JOBS) {
            // Queue is full, wait until a job completes
            int job_pid = wait(NULL);
            printf("Job %d completed\n", job_pid);
            job_queue_size--;
        } else {
            // New job request received, add to queue and start it
            if (job_index < MAX_JOBS) {
                jobs[job_index] = fork();
                if (jobs[job_index] == 0) {
                    // Child process executes the command
                    int status;
                    execv("/path/to/command", NULL);
                    _exit(status);
                } else if (jobs[job_index] > 0) {
                    job_queue[job_queue_size++] = jobs[job_index];
                }
            }

            job_index++;
        }

        // Monitor and report job queue size and success/failure rates
        printf("Job queue size: %d\n", job_queue_size);
        printf("Jobs ran: %d, Successes: %d, Failures: %d\n", total_jobs_ran, jobs_succeeded, job_queue_size - jobs_succeeded);
    }

    return 0;
}

int main() {
    signal(SIGCHLD, sig_handler);

    while (1) {
        manage_job_pool();
    }

    return 0;
}
