```java
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class JobManager {
    private ExecutorService executor;
    private int maxThreads;

    public JobManager(int maxThreads) {
        this.maxThreads = maxThreads;
        this.executor = Executors.newFixedThreadPool(maxThreads);
    }

    public void submitJob(Job job) throws InterruptedException, ExecutionException {
        Future<String> future = executor.submit(() -> executeJob(job));
        String output = future.get();
        if (future.isDone()) {
            System.out.println("Job completed: " + job.toString());
        } else {
            throw new ExecutionException("Job failed", future.getCause());
        }
    }

    private String executeJob(Job job) throws InterruptedException, IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(job.getCommand());
        processBuilder.environment().putAll(job.getEnvironment());

        try (Process process = processBuilder.start()) {
            StringBuilder outputBuilder = new StringBuilder();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                outputBuilder.append(line).append("\n");
            }

            int exitValue = process.waitFor();
            if (exitValue == 0) {
                return outputBuilder.toString();
            } else {
                throw new IOException("Job failed with exit code " + exitValue);
            }
