using System;
using System.Security.Cryptography;
using System.Text;

public enum ErrorCode {
    Success,
    InvalidPassword,
    ConnectionTitleNullOrTooShort,
    CallbackFunctionNull
}

public static ErrorCode ProcessInput(string* password, string* connectionTitle, Action callback) {
    if (password == null || string.IsNullOrEmpty((string)password)) return ErrorCode.InvalidPassword;
    if (connectionTitle == null || ((string)connectionTitle).Length < 2) return ErrorCode.ConnectionTitleNullOrTooShort;
    if (callback == null) return ErrorCode.CallbackFunctionNull;

    // Decrypt password
    using var tripleDes = TripleDES.Create();
    tripleDes.Key = Convert.FromBase64String("YOUR_DES_KEY_HERE");
    tripleDes.IV = Convert.FromBase64String("YOUR_DES_IV_HERE");

    try {
        using var memoryStream = new MemoryStream();
        using (var cryptoStream = new CryptoStream(memoryStream, tripleDes.CreateDecryptor())) {
            byte[] encryptedBytes = Convert.FromBase64String((string)password);
            cryptoStream.Write(encryptedBytes, 0, encryptedBytes.Length);
            cryptoStream.FlushFinalBlock();

            memoryStream.Position = 0;
            byte[] decryptedBytes = new byte[memoryStream.Length];
            memoryStream.Read(decryptedBytes, 0, decryptedBytes.Length);

            callback(new string(decryptedBytes));
        }
    } catch {
        return ErrorCode.Failure;
    }

    return ErrorCode.Success;
}
