bool validate_config(json_object* conf) {
    json_object *port_obj, *server_name_obj, *document_root_path_obj;
    port_obj = json_object_object_get(conf, "port");
    if (!json_object_is_type(port_obj, json_type_integer)) return false;
    int port = json_object_get_int(port_obj);
    if (port < 1 || port > 65535) return false; // or allow ports below 1024 for testing

    server_name_obj = json_object_object_get(conf, "server_name");
    if (!json_object_is_type(server_name_obj, json_type_string)) return false;
    char* server_name = (char*)json_object_get_string(server_name_obj);
    if (strlen(server_name) > 64 || strlen(server_name) < 1) return false; // or adjust the length limit as needed
    for (int i = 0; i < strlen(server_name); i++) {
        if (!isalnum((unsigned char)server_name[i]) && server_name[i] != '.') return false;
    }

    document_root_path_obj = json_object_object_get(conf, "document_root_path");
    if (!json_object_is_type(document_root_path_obj, json_type_string)) return false;
    char* document_root_path = (char*)json_object_get_string(document_root_path_obj);
    struct stat sb;
    if(stat(document_root_path, &sb) != 0 || !S_ISDIR(sb.st_mode)) return false;

