        ssl_key_path = (char*)json_object_get_string(ssl_key_path_obj);
        struct stat sb;
        if(stat(ssl_key_path, &sb) == 0 && S_ISREG(sb.st_mode) && access(ssl_key_path, R_OK) != -1) {}
        else return false;
    }

    // Logging settings
    json_object *log_file_path_obj = json_object_object_get(conf, "log_file_path");
    json_object *log_level_obj = json_object_object_get(conf, "log_level");
