        public DatabaseModule(string connectionString)
        {
            _connectionString = connectionString;
        }

        public async Task ProcessDataAsync(string query)
        {
            using (var connection = GetConnection(query))
            {
                await connection.OpenAsync();
                var reader = await connection.ExecuteReaderAsync(query);
                while (await reader.ReadAsync())
                {
                    // process data
                }
            }
        }

        private SqlConnection GetConnection(string query)
        {
            if (!_connections.TryGetValue(query, out var connections))
            {
                connections = new List<SqlConnection>();
                _connections[query] = connections;
            }

            foreach (var connection in connections)
            {
                if (!connection.State.HasFlag(ConnectionState.Opened))
                {
                    return connection;
                }
            }

            var newConnection = new SqlConnection(_connectionString);
            connections.Add(newConnection);
            return newConnection;
        }
    }

}

