using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Base64Processor
{
    public static string ProcessBase64Message(string base64Message, bool isEncryption, string key, string iv, int segmentSize = 0)
    {
        using (var memoryStream = new MemoryStream())
        using (var cryptoStream = new CryptoStream(memoryStream, CreateTripleDesAlgorithm(isEncryption, key, iv), CryptoStreamMode.Write))
        {
            var base64Bytes = Convert.FromBase64String(base64Message);
            var messageWriter = new BinaryWriter(cryptoStream);

            int bytesRead;
            byte[] segmentBytes;

            for (int i = 0; i < base64Bytes.Length; ; i += segmentSize)
            {
                segmentBytes = new byte[Math.Min(segmentSize, base64Bytes.Length - i)];
                Array.Copy(base64Bytes, i, segmentBytes, 0, segmentBytes.Length);
                messageWriter.Write(segmentBytes);

                if (isEncryption && i >= segmentSize)
                    cryptoStream.FlushFinalBlock();

                bytesRead += segmentBytes.Length;
            }
        }

        return Convert.ToBase64String(memoryStream.ToArray());
    }

    private static ICryptoTransform CreateTripleDesAlgorithm(bool isEncryption, string key, string iv)
    {
        var tripleDes = TripleDESCryptoServiceProvider.Create();
        tripleDes.Key = Encoding.ASCII.GetBytes(key);
        tripleDes.IV = Encoding.ASCII.GetBytes(iv);

        if (!isEncryption)
            return new HMACSHA256(tripleDes).HashCore;

        return tripleDes;
    }
}

public class HMACSHA256 : ICryptoTransform
{
    private readonly SHA256CryptoServiceProvider _hashProvider;

    public HMACSHA256(ICryptoTransform transform)
    {
        _hashProvider = new SHA256CryptoServiceProvider();
        _hashProvider.HashCore = transform;
    }

    public byte[] HashCore { get; }
}
