using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly Dictionary<string, string> _filePaths = new Dictionary<string, string>();

    public async Task<Dictionary<string, string>> GetFileHashesAsync()
    {
        if (_filePaths.Count == 0)
        {
            // Load file paths from external configuration source here
            // For demonstration purposes, assume the file paths are already loaded
            _filePaths.Add("path1", "C:\\Path\\To\\File1.txt");
            _filePaths.Add("path2", "C:\\Path\\To\\File2.txt");
            // ...
        }

        var fileHashes = new Dictionary<string, string>();

        foreach (var filePath in _filePaths.Values)
        {
            if (!string.IsNullOrEmpty(filePath) && File.Exists(filePath))
            {
                using (var stream = File.OpenRead(filePath))
                {
                    using (var hashAlgorithm = SHA256.Create())
                    {
                        var hashValue = await CalculateHashAsync(stream, hashAlgorithm);
                        fileHashes.Add(filePath, BitConverter.ToString(hashValue).Replace("-", string.Empty));
                    }
                }
            }
        }

        return fileHashes;
    }

    private async Task<byte[]> CalculateHashAsync(Stream stream, SHA256 sha256)
    {
        var hashValue = await Task.Run(() => HashStream(stream, sha256));
        return hashValue;
    }

    private byte[] HashStream(Stream stream, SHA256 sha256)
    {
        using (var hashAlgorithm = sha256)
        {
            var hashValue = new byte[hashAlgorithm.HashSize / 8];
            await Task.Run(() => {
                var buffer = new byte[0x10000]; // Adjust this size based on your needs
                int bytesRead;
                do
                {
                    bytesRead = stream.Read(buffer, 0, buffer.Length);
                    hashAlgorithm.TransformBlock(buffer, 0, bytesRead);
                }
                while (bytesRead > 0);

                hashAlgorithm.TransformFinalBlock();
                Array.Copy(hashAlgorithm.Hash, hashValue, hashAlgorithm.HashSize / 8);
            });
            return hashValue;
        }
    }
}
