public byte[] DecryptCiphertext(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector)
{
    using (Aes aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = initializationVector;

        ICryptoTransform decryptor = aes.CreateDecryptor();

        using (MemoryStream ms = new MemoryStream(ciphertext))
        {
            using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                byte[] decryptedBytes = new byte[ciphertext.Length];
                int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);

                if (bytesRead != ciphertext.Length)
                    throw new CryptographicException("Padding error occurred during decryption.");

                return decryptedBytes;
            }
        }
    }
}

public bool VerifyDecryptedData(byte[] decryptedBytes, byte[] hmacKey, byte[] expectedHmac)
{
    using (HMACSHA256 hmac = HMACSHA256.Create())
    {
        hmac.Key = hmacKey;

        byte[] hash = hmac.ComputeHash(decryptedBytes);

        return hash.SequenceEqual(expectedHmac);
    }
}

