import sun.misc.Unsafe;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.util.concurrent.atomic.AtomicReference;

public class DynamicClassLoader {
    private static final Unsafe UNSAFE =Unsafe.getUnsafe();
    private static final AtomicReference<ByteBuffer> byteBufferRef = new AtomicReference<>();

    public static Object instantiateObject(byte[] data) throws Exception {
        ByteBuffer buffer = byteBufferRef.getAndSet(null);
        if (buffer == null) {
            buffer = ByteBuffer.wrap(data).asReadOnlyBuffer();
            byteBufferRef.set(buffer);
        }

        Field field = buffer.getClass().getDeclaredField("position");
        field.setAccessible(true);
        UNSAFE.putLong(buffer, field, 0);

        Object obj;
        try {
            obj = UNSAFE.allocateInstance(Object.class);
            field = buffer.getClass().getDeclaredField("limit");
            field.setAccessible(true);
            UNSAFE.putInt(buffer, field, data.length);
            UNSAFE.copyMemory(data, 0, UNSAFE.addressOf(obj), data.length);
        } catch (Exception e) {
            // Log error and return null
            System.err.println("Error instantiating object: " + e.getMessage());
            obj = null;
        }

        return obj;
    }
}
