    private const int BufferSize = 1024 * 1024; // 1MB buffer size
    private readonly Random _random = new();
    private readonly HttpClient _httpClient;
    private readonly string _storageServiceUrl;

    public FileUploader(HttpClient httpClient, string storageServiceUrl)
    {
        _httpClient = httpClient;
        _storageServiceUrl = storageServiceUrl;
    }

    public async Task<(string, long)> UploadFile(string url)
    {
        var memoryStream = new MemoryStream();
        var buffer = new byte[BufferSize];

        try
        {
            using (var client = _httpClient.GetAsync(url).Result)
            {
                await client.CopyToAsync(memoryStream);
            }

            memoryStream.Position = 0;

            // Initialize arrays for 'long' offset values, 'int' keys and 'record' structures
            var offsets = new long[10];
            var keys = new int[10];
            var records = new Record[10];

            for (var i = 0; i < 10; i++)
            {
                records[i] = new Record { Value = _random.Next(100, 200) };
                offsets[i] = memoryStream.Position;
                keys[i] = i;
            }

            // Upload the file to the storage service
            var response = await _httpClient.PostAsync(_storageServiceUrl, new StreamContent(memoryStream));
            response.EnsureSuccessStatusCode();

            var uploadedFileUrl = await response.Content.ReadAsStringAsync();
            var memoryUsage = memoryStream.Position / 1024 / 1024; // Convert bytes to MB

            return (uploadedFileUrl, memoryUsage);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error uploading file: " + ex.Message);
            throw;
        }
    }

    public record Record(int Value);

    public class RecordComparer : IEqualityComparer<Record>
    {
        public bool Equals(Record x, Record y) => x.Value == y.Value;

        public int GetHashCode(Record obj) => obj.Value.GetHashCode();
    }
}
