const { spawn } = require('child_process');
const schema = {
  type: 'object',
  properties: {
    command: { type: 'string' },
    parameters: {
      type: 'array',
      items: { type: 'string' }
    }
  }
};

function executeShellCommand(input) {
  try {
    const validation = Joi.validate(input, schema);
    if (validation.error) throw new Error('Invalid input');

    let commandString = `${input.command} `;
    if (Array.isArray(input.parameters)) {
      input.parameters.forEach((param, i) => {
        commandString += `--${i+1} ${param} `;
      });
    }

    const childProcess = spawn('bash', ['-c', commandString]);
    let output = '';
    childProcess.stdout.on('data', (data) => {
      output += data.toString();
    });
    childProcess.stderr.on('data', (data) => {
      console.error(`Error: ${data.toString()}`);
    });
    childProcess.on('exit', (code) => {
      if (code !== 0) throw new Error(`Command failed with exit code ${code}`);
    });

    return output;
  } catch (error) {
    const errorLogger = require('./error-logger');
    errorLogger.logError(error);
    return null;
  }
}

module.exports = executeShellCommand;
