use tokio::prelude::*;
use log::{info, error};
use serde_json::Value;
use std::path::{Path, PathBuf};

async fn load_task(task_name: &str) -> Result<Box<dyn Fn() + Sync>, Box<dyn std::error::Error>> {
    let mut path = PathBuf::from("tasks");
    path.push(format!("{}.rs", task_name));
    let src_path = path.clone();
    let module = tokio::fs::read_dir(src_path)
        .await?
        .map(|entry| entry?.path())
        .filter_map(|path| {
            if path.extension() == Some("rs".parse().unwrap()) {
                Some(path)
            } else {
                None
            }
        })
        .find(|path| path.file_name().unwrap() == task_name.as_bytes());
    match module {
        Some(file_path) => {
            let module = tokio::fs::read_to_string(file_path).await?;
            let func: Box<dyn Fn() + Sync> = eval(&module)?;
            Ok(func)
        }
        None => Err(format!("Task {} not found", task_name).into()),
    }
}

async fn execute_tasks(tasks: Vec<String>, log_level: String) {
    let mut runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap();
    runtime.block_on(async move {
        for task in tasks {
            info!("Executing task {}", &task);
            if let Err(err) = load_task(&task).await.and_then(|f| f()) {
                error!("Task {} failed with error: {}", &task, err);
            }
        }
    });
}

#[tokio::main]
async fn main() {
    env_logger::from_env((env!("LOG_LEVEL"), "info"));
    let mut args = std::env::args();
    let log_level = args.next().unwrap_or_default().to_string();
    let tasks: Vec<String> = args.collect();
    execute_tasks(tasks, log_level).await;
}

fn eval(src: &str) -> Result<Box<dyn Fn() + Sync>, Box<dyn std::error::Error>> {
    let module = src.to_string();
    let func: Box<dyn Fn() + Sync> = match syn::parse_module(&module) {
        Ok(module) => Box::new(eval_syn(&module)?),
        Err(err) => return Err(format!("Invalid module: {}", err).into()),
    };
    Ok(func)
}

fn eval_syn(module: &syn::File) -> Result<Box<dyn Fn() + Sync>, Box<dyn std::error::Error>> {
    let items = module.items.iter().filter_map(|item| match item {
        syn::ItemFn { ref sig, .. } => Some((&**sig)),
        _ => None,
    });
    let func: Box<dyn Fn() + Sync> = items.next().ok_or("No function found")?;
    Ok(func)
}
