}

impl ConfigDir {
    fn new(dir_name: &str) -> Result<Self, String> {
        let path = Path::new(dir_name).to_path_buf();
        let lock = Arc::new(AtomicUsize::new(0));
        Ok(ConfigDir { dir_path: Arc::new(path), lock })
    }

    fn create_dir(&self) -> Result<(), String> {
        if !self.dir_path.exists() {
            match fs::create_dir_all(&self.dir_path) {
                Ok(_) => println!("Directory created successfully: {}", self.dir_path.display()),
                Err(e) => return Err(format!("Failed to create directory: {}", e)),
            }
            let _ = env::set_var("CONFIG_DIR", &self.dir_path.display());
            Ok(())
        } else {
            Ok(())
        }
    }

    fn lock(&self, timeout: u64) -> Result<(), String> {
        match self.lock.compare_exchange(0, 1, Ordering::Relaxed) {
            Ok(_) => {
                println!("Directory locked successfully");
                Ok(())
            },
            Err(e) => Err(format!("Failed to lock directory: {}", e)),
        }
    }

    fn unlock(&self) -> Result<(), String> {
        self.lock.store(0, Ordering::Relaxed);
        println!("Directory unlocked successfully");
        Ok(())
    }
}

fn main() {
    let config_dir = ConfigDir::new("config").unwrap();
    match config_dir.create_dir() {
        Ok(_) => println!("Configuration directory created"),
        Err(e) => println!("Error creating configuration directory: {}", e),
    }

    // Example of concurrent access control
    let mut handles = vec![];
    for _ in 0..5 {
        let handle = std::thread::spawn(move || {
            match config_dir.lock(std::time::Duration::from_millis(100)) {
                Ok(_) => println!("Thread locked directory"),
                Err(e) => eprintln!("Error locking directory: {}", e),
            }
            // Perform operations on the configuration directory
            // ...
            match config_dir.unlock() {
                Ok(_) => println!("Thread unlocked directory"),
                Err(e) => eprintln!("Error unlocking directory: {}", e),
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }
}
