import json
import asyncio
from functools import lru_cache

class JSONRegistry:
    def __init__(self):
        self.registry = {}
        self.cache_size = 1000
        self.cached_data = {}

    @lru_cache(maxsize=self.cache_size)
    async def parse_json(self, data: str) -> dict:
        try:
            return json.loads(data)
        except json.JSONDecodeError as e:
            print(f"Failed to parse JSON: {e}")
            raise

    @lru_cache(maxsize=self.cache_size)
    async def serialize_json(self, data: dict) -> str:
        try:
            return json.dumps(data)
        except Exception as e:
            print(f"Failed to serialize JSON: {e}")
            raise

    def register_factory(self, identifier: str, factory):
        self.registry[identifier] = factory

    async def create_instance(self, identifier: str) -> dict:
        if identifier in self.registry:
            return self.registry[identifier]()
        else:
            print(f"Unknown identifier: {identifier}")
            raise ValueError

class JSONConverter(JSONRegistry):
    async def convert_data(self, data: str, mode: str = 'to_json') -> dict:
        if mode == 'to_json':
            return await self.serialize_json(data)
        elif mode == 'from_json':
            return await self.parse_json(data)
        else:
            print("Invalid conversion mode")
            raise ValueError

    async def fetch_data(self, url: str) -> dict:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as response:
                    data = await response.text()
                    return await self.convert_data(data)
        except Exception as e:
            print(f"Failed to fetch JSON: {e}")
            raise

    async def update_registry(self, data: dict):
        for key, value in data.items():
            if isinstance(value, list):
                await asyncio.gather(*[self.update_registry(item) for item in value])
            elif isinstance(value, dict):
                await self.update_registry(value)

class JSONProcessor(JSONConverter):
    async def process_data(self, url: str):
        try:
            data = await self.fetch_data(url)
            await self.update_registry(data)
        except Exception as e:
            print(f"Failed to process JSON: {e}")
            raise

async def main():
    registry = JSONRegistry()
    converter = JSONConverter()

    # Register factories
    registry.register_factory('user', lambda: {'name': 'John Doe'})
    registry.register_factory('product', lambda: {'name': 'Product X'})

    # Create instances
    user_instance = await registry.create_instance('user')
    product_instance = await registry.create_instance('product')

    # Process data
    await converter.process_data('https://example.com/data.json')

asyncio.run(main())
