#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
} record_t;

void init_arrays(record_t **records, int *key_array, int size) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for records and key array
    *records = (record_t *)malloc(size * sizeof(record_t));
    *key_array = (int *)calloc(size, sizeof(int));

    if (*records == NULL || *key_array == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize records and key array with random values
    for (int i = 0; i < size; i++) {
        record_t* rec = &(*records)[i];
        rec->key = rand() % 100 + 1;
        rec->offset = (long)rand();
        *key_array[i] = rec->key;
    }
}

void serialize_data(const record_t *records, int *key_array, FILE *file) {
    // Serialize records and key array to file
    for (int i = 0; i < size; i++) {
        fwrite(&records[i], sizeof(record_t), 1, file);
        fwrite(&key_array[i], sizeof(int), 1, file);
    }
}

void verify_data(const record_t *records, int *key_array) {
    // Verify records and key array integrity
    for (int i = 0; i < size; i++) {
        if (records[i].key != key_array[i]) {
            printf("Data corruption detected.\n");
            return;
        }
    }
    printf("Data integrity verified.\n");
}

int main() {
    int size = 1000; // Adjust the size as needed
    record_t *records = NULL;
    int *key_array = NULL;

    init_arrays(&records, &key_array, size);

    FILE *file = fopen("data.bin", "wb"); // Open file for binary write

    if (file == NULL) {
        printf("Failed to open file.\n");
        return 1;
    }

    serialize_data(records, key_array, file);
    fclose(file);

    verify_data(records, key_array);

    free(key_array);
    free(records);

    return 0;
}
