#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    long timestamp;
    enum { NONE = 0, AES, CAMELLIA, MD5, SHA } status;
    char *aes_key;
    char *camellia_key;
    unsigned char *md5_hash;
    unsigned char *sha_hash;
    RSA *rsa_key;
} EventNotification;

typedef struct {
    pthread_mutex_t lock;
    int size;
    EventNotification **events;
} EventList;

EventList* event_list_init() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->events = NULL;
    return list;
}

void event_list_free(EventList* list) {
    for(int i = 0; i < list->size; i++) {
        free(list->events[i]->aes_key);
        free(list->events[i]->camellia_key);
        OPENSSL_free(list->events[i]->md5_hash);
        OPENSSL_free(list->events[i]->sha_hash);
        RSA_free(list->events[i]->rsa_key);
    }
    pthread_mutex_destroy(&list->lock);
    free(list->events);
    free(list);
}

void event_list_add(EventList* list, EventNotification* event) {
    pthread_mutex_lock(&list->lock);
    list->events = (EventNotification**)realloc(list->events, sizeof(EventNotification*) * (list->size + 1));
    list->events[list->size] = event;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

EventNotification* event_list_get(EventList* list, int id) {
    pthread_mutex_lock(&list->lock);
    for(int i = 0; i < list->size; i++) {
        if(list->events[i]->id == id) {
            EventNotification* event = list->events[i];
            pthread_mutex_unlock(&list->lock);
            return event;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void event_list_update(EventList* list, int id, enum { NONE = 0, AES, CAMELLIA, MD5, SHA } status) {
    pthread_mutex_lock(&list->lock);
    for(int i = 0; i < list->size; i++) {
        if(list->events[i]->id == id) {
            list->events[i]->status = status;
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void event_list_remove(EventList* list, int id) {
    pthread_mutex_lock(&list->lock);
    for(int i = 0; i < list->size; i++) {
        if(list->events[i]->id == id) {
            free(list->events[i]);
            memmove(&list->events[i], &list->events[i + 1], (list->size - i - 1) * sizeof(EventNotification*));
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void event_list_clear(EventList* list) {
    for(int i = 0; i < list->size; i++) {
        free(list->events[i]);
    }
    list->size = 0;
}
