#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <jansson/jansson.h>

int main() {
    // Implement connection setup and error handling here
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    // Read integers from the file descriptor
    int *integers = NULL;
    size_t num_integers = 0;
    while (true) {
        // Dynamically allocate memory for up to 10,000 integers
        if (num_integers >= 10000) {
            break;
        }

        char buffer[1024];
        ssize_t bytes_read = read(sock, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("Read failed");
            return -1;
        } else if (bytes_read == 0) {
            // Connection closed
            break;
        }

        char *str = buffer;
        while (*str != '\0') {
            str++;
        }
        int integer = strtol(buffer, &str, 10);
        if (*str == '\0' && integer != INT_MAX) {
            integers = realloc(integers, (num_integers + 1) * sizeof(int));
            integers[num_integers++] = integer;
        } else {
            // Malformed input or unexpected data type
            free(integers);
            return -1;
        }
    }

    if (num_integers == 0) {
        printf("No valid integers found.\n");
    } else {
        qsort(integers, num_integers, sizeof(int), compare);

        printf("Largest integer: %d\n", integers[num_integers - 1]);
        int second_largest = integers[0];
        for (size_t i = 1; i < num_integers; i++) {
            if (integers[i] > second_largest) {
                second_largest = integers[i];
            }
        }

        if (second_largest != integers[num_integers - 1]) {
            printf("Distinct second-largest integer: %d\n", second_largest);
        } else {
            printf("No distinct second-largest integer found.\n");
        }

        free(integers);
    }

    close(sock);

    return 0;
}

int compare(const void *a, const void *b) {
    int *ia = (int *)a;
    int *ib = (int *)b;

    if (*ia > *ib) {
        return -1;
    } else if (*ia < *ib) {
        return 1;
    } else {
        return 0;
    }
}

