import java.io.File;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessor {
    private static final int MAX_THREADS = 5;
    private static final int CACHE_SIZE = 1000; // adjust as needed
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    public void processFiles(String[] filePaths) throws Exception {
        for (String filePath : filePaths) {
            if (!cache.containsKey(filePath)) {
                executor.submit(() -> processFile(filePath));
            }
        }
        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private void processFile(String filePath) throws Exception {
        File file = new File(filePath);
        if (!file.exists()) {
            System.out.println("File not found: " + filePath);
            return;
        }
        try (MessageDigest md = MessageDigest.getInstance("SHA-256")) {
            byte[] buffer = new byte[4096];
            StringBuilder hash = new StringBuilder();
            try (java.io.FileReader reader = new java.io.FileReader(file)) {
                int bytesRead;
                while ((bytesRead = reader.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                byte[] digest = md.digest();
                for (byte b : digest) {
                    String hex = Integer.toHexString(b & 0xFF);
                    hash.append(hex.length() == 1 ? "0" + hex : hex);
                }
            }
            String fileHash = hash.toString();
            if (!cache.putIfAbsent(filePath, fileHash)) {
                System.out.println("Updated hash for: " + filePath);
            } else {
                System.out.println("No change detected for: " + filePath);
            }
        }

        // Retrieve metadata from external service
        try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(new URL("https://metadata-service.com/api/files/" + file.getAbsolutePath()).openStream()))) {
            String metadata = reader.readLine();
            if (metadata != null) {
                System.out.println(metadata);
            } else {
                System.out.println("Failed to retrieve metadata for: " + filePath);
            }
        } catch (Exception e) {
            System.out.println("Error retrieving metadata for: " + filePath);
            e.printStackTrace(System.out);
        }

        // Log any exceptions
        if (e != null) {
            System.out.println("Error processing file: " + filePath);
            e.printStackTrace(System.out);
        }
    }
}
