    {
        _authenticationService = authenticationService;
        _htmlContentService = htmlContentService;
        _logManager = logManager;
    }

    [HttpPost]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> UpdateHtmlElement(string pageSectionId, string elementId, string htmlContent)
    {
        if (!await _authenticationService.VerifyUserPermissions())
            return new UnauthorizedResult();

        try
        {
            var version = await GetVersion(pageSectionId);
            if (version == null)
                return new BadRequestObjectResult("Invalid page section ID");

            var updatedHtmlContent = await UpdateHtmlContent(version, elementId, htmlContent);

            // Check for potential delays or failures in HTML content updates
            if (!await _htmlContentService.VerifyUpdateSuccess(updatedHtmlContent))
                return new StatusCodeResult(500); // Internal Server Error

            // Log update success and maintain version history
            await _logManager.LogUpdateSuccess(version, updatedHtmlContent);

            // Return response indicating page should be refreshed
            return new OkObjectResult("Refresh the page to see the updated content.");
        }
        catch (Exception ex)
        {
            // Handle exceptions by rolling back updates and logging errors
            if (await RollbackUpdates(pageSectionId, version))
                return new InternalServerErrorResult(); // Internal Server Error

            _logManager.LogError(ex);
            return new BadRequestObjectResult("Error updating HTML element.");
        }
    }

