use reqwest::blocking::get;
use std::time::{Duration, Instant};

pub struct RustHttpClient {
    timeout: u64,
}

impl RustHttpClient {
    pub fn new(timeout: u64) -> Self {
        RustHttpClient { timeout }
    }

    async fn send_request(&self, url: &str) -> Result<String, reqwest::Error> {
        let start_time = Instant::now();
        loop {
            match get(url).timeout(Duration::from_millis(self.timeout as u128)).send().await {
                Ok(response) => {
                    if response.status().is_success() {
                        return Ok(response.text().await.unwrap());
                    } else {
                        error!("Server returned an error: {}", response.status());
                    }
                }
                Err(err) => match err {
                    reqwest::Error::Timeout => {
                        if start_time.elapsed().as_millis() > self.timeout as u128 {
                            return Err(reqwest::Error::Timeout);
                        }
                    }
                    _ => {}
                },
            }
        }
    }

