#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CACHE_LINE_SIZE 64
#define STRUCT_ELEMENT_ALIGN (sizeof(long)) // assuming long is the largest type in the struct

typedef struct {
    int i;
    double d;
    char c;
} element_t;

void* alloc_arrays(void) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t array_size = 10; // adjust according to your needs
    double* doubles = aligned_alloc(CACHE_LINE_SIZE, sizeof(double) * array_size);
    if (!doubles) {
        return NULL;
    }

    char* chars = aligned_alloc(CACHE_LINE_SIZE, sizeof(char) * array_size);
    if (!chars) {
        free(doubles);
        return NULL;
    }

    element_t** elements = aligned_alloc(STRUCT_ELEMENT_ALIGN, sizeof(element_t*) * array_size);
    if (!elements) {
        free(doubles);
        free(chars);
        return NULL;
    }

    for (size_t i = 0; i < array_size; ++i) {
        elements[i] = aligned_alloc(CACHE_LINE_SIZE, sizeof(element_t));
        if (!elements[i]) {
            for (size_t j = 0; j <= i; ++j) {
                free(elements[j]);
            }
            free(doubles);
            free(chars);
            return NULL;
        }

        element_t* elem = elements[i];
        elem->i = i;
        elem->d = (double)i;
        elem->c = (char)(i % 2 ? 'a' : 'b');
    }

    int active_count = array_size; // track the number of active elements
    pthread_mutex_init(&mutex, NULL);

    return struct {
        double* doubles;
        char* chars;
        element_t** elements;
        pthread_mutex_t mutex;
        int active_count;
    };
}

void dealloc_arrays(void* ptr) {
    struct {
        double* doubles;
        char* chars;
        element_t** elements;
        pthread_mutex_t mutex;
        int active_count;
    } *arr = ptr;

    for (size_t i = 0; i < arr->active_count; ++i) {
        free(arr->elements[i]);
    }

    free(arr->chars);
    free(arr->doubles);

    pthread_mutex_destroy(&arr->mutex);

    free(ptr);
}

void update_element(void* ptr, size_t idx, int value) {
    struct {
        double* doubles;
        char* chars;
        element_t** elements;
        pthread_mutex_t mutex;
        int active_count;
    } *arr = ptr;

    pthread_mutex_lock(&arr->mutex);

    if (idx < arr->active_count) {
        element_t* elem = arr->elements[idx];
        elem->i = value;
    }

    pthread_mutex_unlock(&arr->mutex);
}

void print_elements(void* ptr) {
    struct {
        double* doubles;
        char* chars;
        element_t** elements;
        pthread_mutex_t mutex;
        int active_count;
    } *arr = ptr;

    for (size_t i = 0; i < arr->active_count; ++i) {
        element_t* elem = arr->elements[i];
        printf("(%zu: %d, %.2f, '%c')\n", i, elem->i, elem->d, elem->c);
    }
}

int main() {
    void* ptr = alloc_arrays();

    if (!ptr) {
        return 1; // handle error
    }

    update_element(ptr, 3, 10);

    print_elements(ptr);

    dealloc_arrays(ptr);

    return 0;
}
