using System;
using System.Diagnostics;
using System.Threading;

public class RandomValueGenerator
{
    private double minValue;
    private double maxValue;

    public RandomValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value", nameof(minValue));

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public double GetRandomFloat()
    {
        Random random = new Random();
        return random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        Random random = new Random();
        if (random.NextDouble() < (maxValue - minValue) / (double)(1 << 31))
            return minValue;
        else
            return (int)((maxValue - minValue) * random.NextDouble() + minValue);
    }

    public Vector2 GetRandomVector2()
    {
        return new Vector2(GetRandomFloat(), GetRandomFloat());
    }

    public override string ToString()
    {
        return $"Min: {minValue}, Max: {maxValue}";
    }
}

public class BackgroundProcessManager
{
    private string commandString;

    public BackgroundProcessManager(string commandString)
    {
        if (string.IsNullOrEmpty(commandString))
            throw new ArgumentException("Command string cannot be empty or null", nameof(commandString));

        this.commandString = commandString;
    }

    public void ExecuteCommand()
    {
        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo();
            startInfo.FileName = "cmd.exe";
            startInfo.Arguments = "/c " + commandString;

            using (Process process = Process.Start(startInfo))
            {
                process.WaitForExit();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error executing command: {ex.Message}");
        }
    }

    public void DisplayCommand()
    {
        Console.WriteLine(commandString);
    }

    public RandomValueGenerator GetRandomValueGenerator(double minValue, double maxValue)
    {
        return new RandomValueGenerator(minValue, maxValue);
    }
}

public struct Vector2
{
    public double X;
    public double Y;

    public Vector2(double x, double y)
    {
        X = x;
        Y = y;
    }

    public override string ToString()
    {
        return $"X: {X}, Y: {Y}";
    }
}
```
Please note that the `RandomValueGenerator` class does not support generating random values for other types such as strings or booleans. You can extend this class to support these types if needed.']

