char* generateNewFilename(char *filename, int maxLength, char *prefix) {
    char baseName[256];
    char extension[16];
    int baseNameLength = 0;
    int extensionIndex = 0;

    // Extract the base name and extension from the input filename
    for(int i = strlen(filename)-1; i >= 0; i--) {
        if(filename[i] == '.') {
            break;
        }
        baseName[baseNameLength++] = filename[i];
    }

    // Determine the length of the base name
    int baseNameLengthFinal = baseNameLength;

    // Truncate the base name to the specified maximum length
    for(int i = 0; i < baseNameLengthFinal && i < maxLength; i++) {
        if(strchr("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789", baseName[i]) != NULL) {
            baseNameLengthFinal = i;
            break;
        }
    }

    // Handle invalid characters in the base name
    char newBaseName[256];
    for(int i = 0; i < baseNameLengthFinal; i++) {
        if(strchr("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789", baseName[i]) != NULL) {
            newBaseName[i] = baseName[i];
        } else {
            newBaseName[i] = '_';
        }
    }

    // Determine the number of digits in the new extension
    int extensionLength = strlen(extension);
    if(baseNameLengthFinal > 0) {
        extensionLength += sprintf(&extension[0], "_%d", baseNameLengthFinal);
    } else {
        strcpy(extension, DEFAULT_EXTENSION);
    }

    // Construct the new filename
    char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH + 1);
    if(prefix != NULL) {
        snprintf(newFilename, MAX_FILENAME_LENGTH + 1, "%s%s", prefix, newBaseName);
    } else {
        strcpy(newFilename, newBaseName);
    }
    strcat(newFilename, extension);

    return newFilename;
}

int main() {
    char* filename = "example.txt";
    int maxLength = 20;
    char* prefix = NULL;

    // Generate the new filename
    char* newFilename = generateNewFilename(filename, maxLength, prefix);

    printf("Original Filename: %s\n", filename);
    printf("Generated New Filename: %s\n", newFilename);

    free(newFilename);

    return 0;
}
