// Structure for record nodes
typedef struct Node {
    int value;
    struct Node* predecessor;
    struct Node* successor;
} Node;

// Function to initialize the system and set random values
void initializeSystem(int maxNodes, int maxValue) {
    // Initialize doubly linked list head and tail
    Node* head = NULL;
    Node* tail = NULL;

    // Initialize node count and memory usage
    int nodesCreated = 0;
    size_t memoryUsage = 0;

    while (nodesCreated < maxNodes && memoryUsage <= getMaxMemoryLimit()) {
        Node* newNode = (Node*) malloc(sizeof(Node));
        if (!newNode) {
            printf("Memory allocation failed. Aborting.\n");
            return;
        }

        // Set random value within specified range
        newNode->value = rand() % maxValue;

        // Update node count and memory usage
        nodesCreated++;
        memoryUsage += sizeof(Node);

        // Update doubly linked list head and tail
        if (!head) {
            head = newNode;
            tail = newNode;
        } else {
            tail->successor = newNode;
            newNode->predecessor = tail;
            tail = newNode;
        }
    }

    printf("System initialized with %d nodes.\n", maxNodes);
}

// Function to update node value based on index and key
void updateNodeValue(int index, int key, Node* head) {
    // Find the node by its index and key
    Node* current = head;
    while (current && current->value != key) {
        if (index == 0) break; // Reached end of list
        current = current->successor;
        index--;
    }

    if (!current) {
        printf("Node not found.\n");
        return;
    }

    // Update node value
    current->value = rand() % 100;

    printf("Updated node value: %d\n", current->value);
}

// Helper function to find and print the largest integer in an array
int largestIntegerInArray(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Example usage
int main() {
    srand(time(NULL)); // Initialize random number generator

    int maxNodes = 1000;
    int maxValue = 100;

    initializeSystem(maxNodes, maxValue);

    int size = 10;
    int* arr = (int*) malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 50;
    }

    printf("Largest integer in array: %d\n", largestIntegerInArray(arr, size));

    updateNodeValue(5, 30, head); // Update node value based on index and key

    free(arr);
    return 0;
}

