#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    int id;
    long timestamp;
    double value;
    double weight;
} Transaction;

typedef struct Window {
    int start;
    int end;
    double sum;
    int count;
} Window;

Transaction* process_transactions(Transaction* transactions, int num_transactions) {
    // Initialize the sliding window
    Window* window = (Window*)malloc(sizeof(Window));
    window->start = 0;
    window->end = 0;
    window->sum = 0.0;
    window->count = 0;

    // Process transactions
    Transaction* processed_transactions = (Transaction*)malloc((num_transactions + 1) * sizeof(Transaction));
    int i = 0, j = 0;
    for (; i < num_transactions; i++) {
        Transaction transaction = transactions[i];
        if (transaction.timestamp > window->end) {
            // New window
            window->start = transaction.timestamp;
            window->end = window->start + 5000; // Assume 5 seconds
            window->sum = transaction.value * transaction.weight;
            window->count = 1;
        } else if (transaction.timestamp <= window->end) {
            // Same window
            window->sum += transaction.value * transaction.weight;
            window->count++;
            if (window->timestamp == window->end) {
                // Window ended, find the maximum weighted sum and return the associated ID
                double max_sum = window->sum;
                int max_id = transactions[j].id;
                for (; j < num_transactions; j++) {
                    Transaction next_transaction = transactions[j];
                    if (next_transaction.timestamp <= window->end && 
                        next_transaction.value * next_transaction.weight > max_sum) {
                        max_sum = next_transaction.value * next_transaction.weight;
                        max_id = next_transaction.id;
                    }
                }
                return &processed_transactions[max_id];
            }
        } else {
            // New transaction outside the current window, process it separately
            processed_transactions[j] = transaction;
            j++;
        }
    }
    return NULL;
}

int main() {
    // Example usage:
    Transaction transactions[] = {{1, 1643723400, 10.0, 2.0}, {2, 1643723401, 5.0, 3.0},
                                   {3, 1643723402, 15.0, 4.0}, {4, 1643723405, 20.0, 5.0}};
    int num_transactions = sizeof(transactions) / sizeof(transactions[0]);
    Transaction* processed_transactions = process_transactions(transactions, num_transactions);
    // Processed transactions list...
    return 0;
}

