using System;
using System.Net;
using System.Threading;

public class DynamicValueGenerator
{
    private readonly Random _random = new();
    private double _minValue;
    private double _maxValue;
    private IExternalService _externalService;
    private int _getRandomCalls = 0;
    private int _getCurrentRangeCalls = 0;

    public DynamicValueGenerator(IExternalService externalService)
    {
        _externalService = externalService;
        UpdateRange();
    }

    public double GetRandomFloat(bool inclusiveUpperBound)
    {
        _getRandomCalls++;
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt(bool inclusiveUpperBound)
    {
        _getRandomCalls++;
        return (int)(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public double GetRandomDouble(bool inclusiveUpperBound)
    {
        _getRandomCalls++;
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public string GetCurrentRange()
    {
        _getCurrentRangeCalls++;
        if (_externalService.IsConnected())
        {
            UpdateRange();
            return $"Current range: [{_minValue}, {_maxValue})";
        }
        else
        {
            return "External service not connected. Current range unknown.";
        }
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator - Range: [{_minValue}, {_maxValue}), GetRandom calls: {_getRandomCalls}, GetCurrentRange calls: {_getCurrentRangeCalls}";
    }

    private void UpdateRange()
    {
        try
        {
            var range = _externalService.GetLatestRange();
            if (range != null)
            {
                _minValue = range.Min;
                _maxValue = range.Max;
            }
            else
            {
                throw new Exception("Failed to retrieve the latest range from the external service.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error updating range: {ex.Message}");
        }
    }
}

public interface IExternalService
{
    bool IsConnected();
    Range GetLatestRange();
}

public class Range
{
    public double Min { get; set; }
    public double Max { get; set; }
}
