#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

const char* generate_new_filename(const char* original_filename) {
    size_t original_len = strlen(original_filename);
    size_t new_len = 0;
    const char* p = original_filename;

    // Calculate the length of the new filename
    while (*p != '\0') {
        if (*p == '.') {
            ++new_len;
            break;
        }
        ++p;
        ++new_len;
    }

    // Calculate the sequence number
    char buffer[16];
    sprintf(buffer, "%03zu", original_len);

    // Create a new filename with timestamp and file type
    size_t len = strlen(buffer) + 15; // YYYYMMDDHHMMSS length is 14, plus one for the dot separator
    if (p != original_filename && *p != '\0') {
        ++len;
    }

    char* new_filename = malloc(len + 1);
    if (!new_filename) {
        return NULL;
    }

    // Copy the sequence number and timestamp to the new filename
    sprintf(new_filename, "%s.%s", buffer, p ? strrchr(p, '.') : "txt");

    return new_filename;
}
