                    sizeof(MeasurementReport_t) * (lte_ue_radio_state->measurement_report_count + 1));
            if (!new_array) {
                printf("Error: Out of memory\n");
                exit(-1);
            }
            lte_ue_radio_state->measurement_reports = new_array;
        }
        lte_ue_radio_state->measurement_reports[lte_ue_radio_state->measurement_report_count++] = measurement_report;
        pthread_mutex_unlock(&lock);
    } else {
        printf("Error: UE not found\n");
    }
}

void free_lte_ue_radio_states() {
    for (int i = 0; i < lte_ue_radio_state_count; i++) {
        free(lte_ue_radio_states[i]);
    }
