    private float _minValue;
    private float _maxValue;

    public GraphValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value");
        }

        _minValue = minValue;
        _maxValue = maxValue;
