        printf("Invalid number of records. Supported range: 5,000 to 15,000.\n");
        return NULL;
    }

    size_t total_size = sizeof(Record) * num_records;

    Record* dataset = (Record*)malloc(total_size);
    if (!dataset) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        dataset[i].key = i + 1;
        dataset[i].value = rand() % 21000 - 10000; // random value in range [-10,000, 10,000]
        sprintf(dataset[i].buffer, "Record %zu", i);
    }

    return dataset;
}

