// Function to initialize and fill records array
Record** initRecords(int numRecords, int* maxKey, long* maxLength, size_t limit) {
    // Initialize arrays for 'long' offset values and 'int' keys
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Initialize array of record structures
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));

        // Set random value for each record's int field
        records[i]->value = rand() % 100;

        // Assign a key and offset to each record
        keys[i] = i;
        offsets[i] = (long)i * 10;

        // Check if memory usage exceeds the limit
        size_t totalSize = sizeof(long) + sizeof(int) + sizeof(Record);
        if ((totalSize * numRecords) > limit) {
            printf("Memory allocation failed. Limit exceeded.\n");
            return NULL;
        }
    }

    // Handle potential memory allocation failures gracefully
    if (offsets == NULL || keys == NULL || records == NULL) {
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Update the value of specific records based on their index and key
    for (int i = 0; i < numRecords; i++) {
        if (keys[i] == *maxKey && offsets[i] == *maxLength) {
            printf("Updating record at index %d with key %d.\n", i, keys[i]);
            records[i]->value = rand() % 100;
        }
    }

    // Return the initialized array of records
    return records;
}
