class DataChunk {
public:
    std::vector<double> values;
    long long timestamp = 0;

    DataChunk(size_t size) : values(size) {}
};

class DataChunkManager {
private:
    size_t memoryLimit = 1024 * 1024; // 1MB
    size_t chunkSize = 256; // adjust this value to optimize cache utilization and minimize fragmentation

    std::map<long long, std::unique_ptr<DataChunk>> chunks;
    std::unordered_map<size_t, DataChunk*> allocatedChunks;

    void updateTimestamp(DataChunk* chunk) {
        chunk->timestamp = static_cast<long long>(std::chrono::high_resolution_clock::now().time_since_epoch().count());
    }

public:
    DataChunkManager(size_t memoryLimit) : memoryLimit(memoryLimit) {}

    std::unique_ptr<DataChunk> createDataChunk(size_t size) {
        if (size > chunkSize) {
            // handle large data chunks or adjust the chunk size
        }
        auto chunk = std::make_unique<DataChunk>(size);
        allocatedChunks[size] = chunk.get();
        return chunk;
    }

    void updateValue(DataChunk* chunk, size_t index, double value) {
        if (chunk != nullptr) {
            chunk->values[index] = value;
            updateTimestamp(chunk);
        }
    }

    void deleteDataChunk(DataChunk* chunk) {
        if (chunk != nullptr) {
            chunks.erase(chunk->timestamp);
            allocatedChunks.erase(std::distance(allocatedChunks.begin(), allocatedChunks.end()) - 1);
            delete chunk;
        }
    }

    size_t getActiveChunkCount() const {
        return allocatedChunks.size();
    }

    long long getTotalMemoryUsage() const {
        size_t total = 0;
        for (const auto& pair : chunks) {
            total += pair.second->values.size() * sizeof(double);
        }
        return total + sizeof(DataChunk);
    }

    void writeDataChunksToFile(const std::string& filename) {
        FILE* file = fopen(filename.c_str(), "wb");
        if (file == nullptr) {
            // handle file operations errors
        } else {
            for (const auto& pair : chunks) {
                fwrite(&pair.second->values[0], sizeof(double), pair.second->values.size(), file);
                fwrite(&pair.first, sizeof(long long), 1, file);
            }
            fclose(file);
        }
    }

    void readDataChunksFromFile(const std::string& filename) {
        FILE* file = fopen(filename.c_str(), "rb");
        if (file == nullptr) {
            // handle file operations errors
        } else {
            std::vector<DataChunk*> newChunks;
            while (fread(&chunk.timestamp, sizeof(long long), 1, file)) {
                size_t size = fread(&chunk.values[0], sizeof(double), chunk.values.size(), file);
                if (size != chunk.values.size()) {
                    // handle corruption or incorrect data
                }
                newChunks.push_back(&chunk);
            }
            fclose(file);

            for (DataChunk* chunk : newChunks) {
                chunks[chunk->timestamp] = std::move(std::make_unique<DataChunk>(*chunk));
                allocatedChunks[chunk->values.size()] = chunk;
            }
        }
    }
};
