#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int age;
    int count;
    int priority;
} Packet;

Packet* processPackets(Packet** packets, int nPackets) {
    // Initialize variables
    time_t now = time(NULL);
    int packetCount = 0;
    double avgDelay = 0.0;
    int criticalPacketCount = 0;
    int recentPackets[50];

    for (int i = 0; i < 50; i++) {
        recentPackets[i] = -1; // Initialize to invalid packet
    }

    for (int i = 0; i < nPackets; i++) {
        Packet* p = packets[i];

        // Check packet age and priority
        if (p->age > 50) {
            continue; // Too old, discard
        }
        if (p->priority < 3) {
            criticalPacketCount++;
        }

        // Update metrics
        packetCount++;
        avgDelay += p->age;

        // Add to sliding window of recent packets
        for (int j = 49; j > 0; j--) {
            recentPackets[j] = recentPackets[j - 1];
        }
        recentPackets[0] = i; // Newest packet

        // Process critical packets first
        if (criticalPacketCount >= 5) {
            for (int j = 0; j < 50; j++) {
                int idx = recentPackets[j];
                if (idx != -1) {
                    processCriticalPacket(&packets[idx]);
                    criticalPacketCount--;
                    break;
                }
            }
        } else {
            // Process all packets
            for (int j = 0; j < nPackets; j++) {
                Packet* p = packets[j];
                if (p->priority > 2) {
                    processPacket(p);
                }
            }
        }
    }

    // Calculate average delay
    avgDelay /= packetCount;

    return packets;
}

void processCriticalPacket(Packet* p) {
    printf("Processing critical packet %d\n", p->age);
}

void processPacket(Packet* p) {
    printf("Processing packet %d\n", p->age);
}
