['Here is a C code example that dynamically manages memory for and initializes multiple record structures:

```c
#include <stdlib.h>
#include <stdio.h>

// Define the structure to hold 'int' value
typedef struct {
    int val;
} Record;

// Define the structure to hold 'long' offset, 'int' key, and 'Record'
typedef struct {
    long offset;
    int key;
    Record record;
} RecordStruct;

// Function to dynamically manage memory for multiple records
void* initRecords(int numRecords, size_t maxMemory, size_t* usedMemory) {
    // Calculate the total memory required per record
    size_t recordSize = sizeof(RecordStruct);

    // Check if total memory exceeds the limit
    if (numRecords * recordSize > maxMemory) {
        printf("Insufficient memory. Exiting.\n");
        return NULL;
    }

    void* records = malloc(numRecords * recordSize);
    if (!records) {
        printf("Failed to allocate memory. Exiting.\n");
        return NULL;
    }

    // Initialize each record
    for (int i = 0; i < numRecords; i++) {
        RecordStruct* rec = (RecordStruct*) (((char*) records) + i * recordSize);
        rec->offset = i;
        rec->key = i;
        rec->record.val = i;
    }

    *usedMemory = numRecords * recordSize;

    return records;
}

// Function to free the memory allocated by initRecords
void freeRecords(void* records, size_t usedMemory) {
    free(records);
}
