void* dynamic_record_data_structure_alloc(size_t capacity) {
    void* ptr = calloc(1, sizeof(DynamicRecordDataStructure));
    if (!ptr) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void dynamic_record_data_structure_free(void** data) {
    DynamicRecordDataStructure* d = (DynamicRecordDataStructure*)data[0];
    free(d->records);
    free(*data);
}

int dynamic_record_data_structure_resize(void** data, size_t capacity) {
    DynamicRecordDataStructure* d = (DynamicRecordDataStructure*)data[0];
    Record* new_records = realloc(d->records, capacity * sizeof(Record));
    if (!new_records) {
        printf("Memory reallocation failed\n");
        return -1;
    }
    d->records = new_records;
    d->capacity = capacity;
    return 0;
}

int main() {
    // Create a data structure
    void* data = dynamic_record_data_structure_alloc(10);

    // Add records
    pthread_mutex_lock(&((DynamicRecordDataStructure*)data)->mutex);
    ((DynamicRecordDataStructure*)data)->records[0].key = 1;
    ((DynamicRecordDataStructure*)data)->records[0].offset = 100;
    pthread_mutex_unlock(&((DynamicRecordDataStructure*)data)->mutex);

    // Resize the data structure
    dynamic_record_data_structure_resize(&data, 20);

    // Add more records
    pthread_mutex_lock(&((DynamicRecordDataStructure*)data)->mutex);
    ((DynamicRecordDataStructure*)data)->records[1].key = 2;
    ((DynamicRecordDataStructure*)data)->records[1].offset = 200;
    pthread_mutex_unlock(&((DynamicRecordDataStructure*)data)->mutex);

    // Free the data structure
    dynamic_record_data_structure_free(&data);

