    for (int i = 0; i < num_records; i++) {
        Record* current_record = create_record(rand() % (max_value - min_value + 1) + min_value);
        if (*records == NULL) {
            *records = current_record;
        } else {
            Record* temp = *records;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = current_record;
        }
    }
