typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
} DynamicRecordArray;

DynamicRecordArray*
dynamic_record_array_init(size_t initial_capacity) {
    DynamicRecordArray* arr = (DynamicRecordArray*)malloc(sizeof(DynamicRecordArray));
    if (!arr) {
        return NULL; // allocation failed
    }
    arr->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!arr->records) {
        free(arr);
        return NULL; // allocation failed
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    return arr;
}

void
dynamic_record_array_free(DynamicRecordArray* arr) {
    if (arr) {
        if (arr->records) {
            free(arr->records);
        }
        free(arr);
    }
}

int
dynamic_record_array_insert(DynamicRecordArray* arr, int key, long offset) {
    if (!arr || arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        Record* new_records = (Record*)malloc(new_capacity * sizeof(Record));
        if (!new_records) {
            return -1; // allocation failed
        }
        memcpy(new_records, arr->records, arr->size * sizeof(Record));
        free(arr->records);
        arr->records = new_records;
        arr->capacity = new_capacity;
    }
    Record* record = &arr->records[arr->size];
    record->key = key;
    record->offset = offset;
    arr->size++;
    return 0;
}

int
dynamic_record_array_lookup(DynamicRecordArray* arr, int key) {
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->records[i].key == key) {
            return arr->records[i].offset;
        }
    }
    return -1; // not found
}
