['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure for record
typedef struct {
    int value;
    long offset;
    int key;
} Record;

// Linked list node structure
typedef struct Node {
    Record* record;
    struct Node* next;
} Node;

// Dynamic record collection
typedef struct {
    Node* head; // Head of the linked list
    int size; // Number of records in the collection
    long max_memory_usage; // Maximum total memory usage threshold
    pthread_mutex_t mutex; // Mutex for thread safety
} RecordCollection;

// Function to add a new record to the collection
void record_collection_add(RecordCollection* collection, Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->record = record;
    node->next = collection->head;
    collection->head = node;
    collection->size++;
}

// Function to update a record value based on its key
void record_collection_update_by_key(RecordCollection* collection, int key, int new_value) {
    Node* current = collection->head;
    while (current != NULL) {
        if (current->record->key == key) {
            current->record->value = new_value;
            break;
        }
        current = current->next;
    }
}

// Function to update a record value based on its index
void record_collection_update_by_index(RecordCollection* collection, int index, int new_value) {
    Node* current = collection->head;
    int i = 0;
    while (current != NULL) {
        if (i == index) {
            current->record->value = new_value;
            break;
        }
        i++;
        current = current->next;
    }
}

// Function to delete a record from the collection
void record_collection_delete_by_key(RecordCollection* collection, int key) {
    Node* current = collection->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->record->key == key) {
            if (prev == NULL) {
                collection->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            collection->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
}

// Function to handle memory pressure and release older records
void record_collection_handle_memory_pressure(RecordCollection* collection) {
    if (collection->max_memory_usage > 0 && collection->size * sizeof(Record) + sizeof(Node) > collection->max_memory_usage) {
        Node* current = collection->head;
        Node* prev = NULL;
        while (current != NULL) {
            prev = current;
            current = current->next;
            free(prev);
        }
        collection->head = NULL;
        collection->size = 0;
    }
}

// Function to create a new record collection
RecordCollection* record_collection_create(long max_memory_usage) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    pthread_mutex_init(&collection->mutex, NULL);
    collection->head = NULL;
    collection->size = 0;
    collection->max_memory_usage = max_memory_usage;
    return collection;
}

// Function to destroy a record collection
void record_collection_destroy(RecordCollection* collection) {
    Node* current = collection->head;
    Node* prev = NULL;
    while (current != NULL) {
        prev = current;
        current = current->next;
        free(prev);
    }
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
