function dynamicCompression($data, $compressionLevel = 5) {
    $algorithms = array('LZ77', 'LZ78', 'LZW');
    $bestAlgorithm = null;
    $bestPerformance = array();

    foreach ($algorithms as $algorithm) {
        $performance = compressData($data, $algorithm, $compressionLevel);

        if (empty($bestPerformance)) {
            $bestPerformance = $performance;
            $bestAlgorithm = $algorithm;
        } elseif ($performance['compressionRatio'] > $bestPerformance['compressionRatio']) {
            $bestPerformance = $performance;
            $bestAlgorithm = $algorithm;
