typedef struct {
    long offset;
    int key;
    Record* record;
} RecordEntry;

void initRecordManager(int maxRecords, int maxMemory, void** metadata) {
    // Initialize the metadata
    *metadata = (void*)malloc(sizeof(long));
    *(long*)*metadata = 0;

    for (int i = 0; i < maxRecords; i++) {
        RecordEntry* entry = (RecordEntry*)malloc(sizeof(RecordEntry));
        entry->offset = i;
        entry->key = i % 100 + 1;
        entry->record = &((Record){i});
        // Add the entry to the metadata
        ((long*)*metadata) += sizeof(RecordEntry);
    }
}

void updateRecordManager(long offset, int key, Record value) {
    // Find the record and update its value
    for (int i = 0; i < offset; i++) {
        RecordEntry* entry = (RecordEntry*)malloc(sizeof(RecordEntry));
        if (entry->key == key) {
            entry->record->value = value;
            break;
        }
    }
}

void deleteRecordManager(int index, int key) {
    // Find the record and free its memory
    for (int i = 0; i < index; i++) {
        RecordEntry* entry = (RecordEntry*)malloc(sizeof(RecordEntry));
        if (entry->key == key) {
            free(entry);
            break;
        }
    }
}

void printRecords(void** metadata) {
    // Print the records
    long offset = *(long*)metadata;
    for (int i = 0; i < offset; i++) {
        RecordEntry* entry = (RecordEntry*)malloc(sizeof(RecordEntry));
        printf("%d: key %d, value %d\n", i, entry->key, entry->record->value);
    }
}

int main() {
    void* metadata;
    initRecordManager(1000, 1024*1024, &metadata);

    updateRecordManager(5, 50, (Record){123});
    printRecords(&metadata);

    deleteRecordManager(10, 55);

    return 0;
}
