    for (int i = 0; i < *count; i++) {
        point* p = malloc(sizeof(point));
        p->x = ((double)(rand_r(&seed))) / RAND_MAX * (range_max - range_min) + range_min;
        p->y = ((double)(rand_r(&seed))) / RAND_MAX * (range_max - range_min) + range_min;
        (*analysis_array)[i].coord = p;
    }
}

float euclidean_distance(point* start, point* end) {
