// Structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to update an existing resource
void updateCRCResource(NFAPI_CRC_INDATION_PDU_T* pCrcIndPdu, int request_body_crcflag) {
    semaphore_acquire(&update_semaphore);
    // Update the CRCFLAG in the resource
    pCrcIndPdu->crc_indication.crc_flag = request_body_crcflag;
    semaphore_release(&update_semaphore);
}

// Function to delete a resource
NFAPI_CRC_INDICATION_PDU_T* deleteCRCResource(NFAPI_CRC_INDICATION_PDU_T* pCrcIndPdu) {
    NFAPI_CRC_INDICATION_PDU_T* new_resource = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    semaphore_acquire(&delete_semaphore);
    // Clean up dependent resources
    free(pCrcIndPdu->rx_ue_info.ue_info);
    pCrcIndPdu->rx_ue_info.ue_info = NULL;

    // Free the original resource
    free(pCrcIndPdu);
    pCrcIndPdu = new_resource;
    semaphore_release(&delete_semaphore);

    return pCrcIndPdu;
}

// Initialize semaphores
void initSemaphores() {
    update_semaphore = semaphore_create(1, 0);
    delete_semaphore = semaphore_create(1, 0);
}

// Clean up semaphores
void cleanUpSemaphores() {
    semaphore_destroy(update_semaphore);
    semaphore_destroy(delete_semaphore);
}
