// Define the custom 'data' structure containing both int and float fields
typedef struct {
    int i;
    float f;
    pthread_mutex_t lock; // Mutex for concurrent access management
    int ref_count; // Reference count for shared ownership management
} Data;

// Initialize a new data structure with default values
Data* newData(int i, float f) {
    Data* d = (Data*)malloc(sizeof(Data));
    if (!d) return NULL;

    d->i = i;
    d->f = f;
    pthread_mutex_init(&d->lock, NULL); // Initialize the mutex for concurrent access
    d->ref_count = 1; // Set initial reference count to 1

    return d;
}

// Deallocation function: decrement the reference count and free memory when necessary
void deallocate(Data* data) {
    pthread_mutex_lock(&data->lock);

    if (--data->ref_count == 0) {
        free(data); // Free memory when the last reference is released
    }

    pthread_mutex_unlock(&data->lock);
}

// Example implementation of a complex data source (e.g., reading from a file or network)
float get_float_value() {
    // Simulate delayed or inconsistent data access
    sleep(1); // Delay for 1 second
    return (float)rand() / RAND_MAX;
}

int main() {
    Data* d = newData(42, 3.14f);

    // Example usage: create multiple structures and manage shared ownership
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        threads[i] = pthread_self();

        // Simulate concurrent access and updates
        pthread_mutex_lock(&d->lock);
        d->i += 1;
        d->f += get_float_value();
        pthread_mutex_unlock(&d->lock);
    }

    deallocate(d); // Release the data structure when done

    return 0;
}
