```c
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    double value;
    int ref_count;
} DoubleStruct;

typedef struct {
    char* str;
    int ref_count;
} CharStruct;

typedef struct {
    int i;
    float f;
    int ref_count;
} DataStruct;

typedef struct Node {
    void* data;
    int ref_count;
    struct Node* next;
} Node;

void* alloc_double(double value) {
    DoubleStruct* ds = (DoubleStruct*)malloc(sizeof(DoubleStruct));
    if (!ds) return NULL;
    ds->value = value;
    ds->ref_count = 1;
    return ds;
}

void free_double(void* ptr) {
    DoubleStruct* ds = (DoubleStruct*)ptr;
    if (--ds->ref_count > 0) return;
    free(ptr);
}

void* alloc_char(char* str) {
    CharStruct* cs = (CharStruct*)malloc(sizeof(CharStruct));
    if (!cs) return NULL;
    cs->str = str;
    cs->ref_count = 1;
    return cs;
}

void free_char(void* ptr) {
    CharStruct* cs = (CharStruct*)ptr;
    if (--cs->ref_count > 0) return;
    free(ptr);
}

void* alloc_data(int i, float f) {
    DataStruct* ds = (DataStruct*)malloc(sizeof(DataStruct));
    if (!ds) return NULL;
    ds->i = i;
    ds->f = f;
    ds->ref_count = 1;
    return ds;
}

void free_data(void* ptr) {
    DataStruct* ds = (DataStruct*)ptr;
    if (--ds->ref_count > 0) return;
    free(ptr);
}

void* alloc_node(Node** head, void* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node || !data) return NULL;
    node->data = data;
    node->ref_count = 1;
    node->next = *head;
    *head = node;
    return node;
}

void free_node(void* ptr) {
    Node* node = (Node*)ptr;
    if (--node->ref_count > 0) return;
    Node* temp = node;
    while (temp && temp->next) {
        temp = temp->next;
        free(temp);
    }
    free(ptr);
}

void report_alloc_dealloc_stats(int allocs, int deallocs) {
    printf("Allocations: %d, Deallocation: %d\n", allocs, deallocs);
}

int main() {
    // Example usage:
    DoubleStruct* ds = (DoubleStruct*)alloc_double(3.14);
    CharStruct* cs = (CharStruct*)alloc_char("Hello");
    DataStruct* data = (DataStruct*)alloc_data(1, 2.71);
    Node* head = NULL;
    alloc_node(&head, ds);
    alloc_node(&head, cs);
    alloc_node(&head, data);

    free_double(ds);
    free_char(cs);
    free_data(data);
    free_node(head);

    report_alloc_dealloc_stats(4, 4);

    return 0;
}

