    dw->data = data;
    dw->metadata = metadata;
    pthread_mutex_init(&dw->lock, NULL);
    dw->ref_count = 1;
    return dw;
}

// Function to increment the reference count
void increment_ref_count(DataWrapper* dw) {
    dw->ref_count++;
}

// Function to decrement the reference count and free the DataWrapper if necessary
void decrement_ref_count(DataWrapper* dw) {
    dw->ref_count--;
    if (dw->ref_count == 0) {
        pthread_mutex_destroy(&dw->lock);
        free(dw);
    }
}

// Function to update metadata
void update_metadata(DataWrapper* dw, Metadata new_metadata) {
    pthread_mutex_lock(&dw->lock);
    dw->metadata = new_metadata;
    pthread_mutex_unlock(&dw->lock);
}

