// Initialize memory for arrays and linked list
int main() {
    srand(time(NULL)); // seed random number generator

    // Initialize timestamp array
    long* timestamp_array = (long*)malloc(TIMESTAMP_ARRAY_SIZE * sizeof(long));
    if (!timestamp_array) {
        fprintf(stderr, "Error: failed to allocate memory for timestamp array\n");
        return 1;
    }

    // Initialize sensor readings array
    float* sensor_readings_array = (float*)malloc(SENSOR_READINGS_ARRAY_SIZE * sizeof(float));
    if (!sensor_readings_array) {
        free(timestamp_array);
        fprintf(stderr, "Error: failed to allocate memory for sensor readings array\n");
        return 1;
    }

    // Initialize linked list
    device* head = NULL;

    // Populate linked list with at least five device nodes
    add_device(&head, 'A');
    add_device(&head, 'B');
    add_device(&head, 'C');
    add_device(&head, 'D');
    add_device(&head, 'E');

    return 0;
}

// Function to create a new device node with unique serial number
device* create_device(char serial_number) {
    device* new_node = (device*)malloc(sizeof(device));
    if (!new_node) {
        // handle memory allocation failure
    }
    new_node->serial_number = serial_number;
    new_node->next = NULL;
    return new_node;
}

// Function to add a device node to the linked list
void add_device(device** head, char serial_number) {
    device* new_node = create_device(serial_number);
    if (!new_node) {
        // handle memory allocation failure
    }
    if (*head == NULL) {
        *head = new_node;
    } else {
        device* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to remove a device node from the linked list
void remove_device(device** head, char serial_number) {
    if (*head == NULL) {
        // handle empty list
    }
    if ((*head)->serial_number == serial_number) {
        device* temp = *head;
        *head = (*head)->next;
        free(temp);
    } else {
        device* current = *head;
        while (current->next != NULL && current->next->serial_number != serial_number) {
            current = current->next;
        }
        if (current->next != NULL) {
            device* temp = current->next;
            current->next = current->next->next;
            free(temp);
        }
    }
}
