enum class AttackStrategy {
    STRATEGY_1,
    STRATEGY_2
};

struct record {
    int attackNumber;
};

record* generateAttackOptions(int attackOptionRange, int numOptions) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, attackOptionRange);

    record* options = new record[numOptions];
    for (int i = 0; i < numOptions; ++i) {
        options[i].attackNumber = dis(gen);
    }
    return options;
}

void executeRandomAttack() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    record* strategyOptions[2];
    for (int i = 0; i < 2; ++i) {
        strategyOptions[i] = generateAttackOptions(100, 3);
    }

    int lastAttackTime = std::chrono::steady_clock::now().time_since_epoch().count();
    while (true) {
        if (std::chrono::steady_clock::now().time_since_epoch().count() - lastAttackTime > 9000000) {
            int selectedStrategy = gen() % 2;
            record* attackOptions = strategyOptions[selectedStrategy];
            std::cout << "Selected Attack: " << attackOptions[gen() % 3].attackNumber << std::endl;
            lastAttackTime = std::chrono::steady_clock::now().time_since_epoch().count();
        }
        else {
            // Cooldown not expired yet
            // Do nothing and sleep for a short period to reduce CPU usage
            if (dis(gen) > 0.9) {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        }
    }
}

int main() {
    executeRandomAttack();
    return 0;
}
