// Define structure for transaction record
typedef struct {
    int id;
    time_t timestamp;
    char account[20];
    double amount;
    int status; // 0: debit, 1: credit
    int payment_method; // 0: credit card, 1: bank transfer, 2: digital wallet
} transaction_record;

// Define structure for memory allocation offsets
typedef struct {
    long offset;
    int key;
} allocation_offset;

// Function to initialize and manage transactions
transaction_record* init_transactions(int num_records) {
    transaction_record* records = (transaction_record*) malloc(num_records * sizeof(transaction_record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].id = i + 1;
        records[i].timestamp = time(NULL);
        strcpy(records[i].account, "Account X");
        records[i].amount = rand() / (double) RAND_MAX * 100.0;
        if (rand() % 2) {
            records[i].status = 0; // debit
        } else {
            records[i].status = 1; // credit
        }
        records[i].payment_method = rand() % 3;

        allocation_offset* offset_array = (allocation_offset*) malloc(num_records * sizeof(allocation_offset));
        if (!offset_array) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        for (int j = 0; j < num_records; j++) {
            offset_array[j].offset = i + 1;
            offset_array[j].key = j;
        }

        // Serialize transactions and store in binary format
        FILE* file = fopen("transactions.bin", "wb");
        if (!file) {
            printf("File open failed.\n");
            return NULL;
        }
        fwrite(records, sizeof(transaction_record), num_records, file);
        fclose(file);

        // Clean up unused transactions
        for (int j = 0; j < i; j++) {
            free(&records[j]);
        }

        return records;
    }

    return NULL;
}

// Function to deserialize and process transactions
void process_transactions(transaction_record* records) {
    FILE* file = fopen("transactions.bin", "rb");
    if (!file) {
        printf("File open failed.\n");
        return;
    }
    fread(records, sizeof(transaction_record), 1000, file);
    fclose(file);

    // Verify integrity of serialized data
    for (int i = 0; i < 1000; i++) {
        printf("%d: %s - %.2f\n", records[i].id, records[i].account, records[i].amount);
    }
}
