            var resourceData = await LoadAndDeserialize(resourceId);

            if (resourceData == null) return NotFound();

            // Validate incoming request body against schema specific to the category of the resource
            if (!ValidateRequest(request, resourceId)) return BadRequest();

            // Update the resource with optimistic locking
            if (!UpdateResourceWithLocking(resourceId, request))
                return Conflict("Concurrent update detected");

