using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace UserProfilesAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ProfilesController : ControllerBase
    {
        private readonly ProfileDbContext _dbContext;
        private readonly IPaginationService _paginationService;

        public ProfilesController(ProfileDbContext dbContext, IPaginationService paginationService)
        {
            _dbContext = dbContext;
            _paginationService = paginationService;
        }

        // Update user profile
        [HttpPut]
        public async Task<IActionResult> UpdateProfile([FromRoute]Guid userProfileId, [FromBody]UserProfileUpdate payload)
        {
            var profile = await _dbContext.Profiles.FindAsync(userProfileId);
            if (profile == null) return NotFound();
            profile.Update(payload);
            await _dbContext.SaveChangesAsync();
            return Ok();
        }

        // Delete user profile
        [HttpDelete]
        public async Task<IActionResult> DeleteProfile([FromRoute]Guid userProfileId)
        {
            var profile = await _dbContext.Profiles.FindAsync(userProfileId);
            if (profile == null) return NotFound();
            _dbContext.Profiles.Remove(profile);
            await _dbContext.SaveChangesAsync();
            return Ok();
        }

        // Retrieve paginated and sorted list of active users
        [HttpGet]
        public async Task<IActionResult> GetUsers([FromQuery]UserFilter filter, [FromQuery]int pageIndex = 1, int pageSize = 10)
        {
            var users = _dbContext.Profiles
                .Where(filter.GetCondition())
                .OrderBy(filter.OrderBy)
                .Skip((pageIndex - 1) * pageSize)
                .Take(pageSize)
                .ToList();
            var paginatedUsers = _paginationService.Paginate(users, pageIndex, pageSize);
            return Ok(paginatedUsers);
        }
    }

    public class UserProfileUpdate
    {
        public string Name { get; set; }
        public int Age { get; set; }
        // ...
    }

    public class UserFilter
    {
        public DateTime? MinActivityDate { get; set; }
        public DateTime? MaxActivityDate { get; set; }
        public int? MinAge { get; set; }
        public string SortBy { get; set; }

        public Func<UserProfile, bool> GetCondition()
        {
            // implement filter logic based on query parameters
        }
    }

    public class IPaginationService
    {
        public PaginatedList<T> Paginate<T>(IQueryable<T> data, int pageIndex, int pageSize)
        {
            var paginatedData = new PaginatedList<T>();
            paginatedData.Source = data;
            paginatedData.PageSize = pageSize;
            paginatedData.PageIndex = pageIndex;

            // implement pagination logic based on the provided data
            return paginatedData;
        }
    }

    public class PaginatedList<T>
    {
        public IQueryable<T> Source { get; set; }
        public int PageSize { get; set; }
        public int PageIndex { get; set; }

        public int TotalCount => Source.Count();
        public int TotalPages => (int)Math.Ceiling((double)TotalCount / PageSize);
    }
}
