using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public async Task<UpdatePageResponse> UpdatePageAsync(string sessionToken, int pageId, string jsonData)
{
    if (string.IsNullOrEmpty(sessionToken))
        throw new ArgumentException("Session token is required");

    var json = JsonConvert.DeserializeObject<UpdatePageRequest>(jsonData);
    if (json == null || json.Elements == null || json.Elements.Count == 0)
        return new UpdatePageResponse { RefreshRequired = false };

    using (var client = new HttpClient())
    {
        client.DefaultRequestHeaders.Add("Session-Token", sessionToken);

        foreach (var element in json.Elements)
        {
            try
            {
                var response = await client.PostAsync($"pages/{pageId}/elements/{element.Id}", new StringContent(element.NewContent, Encoding.UTF8, "text"));
                if (!response.IsSuccessStatusCode)
                    throw new Exception("Failed to update element");
            }
            catch (HttpRequestException e) when (e.StatusCode == System.Net.HttpStatusCode.Conflict)
            {
                var conflictResponse = await client.GetAsync($"pages/{pageId}/elements/{element.Id}");
                if (conflictResponse.IsSuccessStatusCode)
                {
                    var conflictJson = await conflictResponse.Content.ReadAsStringAsync();
                    var conflictElement = JsonConvert.DeserializeObject<UpdatePageRequest>(conflictJson);
                    element.NewContent = ResolveConflict(element, conflictElement);
                }
                else
                    throw;
            }
        }
    }

    return new UpdatePageResponse { RefreshRequired = true };
}

public class UpdatePageRequest
{
    public List<UpdatePageElement> Elements { get; set; }
}

public class UpdatePageElement
{
    public int Id { get; set; }
    public string NewContent { get; set; }
}

public class UpdatePageResponse
{
    public bool RefreshRequired { get; set; }
}
