        new_node->key = data[rand() % sizeof(data) / sizeof(int)];
        new_node->record = rand() % RAND_RANGE;
        if(head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            new_node->prev = tail;
            new_node->next = NULL;
            tail->next = new_node;
            tail = new_node;
        }
        node_count++;
    }
    return NULL;
}

