void init_record(Record* r) {
    r->value = rand() % TIMERANGE;
    r->timestamp = (double)srand() / RAND_MAX;
}

void* allocate_records(int capacity) {
    if (capacity > MAX_RECORDS) {
        printf("Capacity limit exceeded.\n");
        return NULL;
    }

    records = (Record*)malloc(capacity * sizeof(Record));
    for (int i = 0; i < capacity; i++) {
        init_record(&records[i]);
    }
    record_count = capacity;
    max_key = -1;

