#include <pthread.h>

typedef struct {
    int value;
    long timestamp;
} record;

void* allocArrays(size_t limit) {
    long** offsets = (long**)malloc(sizeof(long*) * 3);
    int** keys = (int**)malloc(sizeof(int*) * 3);
    record** records = (record**)malloc(sizeof(record*) * (limit / sizeof(record)));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < 3; i++) {
        offsets[i] = (long*)malloc(sizeof(long));
        keys[i] = (int*)malloc(sizeof(int));

        if (!offsets[i] || !keys[i]) {
            free(offsets);
            free(keys);
            free(records);

            for (size_t j = i + 1; j < 3; j++) {
                free(offsets[j]);
                free(keys[j]);
            }

            return NULL;
        }
    }

    return records;
}

