    thread->data = data;
    return thread;
}

// Initialize serialization mechanism
serialize_t* init_serialize(char* format, FILE* file) {
    serialize_t* serialize = (serialize_t*)malloc(sizeof(serialize_t));
    serialize->format = format;
    serialize->file = file;
    pthread_mutex_init(&serialize->mutex, NULL);
    return serialize;
}

