    version_control_t* control = (version_control_t*)malloc(sizeof(version_control_t));
    control->version = version;
    control->history = history;
    pthread_mutex_init(&control->mutex, NULL);
    return control;
}

// Insert key-value pair into hash table
void insert_hash_table(hash_table_t* table, char* key, int value) {
    pthread_mutex_lock(&table->mutex);
    int index = hash(key, table->size);
    if (!table->entries[index]) {
        table->entries[index] = (config_entry_t*)malloc(sizeof(config_entry_t));
        table->entries[index]->key = strdup(key);
        table->entries[index]->value = value;
    } else {
        config_entry_t* entry = table->entries[index];
        free(entry->key);
        entry->key = strdup(key);
        entry->value = value;
    }
    pthread_mutex_unlock(&table->mutex);
}

