#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    char* buffer;
    int value;
    int keyIndex;
} record;

record** allocateMemory(int offsetSize, int keySize) {
    if(offsetSize <= 0 || keySize <= 0) return NULL;

    record** records = (record**)malloc(offsetSize * sizeof(record*));
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(keySize * sizeof(int));

    // Initialize offsets and keys
    for(int i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % 100;
    }
    for(int i = 0; i < keySize; i++) {
        keys[i] = rand() % 100;
    }

    // Ensure all records have a unique key
    int numRecords = offsetSize > keySize ? keySize : offsetSize;
    for(int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->buffer = (char*)malloc(64 * sizeof(char));
        records[i]->value = rand() % 100;
        records[i]->keyIndex = keys[i % keySize];
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    for(int i = 0; i < numRecords; i++) {
        free(records[i]->buffer);
        free(records[i]);
    }
    free(records);

    return records;
}

void deallocateMemory(record** records, int offsetSize) {
    if(!records) return;

    for(int i = 0; i < offsetSize; i++) {
        free(((record*)records[i])->buffer);
        free((records[i]));
    }
    free(records);
}
