    // Allocate memory for double accuracy values array
    double* double_array = (double*)malloc(sizeof(double));
    if (!double_array) {
        printf("Error: Double array allocation failed.\n");
        free(float_array);
        return NULL;
    }

    // Initialize double_array with some values
