}

// Function to dynamically resize the data_point vector using custom allocator
void* resize_data_points(allocator* allocator, void* old_vector, size_t new_capacity) {
    // Get the size of the current vector
    size_t old_size = sizeof(data_point);
    if (!old_vector) {
        old_size = 0;
    }

    // Calculate the total memory needed for the new vector
    size_t total_memory_needed = old_size * new_capacity;

    // Allocate memory for the new vector using custom allocator
    void* new_vector = (*allocator->malloc)(total_memory_needed);
    if (!new_vector) {
        printf("Error: Data point vector allocation failed.\n");
        return NULL;
    }

    // Copy the contents of the old vector to the new vector
    memcpy(new_vector, old_vector, old_size * (new_capacity > old_size ? new_capacity : old_size));

    // Free the memory allocated for the old vector
    (*allocator->free)(old_vector);

    return new_vector;
}

// Function to export the populated data_point vector to a file in a specified format
void export_data_points(void* data_points, FILE* file) {
    // Write the contents of the data point vector to the file
    fwrite(data_points, sizeof(data_point), 10, file);
}

int main() {
    // Initialize arrays using custom allocator
    data_point* data_points = initialize_arrays(&custom_allocator);

    // Dynamically resize the data point vector if needed
    size_t new_capacity = 20;
    void* resized_vector = resize_data_points(&custom_allocator, data_points, new_capacity);
    free(data_points);

    // Export the populated data point vector to a file in specified format
    FILE* file = fopen("data_points.txt", "wb");
    if (file) {
        export_data_points(resized_vector, file);
        fclose(file);
    }

    return 0;
}

