["```javascript
const fs = require('fs');
const path = require('path');
const os = require('os');

class DirectoryReader {
  constructor(config) {
    this.config = config;
    this.cache = {};
    this.lastCacheRefresh = Date.now();
  }

  async readDirectory(dirPath, callback) {
    const dirEntries = await fs.promises.readdir(dirPath);
    for (const file of dirEntries) {
      const filePath = path.join(dirPath, file);
      try {
        if (await fs.promises.lstat(filePath).isSymbolicLink()) {
          continue;
        }
        const stat = await fs.promises.stat(filePath);
        if (this.config.filter && !this.config.filter.test(path.extname(filePath))) {
          continue;
        }
        if (!this.cache[filePath]) {
          this.cache[filePath] = {
            size: stat.size,
            modifiedTime: stat.mtimeMs
          };
          await this.updateCache(filePath, stat);
        }
      } catch (err) {
        console.error(err);
        continue;
      }
    }
  }

  updateCache(file, stat) {
    const cacheEntry = {
      size: stat.size,
      modifiedTime: stat.mtimeMs
    };
    return this.cache[file] = cacheEntry;
  }

  async getCacheHit(file) {
    if (!this.cache[file]) {
      return null;
    }
    return this.cache[file];
  }

  async refreshCache() {
    for (const file of Object.keys(this.cache)) {
      try {
        const stat = await fs.promises.stat(file);
        this.cache[file] = {
          size: stat.size,
          modifiedTime: stat.mtimeMs
        };
      } catch (err) {
        delete this.cache[file];
      }
    }
  }

  async readDirectorySync(dirPath) {
    const dirEntries = fs.readdirSync(dirPath);
    for (const file of dirEntries) {
      const filePath = path.join(dirPath, file);
      try {
        if (fs.lstatSync(filePath).isSymbolicLink()) {
          continue;
        }
        const stat = fs.statSync(filePath);
        if (this.config.filter && !this.config.filter.test(path.extname(filePath))) {
          continue;
        }
        if (!this.cache[filePath]) {
          this.cache[filePath] = {
            size: stat.size,
            modifiedTime: stat.mtimeMs
          };
          this.updateCache(filePath, stat);
        }
      } catch (err) {
        console.error(err);
        continue;
      }
    }
  }

  getCacheExpirationTime() {
    return this.lastCacheRefresh + (24 * 60 * 60 * 1000); // 24 hours
  }

  async cacheIsValid() {
    const now = Date.now();
    if (now > this.getCacheExpirationTime()) {
      await this.refreshCache();
      this.lastCacheRefresh = now;
      return true;
    }
    return false;
  }
}

module.exports = DirectoryReader;"]

