function processFiles({
  dirs = [],
  extensions = ['txt', 'json', 'xml'],
  concurrencyLimit = 100,
  cachingDuration = 24 * 60 * 60 * 1000,
  asyncMode = true
}) {
  const cache = new Map();
  const fs = require('fs').promises;
  const path = require('path');
  let errorCount = 0;

  function processDirectory(dir) {
    return fs.readdir(dir)
      .then(files => Promise.all(
        files.map(file => {
          const filePath = path.join(dir, file);
          if (fs.statSync(filePath).isFile()) {
            const ext = path.extname(file).toLowerCase();
            if (extensions.includes(ext)) {
              return processFile(filePath);
            }
          }
        })
      ))
      .catch(err => {
        console.error(`Error processing directory ${dir}: ${err}`);
        errorCount++;
      });
  }

  function processFile(filePath) {
    const stat = fs.statSync(filePath);
    const fileSize = stat.size;
    const lastModified = stat.mtimeMs;

    if (asyncMode) {
      return fs.readFile(filePath)
        .then(content => ({
          name: path.basename(filePath),
          size: fileSize,
          lastModified,
          content
        }));
    } else {
      return { name: path.basename(filePath), size: fileSize, lastModified };
    }
  }

  function cacheFileMetadata({ name, size, lastModified }) {
    const cached = cache.get(name);
    if (!cached || cached.size !== size || cached.lastModified !== lastModified) {
      cache.set(name, { size, lastModified });
    }
  }

  async function processFilesAsync() {
    for (const dir of dirs) {
      await processDirectory(dir);

      while (cache.size >= concurrencyLimit) {
        await new Promise(resolve => setTimeout(() => resolve(), 100));
      }
    }

    return Array.from(cache.values());
  }

  if (asyncMode) {
    return processFilesAsync();
  } else {
    const files = [];
    for (const dir of dirs) {
      for (const file of (await processDirectory(dir))) {
        if (file) {
          cacheFileMetadata(file);
          files.push(file);
        }
      }
    }
    return files;
  }
}
