function runTests(label, f, envConfig, maxConcurrency) {
  const blueSlip = require('blueslip');
  let totalPassed = 0;
  let totalFailed = 0;
  let totalSkipped = 0;

  async function runTest(envName, testFunction) {
    try {
      // Reset blueslip
      blueSlip.reset();

      // Run the test in the given environment
      await testFunction(envName);

      // If the test passed, increment the total count
      if (!testFunction.envskaipped) {
        totalPassed++;
      } else if (testFunction.envsfailed) {
        totalFailed++;
      } else {
        totalSkipped++;
      }
    } catch (err) {
      console.error(`Test "${label}" failed in environment "${envName}": ${err}`);
      totalFailed++;
    } finally {
      // Always reset blueslip
      blueSlip.reset();
    }
  }

  const testQueue = [];
  let concurrentCount = 0;
  let concurrencyLimitReached = false;

  async function executeTests() {
    while (testQueue.length > 0 || concurrencyLimitReached) {
      if (concurrentCount >= maxConcurrency) {
        await new Promise((resolve) => setTimeout(() => resolve(), 100));
        concurrencyLimitReached = true;
      }

      let currentTest = testQueue.shift();
      concurrentCount++;

      try {
        await runTest(currentTest.envName, currentTest.testFunction);
      } catch (err) {
        console.error(`Error executing tests: ${err}`);
      } finally {
        concurrentCount--;
      }
    }
  }

  async function main() {
    // Add or remove environments dynamically
    envConfig.forEach((env) => {
      testQueue.push({ envName: env.name, testFunction: f.bind(null, env) });
    });

    // Run the tests concurrently
    executeTests();

    console.log(`Test results for "${label}":`);
    console.log(`Passed: ${totalPassed}`);
    console.log(`Failed: ${totalFailed}`);
    console.log(`Skipped: ${totalSkipped}`);
  }

  main();
}
