// Define a struct for the record storage system
typedef struct {
    int key;
    size_t offset;
    void* value;
} Record;

// Define the resource manager structure
typedef struct {
    pthread_mutex_t mutex; // Mutex for thread safety
    size_t total_alloc;     // Total allocated memory
    size_t max_allowed;     // Maximum allowed memory usage
    size_t current_usage;   // Current memory usage
} ResourceManager;

// Initialize the resource manager
void initResourceManager(ResourceManager* rm, size_t maxAllowed) {
    pthread_mutex_init(&rm->mutex, NULL);
    rm->max_allowed = maxAllowed;
    rm->current_usage = 0;
}

// Free allocated resources
void freeResources(ResourceManager* rm) {
    pthread_mutex_lock(&rm->mutex);
    rm->total_alloc -= rm->current_usage;
    rm->current_usage = 0;
    pthread_mutex_unlock(&rm->mutex);
}

// Allocate memory for a new record
Record* allocateRecord(size_t size, ResourceManager* rm) {
    Record* record;
    void* ptr;

    pthread_mutex_lock(&rm->mutex);

    // Check if the allocation would exceed the maximum allowed memory usage
    if (rm->total_alloc + size > rm->max_allowed) {
        pthread_mutex_unlock(&rm->mutex);
        return NULL;  // Memory limit exceeded
    }

    // Allocate memory for the record
    ptr = malloc(size);
    if (!ptr) {
        pthread_mutex_unlock(&rm->mutex);
        return NULL;  // Allocation failed
    }

    // Update the resource manager's tracking information
    rm->total_alloc += size;
    rm->current_usage += size;

    // Initialize the record structure
    record = ptr;
    record->key = 0;
    record->offset = 0;
    record->value = NULL;

    pthread_mutex_unlock(&rm->mutex);
    return record;
}

