    pthread_mutex_lock(&system->lock);
    system->events = realloc(system->events, (system->num_events + 1) * sizeof(EventNotification*));
    system->events[system->num_events] = (EventNotification*)malloc(sizeof(EventNotification));
    system->events[system->num_events]->id = id;
    system->events[system->num_events]->timestamp = timestamp;
    strcpy(system->events[system->num_events]->status, status);
