#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <rand.h>

typedef struct {
    int integer;
    double decimal;
    char* str;
} record;

record* create_records(int num_records, size_t total_size) {
    if (total_size > RAND_MAX) {
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    double* values = (double*)malloc(num_records * sizeof(double));

    char** strings = (char**)malloc(num_records * sizeof(char*));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % RAND_MAX;
        keys[i] = rand() % RAND_MAX;
        values[i] = (double)rand() / RAND_MAX;

        int str_len = sprintf("%ld %d %.2f", offsets[i], keys[i], values[i]) + 1;
        strings[i] = (char*)malloc(str_len);
        sprintf(strings[i], "%ld %d %.2f", offsets[i], keys[i], values[i]);
    }

    for (int i = 0; i < num_records; i++) {
        records[i].integer = keys[i];
        records[i].decimal = values[i];
        records[i].str = strings[i];
    }

    free(offsets);
    free(keys);
    free(values);

    return records;
}

void serialize_records(record* records, int num_records, FILE* file) {
    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i].integer, sizeof(int), 1, file);
        fwrite(&records[i].decimal, sizeof(double), 1, file);
        size_t str_len = strlen(records[i].str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(records[i].str, 1, str_len + 1, file);
    }
}

record* deserialize_records(int* num_records, FILE* file) {
    record* records;
    *num_records = 0;

    int tmp_num_records;
    fread(&tmp_num_records, sizeof(int), 1, file);
    *num_records = tmp_num_records;

    records = (record*)malloc(*num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < *num_records; i++) {
        int tmp_integer;
        double tmp_decimal;
        size_t str_len;
        char* str;

        fread(&tmp_integer, sizeof(int), 1, file);
        records[i].integer = tmp_integer;

        fread(&tmp_decimal, sizeof(double), 1, file);
        records[i].decimal = tmp_decimal;

        fread(&str_len, sizeof(size_t), 1, file);
        str = (char*)malloc(str_len + 1);
        fread(str, 1, str_len + 1, file);
        records[i].str = str;
    }

    return records;
}
