#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
    long offset;
    int key;
} record_t;

// Define the dynamic record store
typedef struct {
    record_t* records;
    size_t capacity;
    pthread_mutex_t lock;
    size_t allocated_size;
} record_store_t;

// Initialize the record store with an initial capacity and allocate memory for the records array
record_store_t* record_store_init(size_t initial_capacity) {
    record_store_t* store = malloc(sizeof(record_store_t));
    store->records = malloc(initial_capacity * sizeof(record_t));
    store->capacity = initial_capacity;
    store->allocated_size = initial_capacity * sizeof(record_t);
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Resize the records array to accommodate new records
void record_store_resize(record_store_t* store, size_t new_capacity) {
    if (new_capacity <= store->capacity) {
        free(store->records);
    }
    store->records = realloc(store->records, new_capacity * sizeof(record_t));
    store->capacity = new_capacity;
    store->allocated_size = new_capacity * sizeof(record_t);
}

// Initialize a record with an offset and key
void record_init(record_t* record, long offset, int key) {
    record->offset = offset;
    record->key = key;
    // Initialize the value to some default or zero value
    record->value = 0;
}

// Update a record's value
void record_update(record_store_t* store, int index, int new_value) {
    pthread_mutex_lock(&store->lock);
    if (index < store->capacity) {
        store->records[index].value = new_value;
    }
    pthread_mutex_unlock(&store->lock);
}

// Retrieve a record's value
int record_get(record_store_t* store, int index) {
    pthread_mutex_lock(&store->lock);
    if (index < store->capacity) {
        return store->records[index].value;
    } else {
        // Handle the case where the index is out of bounds
        return -1;  // or some other error value
    }
    pthread_mutex_unlock(&store->lock);
}

// Serialize the record store to a file
void record_store_serialize(record_store_t* store, FILE* file) {
    fwrite(&store->capacity, sizeof(size_t), 1, file);
    fwrite(store->records, sizeof(record_t), store->capacity, file);
}

// Deserialize the record store from a file
record_store_t* record_store_deserialize(FILE* file) {
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    record_store_t* store = malloc(sizeof(record_store_t));
    store->records = malloc(capacity * sizeof(record_t));
    fread(store->records, sizeof(record_t), capacity, file);
    store->capacity = capacity;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Free the record store and its associated memory
void record_store_free(record_store_t* store) {
    free(store->records);
    free(store);
}
