void init_records(int initial_capacity) {
    pthread_mutex_lock(&lock);
    if (records == NULL || capacity < initial_capacity) {
        int new_capacity = (capacity > initial_capacity) ? capacity : initial_capacity * 2;
        records = realloc(records, sizeof(record_t) * new_capacity);
        metadata = realloc(metadata, sizeof(metadata_t) * new_capacity);
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&lock);
}

void update_record(int key, int value) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
