```c
#include <stdlib.h>
#include <stdio.h>

typedef struct record {
    int key;
    long offset;
    char *value;
} record;

record **allocateRecords(int numRecords) {
    record **records = (record **)malloc(numRecords * sizeof(record *));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (record *)malloc(sizeof(record));
        records[i]->key = -1;
        records[i]->offset = -1;
        records[i]->value = NULL;
    }
    return records;
}

void deallocateRecords(record **records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]->value);
        free(records[i]);
    }
    free(records);
}

void compactMemory(record **records, int numRecords) {
    record *tmp;
    for (int i = 0; i < numRecords; i++) {
        if (records[i]->key == -1 && records[i]->offset == -1) {
            tmp = records[i];
            for (int j = i; j < numRecords - 1; j++) {
                records[j] = records[j + 1];
            }
            free(tmp);
            numRecords--;
            i--;
        }
    }
}
