typedef struct {
    float x;
    float y;
} point;

void init_data(struct json_object *json, double **floats, char ***strings, point ***points) {
    int i;

    // Initialize floating-point numbers
    for (i = 0; i < 100; i++) {
        json_object *num = json_object.GetObject(json, "double_set");
        floats[i] = malloc(sizeof(double));
        *floats[i] = json_object_get_number(num, NULL);
    }

    // Initialize strings
    for (i = 0; i < 100; i++) {
        json_object *str = json_object.GetObject(json, "char_set");
        strings[i] = malloc(11); // max length + null terminator
        strcpy(strings[i], json_object_get_string(str, NULL));
    }

    // Initialize points
    for (i = 0; i < 100; i++) {
        json_object *point_obj = json_object.GetObject(json, "point_set");
        points[i] = malloc(sizeof(point));
        points[i]->x = json_object_get_number(point_obj, "x");
        points[i]->y = json_object_get_number(point_obj, "y");
    }
}

int main() {
    struct json_object *json = json_load_file("data.json", 0);

    if (!json) {
        fprintf(stderr, "Error: Could not load JSON data.\n");
        return -1;
    }

    double *floats[100];
    char **strings[100];
    point *points[100];

    init_data(json, floats, strings, points);

    // Release resources
    for (int i = 0; i < 100; i++) {
        free(floats[i]);
        free(strings[i]);
        free(points[i]);
    }

    json_object_put(json);

    return 0;
}
