    scanf("%d", &num_points);
    printf("Enter number of colors: ");
    scanf("%d", &num_colors);

    printf("Enter matrix row and column sizes (separated by space): ");
    scanf("%d %d", &rows, &cols);

    // Allocate memory for arrays
    *arr_double = malloc(num_points * sizeof(double));
    if (*arr_double == NULL) {
        return -1;
    }

    *arr_char = (char**)malloc(num_colors * sizeof(char*));
    for (int i = 0; i < num_colors; i++) {
        *arr_char[i] = malloc(11); // Include space for null-termination
        if (*arr_char[i] == NULL) {
            return -1;
        }
    }

    *arr_point = (point*)malloc(num_points * sizeof(point));
    if (*arr_point == NULL) {
        return -1;
    }

    *arr_color = (color*)malloc(num_colors * sizeof(color));
    if (*arr_color == NULL) {
        return -1;
    }

    *matrix_int = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        *matrix_int[i] = malloc(cols * sizeof(int));
        if (*matrix_int[i] == NULL) {
            return -1;
        }
    }

    // Initialize arrays
    srand(time(NULL));

    for (int i = 0; i < num_points; i++) {
        (*arr_point)[i].x = rand() / (float)RAND_MAX;
        (*arr_point)[i].y = rand() / (float)RAND_MAX;
        (*arr_point)[i].z = rand() / (float)RAND_MAX;
    }

    for (int i = 0; i < num_colors; i++) {
        char temp[10];
        sprintf(temp, "Color %d", i);
        strcpy(*arr_char[i], temp);
        (*arr_color)[i].r = rand() / (float)RAND_MAX;
        (*arr_color)[i].g = rand() / (float)RAND_MAX;
        (*arr_color)[i].b = rand() / (float)RAND_MAX;
    }

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            (*matrix_int[i])[j] = rand() % 100;
        }
