// Define the record structure
typedef struct {
    int key;
    long timestamp;
} Record;

// Function to allocate memory for and initialize arrays
void* alloc_arrays(size_t size) {
    void *ptr = NULL;

    // Calculate total required memory
    size_t total_size = sizeof(long) * 3 + sizeof(int) * 3 + sizeof(Record) * 10;

    // Check if the total memory usage exceeds the limit
    if (total_size > MAX_MEMORY_USAGE) {
        return ptr; // Return NULL and exit
    }

    // Allocate memory for arrays
    ptr = malloc(total_size);

    // Initialize offset values, keys, and records
    long *offsets = (long *) ((char *) ptr + 0);
    int *keys = (int *) ((char *) ptr + sizeof(long) * 3);
    Record *records = (Record *) ((char *) ptr + sizeof(int) * 3 + sizeof(long) * 3);

    // Initialize offset values
    offsets[0] = 100000;
    offsets[1] = 200000;
    offsets[2] = 300000;

    // Initialize keys
    keys[0] = 1;
    keys[1] = 2;
    keys[2] = 3;

    // Initialize records
