@RestController
public class TransactionController {

    @Autowired
    private TransactionService transactionService;

    @GetMapping("/transactions")
    public ResponseEntity<List<Transaction>> getTransactions() {
        List<Transaction> transactions = transactionService.getTransactions();
        return new ResponseEntity<>(transactions, HttpStatus.OK);
    }

    @PostMapping("/transactions/{transactionId}")
    public ResponseEntity<Transaction> reverseTransaction(@PathVariable String transactionId) {
        Transaction transaction = transactionService.reverseTransaction(transactionId);
        return new ResponseEntity<>(transaction, HttpStatus.CREATED);
    }

    @PutMapping("/transactions/{transactionId}")
    public ResponseEntity<Map<String, Object>> updateTransaction(@PathVariable String transactionId, @RequestBody Map<String, Object> body) {
        try {
            transactionService.updateTransaction(transactionId, body);
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        } catch (Exception e) {
            return new ResponseEntity<>(Map.of("error", e.getMessage()), HttpStatus.BAD_REQUEST);
        }
    }

    @PatchMapping("/transactions/{transactionId}")
    public ResponseEntity<Map<String, Object>> partialUpdateTransaction(@PathVariable String transactionId, @RequestBody Map<String, Object> body) {
        try {
            transactionService.partialUpdateTransaction(transactionId, body);
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        } catch (Exception e) {
            return new ResponseEntity<>(Map.of("error", e.getMessage()), HttpStatus.BAD_REQUEST);
        }
    }

    @DeleteMapping("/transactions/{transactionId}")
    public ResponseEntity<Map<String, Object>> deleteTransaction(@PathVariable String transactionId) {
        try {
            transactionService.deleteTransaction(transactionId);
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        } catch (Exception e) {
            return new ResponseEntity<>(Map.of("error", e.getMessage()), HttpStatus.BAD_REQUEST);
        }
    }

}

