#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    double score;
    char* name;
} entry;

typedef struct _node {
    entry data;
    struct _node* next;
} node;

void linked_list_init(node** head, size_t max_size) {
    *head = NULL;
}

int linked_list_insert(node** head, entry* new_entry, size_t max_size) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return -1;  // Memory allocation failed

    new_node->data = *new_entry;
    new_node->next = *head;
    *head = new_node;

    return 0;
}

void linked_list_free(node** head) {
    node* temp = *head;
    while (temp) {
        node* next = temp->next;
        free(temp);
        temp = next;
    }
    *head = NULL;
}

// Serialization
int serialize_linked_list(const node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;  // File opening failed

    node* current = head;
    while (current) {
        entry serialized_entry = current->data;
        size_t name_len = strlen(current->name);
        fwrite(&serialized_entry.id, sizeof(int), 1, file);
        fwrite(&serialized_entry.score, sizeof(double), 1, file);
        fwrite(&name_len, sizeof(size_t), 1, file);
        fwrite(current->name, 1, name_len + 1, file);
        current = current->next;
    }

    fclose(file);
    return 0;
}

// Deserialization
int deserialize_linked_list(node** head, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;  // File opening failed

    node* new_head = NULL;
    while (1) {
        entry deserialized_entry;
        size_t name_len;
        fread(&deserialized_entry.id, sizeof(int), 1, file);
        fread(&deserialized_entry.score, sizeof(double), 1, file);
        fread(&name_len, sizeof(size_t), 1, file);
        char* new_name = (char*)malloc(name_len + 1);
        fread(new_name, 1, name_len + 1, file);

        entry* new_entry = (entry*)malloc(sizeof(entry));
        *new_entry = deserialized_entry;
        new_entry->name = new_name;

        linked_list_insert(&new_head, new_entry, SIZE_MAX);
    }

    fclose(file);
    return 0;
}

