#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the size of the record structure
typedef struct {
    int value;
} record;

// Define the hash table structure
typedef struct {
    long offset[128];
    int keys[128];
    pthread_mutex_t mutex; // Lock for concurrent access
    int numRecords;
    int capacity;
} hashtable;

hashtable* createHasTable(int initialCapacity) {
    hashtable* hash = (hashtable*)malloc(sizeof(hashtable));
    hash->numRecords = 0;
    hash->capacity = initialCapacity;
    pthread_mutex_init(&hash->mutex, NULL);

    for (int i = 0; i < hash->capacity; i++) {
        hash->offset[i] = -1;
        hash->keys[i] = -1;
    }

    return hash;
}

void resize(hashtable* hash) {
    int newCapacity = hash->capacity * 2;
    hashtable* temp = (hashtable*)malloc(sizeof(hashtable));

    for (int i = 0; i < hash->capacity; i++) {
        if (hash->offset[i] != -1) {
            // Re-index and re-insert records into the new table
            int index = i % newCapacity;
            while (index > 0 && hash->offset[index-1] != -1) {
                index--;
            }
            temp->keys[index] = hash->keys[i];
            temp->offset[index] = hash->numRecords++;
        }
    }

    // Copy the old table into the new one
    for (int i = 0; i < hash->capacity; i++) {
        hash->keys[i] = -1;
        hash->offset[i] = -1;
    }

    pthread_mutex_lock(&hash->mutex);
    free(hash);
    hash = temp;
    pthread_mutex_unlock(&hash->mutex);
}

void insertRecord(hashtable* hash, int key, int value) {
    pthread_mutex_lock(&hash->mutex);

    int index = key % hash->capacity;
    while (index > 0 && hash->offset[index-1] != -1) {
        index--;
    }

    if (hash->numRecords < hash->capacity) {
        // Insert into the first available slot
        hash->keys[index] = key;
        hash->offset[index] = hash->numRecords++;
    } else {
        // Resize and re-insert record
        resize(hash);
        insertRecord(hash, key, value);
    }

    pthread_mutex_unlock(&hash->mutex);
}

record* getRecord(hashtable* hash, int key) {
    pthread_mutex_lock(&hash->mutex);

    int index = key % hash->capacity;
    while (index > 0 && hash->offset[index-1] != -1) {
        index--;
    }

    if (hash->keys[index] == key) {
        record* record = (record*)malloc(sizeof(record));
        record->value = value; // Get the associated value from the records
        return record;
    } else {
        return NULL;
    }

    pthread_mutex_unlock(&hash->mutex);
}

void freeHasTable(hashtable* hash) {
    pthread_mutex_lock(&hash->mutex);
    for (int i = 0; i < hash->capacity; i++) {
        if (hash->keys[i] != -1) {
            // Free the records
            record* record = getRecord(hash, hash->keys[i]);
            free(record);
        }
    }

    pthread_mutex_unlock(&hash->mutex);
    free(hash);
}
