#include <stdlib.h>
#include <stdio.h>

typedef struct {
    unsigned long key;
    double value;
    struct node* left;
    struct node* right;
} node;

// Custom allocator with a fixed-size buffer
void* my_malloc(size_t size) {
    static char buffer[1024]; // Fixed-size buffer for memory allocation
    void* ptr = (void*)&buffer[(size + 1023) & ~(size - 1)];
    return ptr;
}

// Reallocates the fixed-size buffer when needed
void* my_realloc(void* ptr, size_t size) {
    if (size > sizeof(buffer)) {
        // Dynamically allocate memory if buffer capacity is exceeded
        void* new_ptr = malloc(size);
        memmove(new_ptr, ptr, size);
        free(ptr);
        return new_ptr;
    }
    return ptr;
}

// Freeing memory with custom allocator
void my_free(void* ptr) {
    if (ptr != NULL) {
        if ((char*)ptr - buffer > 0) {
            // Dynamically allocated memory; call the original free function
            free(ptr);
        } else {
            // Fixed-size buffer allocation, just decrement a counter or something
        }
    }
}

// Function to insert a node into the binary search tree (BST)
node* bst_insert(node* root, unsigned long key, double value) {
    if (root == NULL) {
        return my_malloc(sizeof(node));
    }

    node* curr = root;
    while (1) {
        if (key < curr->key) {
            if (curr->left == NULL) {
                curr->left = my_malloc(sizeof(node));
                curr->left->key = key;
                curr->left->value = value;
                return curr->left;
            }
            curr = curr->left;
        } else if (key > curr->key) {
            if (curr->right == NULL) {
                curr->right = my_malloc(sizeof(node));
                curr->right->key = key;
                curr->right->value = value;
                return curr->right;
            }
            curr = curr->right;
        } else {
            // Node already exists, update the value
            curr->value = value;
            return curr;
        }
    }

    // Memory allocation failed; handle error or exit program
}

// Insertion algorithm for efficient insertion into a BST while minimizing memory fragmentation
node* bst_insert_no_thread_safety(node* root, unsigned long key, double value) {
    if (root == NULL || key < root->key) {
        node* new_node = my_malloc(sizeof(node));
        new_node->key = key;
        new_node->value = value;
        new_node->left = new_node->right = NULL;

        if (root != NULL) {
            // Update the parent node's left or right child
            if (key < root->key) {
                root->left = new_node;
            } else {
                root->right = new_node;
            }
        } else {
            return new_node;
        }
    }

    // Node already exists, update the value
    root->value = value;

    return root;
}

// Function to handle node updates and deletions under concurrent access
void bst_update_delete(node* root, unsigned long key) {
    if (root == NULL) {
        printf("Node not found\n");
        return;
    }

    if (key < root->key) {
        if (root->left != NULL) {
            // Traverse left subtree to find the node or handle deletion
            bst_update_delete(root->left, key);
        }
    } else if (key > root->key) {
        if (root->right != NULL) {
            // Traverse right subtree to find the node or handle deletion
            bst_update_delete(root->right, key);
        }
    } else {
        printf("Node found and updated/deleted\n");
    }
}

int main() {
