#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>

class Task {
public:
    std::string name;
    double priority;
    std::vector<int> dependencies;

    Task(const std::string& name, double priority, const std::vector<int>& dependencies)
        : name(name), priority(priority), dependencies(dependencies) {}
};

class TaskManager {
private:
    std::map<int, Task*> tasks;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void addTask(Task* task) {
        int id = tasks.size();
        tasks[id] = task;
    }

    void removeTask(int id) {
        tasks.erase(id);
    }

    void updateTask(int id, const Task& task) {
        if (tasks.find(id) != tasks.end()) {
            tasks[id]->name = task.name;
            tasks[id]->priority = task.priority;
            tasks[id]->dependencies = task.dependencies;
        }
    }

    void executeTasks() {
        while (!tasks.empty()) {
            int id = 0;
            std::vector<int> toExecute;
            {
                std::unique_lock<std::mutex> lock(mutex);
                for (const auto& task : tasks) {
                    if (task.second->dependencies.empty()) {
                        toExecute.push_back(task.first);
                    } else {
                        bool executed = false;
                        for (int dependency : task.second->dependencies) {
                            if (tasks.find(dependency) != tasks.end() &&
                                !tasks[dependency]->dependencies.empty()) {
                                executed = true;
                                break;
                            }
                        }
                        if (!executed) {
                            toExecute.push_back(task.first);
                        }
                    }
                }
            }

            for (int id : toExecute) {
                std::cout << "Executing task: " << tasks[id]->name << std::endl;
                // Task execution logic here
                std::this_thread::sleep_for(std::chrono::seconds(1));
                removeTask(id);
            }
        }
    }
};
