void* manage_dataset(int num_records, long max_offset, int max_key, size_t max_buffer_size) {
    // Calculate required memory for arrays and nodes
    size_t total_memory = (num_records * sizeof(long) + num_records * sizeof(int) +
                           num_records * (sizeof(Node) + max_buffer_size));

    // Allocate memory for arrays and nodes
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    Node* records = (Node*)malloc(total_memory);

    // Initialize arrays and nodes
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
        keys[i] = rand() % max_key;
        records[i].key = keys[i];
        records[i].value = rand() % max_key;
        records[i].prev = &records[(i - 1 + num_records) % num_records];
        records[i].next = &records[(i + 1) % num_records];
    }

    // Initialize the doubly linked list
    Node* head = &records[0];
    Node* tail = &records[num_records - 1];

    return (void*)head;
}

int main() {
    int num_records = 10000;
    long max_offset = 0x7fffffff;
    int max_key = 100000;
    size_t max_buffer_size = 256;

    void* head = manage_dataset(num_records, max_offset, max_key, max_buffer_size);

    // Read input and store integers in an array
    int nums[num_records];
    for (int i = 0; i < num_records; i++) {
        scanf("%d", &nums[i]);
    }

    // Find the largest integer in the array
    int largest = find_largest(nums, num_records);

    printf("Largest number: %d\n", largest);

    // Free allocated memory
    free(head);

    return 0;
}

int find_largest(int* nums, int num_records) {
    int max = nums[0];
    for (int i = 1; i < num_records; i++) {
        if (nums[i] > max) {
            max = nums[i];
        }
    }
    return max;
}
