    config_entry_t** table;
} config_db_t;

config_db_t config_db = {0};

void init_config_db(int capacity) {
    config_db.capacity = capacity;
    config_db.size = 0;
    config_db.table = (config_entry_t**)malloc(sizeof(config_entry_t*) * capacity);
}

int hash_function(char* key, int capacity) {
    // custom hash function implementation
    return (int)(strlen(key) % capacity);
}

bool resize_config_db(int new_capacity) {
    if (new_capacity <= 0 || new_capacity < config_db.size / 7) {
        return false;
    }

    config_entry_t** new_table = (config_entry_t**)malloc(sizeof(config_entry_t*) * new_capacity);
    for (int i = 0; i < new_capacity; i++) {
        new_table[i] = NULL;
    }

    for (int i = 0; i < config_db.capacity; i++) {
        if (config_db.table[i]) {
            int new_index = hash_function(config_db.table[i]->key, new_capacity);
            while (new_table[new_index]) {
                new_index = (new_index + 1) % new_capacity;
            }
            new_table[new_index] = config_db.table[i];
        }
    }

    free(config_db.table);
    config_db.table = new_table;
    config_db.capacity = new_capacity;

    return true;
}

void put_config_entry(char* key, int value) {
    int index = hash_function(key, config_db.capacity);
    while (config_db.table[index]) {
        if (strcmp(config_db.table[index]->key, key) == 0) {
            // update existing entry
            config_db.table[index]->value = value;
            return;
        }
        index = (index + 1) % config_db.capacity;
    }

    config_entry_t* new_entry = malloc(sizeof(config_entry_t));
    new_entry->key = strdup(key);
    new_entry->value = value;

    if (config_db.size >= config_db.capacity * 0.7 && !resize_config_db(config_db.capacity * 2)) {
        printf("Database resizing failed.\n");
        return;
    }

    config_db.table[index] = new_entry;
    config_db.size++;
}

int get_config_value(char* key) {
    int index = hash_function(key, config_db.capacity);
    while (config_db.table[index]) {
        if (strcmp(config_db.table[index]->key, key) == 0) {
            return config_db.table[index]->value;
        }
        index = (index + 1) % config_db.capacity;
    }

    return -1; // not found
}

void load_config_from_service() {
    // implementation to fetch initial settings from external service
}

void save_config_to_service() {
    // implementation to synchronize changes with external service
}

void serialize_config_db_to_json(char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        return;
    }

    fprintf(file, "{\"config\": [");

    for (int i = 0; i < config_db.size; i++) {
        if (i > 0) {
            fprintf(file, ",");
        }
        fprintf(file, "{\"key\": \"%s\", \"value\": %d}", config_db.table[i]->key, config_db.table[i]->value);
    }

    fprintf(file, "]}\n");
}

void deserialize_config_db_from_json(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return;
    }

    char line[1024];
    fgets(line, 1024, file);

    int i = 0;
    do {
        sscanf(line, "{\"key\": \"%[^\", \"value\": %d},", &i);
        // handle JSON parsing and deserialization
    } while (fgets(line, 1024, file));
}

void main() {
