typedef struct node {
    int key;
    int value;
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(int key, int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL;
    }
    node->key = key;
    node->value = value;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if (!node) {
        return;
    }
    Node* current = node;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    // Initialize memory pool
    void* buffer = malloc(1024 * 1024); // 1MB buffer
    if (!buffer) {
        return -1; // Memory allocation failure
    }

    int num_records = 10000; // Number of records (5,000 to 15,000)
