#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    int key;
    long offset;
    int value;
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(int key, long offset) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }
    new_node->key = key;
    new_node->offset = offset;
    new_node->value = rand() % 100; // random value
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void update_node(Node** head, int index) {
    Node* temp = *head;
    for (int i = 0; i < index && temp != NULL; i++) {
        temp = temp->next;
    }
    if (temp != NULL) {
        temp->value = rand() % 100; // random value
    } else {
        printf("Error: Index out of range.\n");
    }
}

void print_largest(Node* head) {
    Node* max_node = head;
    for (Node* temp = head->next; temp != NULL; temp = temp->next) {
        if (temp->value > max_node->value) {
            max_node = temp;
        }
    }
    printf("Largest value: %d\n", max_node->value);
}

void free_memory(Node* head) {
    Node* temp = head;
    while (temp != NULL) {
        Node* next_node = temp->next;
        free(temp);
        temp = next_node;
    }
}

int main() {
    int count, max_count = 15000, min_count = 5000;
    printf("Enter the number of records: ");
    scanf("%d", &count);
    if (count < min_count || count > max_count) {
        printf("Error: Invalid record count.\n");
        return 1;
    }

    int* keys = (int*)malloc(count * sizeof(int));
    long* offsets = (long*)malloc(count * sizeof(long));
    Node** nodes = (Node**)malloc(count * sizeof(Node*));

    for (int i = 0; i < count; i++) {
        keys[i] = rand() % 10000;
        offsets[i] = (long)rand();
        nodes[i] = create_node(keys[i], offsets[i]);
    }

    Node* head = nodes[0];
    Node* current = head;

    for (int i = 1; i < count; i++) {
        current->next = nodes[i];
        nodes[i]->prev = current;
        current = nodes[i];
    }
    current->next = NULL;

    int largest_value_index = -1;
    printf("Enter the integers to find the largest: ");
    int arr[50]; // assume a maximum of 50 integers
    int j = 0;
    while (j < 50) {
        scanf("%d", &arr[j]);
        if (scanf("%*c") == EOF) {
            break; // input ended prematurely
        }
        j++;
    }

    for (int i = 0; i < j; i++) {
        update_node(&head, arr[i]); // update node values based on indices and keys
    }

    print_largest(head);

    free_memory(head);

    return 0;
}
