import time
import logging
from concurrent.futures import ThreadPoolExecutor

class Node:
    def __init__(self, interval, storage_endpoint):
        self.interval = interval
        self.storage_endpoint = storage_endpoint
        self.health_check_status = 'healthy'

    def process_batch(self, batch):
        # simulate processing a batch of data
        time.sleep(2)
        return f'Processed batch {batch} on node {self.interval}'

    def health_check(self):
        if self.health_check_status == 'unhealthy':
            time.sleep(5)
            self.health_check_status = 'healthy'
        return self.health_check_status

class Pipeline:
    def __init__(self, config):
        self.config = config
        self.nodes = []
        self.logger = logging.getLogger('pipeline')

    def add_node(self, node):
        self.nodes.append(node)

    def process_batches(self):
        with ThreadPoolExecutor(max_workers=10) as executor:
            for i in range(10000):  # simulate processing up to 10,000 batches
                batch_result = list(executor.map(lambda node: node.process_batch(i), self.nodes))
                summary_report = [f'Batch {i} completed on node {node.interval}' for node, result in zip(self.nodes, batch_result)]
                self.logger.info('Summary report: ' + '\n'.join(summary_report))

    def start(self):
        while True:
            for node in self.nodes:
                node.health_check()
            self.process_batches()
            time.sleep(self.config['batch_interval'])

if __name__ == '__main__':
    config = {'batch_interval': 15, 'storage_endpoints': ['s3://bucket1', 's3://bucket2']}
    pipeline = Pipeline(config)
    for i in range(10):  # simulate up to 10 nodes
        node = Node(i + 1, config['storage_endpoints'][i % len(config['storage_endpoints'])])
        pipeline.add_node(node)

    pipeline.start()
