    // Caching mechanism for storing recently accessed product data
    // Use an external cache service (e.g., Redis) to reduce frequency of database queries
    // Implement eviction policies and connection reliability considerations
} Category;

// Define a dynamic collection of 'product' objects, with efficient memory allocation strategy
typedef struct {
    int size;
    Product* products;
    Category* categories; // Caching mechanism for product data within the same category
} ProductCollection;

ProductCollection product_collection_create() {
    ProductCollection product_collection = (ProductCollection)malloc(sizeof(struct ProductCollection));
    product_collection->size = 0;
    product_collection->products = NULL;
    product_collection->categories = NULL;
    return product_collection;
}

// Populate the product collection with data read from the database in bulk
void product_collection_populate(ProductCollection* product_collection, char** lines) {
    int num_lines = strlen(lines);
    for (int i = 0; i < num_lines; i++) {
        Product new_product;
        sscanf(lines[i], "%d %d %lf", &new_product.product_id, &new_product.category_id, &new_product.price);
        // Efficiently add the product to the collection
        product_collection->products = (Product*)realloc(product_collection->products, (product_collection->size + 1) * sizeof(Product));
        product_collection->products[product_collection->size] = new_product;
        product_collection->size++;
    }
}

// Calculate and print the average price of all products within a specified category
void product_category_average_price(ProductCollection* product_collection, int category_id) {
    double total_price = 0.0;
    int num_products = 0;
    for (int i = 0; i < product_collection->size; i++) {
        if (product_collection->products[i].category_id == category_id) {
            total_price += product_collection->products[i].price;
            num_products++;
        }
    }
    if (num_products > 0) {
        double average_price = total_price / num_products;
        printf("Average price for products in category %d: %.2f\n", category_id, average_price);
    } else {
        printf("No products found in category %d.\n", category_id);
    }
}

int main() {
    ProductCollection product_collection = product_collection_create();
    char* lines[] = {"1 10 20.00", "2 10 25.00", "3 11 30.00", "4 10 22.50"};
    product_collection_populate(&product_collection, lines);
    product_category_average_price(&product_collection, 10); // Average price for products in category 10
    return 0;
}
