#define MAX_TRANSACTIONS 10000
#define MAX_TRANSACTION_FIELDS 3
#define TRANSACTION_FIELDS_SIZE sizeof(struct transaction)

struct transaction {
    int customer_id;
    char* transaction_date;
    double amount;
};

typedef struct {
    int id;
    pthread_mutex_t lock;
    struct transaction* transactions[MAX_TRANSACTIONS];
} pool_t;

pool_t* create_pool(int size) {
    pool_t* pool = (pool_t*)malloc(sizeof(pool_t));
    pool->id = 0;
    pool->transactions = (struct transaction**)malloc(size * sizeof(struct transaction*));
    for (int i = 0; i < size; i++) {
        pool->transactions[i] = NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void free_pool(pool_t* pool) {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (pool->transactions[i]) {
            free(pool->transactions[i]->transaction_date);
            free(pool->transactions[i]);
        }
    }
    free(pool->transactions);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void* read_transactions(void* arg) {
    pool_t* pool = (pool_t*)arg;
    FILE* file = fopen("transactions.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening file\n");
        return NULL;
    }
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        struct transaction* transaction = pool->transactions[pool->id % MAX_TRANSACTIONS];
        if (!transaction) {
            transaction = (struct transaction*)malloc(TRANSACTION_FIELDS_SIZE);
            pool->transactions[pool->id % MAX_TRANSACTIONS] = transaction;
            transaction->customer_id = atoi(strtok(line, " "));
            transaction->amount = atof(strtok(NULL, " "));
            char* date = strtok(NULL, "\n");
            transaction->transaction_date = strdup(date);
        } else {
            transaction->customer_id = atoi(strtok(line, " "));
            transaction->amount = atof(strtok(NULL, " "));
            char* date = strtok(NULL, "\n");
            transaction->transaction_date = strdup(date);
        }
        pool->id++;
    }
    fclose(file);
    return NULL;
}

void process_transactions(pool_t* pool) {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        struct transaction* transaction = pool->transactions[i];
        if (!transaction) continue;
        // Process the transaction
    }
}

void flush_transactions(pool_t* pool) {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        struct transaction* transaction = pool->transactions[i];
        if (!transaction) continue;
        // Flush the transaction to the central repository
    }
}

void monitor_pipeline() {
    // Monitor the pipeline and report metrics
}

int main() {
    pool_t* pool = create_pool(MAX_TRANSACTIONS);
    pthread_t thread;
    pthread_create(&thread, NULL, read_transactions, pool);
    pthread_join(thread, NULL);
    process_transactions(pool);
    flush_transactions(pool);
    monitor_pipeline();
    free_pool(pool);
    return 0;
}
