// Function to initialize and allocate memory for nodes and records
void* init_nodes(int num_nodes, int max_key_range, int max_bytes) {
    // Calculate total number of bytes needed for records and nodes
    int total_bytes = sizeof(record) * (num_nodes + 1);

    // Check if memory allocation fails
    void* records = malloc(total_bytes);
    if (!records) return NULL;

    node* head = NULL;
    node* tail = NULL;

    // Loop to populate each node's record's int field with a random value
    for (int i = 0; i < num_nodes; i++) {
        // Allocate memory for a new node
        void* temp = malloc(sizeof(node));
        if (!temp) return NULL;

        // Initialize the node's fields
        ((node*)temp)->prev = head;
        ((node*)temp)->next = tail;
        ((node*)temp)->record = (record*)((char*)records + sizeof(record) * i);
        time_t timestamp = time(NULL);

        // Set record's int field to a random value within the specified range
        ((node*)temp)->record->key = rand() % max_key_range;

        // Update the node's timestamp and access count
        ((node*)temp)->record->timestamp = timestamp;
        head = temp;
        tail = temp;

        // Check if memory allocation fails for subsequent nodes
        if (!head) return NULL;
    }

    // Return a pointer to the first node in the doubly linked list
    return head;
}
