#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    struct node* prev;
    struct node* next;
    int offset;
    int key;
    long event_timestamp;
    int status_flag;
    int record;
} Node;

Node* create_node(int offset, int key, long event_timestamp, int status_flag) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->prev = NULL;
    node->next = NULL;
    node->offset = offset;
    node->key = key;
    node->event_timestamp = event_timestamp;
    node->status_flag = status_flag;
    node->record = rand() % 100; // set record value to a random int within range [0, 100]
    return node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL || (*head)->key > new_node->key) {
        new_node->next = *head;
        new_node->prev = NULL;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->key >= new_node->key) {
            current = current->next;
        }
        new_node->next = current->next;
        new_node->prev = current;
        if (new_node->next)
            new_node->next->prev = new_node;
        else
            current->next = new_node;
        *head = new_node->next == NULL ? new_node : *head;
    }
}

void remove_node(Node** head, Node* node) {
    if (node->prev)
        node->prev->next = node->next;
    else
        *head = node->next;

    if (node->next)
        node->next->prev = node->prev;
    free(node);
}

void update_node_status(Node** head, int index, int key, int new_status) {
    Node* current = *head;
    while (current) {
        if (current->key == key && current->status_flag != new_status) {
            current->status_flag = new_status;
            return;
        }
        current = current->next;
    }
}

void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("(%d, %d, %ld, %d, %d)\n", current->offset, current->key, current->event_timestamp, current->status_flag, current->record);
        current = current->next;
    }
}

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void free_nodes(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        remove_node(head, current);
        current = next;
    }
}

int main() {
    int offset_arr[5], key_arr[5], event_timestamp_arr[5], status_flag_arr[5];
    // initialize arrays with values
    for (int i = 0; i < 5; i++) {
        offset_arr[i] = i;
        key_arr[i] = i * 2;
        event_timestamp_arr[i] = i * 3;
        status_flag_arr[i] = i % 2;
    }

    // create node for each array
    Node* node1 = create_node(offset_arr[0], key_arr[0], event_timestamp_arr[0], status_flag_arr[0]);
    Node* node2 = create_node(offset_arr[1], key_arr[1], event_timestamp_arr[1], status_flag_arr[1]);
    Node* node3 = create_node(offset_arr[2], key_arr[2], event_timestamp_arr[2], status_flag_arr[2]);
    Node* node4 = create_node(offset_arr[3], key_arr[3], event_timestamp_arr[3], status_flag_arr[3]);
    Node* node5 = create_node(offset_arr[4], key_arr[4], event_timestamp_arr[4], status_flag_arr[4]);

    // initialize linked list
    Node* head = NULL;
    insert_node(&head, node1);
    insert_node(&head, node2);
    insert_node(&head, node3);
    insert_node(&head, node4);
    insert_node(&head, node5);

    // read integers from standard input and store in array
    int arr[100];
    int size = 0;
    int num;
    while (scanf("%d", &num) == 1 && size < 100) {
        arr[size++] = num;
    }

    // find largest integer in the array
    int max = find_largest(arr, size);

    // print linked list
    printf("Linked List: ");
    print_list(head);
    printf("\n");

    return 0;
}
