} RecordCollection;

void record_collection_init(RecordCollection* collection, int initial_capacity) {
    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->mutex, NULL);
}

int record_collection_resize(RecordCollection* collection, int new_capacity) {
    if (new_capacity <= collection->size) {
        return -1; // cannot shrink the size
    }

    Record* new_records = (Record*)malloc(new_capacity * sizeof(Record));
    memcpy(new_records, collection->records, collection->size * sizeof(Record));

    free(collection->records);
    collection->records = new_records;
    collection->capacity = new_capacity;

    return 0;
}

void record_collection_insert(RecordCollection* collection, Record record) {
