    Record* records = collection->records;
    for (int i = collection->size; i > 0; --i) {
        records[i] = records[i - 1];
    }
    records[0] = record;

    pthread_mutex_lock(&collection->mutex);
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);
}

void record_collection_remove(RecordCollection* collection, int key) {
    for (int i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            for (int j = i + 1; j < collection->size; ++j) {
                Record record = collection->records[j];
                collection->records[j] = collection->records[i];
                i++;
            }
            collection->size--;
            break;
        }
    }
}

void record_collection_update(RecordCollection* collection, int key, int value) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].value = value;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void record_collection_destroy(RecordCollection* collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
}
