#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(record)

typedef struct {
    int value;
    time_t timestamp;
    int id;
} record;

record *records = NULL;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* alloc_record(int max_size) {
    return malloc(max_size);
}

void free_all() {
    for (int i = 0; i < num_records; i++) {
        free(records[i].value);
    }
    free(records);
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    while (1) {
        int expired = 0;
        for (int i = 0; i < num_records; i++) {
            if (time(NULL) - records[i].timestamp > 60*60) { // 1 hour
                expired++;
                record temp = records[i];
                memmove(&records[i], &records[i+1], sizeof(record)*(num_records-1));
                free(temp.value);
                num_records--;
                i--; // Account for shifted indices
            }
        }
        if (!expired) break;
    }
    pthread_mutex_unlock(&mutex);
}

void update(int index, int key, int new_value) {
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < num_records) {
        record *r = &records[index];
        if (key == r->id) {
            r->value = new_value;
            pthread_cond_signal(&cond);
        }
    }
    pthread_mutex_unlock(&mutex);
}

record* get(int id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].id == id) {
            record *r = &records[i];
            pthread_mutex_unlock(&mutex);
            return r;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void init(int max_size) {
    records = (record*)malloc(MAX_RECORDS*RECORD_SIZE);
    num_records = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        record r;
        r.id = i;
        r.timestamp = time(NULL);
        r.value = rand() % max_size + 1;
        records[i] = r;
    }
}

void run_thread() {
    pthread_mutex_lock(&mutex);
    while (1) {
        // Insert new records
        if (num_records < MAX_RECORDS) {
            record *r = (record*)alloc_record(RECORD_SIZE);
            r->id = num_records++;
            r->timestamp = time(NULL);
            r->value = rand() % 100 + 1;
            memmove(&records[num_records], &records[num_records-1], sizeof(record));
            pthread_cond_signal(&cond);
        }
        // Update existing records
        if (rand() % 10 < 3) {
            int index = rand() % num_records;
            int key = records[index].id;
            int new_value = rand() % 100 + 1;
            update(index, key, new_value);
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    srand(time(NULL));
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, run_thread, NULL);
    }
    sleep(60*60); // Run for an hour
    cleanup();
    return 0;
}
