#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Configuration type enumeration
enum ConfigType { INT = 0, STRING, BOOLEAN };

// Configuration setting structure
typedef struct {
    const char* name;
    enum ConfigType type;
    void* value;
} ConfigSetting;

// Dynamic configuration list structure
typedef struct {
    int size;
    int capacity;
    ConfigSetting** settings;
    pthread_mutex_t lock;
} ConfigList;

// Initialize the configuration list
void config_list_init(ConfigList* list, int initial_capacity) {
    list->size = 0;
    list->capacity = initial_capacity;
    list->settings = (ConfigSetting**)malloc(initial_capacity * sizeof(ConfigSetting*));
    pthread_mutex_init(&list->lock, NULL);
}

// Add a configuration setting to the list
void config_list_add(ConfigList* list, const char* name, enum ConfigType type, void* value) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        int new_capacity = list->capacity * 2;
        ConfigSetting** new_settings = (ConfigSetting**)realloc(list->settings, new_capacity * sizeof(ConfigSetting*));
        list->settings = new_settings;
        list->capacity = new_capacity;
    }

    ConfigSetting* setting = malloc(sizeof(ConfigSetting));
    setting->name = strdup(name);
    setting->type = type;
    setting->value = value;

    list->settings[list->size] = setting;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

// Update a configuration setting in the list
void config_list_update(ConfigList* list, const char* name, enum ConfigType type, void* value) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->settings[i]->name, name) == 0 && list->settings[i]->type == type) {
            free(list->settings[i]->value);
            list->settings[i]->value = value;
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Delete a configuration setting from the list
void config_list_delete(ConfigList* list, const char* name) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->settings[i]->name, name) == 0) {
            free(list->settings[i]->value);
            free(list->settings[i]->name);
            memmove(list->settings + i, list->settings + i + 1, (list->size - i - 1) * sizeof(ConfigSetting*));
            list->size--;
            i--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Retrieve the current state of all configurations
void config_list_serialize(ConfigList* list, int* buffer_size, void** buffer) {
    pthread_mutex_lock(&list->lock);

    *buffer_size = list->size * sizeof(ConfigSetting);
    *buffer = malloc(*buffer_size);
    ConfigSetting* settings = (ConfigSetting*)*buffer;
    for (int i = 0; i < list->size; i++) {
        settings[i].name = strdup(list->settings[i]->name);
        settings[i].type = list->settings[i]->type;
        settings[i].value = malloc(sizeof(void));
        *settings[i].value = list->settings[i]->value;

        memcpy(settings + i, list->settings + i, sizeof(ConfigSetting));
    }

    pthread_mutex_unlock(&list->lock);
}

// Deserialize the configuration list from a byte buffer
void config_list_deserialize(ConfigList* list, int buffer_size, void* buffer) {
    ConfigSetting* settings = (ConfigSetting*)buffer;
    for (int i = 0; i < list->size; i++) {
        free(settings[i].name);
        free((void*)settings[i].value);

        settings[i].name = strdup(settings[i].name);
        settings[i].type = settings[i].type;
        settings[i].value = malloc(sizeof(void));
        *settings[i].value = *(void**)settings[i].value;

        list->settings[list->size] = settings[i];
        list->size++;
    }
}

// Report the current size of the configuration list and memory usage
int config_list_size(ConfigList* list) {
    return list->size;
}

// Print the current state of all configurations
void config_list_print(ConfigList* list) {
    for (int i = 0; i < list->size; i++) {
        printf("%s: %d\n", list->settings[i]->name, list->settings[i]->type);
    }
}
