#include <pthread.h>

#define RECORD_SIZE sizeof(record_t)
#define MEMORY_POOL_SIZE 1024
#define KEY_RANGE 1000
#define THREAD_COUNT 5

typedef struct {
    int key;
    int value;
    char identifier[16];
} record_t;

record_t* allocate_record(int count, int* memory_usage) {
    record_t* records = (record_t*)malloc(count * RECORD_SIZE);
    if (!records) {
        return NULL;
    }
    *memory_usage += count * RECORD_SIZE;
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % KEY_RANGE;
        records[i].value = rand();
        sprintf(records[i].identifier, "Record_%d", i);
    }
    return records;
}

void deallocate_record(record_t* records) {
    free(records);
}

int update_record(record_t* records, int count, int key, int value) {
    for (int i = 0; i < count; i++) {
        if (records[i].key == key) {
            records[i].value = value;
            return 1;
        }
    }
    return -1;
}

void serialize_records(record_t* records, FILE* file) {
    fwrite(records, RECORD_SIZE, 5, file);
}

int deserialize_records(record_t** records, FILE* file) {
    *records = malloc(5 * RECORD_SIZE);
    if (!(*records)) {
        return -1;
    }
    fread(*records, RECORD_SIZE, 5, file);
    return 0;
}

void report_memory_usage(int memory_usage) {
    printf("Current Memory Usage: %d bytes\n", memory_usage);
}

int main() {
    int memory_usage = 0;
    record_t* records = allocate_record(5, &memory_usage);
    if (!records) {
        return -1;
    }
    report_memory_usage(memory_usage);
    // Update and serialize records
    update_record(records, 5, 2, 10);
    FILE* file = fopen("record.dat", "wb");
    if (file) {
        serialize_records(records, file);
        fclose(file);
    } else {
        deallocate_record(records);
        return -1;
    }
    // Deserialize and check records
    record_t* deserialized_records = NULL;
    int status = deserialize_records(&deserialized_records, file);
    if (status) {
        deallocate_record(deserialized_records);
        return -1;
    }
    for (int i = 0; i < 5; i++) {
        printf("Key: %d, Value: %d\n", deserialized_records[i].key, deserialized_records[i].value);
    }
    deallocate_record(deserialized_records);
    deallocate_record(records);
    return 0;
}

