    // Dynamically allocate memory for the arrays
    offsets = (long *)malloc(record_count * offset_size);
    keys = (int *)malloc(record_count * key_size);
    records = (record_t *)malloc(record_count * RECORD_SIZE);

    for (i = 0; i < record_count; i++) {
        // Initialize the record's int field with a random value
        records[i].value = rand() % 100;

        // Initialize the offset and key values
        offsets[i] = (long)rand();
        keys[i] = (int)rand();
    }

    // Perform DNS resolution for multiple hostnames
    char *hosts[] = {"host1", "host2", "host3"};
    int host_count = sizeof(hosts) / sizeof(*hosts);
    resolve_dns(hosts, host_count, ip_addrs);

    // Handle errors and return appropriate status codes

    free(ip_addrs);
    free(records);
    free(keys);
    free(offsets);

