record** initialize_records(int num_offsets, int num_records) {
    record** records = NULL;
    long* offsets = NULL;

    if (num_offsets <= 0 || num_records <= 0) {
        return NULL; // Error: invalid parameters
    }

    // Allocate memory for offset array using custom allocator
    offsets = (long*)custom_allocator_alloc(sizeof(long) * num_offsets, CUSTOM_ALLOCATOR_POOL_RECORDS);
    if (offsets == NULL) {
        return NULL; // Allocation failure
    }

    // Initialize offset values randomly
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    // Allocate memory for record array using custom allocator
    records = (record**)custom_allocator_alloc(sizeof(record*) * num_records, CUSTOM_ALLOCATOR_POOL_RECORDS);
    if (records == NULL) {
        free_memory(offsets); // Free previously allocated offset buffer
        return NULL; // Allocation failure
    }

    // Initialize record values randomly and link to corresponding offsets
    for (int i = 0; i < num_records; i++) {
        record* current_record = records[i] = (record*)custom_allocator_alloc(sizeof(record), CUSTOM_ALLOCATOR_POOL_RECORDS);
        if (current_record == NULL) {
