#define MAX_SENSOR_TYPES 10
#define SLIDING_WINDOW_SIZE 100
#define THRESHOLD_LOW 1.5
#define THRESHOLD_HIGH 3.0

typedef struct {
    uint32_t timestamp;
    double value;
} SensorReading;

SensorReading readings[MAX_SENSOR_TYPES][SLIDING_WINDOW_SIZE];

void process_sensor_data(uint8_t sensor_type, uint32_t timestamp, double value) {
    if (sensor_type < MAX_SENSOR_TYPES && timestamp < SLIDING_WINDOW_SIZE) {
        readings[sensor_type][timestamp].timestamp = timestamp;
        readings[sensor_type][timestamp].value = value;
    }
}

double compute_mean(uint8_t sensor_type, uint32_t start_idx, uint32_t end_idx) {
    double sum = 0.0;
    for (int i = start_idx; i <= end_idx; i++) {
        sum += readings[sensor_type][i].value;
    }
    return sum / (end_idx - start_idx + 1);
}

double compute_stddev(uint8_t sensor_type, uint32_t start_idx, uint32_t end_idx) {
    double mean = compute_mean(sensor_type, start_idx, end_idx);
    double variance = 0.0;
    for (int i = start_idx; i <= end_idx; i++) {
        variance += (readings[sensor_type][i].value - mean) * (readings[sensor_type][i].value - mean);
    }
    return sqrt(variance / (end_idx - start_idx + 1));
}

void detect_anomalies(uint8_t sensor_type, uint32_t start_idx, uint32_t end_idx) {
    double mean = compute_mean(sensor_type, start_idx, end_idx);
    double stddev = compute_stddev(sensor_type, start_idx, end_idx);

    for (int i = start_idx; i <= end_idx; i++) {
        if (abs(readings[sensor_type][i].value - mean) > THRESHOLD_LOW * stddev || 
            abs(readings[sensor_type][i].value - mean) > THRESHOLD_HIGH * stddev) {
            // process anomaly
        }
    }
}

void* sliding_window_thread(void* arg) {
    int sensor_type = *((int*)arg);
    uint32_t start_idx = 0;
    uint32_t end_idx = SLIDING_WINDOW_SIZE - 1;

    while (1) {
        detect_anomalies(sensor_type, start_idx, end_idx);

        // slide the window
        if (++start_idx > end_idx) {
            start_idx = 0;
            end_idx++;
        }
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_SENSOR_TYPES];
    for (int i = 0; i < MAX_SENSOR_TYPES; i++) {
        pthread_create(&threads[i], NULL, sliding_window_thread, &i);
    }

    // process sensor data and update the readings array
    process_sensor_data(0, 10, 2.5);
    process_sensor_data(1, 15, 3.8);

    // ...
}

void handle_packet_loss(int packet_id) {
    // retransmit packets if necessary
}

int get_highest_deviation(uint8_t sensor_type, uint32_t start_idx, uint32_t end_idx) {
    double max_deviation = 0.0;
    for (int i = start_idx; i <= end_idx; i++) {
        double deviation = abs(readings[sensor_type][i].value - compute_mean(sensor_type, start_idx, end_idx));
        if (deviation > max_deviation) {
            max_deviation = deviation;
        }
    }
    return max_deviation;
}

