import time
from functools import lru_cache
from threading import Lock
from requests.exceptions import RequestException

MAX_CACHE_SIZE = 1000

class TransactionProcessor:
    def __init__(self):
        self.cache = {}
        self.lock = Lock()

    @lru_cache(maxsize=MAX_CACHE_SIZE)
    def get_user_details(self, user_id):
        try:
            response = requests.get(f'https://api.example.com/users/{user_id}')
            response.raise_for_status()
            return response.json()
        except RequestException as e:
            if isinstance(e, requests.exceptions.ConnectionError):
                time.sleep(0.1)
                return self.get_user_details(user_id)  # Retry with exponential backoff
            raise

    def process_transactions(self, transactions):
        valid_transactions = []
        for transaction in transactions:
            if not all(transaction['user_id'], transaction['amount']):
                continue
            user_details = self.get_user_details(transaction['user_id'])
            if user_details and 'account_status' in user_details and user_details['account_status'] == 'active':
                valid_transactions.append(transaction)
        return valid_transactions

    def run(self):
        while True:
            try:
                transactions = requests.get('https://api.example.com/transactions').json()
                result = self.process_transactions(transactions)
                print(result)
            except RequestException as e:
                if isinstance(e, requests.exceptions.ConnectionError):
                    time.sleep(0.1)  # Retry with exponential backoff
                else:
                    raise

if __name__ == '__main__':
    processor = TransactionProcessor()
    processor.run()
