#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define RECORDS_PER_CACHE 100
#define MAX_RECORDS 5000
#define MEMORY_LIMIT 10000000
#define RAND_MAX 1000

typedef struct {
    int i;
    long l;
    double d;
} record;

record* records = NULL;
int num_records = 0;
int cache_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("memory.log", "w");

void* allocate_record(int index) {
    if (num_records >= MAX_RECORDS || cache_size >= RECORDS_PER_CACHE) {
        // Evict older records from the cache
        record* temp = NULL;
        for (int i = 0; i < cache_size; i++) {
            temp = &records[i];
            memmove(&records[i], &records[i + 1], (MAX_RECORDS - num_records) * sizeof(record));
            free(temp);
        }
        cache_size -= RECORDS_PER_CACHE - num_records;
    }

    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize record with random values
    new_record->i = rand() % RAND_MAX;
    new_record->l = rand() % RAND_MAX * RAND_MAX;
    new_record->d = (double)rand() / RAND_MAX;

    pthread_mutex_lock(&lock);
    records[num_records++] = *new_record;
    pthread_mutex_unlock(&lock);

    return new_record;
}

void deallocate_record(int index, record* to_free) {
    if (index < 0 || index >= num_records) {
        // Handle out-of-range index
        return;
    }

    memmove(&records[index], &records[index + 1], (num_records - index - 1) * sizeof(record));
    free(to_free);
    pthread_mutex_lock(&lock);
    num_records--;
    pthread_mutex_unlock(&lock);

    if (index >= cache_size) {
        // Evict the record from the cache
        cache_size--;
    } else {
        // Update the cached record
        records[index] = *to_free;
    }
}

int main() {
    srand(time(NULL));
    return 0;
}
