function createDashboardWidget(users) {
  const apiCall = async () => {
    try {
      const response = await fetch('/api/users');
      if (!response.ok) throw new Error('Failed to retrieve user data');
      return response.json();
    } catch (error) {
      console.error(error);
      return [];
    }
  };

  const handleApiError = (error) => {
    console.error(error);
    // Provide fallback UI elements for users
    return '<div class="error-message">Error fetching user data.</div>';
  };

  const renderWidget = async () => {
    try {
      const usersData = await apiCall();
      if (!usersData.length) return handleApiError('No users found');

      const widgetHTML = users.map((user) => {
        return `
          <div class="dashboard-item">
            <h2>${user.name}</h2>
            <p>Role: ${user.role}</p>
            <p>Last Active: ${user.lastActive}</p>
          </div>
        `;
      }).join('');

      return widgetHTML;
    } catch (error) {
      return handleApiError(error);
    }
  };

  const readyCallback = () => {
    const widgetHTML = renderWidget();
    document.getElementById('widget-container').innerHTML = widgetHTML;
  };

  // Detect when the layout is ready
  document.addEventListener('DOMContentLoaded', readyCallback);

  return '';
}
