// Function to concatenate streams into a single buffer
char* concat_streams(int** streams, int num_streams) {
    int total_len = 0;
    for (int i = 0; i < num_streams; i++) {
        total_len += sizeof(int) + strlen((char*)streams[i]);
    }

    char* buffer = (char*)malloc(total_len);
    int offset = 0;
    for (int i = 0; i < num_streams; i++) {
        memcpy(buffer + offset, &(streams[i][0]), sizeof(int));
        offset += sizeof(int);
        strcpy(buffer + offset, (char*)streams[i]);
        offset += strlen((char*)streams[i]) + 1;
    }

    return buffer;
}

// Function to allocate memory for an array of int keys
int** alloc_keys(int num_keys) {
    int** keys = (int**)malloc(num_keys * sizeof(int*));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = (int*)malloc(sizeof(int));
        *(keys[i]) = rand() % 100;
    }

    return keys;
}

// Function to initialize each key value with a random value within a specified range
void init_key_values(int** keys, int num_keys) {
    for (int i = 0; i < num_keys; i++) {
        *(keys[i]) = rand() % 100;
    }
}

// Function to allocate memory for an array of char buffers and int fields
void* alloc_records(int num_records, int max_len) {
    void* records = malloc(num_records * sizeof(void*));
    for (int i = 0; i < num_records; i++) {
        *(records + i) = malloc(max_len);
        *(int*)((char*)records + i) = rand() % 100;
    }

    return records;
}

// Function to manage the lifecycle of resources, including deallocation
void free_resources(int** streams, int num_streams, int** keys, int num_keys, void* records, int num_records) {
    for (int i = 0; i < num_streams; i++) {
        free(streams[i]);
    }
    free(streams);

    for (int i = 0; i < num_keys; i++) {
        free(keys[i]);
    }
    free(keys);

    for (int i = 0; i < num_records; i++) {
        free((char*)records + i);
    }
    free(records);
}

int main() {
    srand(time(NULL));

    int** streams = alloc_keys(5);
    init_key_values(streams, 5);

    void* records = alloc_records(10, 100);

    char* buffer = concat_streams(streams, 5);

    // Process the concatenated stream
    printf("%s\n", buffer);

    free_resources(streams, 5, streams, 5, records, 10);

    return 0;
