typedef struct {
    int minKey;
    int maxKey;
    int minValue;
    int maxValue;
    size_t memoryLimit;
    int logLevel;
} Config;

Config* config = NULL;

int loadAndInitializeRecords(const char* filePath, Config* conf) {
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        return -1; // File loading failed
    }

    ResourceBundle bundle;
    size_t bundleSize = fread(&bundle, sizeof(bundle), 1, file);
    fclose(file);

    if (bundleSize != 1) {
        return -2; // Failed to load resource bundle
    }

    int* keys = malloc(conf->memoryLimit);
    long* offsets = malloc(conf->memoryLimit * sizeof(long));
    Record** records = malloc(conf->memoryLimit * sizeof(Record*));

    if (keys == NULL || offsets == NULL || records == NULL) {
        return -3; // Memory allocation failed
    }

    size_t recordCount = bundle.items;
    for (size_t i = 0; i < recordCount; i++) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            free(keys);
            free(offsets);
            free(records);
            return -3; // Memory allocation failed
        }

        int key = rand() % (conf->maxKey - conf->minKey + 1) + conf->minKey;
        long offset = (long)rand() % (conf->memoryLimit / sizeof(long));
        int value = rand() % (conf->maxValue - conf->minValue + 1) + conf->minValue;

        record->key = key;
        record->offset = offset;
        record->value = value;

        records[i] = record;
    }

    free(keys);
    free(offsets);

    return recordCount;
}
