State* createStateList(FSA* fsa, int last_state) {
    pthread_mutex_lock(&fsaptr->mutex);

    // Traverse the FSA to identify reachable states
    for(int i = 0; i < fsaptr->num_states; i++) {
        if(fsaptr->transitions[i][0] == -1)
            continue;

        State* current_state = createState(i);
        State* next_state = NULL;
        while(true) {
            int transition = fsaptr->transitions[i][0];
            if(transition == -1)
                break;

            for(int j = 1; j < fsaptr->num_states; j++) {
                if(fsaptr->transitions[transition][j] != -1) {
                    next_state = createState(j);
                    i = transition;
                    break;
                }
            }

            if(next_state == NULL)
                break;

            // Update the 'next' pointer of the last state in the list
            current_state->id = fsaptr->transitions[i][0];
            int* temp = (int*)malloc(sizeof(int) * (last_state + 1));
            for(int k = 0; k <= last_state; k++)
                temp[k] = fsaptr->transitions[k][0];

            pthread_mutex_unlock(&fsaptr->mutex);
            free(current_state);
            current_state = NULL;
            pthread_mutex_lock(&fsaptr->mutex);

            // Add the states to the list
            if(temp != NULL) {
                for(int k = 0; k <= last_state; k++)
                    temp[k] = fsaptr->transitions[temp[k]][k];
                free(temp);
            }
        }
    }

    pthread_mutex_unlock(&fsaptr->mutex);

    return current_state;
}

int main() {
