import logging
from collections import deque
from functools import lru_cache
import time
import json
import gzip
import boto3
import redis

class EventLogger:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.config = {}
        self.compressors = []

    @property
    def log_file(self):
        return f"log-{int(time.time())}.txt"

    def configure(self, config):
        self.config.update(config)

    def log_event(self, event):
        if event['severity'] == 'ERROR':
            self.logger.error(json.dumps(event))
        elif event['severity'] == 'WARNING':
            self.logger.warning(json.dumps(event))
        else:
            self.logger.info(json.dumps(event))

        with gzip.open(self.log_file, 'a') as f:
            json.dump(event, f)
            f.write(b'\n')

    def route_events(self):
        if self.config.get('route_to_console'):
            print(f"Received {len(queue)} events")

        if self.config.get('route_to_file'):
            with open(self.log_file, 'w') as f:
                for event in queue:
                    json.dump(event, f)
                    f.write(b'\n')

        if self.config.get('route_to_s3'):
            s3 = boto3.client('s3')
            bucket_name = self.config['bucket_name']
            key = f"logs/{int(time.time())}.txt"
            with gzip.open(self.log_file, 'r') as f:
                s3.put_object(Body=f.read(), Bucket=bucket_name, Key=key)

    @lru_cache(maxsize=100)
    def get_redis_connection(self):
        return redis.Redis(host='localhost', port=6379, db=0)

    def log_to_redis(self):
        r = self.get_redis_connection()
        for event in queue:
            r.lpush('log', json.dumps(event))
            if len(r.lrange('log', 0, -1)) > 10000:
                r.save()

    @lru_cache(maxsize=100)
    def get_kafka_producer(self):
        from kafka import KafkaProducer
        return KafkaProducer(bootstrap_servers=['localhost:9092'])

    def log_to_kafka(self):
        producer = self.get_kafka_producer()
        for event in queue:
            producer.send('log', value=json.dumps(event).encode())
            if len(producer.buffer) > 10000:
                producer.flush()

    @lru_cache(maxsize=100)
    def get_grpc_server(self):
        from grpc import server
        return server()

    def log_to_grpc(self):
        for event in queue:
            channel = self.get_grpc_server().add_channel('localhost:50051')
            request = grpc.event_pb2.Event(event=event)
            channel.send(request)

if __name__ == "__main__":
    logger = EventLogger()
    logger.configure({'route_to_console': True, 'route_to_file': False, 'route_to_s3': False})
    queue = deque()

    while True:
        event = {'timestamp': int(time.time()), 'source_id': 1, 'message_content': 'Hello', 'severity': 'INFO'}
        logger.log_event(event)
        queue.append(event)

        if len(queue) > 10000:
            logger.route_events()
            logger.log_to_redis()
            logger.log_to_kafka()
            logger.log_to_grpc()

    print("Event logging service started. Press Ctrl+C to exit.")
