#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void handleFileProcessing(const char* filePath) {
    // Dynamically allocate memory to store file content
    size_t fileSize = 0;
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filePath);
        return;
    }
    fseek(file, 0, SEEK_END);
    fileSize = ftell(file);
    rewind(file);
    char* fileContent = (char*)malloc(fileSize + 1);
    fread(fileContent, 1, fileSize, file);
    fclose(file);

    // Process file content to extract unique words and frequency counts
    size_t wordCount = 0;
    char** words = NULL;
    for (size_t i = 0; i < fileSize; i++) {
        if (fileContent[i] == ' ') {
            wordCount++;
        } else if (fileContent[i] == '\n') {
            wordCount++;
        }
    }

    // Print top three most frequent words
    printf("Top three most frequent words:\n");
    for (size_t i = 0; i < 3 && i < wordCount; i++) {
        printf("%s\n", fileContent);
    }

    free(fileContent);
}
