import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class FileProcessor {
    public static void handleFileProcessing(URI filePath) throws IOException, InterruptedException {
        // Establish connection to remote server using Java HTTP client
        HttpClient client = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(filePath)
                .GET()
                .build();

        // Manage request and response handling asynchronously
        client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(HttpResponse::body)
                .thenAccept(response -> {
                    System.out.println("Received response: " + response);
                })
                .whenComplete((response, throwable) -> {
                    if (throwable != null) {
                        System.err.println("Error handling request: " + throwable.getMessage());
                    }
                });
    }
}
