import java.io.FileWriter;
import java.io.IOException;

public class Logger {
    private static FileWriter fileWriter = null;

    public static void setFileWriter(FileWriter writer) {
        fileWriter = writer;
    }

    public static void log(String message, LogLevel level) throws IOException {
        if (fileWriter == null) return;

        switch (level) {
            case DEBUG:
                fileWriter.write("[DEBUG] " + message + "\n");
                break;
            case INFO:
                fileWriter.write("[INFO] " + message + "\n");
                break;
            case WARNING:
                fileWriter.write("[WARNING] " + message + "\n");
                break;
            case ERROR:
                fileWriter.write("[ERROR] " + message + "\n");
                break;
        }
    }

    public enum LogLevel {
        DEBUG, INFO, WARNING, ERROR
    }
}
