async function customReduce(arr, callback, concurrencyLimit = 5, timeout = 5000) {
  const results = [];
  const queue = [];
  let pendingCount = 0;

  for (const item of arr) {
    queue.push(item);
  }

  while (queue.length > 0) {
    await new Promise((resolve) => {
      setTimeout(() => {
        resolve();
      }, timeout);
    });

    const chunkSize = Math.min(concurrencyLimit, queue.length);
    for (let i = 0; i < chunkSize; i++) {
      const item = queue.shift();
      if (!item) continue;

      try {
        const result = await callback(item, results[results.length - 1]);
        results.push(result);
      } catch (error) {
        console.error(`Error processing item: ${JSON.stringify(item)}, error: ${error}`);
      }
    }

    pendingCount -= chunkSize;
    if (pendingCount <= 0) {
      pendingCount = 0;
    }
  }

  return results[results.length - 1];
}
