typedef struct {
    long offset;
    int key;
    double value;
    time_t timestamp;
} Record;

Record* records = NULL;
int record_count = 0;
int allocated_memory = 0;
int last_compacted_index = -1;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_and_realloc() {
    Record* new_records = (Record*) realloc(records, sizeof(Record) * MAX_RECORDS);
    if (!new_records) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    records = new_records;
    allocated_memory += sizeof(Record) * MAX_RECORDS;
}

void compact_memory() {
    int new_record_count = 0;
    for (int i = last_compacted_index + 1; i < record_count; i++) {
        if (records[i].key != -1 && records[i].timestamp != 0) {
            records[new_record_count++] = records[i];
        }
    }
    free_and_realloc();
    last_compacted_index = new_record_count;
}

void update_record(int index, int key, double value, time_t timestamp) {
    pthread_mutex_lock(&lock);
    if (index < record_count) {
        records[index].key = key;
        records[index].value = value;
        records[index].timestamp = timestamp;
    }
    pthread_mutex_unlock(&lock);
}

void export_to_csv() {
    FILE* file = fopen("output.csv", "w");
    for (int i = 0; i < record_count; i++) {
        fprintf(file, "%ld,%d,%f,%ld\n", records[i].offset, records[i].key, records[i].value, records[i].timestamp);
    }
    fclose(file);
}

void* health_monitor_thread(void*) {
    while (1) {
        pthread_mutex_lock(&lock);
        printf("Memory usage: %d%%\n", (int)((allocated_memory * 100) / MAX_MEMORY));
        printf("Compaction frequency: %d\n", last_compacted_index);
        printf("Concurrent updates: %d\n", record_count);
        sleep(5); // adjust to your needs
        pthread_mutex_unlock(&lock);
    }
}

void initialize_system() {
    records = (Record*) malloc_or_die(sizeof(Record) * MAX_RECORDS);
    allocated_memory += sizeof(Record) * MAX_RECORDS;
}
