#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_SIZE 64 // Size in bytes for each record structure
#define MAX_RECORDS 1000 // Maximum number of records
#define MEMORY_LIMIT 1024 * 1024 * 10 // 10MB memory limit

typedef struct {
    long offset;
    int key;
    double value;
    char* str;
    time_t timestamp;
} Record;

Record* records = NULL;
int record_count = 0;
int allocated_size = 0;

void init_records() {
    if (record_count == 0) {
        records = (Record*)malloc(RECORD_SIZE);
        allocated_size = RECORD_SIZE;
        record_count = 1;
    }
}

void add_record(long offset, int key, double value, char* str, time_t timestamp) {
    init_records();
    Record* new_records = NULL;
    if ((new_records = (Record*)realloc(records, (record_count + 1) * RECORD_SIZE)) == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    allocated_size += RECORD_SIZE;
    records = new_records;
    memcpy(&records[record_count - 1], &offset, sizeof(long));
    memcpy(&records[record_count - 1] + sizeof(long), &key, sizeof(int));
    memcpy(&records[record_count - 1] + sizeof(long) + sizeof(int), &value, sizeof(double));
    records[record_count - 1].str = str;
    records[record_count - 1].timestamp = timestamp;
    record_count++;
}

void compact_records() {
    if (record_count * RECORD_SIZE > MEMORY_LIMIT * 0.8) { // Check if memory usage exceeds 80%
        Record* new_records = NULL;
        int i, j;
        for (i = 0; i < record_count - 1; i++) {
            for (j = i + 1; j < record_count; j++) {
                if (records[i].offset > records[j].offset) {
                    // Swap records
                    Record temp;
                    memcpy(&temp, &records[i], RECORD_SIZE);
                    memcpy(&records[i], &records[j], RECORD_SIZE);
                    memcpy(&records[j], &temp, RECORD_SIZE);
                }
            }
        }
        record_count--;
    }
}

void log_records() {
    printf("Record count: %d\n", record_count);
    for (int i = 0; i < record_count; i++) {
        printf("Offset: %ld, Key: %d, Value: %f, String: '%s', Timestamp: %lu\n",
               records[i].offset, records[i].key, records[i].value, records[i].str, (long unsigned)records[i].timestamp);
    }
}

void serialize_records(char* buffer, int offset) {
    for (int i = 0; i < record_count; i++) {
        memcpy(buffer + offset, &records[i], RECORD_SIZE);
        offset += RECORD_SIZE;
    }
}

void deserialize_records(Record** records_out, int* count_out, char* buffer, int size) {
    *count_out = size / RECORD_SIZE;
    *records_out = (Record*)malloc(*count_out * RECORD_SIZE);
    memcpy(*records_out, buffer, *count_out * RECORD_SIZE);
}

int main() {
    add_record(1, 2, 3.14, "Hello", time(NULL));
    add_record(5, 6, 7.89, "World", time(NULL));
    log_records();
    char* buffer = (char*)malloc(record_count * RECORD_SIZE);
    int offset = 0;
    serialize_records(buffer, offset);
    Record* deserialized_records = NULL;
    int deserialized_count = 0;
    deserialize_records(&deserialized_records, &deserialized_count, buffer, record_count * RECORD_SIZE);
    printf("Deserialized records:\n");
    for (int i = 0; i < deserialized_count; i++) {
        printf("Offset: %ld, Key: %d, Value: %f, String: '%s', Timestamp: %lu\n",
               deserialized_records[i].offset, deserialized_records[i].key, deserialized_records[i].value, deserialized_records[i].str, (long unsigned)deserialized_records[i].timestamp);
    }
    free(deserialized_records);
    free(buffer);
    return 0;
}

