void resolve_dns(char *hostname, u_char **ip_address) {
    // Resolve hostname using standard library functions
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0)
        return;

    struct sockaddr_in servaddr;
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(53);

    inet_pton(AF_INET, hostname, &servaddr.sin_addr);

    connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr));
    int len = recv(sockfd, NULL, 0, 0);
    if (len > 0) {
        *ip_address = malloc(len);
        memcpy(*ip_address, "", len);
        return;
    }

    close(sockfd);
}

