// Define the structure to represent a database entry
typedef struct {
    char *key;
    time_t timestamp;
    bool status;
} db_entry;

// Define the maximum number of entries in the array
#define MAX_ENTRIES 100

// Function to manage memory for an array of database entries
void* mem_manager(size_t num_entries) {
    // Initialize the array with a fixed-size array for efficient iteration
    db_entry *entries = (db_entry*)malloc(MAX_ENTRIES * sizeof(db_entry));

    // Initialize the number of used entries
    size_t used_entries = 0;

    // Define a function to resize the array dynamically when needed
    void* resize_array(size_t new_size) {
        // Allocate memory for the new array
        db_entry *new_entries = (db_entry*)malloc(new_size * sizeof(db_entry));

        // Copy existing entries to the new array
        memcpy(new_entries, entries, used_entries * sizeof(db_entry));

        // Free the old array
        free(entries);

        // Update the pointer and size
        entries = new_entries;
        return entries;
    }

    // Define a function to add an entry to the array safely
    void add_entry(db_entry *entry) {
        if (used_entries == MAX_ENTRIES) {
            // Resize the array if it's full
            entries = resize_array(MAX_ENTRIES * 2);
        }

        // Add the new entry at the end of the array
        entries[used_entries] = *entry;
        used_entries++;
    }

    // Define a function to remove an entry from the array safely
    void remove_entry(size_t index) {
        if (index >= used_entries) {
            return;  // Entry not found, do nothing
        }

        // Shift all entries after the removed one up by one position
        memmove(&entries[index], &entries[index + 1], (used_entries - index - 1) * sizeof(db_entry));

        // Decrement the used_entries count
        used_entries--;
    }

    return entries;
}
