} record;

typedef struct node {
    struct node* prev;
    struct node* next;
    record* data;
} node;

node* head = NULL;

// Function to initialize memory and create the doubly linked list
void init(int num_records) {
    if (num_records < 5000 || num_records > 15000) {
        printf("Invalid number of records. Please enter a value between 5,000 and 15,000.\n");
        return;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    long* offsets = (long*)malloc(num_records * sizeof(long));
    record* records = (record*)malloc(num_records * sizeof(record));

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand();
        offsets[i] = i;
        records[i].key = keys[i];
        records[i].value = rand() % 100 + 1;
    }

    // Create the doubly linked list
    node* current = NULL;
    for (int i = 0; i < num_records; i++) {
        node* new_node = (node*)malloc(sizeof(node));
        new_node->prev = current;
        new_node->next = NULL;
        new_node->data = &records[i];
        if (current) {
            current->next = new_node;
        } else {
            head = new_node;
        }
        current = new_node;
    }
}

// Function to update the value of a specific node
void update(int index, int key, int new_value) {
    node* current = head;
    while (current && current->data->key != key) {
        current = current->next;
    }
    if (!current) {
        printf("Node not found.\n");
        return;
    }
    current->data->value = new_value;
}

// Function to find and print the largest integer
void find_largest() {
    int max_value = 0;
    node* current = head;
    while (current) {
        if (current->data->value > max_value) {
            max_value = current->data->value;
        }
        current = current->next;
    }
    printf("Largest integer: %d\n", max_value);
}

// Function to clean up unused records
void cleanup(int threshold) {
    node* current = head;
    while (current) {
        node* next = current->next;
        if (current->data->value < threshold) {
            // Clean up the record
            free(current->data);
            current->prev->next = current->next;
            if (!current->next) {
                head = current->prev;
            }
            free(current);
        } else {
            current = next;
        }
    }
}

// Function to log operations and their outcomes
void log_operation(char* operation, int outcome) {
    // Implement logging mechanism here
}

