        offset_values[i] = (long)i;
        keys[i] = rand() % key_range;
        records[i] = (record_t*)malloc(sizeof(record_t));
        records[i]->key = keys[i];
        records[i]->value = rand() % value_range;

        // Set initial memory usage to 0
        records[i]->offset = offset_values[i];
    }

    // Initialize total memory usage and record count
    size_t total_memory_usage = num_records * sizeof(long) + num_records * sizeof(int) + num_records * sizeof(record_t);
    int record_count = num_records;

    // Set up synchronization mechanisms for concurrent access
    pthread_mutex_init(&record_lock, NULL);

    return records;
}

