    pthread_mutex_lock(&record_lock);

    if (index >= 0 && index < record_count) {
        records[index]->key = new_key;
        records[index]->value = new_value;
    }

    pthread_mutex_unlock(&record_lock);
}

void* resizeRecords(void*) {
    // Monitor memory usage and trigger compaction when threshold is reached
    size_t total_memory_usage = 0;
    for (int i = 0; i < record_count; i++) {
        total_memory_usage += sizeof(long) + sizeof(int) + sizeof(record_t);
    }

    if (total_memory_usage > max_memory_size && num_records > 1) {
        // Compact records array
        record_t** new_records = (record_t**)malloc((num_records / 2) * sizeof(record_t*));
        int offset = 0;
        for (int i = 0; i < num_records; i++) {
            if (i % 2 == 0) {
                new_records[offset++] = records[i];
            }
        }

        // Update total memory usage and record count
        free(records);
        record_count /= 2;
        records = new_records;

        printf("Memory compaction triggered, reducing array size by half.\n");
    }
}

