void create_transaction(int id) {
    if (id >= MAX_TRANSACTIONS) return;

    pthread_mutex_lock(&global_lock);
    transaction* new_transaction = malloc(sizeof(transaction));
    new_transaction->num_records = 0;
    new_transaction->records = NULL;
    new_transaction->timestamp = time(NULL);
    pthread_mutex_init(&new_transaction->lock, NULL);
    new_transaction->last_accessed_record = -1;
    transactions[id] = new_transaction;
    pthread_mutex_unlock(&global_lock);
}

void update_record(int transaction_id, int record_index, int value) {
    pthread_mutex_lock(&transactions[transaction_id]->lock);

    if (record_index >= transactions[transaction_id]->num_records || 
        transactions[transaction_id]->records == NULL) {
        // Handle out-of-range or non-existent record
    }

    transactions[transaction_id]->records[record_index]->value = value;

    transactions[transaction_id]->last_accessed_record = record_index;

    transactions[transaction_id]->log(transactions[transaction_id], 
                                        transactions[transaction_id]->records[record_index]);

    pthread_mutex_unlock(&transactions[transaction_id]->lock);
}

void log_transaction(transaction* t, record* r) {
    // Implement your logging mechanism here
    printf("Transaction %d: Record %d updated to value %d at timestamp %ld\n", 
           t->timestamp, r->value, t->last_accessed_record);
}

void free_transactions() {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transaction* t = transactions[i];

        if (t != NULL) {
            pthread_mutex_lock(&t->lock);

            for (int j = 0; j < t->num_records; j++) {
                free(t->records[j]->timestamp);
                free(t->records[j]);
            }

            free(t->records);
            free(t);
            pthread_mutex_unlock(&t->lock);
        }
    }
