#include <string.h>
#include <pthread.h>

// Define a structure to hold node information
typedef struct {
    int value;
    struct node* next;
} Node;

// Function to initialize and manage linked list
void* initializeLinkedList() {
    // Allocate memory for arrays
    double* arrDouble = malloc(sizeof(double) * 10);
    char** arrChar = malloc(sizeof(char*) * 10);
    Node** arrNode = malloc(sizeof(Node*) * 10);

    // Initialize arrays
    for (int i = 0; i < 10; i++) {
        arrDouble[i] = 0.0;
        arrChar[i] = NULL;
        arrNode[i] = NULL;
    }

    return (void*)arrDouble;
}

// Function to insert node at arbitrary position in linked list
void insertNode(Node** head, int value) {
    Node* newNode = malloc(sizeof(Node));
    newNode->value = value;

    if (*head == NULL || value < (*head)->value) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL && temp->next->value >= value) {
            temp = temp->next;
        }
        newNode->next = temp->next;
        temp->next = newNode;
    }
}

// Function to delete node at arbitrary position in linked list
void deleteNode(Node** head, int value) {
    if (*head == NULL)
        return;

    Node* temp = *head;
    while (temp->next != NULL && temp->next->value != value) {
        temp = temp->next;
    }
    if (temp->next != NULL) {
        Node* toDelete = temp->next;
        temp->next = toDelete->next;
        free(toDelete);
    } else {
        *head = (*head)->next;
    }
}

// Function to print linked list
void printLinkedList(Node* head) {
    while (head != NULL) {
        printf("%d ", head->value);
        head = head->next;
    }
    printf("\n");
}

int main() {
    // Initialize linked list
    Node* head = NULL;

    while (1) {
        int choice;
        printf("Enter 1 to insert node, 2 to delete node, 3 to print linked list: ");
        scanf("%d", &choice);

        if (choice == 1) {
            int value;
            printf("Enter value for new node: ");
            scanf("%d", &value);
            insertNode(&head, value);
        } else if (choice == 2) {
            int value;
            printf("Enter value of node to delete: ");
            scanf("%d", &value);
            deleteNode(&head, value);
        } else if (choice == 3) {
            printLinkedList(head);
        } else {
            break;
        }
    }

    return 0;
}
