#include <time.h>
#include <pthread.h>

#define MAX_CHUNKS 10000
#define MAX_BYTE_LIMIT (1024 * 1024 * 10) // 10MB

typedef struct {
    long value;
    time_t timestamp;
} DataChunk;

DataChunk* chunks = NULL;
int chunk_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_access[MAX_CHUNKS];

void init_chunks() {
    pthread_mutex_lock(&lock);
    if (chunk_count == 0) {
        chunks = (DataChunk*)malloc(MAX_BYTE_LIMIT);
        for (int i = 0; i < MAX_CHUNKS; i++) {
            last_access[i] = time(NULL);
            chunks[i].value = 0;
            chunks[i].timestamp = time(NULL);
        }
    }
    pthread_mutex_unlock(&lock);
}

void update_chunk(int idx, long value) {
    pthread_mutex_lock(&lock);
    if (idx < MAX_CHUNKS && idx >= 0) {
        chunks[idx].value = value;
        last_access[idx] = time(NULL);
    }
    pthread_mutex_unlock(&lock);
}

long get_largest_value() {
    long max_val = 0;
    for (int i = 0; i < chunk_count; i++) {
        if (chunks[i].value > max_val) {
            max_val = chunks[i].value;
        }
    }
    return max_val;
}

void evict_least_recently_used() {
    pthread_mutex_lock(&lock);
    int idx = -1;
    time_t min_timestamp = time(NULL);
    for (int i = 0; i < chunk_count; i++) {
        if (last_access[i] <= min_timestamp) {
            min_timestamp = last_access[i];
            idx = i;
        }
    }
    if (idx != -1) {
        free(&chunks[idx]);
        chunks[idx].value = 0;
        last_access[idx] = time(NULL);
    }
    pthread_mutex_unlock(&lock);
}

void* read_thread(void* arg) {
    int num_reads = *((int*)arg);
    for (int i = 0; i < num_reads; i++) {
        int val = rand() % MAX_CHUNKS;
        update_chunk(val, val * val);
    }
    pthread_exit(NULL);
}

int main() {
    pthread_t read_thread_id;
    int num_reads = 10000;

    init_chunks();

    pthread_create(&read_thread_id, NULL, read_thread, &num_reads);

    for (int i = 0; i < num_reads; i++) {
        int val = rand() % MAX_CHUNKS;
        update_chunk(val, val * val);
    }

    evict_least_recently_used();

    pthread_join(read_thread_id, NULL);

    return 0;
}

