#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure representing a single message
typedef struct {
    char* text;
    int timestamp;
} Message;

// Circular buffer to store messages
Message** buffer;
int capacity = 100; // Default capacity of the circular buffer
int front = 0, rear = 0;
int size = 0;
int max_size = 0;

// Maximum allowed memory usage in bytes
int max_memory = 1048576; // 1MB

// Lock for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Allocate and initialize the buffer
void init_buffer() {
    buffer = (Message**)malloc(capacity * sizeof(Message*));
    max_size = capacity;
}

// Add a new message to the circular buffer
void add_message(Message* msg) {
    pthread_mutex_lock(&mutex);

    if (size >= max_size) {
        // Resize the buffer when it reaches its maximum size
        capacity *= 2;
        Message** temp = (Message**)malloc(capacity * sizeof(Message*));
        memcpy(temp, buffer, max_size * sizeof(Message*));

        free(buffer);
        buffer = temp;

        max_size = capacity;
    }

    buffer[rear] = msg;
    rear = (rear + 1) % max_size;
    size++;

    pthread_mutex_unlock(&mutex);
}

// Get a message from the circular buffer based on its timestamp
Message* get_message(int timestamp) {
    pthread_mutex_lock(&mutex);

    for (int i = front; i != rear; i = (i + 1) % max_size) {
        if (buffer[i]->timestamp == timestamp) {
            Message* msg = buffer[i];
            buffer[i] = NULL;
            size--;
            return msg;
        }
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Search for messages containing a specific keyword
Message* search_messages(char* keyword) {
    pthread_mutex_lock(&mutex);

    for (int i = front; i != rear; i = (i + 1) % max_size) {
        if (buffer[i]->text != NULL && strstr(buffer[i]->text, keyword) != NULL) {
            Message* msg = buffer[i];
            buffer[i] = NULL;
            size--;
            return msg;
        }
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Periodically flush outdated messages
void flush_messages() {
    pthread_mutex_lock(&mutex);

    for (int i = front; i != rear; i = (i + 1) % max_size) {
        if (buffer[i]->timestamp < 0) { // Marked as outdated
            buffer[i] = NULL;
            size--;
        }
    }

    pthread_mutex_unlock(&mutex);
}

// Process incoming messages from the network socket
void process_messages(Message* msg) {
    add_message(msg);

    // Flush outdated messages periodically
    if (size > max_size / 2) { // Adjust the threshold as needed
        flush_messages();
    }
}
