#include <semaphore.h>

#define MAX_SEMAPHORES 100
#define MAX_THREADS 10
#define SEM_NAME "my_semaphore"
#define LOG_FILE "semaphore_usage.log"

sem_t *semaphores;
int semaphore_values[MAX_SEMAPHORES];
int current_operations = 0;

void init_semaphores(int num_semaphores) {
    semaphores = (sem_t *)malloc(num_semaphores * sizeof(sem_t));
    for (int i = 0; i < num_semaphores; i++) {
        semaphore_values[i] = i + 1;
        if (sem_init(&semaphores[i], 1, semaphore_values[i]) == -1) {
            perror("sem_init");
            exit(1);
        }
    }
}

void delete_semaphores(int num_semaphores) {
    for (int i = 0; i < num_semaphores; i++) {
        if (sem_destroy(&semaphores[i]) == -1) {
            perror("sem_destroy");
            exit(1);
        }
    }
    free(semaphores);
}

void* semaphore_manager(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        sem_wait(&semaphores[i]);
        // Perform operations on the semaphore
        printf("Thread %d: Operating on semaphore %d\n", thread_id, i);
        current_operations++;
        if (current_operations >= MAX_OPERATIONS_PER_SEMAPHORE) {
            // Reset the semaphore
            sem_post(&semaphores[i]);
            current_operations = 0;
        }
    }
    return NULL;
}

int main() {
    int num_semaphores = 100;
    init_semaphores(num_semaphores);

    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, semaphore_manager, &i);
    }

    // Perform operations on the semaphores
    for (int i = 0; i < num_semaphores; i++) {
        if (sem_getvalue(&semaphores[i], &value) == -1) {
            perror("sem_getvalue");
            exit(1);
        }
        printf("Semaphore %d: Value = %d\n", i, value);
    }

    // Clean up
    delete_semaphores(num_semaphores);

    return 0;
}
```

