void initRecordSystem(int max_size, int limit) {
    // Allocate memory for offset array with size determined by largest key divided by 1.5, rounded up
    int offset_size = (max_size / 1.5) + 1;
    int* offsets = (int*)malloc(offset_size * sizeof(int));

    // Initialize record array with specified size and random values
