    for (int i = 0; i < max_size; i++) {
        records[i].value = rand() % 1000 + 1;
        memset(records[i].data, 'A' + (rand() % 26), 9);
        records[i].data[9] = '\0';
    }

    // Initialize key array with size to store up to 100 unique integer keys
    int* keys = (int*)malloc(100 * sizeof(int));
    for (int i = 0; i < 100; i++) {
        keys[i] = -1;
    }

    // Mutex lock to ensure thread safety when updating record values
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize offset array with all zeros
    memset(offsets, 0, offset_size * sizeof(int));
}

// Function to dynamically allocate memory for records based on input integers
void allocateRecords(int* ints, int size) {
    // Read list of integers from standard input
    for (int i = 0; i < size; i++) {
        scanf("%d", &ints[i]);
    }

    // Dynamically allocate memory for records based on input integers
    Record* head = NULL;
    Record* tail = NULL;
    for (int i = 0; i < size; i++) {
        int value = ints[i];
        if (value > 100) {
            printf("Invalid input: %d. Skipping.\n", value);
            continue;
        }

        // Allocate memory for new record
        Record* new_record = (Record*)malloc(sizeof(Record));
        new_record->value = value;
        memset(new_record->data, 'A' + (rand() % 26), 9);
        new_record->data[9] = '\0';

        // Add new record to linked list
        if (!head) {
            head = new_record;
            tail = new_record;
        } else {
            tail->next = new_record;
            tail = new_record;
        }
    }

    printf("Records allocated successfully.\n");
}

int main() {
    int max_size, limit;
    printf("Enter maximum size for record system: ");
    scanf("%d", &max_size);
    printf("Enter memory usage limit in bytes: ");
    scanf("%d", &limit);

    initRecordSystem(max_size, limit);

    int size;
    printf("Enter number of integers to read: ");
    scanf("%d", &size);
    int* ints = (int*)malloc(size * sizeof(int));
    allocateRecords(ints, size);

    free(ints);
    return 0;
}

