```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 15000
#define BUFFER_SIZE 256
#define OFFSET_TYPE long
#define KEY_TYPE int
#define VALUE_TYPE int

typedef struct node {
    struct node* prev;
    struct node* next;
    OFFSET_TYPE offset;
    KEY_TYPE key;
    VALUE_TYPE value;
} Node;

Node* create_node(OFFSET_TYPE offset, KEY_TYPE key, VALUE_TYPE value) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    new_node->prev = NULL;
    new_node->next = NULL;
    new_node->offset = offset;
    new_node->key = key;
    new_node->value = value;
    return new_node;
}

void free_nodes(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

int find_largest_value(Node* head, int key) {
    Node* current = head;
    int largest_value = INT_MIN;
    while (current != NULL && current->key < key) {
        if (current->value > largest_value) {
            largest_value = current->value;
        }
        current = current->next;
    }
    return largest_value;
}

int main() {
    // Read integers from standard input and store in an array
    int num_records;
    scanf("%d", &num_records);
    int* values = (int*) malloc(num_records * sizeof(int));
    for (int i = 0; i < num_records; i++) {
        scanf("%d", &values[i]);
    }

    // Find and print the largest integer
    Node* head = NULL;
    for (int i = 0; i < num_records; i++) {
        Node* new_node = create_node(i, values[i], values[i]);
        if (head == NULL) {
            head = new_node;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
            new_node->prev = current;
        }
    }

    int largest_value = find_largest_value(head, values[0]);
    printf("The largest value is: %d\n", largest_value);

    // Clean up memory
    free_nodes(head);
    free(values);

    return 0;
}
