            doCommand(key);
            return 0;
        } else if (pid > 0) {
            // Parent process
            int status;
            waitpid(pid, &status, 0);
            return WEXITSTATUS(status);
        } else {
            // Error handling
            std::cerr << "Error executing command: fork failed" << std::endl;
            return -1;
        }
