void serialize(Record* records, int size) {
    FILE* file = fopen("records.bin", "wb");
    fwrite(records, sizeof(Record), size, file);
    fclose(file);
}

Record* deserialize() {
    Record* records = NULL;
    FILE* file = fopen("records.bin", "rb");
    if (file != NULL) {
        fseek(file, 0, SEEK_END);
        int size = ftell(file) / sizeof(Record);
        records = (Record*)malloc(size * sizeof(Record));
        rewind(file);
        fread(records, sizeof(Record), size, file);
        fclose(file);
    }
    return records;
}

void clear_memory(Record* records, int size) {
    free(records);
}
