#include <stdlib.h>
#include <stdio.h>

typedef struct {
    long timestamp;
    int priority;
} record;

record* add_record(record** list, long timestamp, int priority) {
    record* new_rec = (record*)malloc(sizeof(record));
    new_rec->timestamp = timestamp;
    new_rec->priority = priority;

    if (*list == NULL || timestamp < (*list)->timestamp) {
        record* temp = *list;
        *list = new_rec;
        new_rec = temp;
    } else {
        record** prev = list;
        while (*prev && (*prev)->timestamp <= timestamp) {
            prev = &(*prev)->next;
        }
        new_rec->next = *prev;
        *prev = new_rec;
    }

    return new_rec;
}

record* update_record(record** list, long timestamp, int priority) {
    record* current = *list;
    while (current && current->timestamp <= timestamp) {
        if (current->timestamp == timestamp) {
            current->priority = priority;
            break;
        }
        current = current->next;
    }

    return current;
}

record* get_record_by_priority(record** list, int threshold) {
    record* current = *list;
    while (current && current->priority <= threshold) {
        current = current->next;
    }

    if (current == NULL || current->priority > threshold)
        return NULL;

    return current;
}

void free_list(record** list) {
    record* current = *list;
    record* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *list = NULL;
}
