```java
import java.util.concurrent.atomic.AtomicReferenceFieldUpdater;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class TimestampedList {
    private static final int INITIAL_CAPACITY = 16;
    private static final int RESIZE_FACTOR = 2;

    private static class Record {
        long timestamp;
        int priority;
    }

    private static class Node {
        Record record;
        Node next;

        public Node(Record record) {
            this.record = record;
            this.next = null;
        }
    }

    private volatile Node head;
    private volatile Node tail;
    private volatile int size;
    private final Lock lock = new ReentrantLock();
    private final AtomicReferenceFieldUpdater<Node, Record> recordUpdater = 
            AtomicReferenceFieldUpdater.newUpdate(Node.class, Record.class);

    public TimestampedList() {
        head = new Node(null);
        tail = head;
        size = 0;
    }

    public void add(Record record) {
        lock.lock();
        try {
            Node newNode = new Node(record);
            if (size == 0) {
                head.record = record;
                tail = newNode;
            } else {
                tail.next = newNode;
                tail = newNode;
            }
            size++;
            if (size >= INITIAL_CAPACITY * RESIZE_FACTOR) {
                resize();
            }
        } finally {
            lock.unlock();
        }
    }

    public void update(long timestamp, int priority) {
        lock.lock();
        try {
            Node current = head;
            while (current != null) {
                if (current.record.timestamp <= timestamp) {
                    break;
                }
                current = current.next;
            }
            current.record.priority = priority;
        } finally {
            lock.unlock();
        }
    }

    public Record getFirstPriority(int threshold) {
        Node current = head;
        while (current != null && current.record.priority <= threshold) {
            current = current.next;
        }
        if (current == null) return null;
        return current.record;
    }

    public int getSize() {
        return size;
    }

    private void resize() {
        lock.lock();
        try {
            Node[] nodes = new Node[INITIAL_CAPACITY * RESIZE_FACTOR];
            for (Node current = head; current != null; current = current.next) {
                nodes[size] = current;
                size++;
            }
            head = nodes[0];
            tail = nodes[size - 1];
        } finally {
            lock.unlock();
        }
    }
}
