void add_transaction(Transaction* transaction) {
    pthread_mutex_lock(&lock);
    transactions[transaction_count] = transaction;
    transaction_count++;
    pthread_mutex_unlock(&lock);
}

Transaction* get_transaction(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i]->id == id) {
            Transaction* result = transactions[i];
            pthread_mutex_unlock(&lock);
            return result;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void update_transaction(int id, float new_amount) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i]->id == id) {
            transactions[i]->amount = new_amount;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void clean_up_transactions() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i]->status == 1) { // status flag indicating transaction is complete
            free(transactions[i]);
        }
    }
    transaction_count = 0;
    pthread_mutex_unlock(&lock);
}

