typedef struct {
    int offset;
    int key;
    int value;
} record;

typedef struct node {
    struct node* prev;
    struct node* next;
    record rec;
} node;

node* create_node(int offset, int key) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    new_node->prev = NULL;
    new_node->next = NULL;
    new_node->rec.offset = offset;
    new_node->rec.key = key;
    return new_node;
}

void insert_node(node** head, node* new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }
    node* current = *head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
    new_node->prev = current;
}

void free_nodes(node* head) {
    node* temp = head;
    while (temp) {
        node* next = temp->next;
        free(temp);
        temp = next;
    }
}

int find_largest(int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void update_node(node** head, node* target, int new_value) {
    target->rec.value = new_value;
}

node* find_node(node* head, int key) {
    node* current = head;
    while (current) {
        if (current->rec.key == key)
            return current;
        current = current->next;
    }
    return NULL;
}

void print_nodes(node* head) {
    node* current = head;
    while (current) {
        printf("Offset: %d, Key: %d, Value: %d\n", current->rec.offset, current->rec.key, current->rec.value);
        current = current->next;
    }
}

void process_dataset(node** head, int num_records, int max_value) {
    node* current = *head;
    for (int i = 0; i < num_records; i++) {
        int offset = rand() % (max_value + 1);
        int key = rand() % (max_value + 1);
        record rec;
        rec.offset = offset;
        rec.key = key;
        rec.value = rand() % (max_value + 1);
        node* new_node = create_node(offset, key);
        insert_node(head, new_node);
    }
}

void handle_input(int num_records) {
    int arr[num_records];
    for (int i = 0; i < num_records; i++) {
        scanf("%d", &arr[i]);
    }
    printf("Largest integer: %d\n", find_largest(arr, num_records));
}

void run_system() {
    srand(time(NULL));
    node* head = NULL;
    int num_records = rand() % (15000 - 5000 + 1) + 5000;
    process_dataset(&head, num_records, 256);
    handle_input(num_records);
    free_nodes(head);
}
