// Function to process file and extract unique words along with their frequency counts
void handleFileProcessing(const char *filePath) {
    // Initialize variables
    int fileSize = 0;
    FILE *file = fopen(filePath, "r");

    if (!file) {
        printf("Error opening file: %s\n", filePath);
        return;
    }

    fseek(file, 0L, SEEK_END);
    fileSize = ftell(file);
    rewind(file);

    // Dynamically allocate memory for the buffer
    char *buffer = (char *)malloc(BUFFER_SIZE * sizeof(char));

    if (!buffer) {
        printf("Memory allocation failed\n");
        fclose(file);
        return;
    }

    int bytesRead = 0;
    int wordCount = 0;

    while ((bytesRead = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        // Process the buffer contents
        char *token = strtok(buffer, " ");

        while (token != NULL) {
            token++;

            if (*token == '\0') {
                break;
            }

            int i = 0;
            bool wordFound = false;

            for (int j = 0; j < wordCount; ++j) {
                if (strcmp(token, words[j]) == 0) {
                    words[j].count++;
                    wordFound = true;
                    break;
                }
            }

            if (!wordFound) {
                strcpy(words[wordCount].word, token);
                words[wordCount].count = 1;
                wordCount++;
            }
        }
    }

    fclose(file);

    // Print the top five most frequent words
    for (int i = 0; i < wordCount && i < 5; ++i) {
        printf("Word: %s, Frequency: %d\n", words[i].word, words[i].count);
    }
}

// Define a struct to store unique words and their frequency counts
typedef struct {
    char *word;
    int count;
} Word;

// Array of 5 elements for storing unique words and their frequency counts
Word words[5];
