    double key;
    Node* node;
} Entry;

// Array of Node pointers
Node** nodes;

// Linked list of Elements
Element* elements = NULL;
pthread_mutex_t elements_lock = PTHREAD_MUTEX_INITIALIZER;

// Hash table of Entries
Entry** entries;
int entries_size = 0;
pthread_mutex_t entries_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize the library
void lib_init(int num_nodes) {
    nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = NULL;
    }
}

// Insert a Node into the linked list and hash table
void node_insert(float value, char* str, int val) {
    pthread_mutex_lock(&elements_lock);
    Element* new_element = (Element*)malloc(sizeof(Element));
    new_element->value = value;
    new_element->next = elements;
    elements = new_element;
    pthread_mutex_unlock(&elements_lock);

    pthread_mutex_lock(&entries_lock);
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    new_entry->key = val;
    new_entry->node = nodes[val];
    int index = val % entries_size;
    if (!entries[index]) {
        entries[index] = &new_entry;
    } else {
        Entry* prev = entries[index];
        while (prev->next) {
            prev = prev->next;
        }
        prev->next = new_entry;
    }
    pthread_mutex_unlock(&entries_lock);
}

// Update a Node in the linked list and hash table
void node_update(int val, char* str, int new_val) {
    pthread_mutex_lock(&elements_lock);
    Element* current = elements;
    while (current) {
        if (((Node*)current)->val == val) {
            ((Node*)current)->str = str;
            ((Node*)current)->val = new_val;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&elements_lock);

    pthread_mutex_lock(&entries_lock);
    for (int i = 0; i < entries_size; i++) {
        if (entries[i]->key == val) {
            entries[i]->node->str = str;
            entries[i]->node->val = new_val;
            break;
        }
    }
    pthread_mutex_unlock(&entries_lock);
}

// Free memory
void lib_free() {
    pthread_mutex_lock(&elements_lock);
    Element* current = elements;
    while (current) {
        Element* next = current->next;
        free(current);
        current = next;
    }
    elements = NULL;
    pthread_mutex_unlock(&elements_lock);

    pthread_mutex_lock(&entries_lock);
    for (int i = 0; i < entries_size; i++) {
        if (entries[i]) {
            Entry* entry = entries[i];
            while (entry) {
                Entry* next = entry->next;
                free(entry);
                entry = next;
            }
        }
        free(entries[i]);
    }
    for (int i = 0; i < entries_size; i++) {
        free(&entries[i]);
    }
    pthread_mutex_unlock(&entries_lock);

    free(nodes);
}
