void init_memory() {
    // Initialize circular buffer
    circular_buffer = (Frame*)malloc(frame_size * sizeof(Frame));
    num_frames = 0;

    // Initialize hash table
    entries = (Entry**)malloc(entry_capacity * sizeof(Entry*));
