void handleFileProcessing(char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    char buffer[1024];
    int fileSize = 0;

    fseek(file, 0, SEEK_END);
    fileSize = ftell(file);

    rewind(file);

    size_t allocatedBytes = 0;
    char* fileContent = NULL;

    while (fread(buffer, 1, 1024, file) > 0) {
        if (allocatedBytes == 0) {
            allocatedBytes = sizeof(char) * 1048576; // 1 MB
            fileContent = (char*)malloc(allocatedBytes);
        } else {
            allocatedBytes *= 2;
            fileContent = (char*)realloc(fileContent, allocatedBytes);
        }

        memcpy(fileContent + fileSize, buffer, fread(buffer, 1, 1024, file));
        fileSize += 1024;
    }

    fclose(file);

    if (fileSize == 0) {
        printf("No valid words found.\n");
        return;
    }

    // Process the file content here
    // ...

    free(fileContent);
}

