class ProductRequestHandler:
    def __init__(self):
        self.cache = {}
        self.lock = Lock()
        self.log_file = open('product_requests.log', 'a')

    def validate_request(self, request):
        # Validate the JSON payload
        return True

    def handle_sub_action(self, sub_action):
        if sub_action == 'create':
            # Handle create action
            pass
        elif sub_action == 'update':
            # Handle update action
            pass
        elif sub_action == 'delete':
            # Handle delete action
            pass
        elif sub_action == 'fetch_by_category':
            # Handle fetch by category action
            pass

    def log_request(self, request):
        self.log_file.write(f"{datetime.now()}: {request}\n")
        self.log_file.flush()

    @wraps(handle_sub_action)
    def handle_request(self, request):
        if not self.validate_request(request):
            return "Invalid request"

        sub_action = request.get('sub_action')
        if sub_action:
            self.handle_sub_action(sub_action)

        product_id = request.get('product_id')
        if product_id and product_id not in self.cache:
            # Cache miss
            if len(self.cache) >= CACHE_SIZE:
                # Evict least recently used item from cache
                oldest_key = min(self.cache, key=self.cache.get)
                del self.cache[oldest_key]
            self.cache[product_id] = request

        self.log_request(request)

    def run(self):
        while True:
            request = json.loads(input())
            self.handle_request(request)

# Example usage
