// Define a structure to hold record data
typedef struct {
    int key;
    long offset;
} Record;

// Function to dynamically allocate memory for an array of 'record' structures
void* allocate_records(int num_records, int range_min, int range_max) {
    void* records = malloc(num_records * sizeof(Record));
    if (!records) {
        // Handle allocation failure
        return NULL;
    }

    // Initialize record data with random numbers within the specified range
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*) ((char*) records + i * sizeof(Record));
        record->key = rand() % (range_max - range_min) + range_min;
        record->offset = rand() % (range_max - range_min) + range_min;
    }

    return records;
}

// Function to serialize the records into a binary format and persist them to disk
void serialize_records(void* records, int num_records, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Handle file opening failure
        return;
    }

    fwrite(records, sizeof(Record), num_records, file);
    fclose(file);
}

// Function to verify the integrity of the data upon deserialization
int deserialize_records(void* records, int num_records, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        // Handle file opening failure
        return 0;
    }

    Record* record = (Record*) malloc(num_records * sizeof(Record));
    fread(record, sizeof(Record), num_records, file);
    fclose(file);

    // Verify the integrity of the data
    for (int i = 0; i < num_records; i++) {
        if (record[i].key < 0 || record[i].offset < 0) {
            // Data corruption detected
            return 0;
        }
    }

    free(record);
    return 1;
}

// Example usage
int main() {
    int num_records = 1000;
    int range_min = 1;
    int range_max = 100;

    void* records = allocate_records(num_records, range_min, range_max);

    // Use the records array...

    char filename[] = "records.bin";
    serialize_records(records, num_records, filename);

    // Verify the integrity of the data...
    if (deserialize_records(records, num_records, filename)) {
        printf("Data integrity verified.\n");
    } else {
        printf("Data corruption detected. Aborting...\n");
    }

    free(records);
    return 0;
}
