    Polygon *poly = (Polygon*)malloc(sizeof(Polygon));
    polygon_init(poly);

    poly->points = (Point*)calloc(max_num_points, sizeof(Point));
    poly->colors = (Color*)calloc(max_num_colors, sizeof(Color));
    poly->color_transitions = (int**)calloc(max_num_color_transitions, sizeof(int*));

    return poly;
}

void polygon_free(Polygon *poly) {
    free(poly->points);
    free(poly->colors);
    for (int i = 0; i < poly->num_color_transitions; i++) {
        free(poly->color_transitions[i]);
    }
    free(poly->color_transitions);
    free(poly);
}

void polygon_add_point(Polygon *poly, Point new_point) {
    if (poly->num_points >= poly->points->num_points - 1) {
        int* temp = (int*)realloc(poly->points, sizeof(Point) * (poly->num_points + 5));
        poly->points = temp;
    }
    poly->points[poly->num_points++] = new_point;
}

void polygon_remove_point(Polygon *poly, int index) {
    if (index >= poly->num_points) return;

    Point* temp = (Point*)malloc(sizeof(Point) * (poly->num_points - 1));
    for (int i = 0; i < index; i++) {
        temp[i] = poly->points[i];
    }
    for (int i = index; i < poly->num_points - 1; i++) {
        temp[i] = poly->points[i + 1];
    }
    free(poly->points);
    poly->points = temp;
    poly->num_points--;
}

void polygon_update_point(Polygon *poly, int index, Point new_point) {
    if (index >= poly->num_points) return;

    poly->points[index] = new_point;
