    try:
        json_data = request.get_json()
        user_id = json_data.get('user_id')
        username = json_data.get('username')
        email = json_data.get('email')
        role = json_data.get('role')
        session_expiration = int(json_data.get('session_expiration'))
        last_activity = int(json_data.get('last_activity'))
        sub_action = json_data.get('sub_action')

        if sub_action == 'create':
            create_session(user_id, username, email, role)
        elif sub_action == 'update':
            update_session(user_id, session_expiration, last_activity)
        elif sub_action == 'logout':
            logout_session(user_id)
        elif sub_action == 'retrieve':
            return retrieve_sessions()
    except Exception as e:
        print(f"Error occurred: {e}")
        return jsonify({'error': str(e)}), 500

def create_session(user_id, username, email, role):
    try:
        session_id = generate_unique_id()
        sessions[session_id] = {'user_id': user_id, 'username': username, 'email': email, 'role': role}
        usernames.append(username)
        session_ids.append(session_id)
        last_activity_timestamps.append(int(random.random() * 1000))
    except Exception as e:
        print(f"Error occurred: {e}")

def update_session(user_id, session_expiration, last_activity):
    try:
        for session in sessions.values():
            if session['user_id'] == user_id:
                session['session_expiration'] = session_expiration
                session['last_activity'] = last_activity
                break
    except Exception as e:
        print(f"Error occurred: {e}")

def logout_session(user_id):
    try:
        for i, session in enumerate(list(sessions.values())):
            if session['user_id'] == user_id:
                del sessions[session_ids[i]]
                usernames.pop(i)
                session_ids.pop(i)
                last_activity_timestamps.pop(i)
                break
    except Exception as e:
        print(f"Error occurred: {e}")

def retrieve_sessions():
    try:
        return jsonify({k: v for k, v in sessions.items()})
    except Exception as e:
        print(f"Error occurred: {e}")
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
