void* alloc_packet() {
    data_packet* packet = (data_packet*)malloc(sizeof(data_packet));
    if (!packet) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return packet;
}

void deallocate_packets() {
    for (int i = 0; i < packet_count; i++) {
        free(packets[i]->str);
        free(packets[i]);
    }
    free(packets);
    packets = NULL;
}

void* alloc_str(int len) {
    char* str = (char*)malloc(len + 1);
    if (!str) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return str;
}

int main() {
    pthread_t thread;

    // Initialize logging
    init_log(STDOUT_FILENO);

    // Main loop
    while (1) {
        // Thread-safe packet allocation
        data_packet** new_packets = (data_packet**)realloc(packets, sizeof(data_packet*) * ++packet_count);
        if (!new_packets) {
            printf("Memory reallocation failed!\n");
            deallocate_packets();
            break;
        }
        packets = new_packets;

