#include <iostream>
#include <string>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <fstream>
#include <sstream>
#include <json/json.h>

using namespace std;
using namespace json;

class ConfigManager {
public:
    ConfigManager(size_t size) : config_(size), cache_(size), lock_() {}

    void put(const string& key, const Value& value) {
        unique_lock<mutex> lk(lock_);
        if (config_.find(key) != config_.end()) {
            // Update existing entry
            config_[key] = value;
        } else {
            // New entry
            config_[key] = value;
        }
        cache_.insert({ key, value });
    }

    Value get(const string& key) {
        unique_lock<mutex> lk(lock_);
        if (config_.find(key) != config_.end()) {
            return config_[key];
        } else {
            // Check cache
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                return it->second;
            }
        }
        return Value(); // Not found
    }

    void del(const string& key) {
        unique_lock<mutex> lk(lock_);
        config_.erase(key);
        cache_.erase(key);
    }

    void save(const string& filename) {
        ofstream file(filename);
        if (!file) {
            cerr << "Failed to open " << filename << endl;
            return;
        }
        file << "{\"config\": " << to_string(config_) << ", \"cache\": " << to_string(cache_) << "}";
        file.close();
    }

    void load(const string& filename) {
        ifstream file(filename);
        if (!file) {
            cerr << "Failed to open " << filename << endl;
            return;
        }
        string line, json;
        while (getline(file, line)) {
            json += line + "\n";
        }
        Json::Value root = Json::parse(json);
        for (auto& entry : root["config"].asArray()) {
            put(entry.asString(), entry.asObject());
        }
    }

private:
    unordered_map<string, Value> config_;
    unordered_map<string, Value> cache_;
    mutex lock_;
};

int main() {
    ConfigManager config(10000);

    // Load configuration from file
    config.load("config.json");

    // Update configuration
    config.put("key1", 123);
    config.put("key2", "hello");

    // Query configuration
    Value val = config.get("key1");
    cout << "Value for key 'key1': " << val.asInt() << endl;

    // Save configuration to file
    config.save("config.json");

    return 0;
}

