#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 10000
#define MAX_RECORDS 10
#define MEMORY_LIMIT 1024000000 //1GB

typedef struct Node {
    int value;
    long offset;
    int key;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_nodes = 0;
int memory_usage = 0;

void* allocate_node(int* value, int* offset, int* key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; //handle allocation failure
    new_node->value = *value;
    new_node->offset = *offset;
    new_node->key = *key;
    new_node->prev = NULL;
    new_node->next = NULL;
    pthread_mutex_lock(&lock);
    new_node->prev = head;
    if (head) head->next = new_node;
    else head = new_node;
    pthread_mutex_unlock(&lock);
    num_nodes++;
    memory_usage += sizeof(Node);
    return (void*)new_node;
}

void free_node(Node* node) {
    pthread_mutex_lock(&lock);
    if (node->prev) node->prev->next = node->next;
    else head = node->next;
    if (node->next) node->next->prev = node->prev;
    pthread_mutex_unlock(&lock);
    num_nodes--;
    memory_usage -= sizeof(Node);
}

void print_largest() {
    Node* curr = head;
    int max_value = INT_MIN;
    while (curr) {
        if (curr->value > max_value) max_value = curr->value;
        curr = curr->next;
    }
    printf("Largest integer: %d\n", max_value);
}

void print_second_largest() {
    Node* curr = head;
    int max_value = INT_MIN;
    int second_max_value = INT_MIN;
    while (curr) {
        if (curr->value > max_value) {
            second_max_value = max_value;
            max_value = curr->value;
        } else if (curr->value > second_max_value && curr->value != max_value)
            second_max_value = curr->value;
        curr = curr->next;
    }
    printf("Second-largest integer: %d\n", second_max_value);
    if (second_max_value == INT_MIN) printf("No distinct second-largest integer found.\n");
}

int main() {
    // read input integers from standard input or CSV file
    int values[MAX_RECORDS];
    int num_values = 0;
    FILE* file = fopen("input.csv", "r"); // replace with your file name and mode
    if (file) {
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            int value = 0;
            if (sscanf(line, "%d", &value) == 1 && value >= 0 && value < 10000000)
                values[num_values++] = value;
        }
        fclose(file);
    } else {
        printf("Please enter integers separated by spaces:\n");
        int i = 0;
        while (i < MAX_RECORDS && scanf("%d", &values[i]) == 1) i++;
    }

    if (!num_values) {
        printf("No valid integers found.\n");
        return 1;
    }

    // initialize memory for the system
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_values; i++) {
        Node* node = allocate_node(&values[i], i, values[i]);
        if (!node) printf("Memory allocation failure. System will continue operating.\n");
    }
    pthread_mutex_unlock(&lock);

    print_largest();
    print_second_largest();

    return 0;
}
