typedef struct {
    char* str;
    int num;
    int flag;
} Item;

Item** item_table = NULL;
int table_size = 0;

void init_item_table(int size) {
    table_size = size;
    item_table = (Item**)malloc(table_size * sizeof(Item*));
}

void free_item_table() {
    for (int i = 0; i < table_size; i++) {
        if (item_table[i] != NULL) {
            Item* current = item_table[i];
            while (current != NULL) {
                Item* next = current->str;
                free(current);
                current = next;
            }
        }
    }
    free(item_table);
}

Item* create_item(char* str, int num, int flag) {
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (new_item == NULL) {
        return NULL;  // Memory allocation failed
    }

    new_item->str = strdup(str);
    if (new_item->str == NULL) {
        free(new_item);  // Freeing the item structure and its string
        return NULL;  // String memory allocation failed
    }
    new_item->num = num;
    new_item->flag = flag;

    return new_item;
}

void insert_item(int index, Item* item) {
    if (index >= table_size) {
        printf("Error: Index out of range.\n");
        return;  // Return without inserting the item
    }

    for (int i = table_size - 1; i > index; i--) {
        item_table[i] = item_table[i-1];
    }
    item_table[index] = item;
}

void print_item(Item* item) {
    printf("Item: %s, Number: %d, Flag: %d\n", item->str, item->num, item->flag);
}
