// Structure representing a record
typedef struct {
    int value;
} record;

record* initialize_records(long** offset_array, int** key_array, int num_offsets, int num_keys) {
    // Calculate the total number of records
    int num_records = num_offsets * num_keys;

    // Allocate memory for the record array
    record* record_array = (record*)malloc(num_records * sizeof(record));

    if (!record_array) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize each record using a configurable formula
    for (int i = 0; i < num_offsets; i++) {
        long offset = (*offset_array)[i];
        for (int j = 0; j < num_keys; j++) {
            int key = (*key_array)[j];
            record_array[i * num_keys + j].value = (int)(offset + key * 5); // Simple formula example
        }
    }

    return record_array;
}

long* generate_offsets(int num_offsets) {
    long* offset_array = (long*)malloc(num_offsets * sizeof(long));

    if (!offset_array) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Implement a pseudo-random number generator (PRNG)
    long seed = 123456789;
    for (int i = 0; i < num_offsets; i++) {
        seed = (seed * 1103515245 + 12345) % 2147483647;
        offset_array[i] = seed % 999999;
    }

    return offset_array;
