void free_record(record_t* rec) {
    free(rec);
}

int main(int argc, char** argv) {
    int c;
    char *output_file = NULL;

    while ((c = getopt(argc, argv, "hc:o:")) != -1) {
        switch (c) {
            case 'h':
                printf("Usage: %s [-h|--help] [-c <count>] [-o <output_file>]\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid option: -%c\n", optopt);
                return EXIT_FAILURE;
        }
    }

    if (argc == 1) {
        printf("No input file provided. Usage information displayed.\n");
        exit(EXIT_SUCCESS);
    }

    srand((unsigned int)time(NULL));

    // Initialize arrays with default sizes
    int offset_size = 16;
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    record_t** records = (record_t**)malloc(offset_size * sizeof(record_t*));

    FILE* input_file = fopen(argv[1], "r");
    if (!input_file) {
        fprintf(stderr, "Error: Unable to open file '%s' for reading.\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), input_file)) {
        // Process each line
        int key = atoi(line);

        if (!records[key]) {
            records[key] = create_record(key);
        }
    }

    fclose(input_file);

    // Perform operations on the arrays

    for (int i = 0; i < offset_size; i++) {
        printf("Offset: %" PRId64 " Record: %p\n", offsets[i], records[i]);
    }

    // Free memory
    for (int i = 0; i < offset_size; i++) {
        free_record(records[i]);
    }
    free(offsets);
    free(records);

    return EXIT_SUCCESS;
}
