typedef struct {
    char* name;
    int id;
    bool flag;
} item;

item* create_item() {
    item* new_item = (item*)malloc(sizeof(item));
    new_item->name = (char*)malloc((rand() % STRING_LENGTH_RANGE + 1) * sizeof(char));
    strcpy(new_item->name, (char*)malloc((rand() % STRING_LENGTH_RANGE + 1) * sizeof(char)));
    new_item->id = rand() % MAX_ITEM_ID + MIN_ITEM_ID;
    new_item->flag = rand() % 2 == 0;
    return new_item;
}

typedef struct {
    item** items;
    int size;
} hash_table;

hash_table* create_hash_table(int initial_size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->items = (item**)calloc(initial_size, sizeof(item*));
    table->size = initial_size;
    return table;
}

void update_item(item* item, int new_id) {
    if (!item) return;
    item->id = new_id;
}

int hash_function(int id, int size) {
    return id % size;
}

bool insert_item(hash_table* table, item* item) {
    int index = hash_function(item->id, table->size);
    if (table->items[index]) {
        // collision resolution
        for (int i = 0; i < table->size; i++) {
            if (table->items[(index + i) % table->size] == NULL) {
                table->items[(index + i) % table->size] = item;
                return true;
            }
        }
    } else {
        table->items[index] = item;
    }
    return false;
}

bool lookup_item(hash_table* table, int id) {
    int index = hash_function(id, table->size);
    if (table->items[index]) {
        // collision resolution
        for (int i = 0; i < table->size; i++) {
            if (table->items[(index + i) % table->size]->id == id) {
                return true;
            }
        }
    } else {
        return false;
    }
}

void free_hash_table(hash_table* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->items[i]) {
            free(table->items[i]->name);
            free(table->items[i]);
        }
    }
    free(table->items);
    free(table);
}

void cleanup() {
    // implement memory leak detection and handling
}

