use tokio::prelude::*;
use tokio::sync::{mpsc, oneshot};
use log::{info, warn, error};

struct ProcessingModule {
    process_data: Box<dyn Fn(&mut Vec<i32>) + Sync + Send>,
}

impl ProcessingModule {
    fn new(process_data: Box<dyn Fn(&mut Vec<i32>) + Sync + Send>) -> Self {
        ProcessingModule { process_data }
    }

    async fn process(mut self, data: &mut Vec<i32>) {
        (self.process_data)(data);
    }
}

async fn main() {
    let mut processing_modules = vec![];

    for arg in std::env::args().skip(1) {
        match arg.as_str() {
            "filter" => {
                processing_modules.push(ProcessingModule::new(|data| {
                    data.retain(|x| x % 2 == 0);
                }));
            }
            "transform" => {
                processing_modules.push(ProcessingModule::new(|data| {
                    data.iter_mut().for_each(|x| *x *= 2);
                }));
            }
            "aggregate" => {
                processing_modules.push(ProcessingModule::new(|data| {
                    let sum: i32 = data.iter().sum();
                    println!("Sum: {}", sum);
                }));
            }
            _ => warn!("Unknown processing module: {}", arg),
        }
    }

    let (tx, mut rx) = mpsc::channel(100);

    tokio::task::spawn(async move {
        // Connect to external data source
        let mut data_stream = // implement data stream

        while let Some(item) = data_stream.next().await {
            tx.send(item).await.unwrap();
        }
    });

    while let Ok(data) = rx.recv().await {
        for processing_module in &processing_modules {
            processing_module.process(&mut data).await;
        }
    }

    // Log performance metrics and error conditions
    info!("Processing completed");
}

tokio::runtime::Builder::new_multi_thread()
    .enable_all()
    .build()
    .unwrap()
    .block_on(main());
