#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 100000
#define LATENCY_MSEC 1
#define LOG_LEVEL 1 // 0: error, 1: debug, 2: info

typedef struct {
    int id;
    time_t timestamp;
    char account[20];
    double amount;
    int status;
    char payment_method[10];
} transaction_record;

transaction_record* init_transactions(int num_transactions) {
    transaction_record* transactions = (transaction_record*)malloc(num_transactions * sizeof(transaction_record));
    if (!transactions) {
        return NULL; // memory allocation failure
    }

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = rand();
        transactions[i].timestamp = time(NULL);
        strcpy(transactions[i].account, "Account_");
        transactions[i].amount = (double)rand() / RAND_MAX;
        transactions[i].status = (rand() % 2 ? 0 : 1); // debit/credit
        strcpy(transactions[i].payment_method, rand() % 3 ? "Credit Card" : rand() % 2 ? "Bank Transfer" : "Digital Wallet");
    }

    return transactions;
}

void* transaction_thread(void* arg) {
    int tid = (int)arg;

    // simulate transaction processing
    for (int i = 0; i < MAX_TRANSACTIONS / 100; i++) {
        int idx = rand() % MAX_TRANSACTIONS;
        transaction_record* record = &transactions[idx];
        if (record->status == 0) { // debit
            printf("Transaction %d: Debit of $%.2f from account %s\n", tid, record->amount, record->account);
        } else { // credit
            printf("Transaction %d: Credit of $%.2f to account %s\n", tid, record->amount, record->account);
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    int num_transactions = MAX_TRANSACTIONS;
    transaction_record* transactions = init_transactions(num_transactions);

    // start threads
    pthread_t threads[num_transactions];
    for (int i = 0; i < num_transactions; i++) {
        pthread_create(&threads[i], NULL, transaction_thread, (void*)i);
    }

    // wait for threads to finish
    for (int i = 0; i < num_transactions; i++) {
        pthread_join(threads[i], NULL);
    }

    free(transactions);

    return 0;
}

