void init_dataset(Node** head, Node** tail, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        Node* new_node = create_node(i * 1024, rand() % 100); // Random key and value
        if (!new_node) {
            break;
        }
        if (*head == NULL) {
            *head = new_node;
            *tail = new_node;
        } else {
            (*tail)->next = new_node;
            new_node->prev = *tail;
            *tail = new_node;
        }
    }
}

void free_dataset(Node* head, Node* tail) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    tail = NULL;
}

