void initializePool(int capacity) {
    pool = (ResourcePool *)malloc(sizeof(ResourcePool));
    pool->capacity = capacity;
    pool->loadThreshold = 0.8; // adjust this value based on your system's performance characteristics
    pool->resources = (Resource *)malloc(sizeof(Resource) * capacity);
    for (int i = 0; i < capacity; i++) {
        pool->resources[i].allocated = 0;
        pthread_mutex_init(&pool->resources[i].lock, NULL);
        pthread_cond_init(&pool->resources[i].cond, NULL);
    }
}

// Manage the lifecycle of a resource
