#define MEMORY_LIMIT 1024*1024 // 1MB
#define MAX_NODES 1000
#define MAX_KEY 1000

typedef struct node {
    int key;
    long offset;
    struct node* predecessor;
    struct node* successor;
} Node;

typedef struct record {
    int value;
} Record;

Node* create_node(int key, long offset) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        return NULL;
    }
    node->key = key;
    node->offset = offset;
    node->predecessor = node->successor = NULL;
    return node;
}

void free_node(Node* node) {
    free(node);
}

Record* create_record(int value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->value = value;
    return record;
}

void free_record(Record* record) {
    free(record);
}

Node* insert_node(Node** head, int key, long offset) {
    Node* node = create_node(key, offset);
    if (!node) {
        return NULL;
    }
    if (*head == NULL || node->key < (*head)->key) {
        node->successor = *head;
        if (*head != NULL) {
            (*head)->predecessor = node;
        }
        *head = node;
    } else {
        Node* current = *head;
        while (current->successor != NULL && current->successor->key > key) {
            current = current->successor;
        }
        if (node->key < current->key) {
            node->successor = current;
            if (current->predecessor != NULL) {
                current->predecessor->successor = node;
            } else {
                *head = node;
            }
            current->predecessor = node;
        } else {
            current->successor = node;
            node->predecessor = current;
            node->successor = NULL;
        }
    }
    return node;
}

Node* delete_node(Node** head, int key) {
    Node* current = *head;
    while (current != NULL && current->key != key) {
        current = current->successor;
    }
    if (current == NULL) {
        return NULL;
    }
    if (current->predecessor == NULL) {
        *head = current->successor;
    } else {
        current->predecessor->successor = current->successor;
    }
    if (current->successor != NULL) {
        current->successor->predecessor = current->predecessor;
    }
    free_node(current);
    return current;
}

int find_node(Node* head, int key) {
    Node* current = head;
    while (current != NULL && current->key != key) {
        current = current->successor;
    }
    if (current == NULL) {
        return -1; // not found
    } else {
        return current->offset; // found, return offset
    }
}

int main() {
    int input[100];
    int count = 0;
    FILE* file = fopen("input.txt", "r");
    while (fscanf(file, "%d\n", &input[count]) != EOF) {
        count++;
    }
    fclose(file);

    Node* head = NULL;
    for (int i = 0; i < count; i++) {
        Node* node = create_node(i, input[i]);
        if (!node) {
            break;
        }
        insert_node(&head, i, input[i]);
    }

    int max = find_max(input, count);
    printf("Largest number in the array is: %d\n", max);

    return 0;
}

int find_max(int* arr, int n) {
    int mx = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > mx)
            mx = arr[i];
    }
    return mx;
}
