typedef struct {
    DataStruct data;
    int refcount;
} RefCountStruct;

RefCountStruct* createDoubleStruct(double d) {
    RefCountStruct* ret = malloc(sizeof(RefCountStruct));
    ret->data.d = d;
    ret->refcount = 1;
    return ret;
}

void freeDoubleStruct(RefCountStruct* ds) {
    if (--ds->refcount > 0)
        return;
    free(ds);
}

RefCountStruct* createCharStruct(char* str, int len) {
    RefCountStruct* ret = malloc(sizeof(RefCountStruct));
    ret->data.str = strdup(str);
    ret->data.len = len;
    ret->refcount = 1;
    return ret;
}

void freeCharStruct(RefCountStruct* cs) {
    if (--cs->refcount > 0)
        return;
    free(cs->data.str);
    free(cs);
}

RefCountStruct* createDataStruct(int i, float f, void* ptr) {
    RefCountStruct* ret = malloc(sizeof(RefCountStruct));
    ret->data.i = i;
    ret->data.f = f;
    ret->data.ptr = ptr;
    ret->refcount = 1;
    return ret;
}

void freeDataStruct(RefCountStruct* ds) {
    if (--ds->refcount > 0)
        return;
    free(ds);
}

RefCountStruct* createRefCountStruct() {
    RefCountStruct* ret = malloc(sizeof(RefCountStruct));
    ret->refcount = 1;
    return ret;
}

void freeRefCountStruct(RefCountStruct* ds) {
    if (--ds->refcount > 0)
        return;
    free(ds);
}

int main() {
    // Test code
    RefCountStruct* d = createDoubleStruct(3.14);
    RefCountStruct* c = createCharStruct("Hello", 5);
    RefCountStruct* data = createDataStruct(1, 2.0, (void*)malloc(sizeof(int)));
    RefCountStruct* refcount = createRefCountStruct();

    // Test code
    printf("Double: %f\n", d->data.d);
    printf("Char: %s\n", c->data.str);
    printf("Data: %d %f %p\n", data->data.i, data->data.f, data->data.ptr);
    printf("RefCount: %d\n", refcount->refcount);

    // Test code
    freeDoubleStruct(d);
    freeCharStruct(c);
    freeDataStruct(data);
    freeRefCountStruct(refcount);

    return 0;
}
