#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <time.h>

#define DATABASE_SIZE 1000
#define MAX_KEY 10000
#define MIN_KEY 1
#define INITIAL_HASH_TABLE_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int key;
    int value;
    struct record* next;
} record;

record* hash_table[INITIAL_HASH_TABLE_CAPACITY];
int current_capacity = INITIAL_HASH_TABLE_CAPACITY;
int num_records = 0;

void* kmalloc(size_t size) {
    return malloc(size);
}

void kfree(void* ptr) {
    free(ptr);
}

int hash(int key) {
    // Implement a simple hash function for demonstration purposes
    return key % current_capacity;
}

record* insert(record* new_record) {
    int index = hash(new_record->key);

    if (!hash_table[index]) {
        hash_table[index] = kmalloc(sizeof(record));
        *hash_table[index] = new_record;
    } else {
        record* current = hash_table[index];
        while (current->next) {
            current = current->next;
        }
        current->next = kmalloc(sizeof(record));
        *current->next = new_record;
    }

    if (++num_records >= (int)(current_capacity * LOAD_FACTOR_THRESHOLD)) {
        resize();
    }

    return NULL;
}

void insert_all(int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        record* new_record = kmalloc(sizeof(record));
        new_record->key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        new_record->value = rand();
        insert(new_record);
    }
}

void resize() {
    int new_capacity = current_capacity * 2;
    record** new_hash_table = kmalloc(sizeof(record*) * new_capacity);

    for (int i = 0; i < current_capacity; ++i) {
        record* current = hash_table[i];
        while (current) {
            int index = hash(current->key);
            if (!new_hash_table[index]) {
                new_hash_table[index] = kmalloc(sizeof(record));
                *new_hash_table[index] = current;
            } else {
                record* next = current->next;
                current->next = NULL;
                while (next) {
                    int new_index = hash(next->key);
                    if (!new_hash_table[new_index]) {
                        new_hash_table[new_index] = kmalloc(sizeof(record));
                        *new_hash_table[new_index] = next;
                    } else {
                        record* temp = new_hash_table[new_index]->next;
                        new_hash_table[new_index]->next = current->next;
                        current->next = temp;
                    }
                    next = next->next;
                }
            }
            current = current->next;
        }

        for (int i = 0; i < current_capacity; ++i) {
            if (hash_table[i]) {
                record* current = hash_table[i];
                while (current) {
                    int index = hash(current->key);
                    record* next = current->next;
                    current->next = NULL;
                    new_hash_table[index]->next = current;
                    current = next;
                }
            }
        }

        for (int i = 0; i < current_capacity; ++i) {
            kfree(hash_table[i]);
        }

        current_capacity = new_capacity;
        for (int i = 0; i < new_capacity; ++i) {
            hash_table[i] = new_hash_table[i];
        }

        for (int i = 0; i < new_capacity; ++i) {
            record* current = hash_table[i];
            while (current) {
                current = current->next;
            }
        }
    }
}

void release() {
    for (int i = 0; i < current_capacity; ++i) {
        record* current = hash_table[i];
        while (current) {
            record* next = current->next;
            kfree(current);
            current = next;
        }
    }

    for (int i = 0; i < current_capacity; ++i) {
        kfree(hash_table[i]);
    }
}

int main() {
    srand(time(NULL));

    insert_all(DATABASE_SIZE);

    release();

    return 0;
}
