#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum number of records in the database
#define MAX_RECORDS 10000

// Define the maximum length of a record key and value
#define MAX_KEY_LENGTH 20
#define MAX_VALUE_LENGTH 50

// Define the random seed for generating initial values
#define RANDOM_SEED 42

// Structure to represent a single database record
typedef struct {
    int key;
    int value;
} Record;

// Structure to represent the hash table
typedef struct {
    Record** records; // Array of pointers to records
    int capacity; // Current capacity of the hash table
    int size; // Number of records currently stored
    double loadFactor; // Load factor for resizing
} HashTable;

// Function to initialize a new hash table with the specified capacity and initial values
HashTable* initHashTable(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->records = (Record**)calloc(capacity, sizeof(Record*));
    table->capacity = capacity;
    table->size = 0;
    table->loadFactor = 0.75; // Default load factor
    return table;
}

// Function to add a new record to the hash table
void addRecord(HashTable* table, int key, int value) {
    // Calculate the index for the given key using a hash function
    int index = key % table->capacity;

    // Create a new record and store it in the array
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;

    // Check if there's already an existing record at this index
    if (table->records[index] != NULL) {
        // Rehash the table and update all affected entries
        rehashTable(table);
    }

    // Store the new record in the array
    table->records[index] = record;
    table->size++;

    // Check if the load factor exceeds the threshold for resizing
    if (table->size / (double)table->capacity > table->loadFactor) {
        resizeTable(table);
    }
}

// Function to retrieve a record from the hash table by its key
Record* getRecord(HashTable* table, int key) {
    // Calculate the index for the given key using a hash function
    int index = key % table->capacity;

    // Search for the record in the array
    while (table->records[index] != NULL && table->records[index]->key != key) {
        index++;
    }

    return table->records[index];
}

// Function to rehash the entire hash table and update all affected entries
void rehashTable(HashTable* table) {
    // Create a new array with double the capacity of the original
    HashTable* newTable = initHashTable(table->capacity * 2);

    // Rehash each record in the original table and store it in the new table
    for (int i = 0; i < table->capacity; i++) {
        while (table->records[i] != NULL) {
            Record* record = table->records[i];
            int newIndex = record->key % newTable->capacity;
            table->records[i] = NULL;

            // Store the rehashed record in the new table
            if (newTable->records[newIndex] == NULL || newTable->size < 0.5 * newTable->capacity) {
                newTable->records[newIndex] = record;
                newTable->size++;
            } else {
                int j = newIndex + 1;
                while (j % newTable->capacity != newIndex && newTable->records[j] != NULL) {
                    j++;
                }
                newTable->records[j] = record;
                newTable->size++;
            }
        }
    }

    // Free the original table and update the current table
    free(table);
    table = newTable;
}

// Function to resize the hash table when it reaches a certain load factor
void resizeTable(HashTable* table) {
    // Create a new array with double the capacity of the original
    HashTable* newTable = initHashTable(table->capacity * 2);

    // Rehash each record in the original table and store it in the new table
    for (int i = 0; i < table->capacity; i++) {
        while (table->records[i] != NULL) {
            Record* record = table->records[i];
            int newIndex = record->key % newTable->capacity;
            table->records[i] = NULL;

            // Store the rehashed record in the new table
            if (newTable->records[newIndex] == NULL || newTable->size < 0.5 * newTable->capacity) {
                newTable->records[newIndex] = record;
                newTable->size++;
            } else {
                int j = newIndex + 1;
                while (j % newTable->capacity != newIndex && newTable->records[j] != NULL) {
                    j++;
                }
                newTable->records[j] = record;
                newTable->size++;
            }
        }
    }

    // Free the original table and update the current table
    free(table);
    table = newTable;
}

// Function to release all allocated memory when the database is no longer in use
void releaseMemory(HashTable* table) {
