        sprintf(arr[i].identifier, "%s%d", arr[i].identifier, i+1);

        arr[i].location = (point*)malloc(sizeof(point));
        arr[i].location->x = (double)i / size;
        arr[i].location->y = (double)(size-i) / size;

        arr[i].stat = NEW;
        arr[i].timestamp = time(NULL);
    }

    return arr;
}

void read_coordinates(analysis* arr, int size) {
    int max_index = 0;
    for (int i = 0; i < size; i++) {
        printf("Enter x and y coordinates for point %s: ", arr[i].identifier);
        scanf("%lf%lf", &arr[i].location->x, &arr[i].location->y);

        if (i > max_index) {
            max_index = i;
        }
    }
}

void calculate_distance(analysis* arr, int size) {
    double distance = 0.0;

    point p1 = arr[0].location;
    point p2 = arr[size-1].location;

    distance = sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));

    printf("Euclidean distance between first and last points: %f\n", distance);
}

