#include <unordered_map>
#include <mutex>
#include <chrono>
#include <thread>

class DistributedSessionCache {
private:
    std::unordered_map<std::string, Session> sessions;
    std::mutex lock;

public:
    class Session {
    public:
        std::string id;
        std::time_t lastActivity;
        std::string ip;
        bool active;

        Session(std::string id, std::string ip, bool active)
            : id(id), lastActivity(std::time(nullptr)), ip(ip), active(active) {}
    };

    void addSession(std::string id, std::string ip, bool active) {
        std::unique_lock<std::mutex> guard(lock);
        sessions[id] = Session{id, std::time(nullptr), ip, active};
    }

    void updateSession(std::string id, bool active) {
        std::unique_lock<std::mutex> guard(lock);
        if (sessions.find(id) != sessions.end()) {
            sessions[id].active = active;
            sessions[id].lastActivity = std::time(nullptr);
        }
    }

    Session* getSession(std::string id) {
        std::unique_lock<std::mutex> guard(lock);
        auto it = sessions.find(id);
        return it == sessions.end() ? nullptr : &it->second;
    }

    void removeExpiredSessions() {
        std::unique_lock<std::mutex> guard(lock);
        for (auto& session : sessions) {
            if (std::time(nullptr) - session.second.lastActivity > 3600) {
                // Evict expired session
                sessions.erase(session.first);
            }
        }
    }

    void cleanup() {
        while (true) {
            removeExpiredSessions();
            std::this_thread::sleep_for(std::chrono::minutes(5)); // Periodic cleanup every 5 minutes
        }
    }
};
