#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    struct node* prev;
    struct node* next;
    long offset;
    int key;
    int record;
    int status;
} Node;

typedef struct record {
    int value;
} Record;

Node* create_node(long offset, int key, int record) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->prev = NULL;
    node->next = NULL;
    node->offset = offset;
    node->key = key;
    node->record = record;
    node->status = 0;
    return node;
}

Record* create_record(int value) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    return record;
}

void update_node(Node** head, int index, int key, int new_status) {
    Node* current = *head;
    for (int i = 0; i < index; i++) {
        if (!current) break;
        current = current->next;
    }
    if (current && current->key == key) {
        current->status = new_status;
    } else {
        printf("Error: Node not found\n");
    }
}

void update_record(Node** head, int index, int key, int value) {
    Node* current = *head;
    for (int i = 0; i < index; i++) {
        if (!current) break;
        current = current->next;
    }
    if (current && current->key == key) {
        Record* record = current->record;
        record->value = value;
    } else {
        printf("Error: Node not found\n");
    }
}

void free_node(Node* node) {
    if (!node) return;
    free_node(node->prev);
    free_node(node->next);
    free(node);
}

int main() {
    // Initialize memory allocation
    long offset_values[100];
    int key_values[100];
    Record record_values[100];
    Node* head = NULL;

    // Initialize arrays and linked list
    for (int i = 0; i < 100; i++) {
        offset_values[i] = i * 10;
        key_values[i] = i % 2;
        record_values[i].value = rand() % 100;
        Node* node = create_node(offset_values[i], key_values[i], &record_values[i]);
        if (head) {
            head->next = node;
            node->prev = head;
        } else {
            head = node;
        }
    }

    // Test update operations
    update_node(&head, 50, 1, 1);
    update_record(&head, 25, 0, 500);

    // Free memory
    while (head) {
        Node* temp = head;
        head = head->next;
        free_node(temp);
    }

    return 0;
}
