#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    char* filename;
    size_t size;
    time_t modified;
} file_metadata;

file_metadata** cache = NULL;
size_t cache_size = 0;
time_t last_cache_update = 0;

void cache_refresh(int dir_fd) {
    DIR* dp = opendir(dir_fd);
    if (!dp)
        return;
    struct dirent* de;
    while ((de = readdir(dp))) {
        char path[PATH_MAX];
        sprintf(path, "%s/%s", getcwd(NULL, 0), de->d_name);
        int fd = open(path, O_RDONLY);
        if (fd >= 0) {
            file_metadata* meta = malloc(sizeof(file_metadata));
            meta->filename = strdup(de->d_name);
            struct stat sb;
            fstat(fd, &sb);
            meta->size = sb.st_size;
            meta->modified = sb.st_mtime;
            cache[cache_size++] = meta;
            close(fd);
        }
        free(de->d_name);
    }
    closedir(dp);
}

int get_largest(int* arr, size_t n) {
    int max = *arr;
    for (size_t i = 1; i < n; i++) {
        if (*arr > max)
            max = *arr;
    }
    return max;
}

void async_monitor(const char* dir_path, size_t cache_limit, int mode) {
    int dir_fd = opendir(dir_path);
    if (!dir_fd)
        return;

    // Dynamic memory allocation
    cache = (file_metadata**)malloc((cache_limit + 1)*sizeof(file_metadata*));
    for (size_t i = 0; i < cache_limit; i++) {
        cache[i] = NULL;
    }

    DIR* dp = opendir(dir_fd);
    if (!dp)
        return;

    struct dirent* de;
    while ((de = readdir(dp))) {
        char path[PATH_MAX];
        sprintf(path, "%s/%s", dir_path, de->d_name);
        int fd = open(path, O_RDONLY);
        if (fd >= 0) {
            file_metadata* meta = malloc(sizeof(file_metadata));
            meta->filename = strdup(de->d_name);
            struct stat sb;
            fstat(fd, &sb);
            meta->size = sb.st_size;
            meta->modified = sb.st_mtime;

            // Cache update
            if (mode == 1) {
                // Asynchronous mode: cache updates are performed concurrently with file processing.
                pthread_t thread;
                pthread_create(&thread, NULL, cache_refresh, dir_fd);
                pthread_join(thread);
            } else {
                // Synchronous mode: cache is updated after processing all files.
                for (size_t i = 0; i < cache_limit; i++) {
                    if (cache[i] == NULL) {
                        file_metadata* meta_new = malloc(sizeof(file_metadata));
                        meta_new->filename = strdup(de->d_name);
                        struct stat sb;
                        fstat(fd, &sb);
                        meta_new->size = sb.st_size;
                        meta_new->modified = sb.st_mtime;
                        cache[i] = meta_new;
                    }
                }
            }

            close(fd);
        }
    }

    closedir(dp);
}

int main() {
    int mode; // 0 for synchronous, 1 for asynchronous
    scanf("%d", &mode);

    // Read integers from standard input and store them in a dynamic array.
    size_t n;
    scanf("%zu", &n);
    int* arr = (int*)malloc(n * sizeof(int));
    for (size_t i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }

    // Find the largest integer in the array.
    size_t max = get_largest(arr, n);

    printf("The largest integer is: %d\n", max);

    return 0;
}
