#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int id;
    int value;
} Record;

// Define the dynamic array of records
typedef struct {
    Record* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize and populate a dynamic array with random values
DynamicArray* create_dynamic_array(size_t initial_capacity, size_t max_size) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->data = (Record*)calloc(initial_capacity, sizeof(Record));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

// Add a record to the dynamic array
void add_record(DynamicArray* arr, int id, int value) {
    Record* new_data = (Record*)realloc(arr->data, ++arr->size * sizeof(Record));
    if (!new_data) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Continuing with existing data.\n");
    } else {
        arr->data = new_data;
        arr->data[arr->size - 1].id = id;
        arr->data[arr->size - 1].value = value;
    }
}

// Update a record in the dynamic array
void update_record(DynamicArray* arr, int id, int value) {
    pthread_mutex_lock(&arr->lock);
    for (int i = 0; i < arr->size; i++) {
        if (arr->data[i].id == id) {
            arr->data[i].value = value;
            break;
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

// Get the record at a specified index
Record* get_record(DynamicArray* arr, size_t index) {
    Record* result = NULL;
    pthread_mutex_lock(&arr->lock);
    if (index < arr->size) {
        result = &arr->data[index];
    }
    pthread_mutex_unlock(&arr->lock);
    return result;
}

// Destroy the dynamic array
void destroy_dynamic_array(DynamicArray* arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}
