Record* record_array[MAX_RECORDS];
int record_count = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* init_records(int max_size) {
    for (int i = 0; i < max_size; i++) {
        record_array[i] = NULL;
    }
}

int add_record(Record* new_record) {
    pthread_mutex_lock(&lock);

    if (record_count >= MAX_RECORDS) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return -1;
    }

    record_array[record_count] = new_record;
    record_count++;

    pthread_mutex_unlock(&lock);
    return 0;
}

int get_record(int index, Record** record) {
    pthread_mutex_lock(&lock);

    if (index >= record_count) {
        // Handle out-of-bounds access
        printf("Index out of bounds.\n");
        return -1;
    }

    *record = record_array[index];

    pthread_mutex_unlock(&lock);
    return 0;
}

int update_record(int index, Record* updated_record) {
    pthread_mutex_lock(&lock);

    if (index >= record_count) {
        // Handle out-of-bounds access
        printf("Index out of bounds.\n");
        return -1;
    }

    record_array[index] = updated_record;

    pthread_mutex_unlock(&lock);
    return 0;
}

int invalidate_expired_records() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < record_count; i++) {
        if ((time(NULL) - record_array[i]->timestamp) > TIMESTAMP_MAX) {
            // Handle invalidation logic
            printf("Invalidated expired record.\n");
            record_array[i] = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

int main() {
    init_records(MAX_RECORDS);

    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* new_record = malloc(sizeof(Record));
        new_record->id = rand() % MAX_VALUE;
        new_record->value = rand() % MAX_VALUE;
        new_record->timestamp = time(NULL);

        if (add_record(new_record) != 0) {
            break;
        }
    }

    return 0;
}
