public class DynamicProcessManager
{
    private readonly object _lock = new object();
    private int _maxBackgroundProcesses = 10000;
    private Queue<Command> _commandQueue = new Queue<Command>();

    public delegate void CommandHandler(Command command);

    public event CommandHandler OnCommandExecuted;

    public void ExecuteCommand(string command, string[] envVars)
    {
        lock (_lock)
        {
            if (_commandQueue.Count >= _maxBackgroundProcesses)
            {
                // Queue full, wait for a slot to open
                while (_commandQueue.Count >= _maxBackgroundProcesses)
                {
                    Thread.Sleep(100);
                }
            }

            _commandQueue.Enqueue(new Command(command, envVars));
        }
    }

    public void DisplayCommandInfo(Command command)
    {
        Console.WriteLine($"Command: {command.Command}");
        foreach (var envVar in command.EnvVars)
        {
            Console.WriteLine($"{envVar.Key} = {envVar.Value}");
        }
    }

    public RandomValueGenerator GetRandomValueGenerator(int min, int max, bool exclusiveMax)
    {
        // implementation of a custom random value generator
    }

    public void OnCommandExecutedHandler(Command command)
    {
        if (OnCommandExecuted != null)
        {
            OnCommandExecuted(command);
        }
    }

    private class Command : IDisposable
    {
        public string Command { get; }
        public Dictionary<string, string> EnvVars { get; }

        public Command(string command, string[] envVars)
        {
            Command = command;
            EnvVars = new Dictionary<string, string>();
            foreach (var envVar in envVars)
            {
                var parts = envVar.Split('=');
                if (parts.Length == 2)
                {
                    EnvVars.Add(parts[0], parts[1]);
                }
            }
        }

        public void Dispose()
        {
            // dispose of the command's resources
        }
    }
}
