// Structure to represent a record
typedef struct {
    int value;
} record;

// Function to process records efficiently
record** processRecords(long* offsets, int* keys, int numRecords, int minRange, int maxRange) {
    // Check for invalid input range
    if (minRange > maxRange) {
        printf("Invalid input range: %d - %d\n", minRange, maxRange);
        return NULL;
    }

    // Initialize result list and its size
    record** results = NULL;
    int numResults = 0;

    // Traverse records recursively
    processRecordsRecursive(offsets, keys, &results, &numResults, numRecords, minRange, maxRange);

    // Return the result list
    return results;
}

// Recursive function to traverse records and evaluate each record against the specified range
void processRecordsRecursive(long* offsets, int* keys, record*** results, int* numResults, int start, int end, int currentRecord) {
    if (currentRecord >= start && currentRecord <= end) {
        // Allocate memory for new result record
        *results = realloc(*results, (*numResults + 1) * sizeof(record*));
        (*results)[*numResults] = malloc(sizeof(record));
        (*((*results)[*numResults]))->value = keys[currentRecord];
        (*((*results)[*numResults]))->offset = offsets[currentRecord];

        // Increment the result list size
        (*numResults)++;
    }

    if (currentRecord < start) {
        return;
    }

    processRecordsRecursive(offsets, keys, results, numResults, start - 1, end - 1, currentRecord - 1);
}

int main() {
    long offsets[] = {0, 5, 10, 15};
    int keys[] = {1, 2, 3, 4};
    int numRecords = sizeof(offsets) / sizeof(offsets[0]);
    int minRange = 5;
    int maxRange = 15;

    record** results = processRecords(offsets, keys, numRecords, minRange, maxRange);

    // Print the result list
    for (int i = 0; i < *numResults; i++) {
        printf("Offset: %ld, Key: %d\n", (*results)[i]->offset, (*results)[i]->value);
    }

    // Free memory allocated for results
    for (int i = 0; i < *numResults; i++) {
        free((*results)[i]);
    }
    free(*results);

    return 0;
}

