typedef struct {
    char *key;
    int value;
    struct Entry *next;
} Entry;

void* emalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void efree(void* ptr) {
    free(ptr);
}

Entry* create_entry(const char* key, int value, Entry* next) {
    Entry* entry = (Entry*) emalloc(sizeof(Entry));
    entry->key = (char*) emalloc(strlen(key) + 1);
    strcpy(entry->key, key);
    entry->value = value;
    entry->next = next;
    return entry;
}

void insert_entry(Entry** root, const char* key, int value) {
    Entry* new_entry = create_entry(key, value, *root);
    if (*root == NULL) {
        *root = new_entry;
    } else {
        Entry* current = *root;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }
}

void free_entries(Entry** root) {
    Entry* current = *root;
    Entry* next;
    while (current != NULL) {
        next = current->next;
        efree(current->key);
        efree(current);
        current = next;
    }
    *root = NULL;
}
