    long* offsets = (long*)malloc(size * sizeof(long));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i * (maxOffset + 1);
    }
    return offsets;
}

int* initKeys(size_t offsetSize, int maxKey) {
    int* keys = (int*)malloc(offsetSize * sizeof(int));
    for (size_t i = 0; i < offsetSize; ++i) {
        keys[i] = (int)(offsets[i] % maxKey);
    }
    return keys;
}

void invalidateUnusedRecords(record* records, size_t offsetSize) {
