    matrix* mat = (matrix*)malloc(sizeof(matrix));
    if (!mat) return NULL;

    mat->size = size;
    mat->data = (double*)calloc(size*size, sizeof(double));
    if (!mat->data) {
        free(mat);
        return NULL;
    }

    for(int i=0; i<size; i++) {
        for(int j=0; j<size; j++) {
            mat->data[i*size+j] = init_func(i);
        }
    }

    return mat;
}

int* create_indices(int num_data, int (*transform_func)(double)) {
    int* indices = (int*)calloc(num_data, sizeof(int));
    if (!indices) return NULL;

    for(int i=0; i<num_data; i++) {
        indices[i] = transform_func(i);
    }

    return indices;
}

double* create_dataset(int min_size, int max_size) {
    double* dataset = (double*)calloc((max_size-min_size+1)*sizeof(double), sizeof(double));
    if (!dataset) return NULL;

    for(int i=min_size; i<=max_size; i++) {
        dataset[i-min_size] = (double)i;
    }

    return dataset;
}

