        printf("Memory allocation failed.\n");
        for(int i=0; i<num_data; i++) free(matrices[i]->data);
        for(int i=0; i<num_data; i++) free(matrices[i]);
        free(dataset);
        return -1;
    }

    // Now, you can use the allocated structures with your existing linear algebra libraries.

    // Don't forget to free the memory when you're done:
    for(int i=0; i<num_data; i++) {
        free(matrices[i]->data);
        free(matrices[i]);
    }
    free(indices);
    free(dataset);

