            if (nodes[i] != NULL) {
                free(nodes[i]->string);
                free(nodes[i]);
            }
        }
        free(nodes);
    }

    void free_entries(Entry* entries) {
        Entry* temp = entries;
        while (temp != NULL) {
            Entry* next = temp->next;
            free(temp->key);
            free(temp);
            temp = next;
        }
    }

