#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    unsigned int id;
    bool status;
} Event;

typedef struct Node {
    Event event;
    struct Node* prev;
    struct Node* next;
} Node;

Node* events = NULL;
int capacity = 10;
int size = 0;

void addEvent(Event e) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->event = e;
    if (size == 0) {
        newNode->prev = NULL;
        newNode->next = NULL;
        events = newNode;
    } else if (size < capacity) {
        newNode->prev = events;
        newNode->next = events->next;
        events->next = newNode;
        if (newNode->prev != NULL)
            newNode->prev->next = newNode;
        else
            newNode->next->prev = newNode;
        size++;
    } else {
        printf("Event collection is full. Please resize or clear the collection.\n");
    }
}

void printEvents() {
    Node* current = events;
    while (current != NULL) {
        printf("Timestamp: %ld, ID: %u, Status: %s\n", current->event.timestamp, current->event.id, current->event.status ? "True" : "False");
        current = current->next;
    }
}

void resizeCollection() {
    capacity *= 2;
    Node* newEvents = (Node*)malloc(sizeof(Node) * capacity);
    int i = 0;
    Node* current = events;
    while (current != NULL) {
        newEvents[i] = current->event;
        current = current->next;
        i++;
    }
    for (int j = 0; j < size - 1; j++) {
        newEvents[j].prev = &newEvents[j];
        newEvents[j].next = &newEvents[j + 1];
    }
    if (size > 0)
        newEvents[size - 1].next = NULL;
    else
        newEvents[0].next = NULL;
    for (int k = 0; k < size; k++) {
        free(&events);
        events = &newEvents[k];
    }
}

void logEvents() {
    // Logging mechanism implementation
}

int main() {
    Event e1 = {time(NULL), 1, true};
    addEvent(e1);

    Event e2 = {time(NULL) + 10, 2, false};
    addEvent(e2);

    printEvents();

    resizeCollection();
    logEvents();

    return 0;
}
