import heapq
from typing import Dict, List, Tuple

def shortest_path(graph: Dict[int, Dict[int, int]], start_node: int, end_node: int, heuristic=None):
    if not graph:
        return None

    algorithms = ['Dijkstra', 'A*', 'Bellman-Ford']
    algorithm = input("Choose an algorithm ({}): ".format(", ".join(algorithms)))

    try:
        algorithm_index = algorithms.index(algorithm)
    except ValueError:
        print("Invalid choice. Defaulting to Dijkstra.")
        algorithm_index = 0

    max_path_length = int(input("Enter maximum path length: "))
    allowed_error_margin = float(input("Enter allowed error margin (0-1): "))

    if algorithm == algorithms[0]:  # Dijkstra
        if heuristic:
            raise ValueError("Heuristic not applicable to Dijkstra's algorithm.")

        queue, distances = [(0, start_node)], {start_node: 0}
        while queue and max_path_length > 0:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > max_path_length:
                break

            for neighbor, weight in graph.get(current_node, {}).items():
                distance = distances[current_node] + weight
                if neighbor not in distances or distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

    elif algorithm == algorithms[1]:  # A*
        if heuristic:
            queue, distances = [(0, start_node)], {start_node: 0}
            while queue and max_path_length > 0:
                current_distance, current_node = heapq.heappop(queue)

                if current_distance > max_path_length:
                    break

                for neighbor, weight in graph.get(current_node, {}).items():
                    distance = distances[current_node] + weight
                    if neighbor not in distances or distance < distances[neighbor]:
                        distances[neighbor] = distance
                        heapq.heappush(queue, (distance + heuristic[neighbor], neighbor))

        else:
            raise ValueError("Heuristic required for A* algorithm.")

    elif algorithm == algorithms[2]:  # Bellman-Ford
        if heuristic:
            raise ValueError("Heuristic not applicable to Bellman-Ford algorithm.")

        distances = {node: float('inf') for node in graph}
        distances[start_node] = 0

        for _ in range(len(graph) - 1):
            for current_node, neighbors in graph.items():
                for neighbor, weight in neighbors.items():
                    if distances[current_node] + weight < distances[neighbor]:
                        distances[neighbor] = distances[current_node] + weight

    else:
        raise ValueError("Invalid algorithm choice.")

    path_length = distances[end_node]

    if max_path_length > 0 and path_length > max_path_length:
        print(f"Path length exceeds maximum {max_path_length}.")

    computation_time = 0.0
    memory_usage = 0

    return {
        "algorithm": algorithm,
        "path_length": path_length,
        "computation_time": computation_time,
        "memory_usage": memory_usage,
        "graph_metadata": {"nodes": len(graph), "edges": sum(len(neighbors) for neighbors in graph.values())}
    }
