#include <stdbool.h>

typedef struct {
    time_t timestamp;
    unsigned int event_id;
    bool status;
} Event;

// Dynamic collection of events
typedef struct {
    Event *events;
    size_t capacity;
    size_t size;
} EventCollection;

EventCollection* event_collection_new(size_t initial_capacity) {
    EventCollection* ec = malloc(sizeof(EventCollection));
    ec->capacity = initial_capacity;
    ec->size = 0;
    ec->events = malloc(ec->capacity * sizeof(Event));
    return ec;
}

void event_collection_free(EventCollection* ec) {
    free(ec->events);
    free(ec);
}

// Resize the collection when it reaches 75% of its current capacity
void event_collection_resize(EventCollection* ec) {
    if (ec->size >= ec->capacity * 0.75f) {
        size_t new_capacity = ec->capacity * 2;
        Event* new_events = realloc(ec->events, new_capacity * sizeof(Event));
        ec->events = new_events;
        ec->capacity = new_capacity;
    }
}

void event_collection_add(EventCollection* ec, Event e) {
    if (ec->size >= ec->capacity) {
        event_collection_resize(ec);
    }
    ec->events[ec->size] = e;
    ec->size++;
}

void print_event(const Event* e) {
    printf("Timestamp: %ld, Event ID: %u, Status: %s\n", (long)e->timestamp, e->event_id, e->status ? "true" : "false");
}

// Filter events based on a user-defined condition
bool event_filter(const Event* e, bool (*condition)(const Event*)) {
    return condition(e);
}

void iterate_events(EventCollection* ec, bool (*filter_condition)(const Event*)) {
    for (size_t i = 0; i < ec->size; i++) {
        if (event_filter(&ec->events[i], filter_condition)) {
            print_event(&ec->events[i]);
        }
    }
}

int main() {
    EventCollection* ec = event_collection_new(10); // Initial capacity of 10 events

    // Add some events
    Event e1 = {1634345678, 1, true};
    Event e2 = {1634345680, 2, false};
    Event e3 = {1634345690, 3, true};
    event_collection_add(ec, e1);
    event_collection_add(ec, e2);
    event_collection_add(ec, e3);

    // Filter events
    bool (*filter_condition)(const Event*) = [](const Event* e) {
        return e->status;
    };
    iterate_events(ec, filter_condition);

    event_collection_free(ec);

    return 0;
}
