#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define structure types
typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    char* str;
    double value;
} Data;

typedef struct {
    int value;
} Record;

typedef struct {
    time_t timestamp;
    int validFlag;
    int referenceCount;
} Metadata;

// Function to initialize and populate data structures
void init_data(struct Offset** offsets, struct Key** keys, struct Data** datas, struct Record** records, struct Metadata** metadata) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for each structure type
    *offsets = (struct Offset*)malloc(sizeof(struct Offset) * 5);
    *keys = (struct Key*)malloc(sizeof(struct Key) * 5);
    *datas = (struct Data*)malloc(sizeof(struct Data) * 5);
    *records = (struct Record*)malloc(sizeof(struct Record) * 5);
    *metadata = (struct Metadata*)malloc(sizeof(struct Metadata) * 5);

    // Populate data structures
    for(int i = 0; i < 5; i++) {
        (*offsets)[i].offset = rand() % 1000000;
        (*keys)[i].key = rand() % 10000;
        char str[20];
        sprintf(str, "Data_%d", i);
        (*datas)[i].str = (char*)malloc(strlen(str) + 1);
        strcpy((*datas)[i].str, str);
        (*datas)[i].value = (double)i / 5.0;

        (*records)[i].value = rand() % 100;
        (*metadata)[i].timestamp = time(NULL);
        (*metadata)[i].validFlag = i % 2;
        (*metadata)[i].referenceCount = i + 1;
    }
}

// Serialize data structures to binary file
void serialize_data(struct Offset* offsets, struct Key* keys, struct Data* datas, struct Record* records, struct Metadata* metadata, FILE* file) {
    // Write offset values
    fwrite(offsets, sizeof(struct Offset), 5, file);

    // Write key values
    fwrite(keys, sizeof(struct Key), 5, file);

    // Write data values
    for(int i = 0; i < 5; i++) {
        size_t str_len = strlen(datas[i].str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(datas[i].str, 1, str_len + 1, file);
        fwrite(&datas[i].value, sizeof(double), 1, file);
    }

    // Write record values
    for(int i = 0; i < 5; i++) {
        fwrite(&records[i], sizeof(struct Record), 1, file);
    }

    // Write metadata values
    for(int i = 0; i < 5; i++) {
        fwrite(&metadata[i], sizeof(struct Metadata), 1, file);
    }
}

int main() {
    // Initialize data structures
    struct Offset* offsets;
    struct Key* keys;
    struct Data* datas;
    struct Record* records;
    struct Metadata* metadata;

    init_data(&offsets, &keys, &datas, &records, &metadata);

    // Open file for serialization
    FILE* file = fopen("data.bin", "wb");

    // Serialize data structures to binary file
    serialize_data(offsets, keys, datas, records, metadata, file);

    // Close file
    fclose(file);

    return 0;
}
