pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initRecords(int capacity, int limit) {
    if (capacity > recordCapacity) {
        recordCapacity = capacity;
        records = realloc(records, sizeof(Record) * capacity);
    }
    memoryLimit = limit;
}

Record* getRecord(int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < recordCount) {
        Record* record = &records[index];
        pthread_mutex_unlock(&lock);
        return record;
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

void updateRecord(int index, int value) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < recordCount) {
        Record* record = &records[index];
        record->value = value;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}

int getRecordValue(int index) {
    pthread_mutex_lock(&lock);
    if (index >= 0 && index < recordCount) {
        Record* record = &records[index];
        int value = record->value;
        pthread_mutex_unlock(&lock);
        return value;
    } else {
        pthread_mutex_unlock(&lock);
        return -1;
    }
}

void resizeRecords() {
    int newCapacity = recordCapacity * 2 + 1;
    if (newCapacity > memoryLimit) {
        newCapacity = memoryLimit;
