#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Function to calculate average of valid numbers
double average_helper(double *arr, int n) {
    double sum = 0;
    for(int i=0; i<n; i++) {
        sum += arr[i];
    }
    return sum / (double)n;
}

int main() {
    int max_len = 1000; // Max length of array
    double *arr = (double*)malloc(max_len * sizeof(double));
    int len = 0;

    while(1) {
        double num;
        if(scanf("%lf", &num) != 1) break;

        if(num < -10.0 || num > 10.0) { // Check for numbers within range
            printf("Invalid number: %f\n", num);
            continue;
        }

        arr[len++] = num; // Store valid numbers

        if(len >= max_len) {
            double *temp = (double*)malloc((max_len*2) * sizeof(double));
            memcpy(temp, arr, max_len * sizeof(double));
            free(arr);
            arr = temp;
            max_len *= 2;
        }
    }

    printf("Average: %f\n", average_helper(&arr[0], len));

    free(arr); // Free memory

    return 0;
}
