// Define a custom memory allocator structure
typedef struct {
    void* base;
    size_t size;
    size_t used;
} MemoryPool;

// Custom memory allocator function
MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->base = malloc(initial_size);
    pool->size = initial_size;
    pool->used = 0;
    return pool;
}

// Allocate a block of memory from the pool
void* mem_pool_alloc(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        // Pool is full; reallocate and expand
        pool->base = realloc(pool->base, pool->size * 2);
        pool->size *= 2;
    }
    void* ptr = ((char*)pool->base) + pool->used;
    pool->used += size;
    return ptr;
}

// Free a block of memory back to the pool
void mem_pool_free(MemoryPool* pool, void* ptr, size_t size) {
    pool->used -= size;
}

// Define the record structure
typedef struct {
    int value;
    MemoryPool* hash_table;
} Record;

// Define the hash table structure
typedef struct {
    Record** records;
    size_t size;
    size_t used;
} HashTable;

// Create a new hash table
HashTable* create_hash_table(size_t initial_size) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->records = (Record**)malloc(initial_size * sizeof(Record*));
    ht->size = initial_size;
    ht->used = 0;
    return ht;
}

// Insert a record into the hash table
void insert_record(HashTable* ht, Record* record) {
    int key = record->value;
    size_t index = key % ht->size;
    if (ht->records[index] == NULL) {
        ht->records[index] = &record;
        ht->used++;
    } else {
        // Collision; search for empty slot or resize
        for (int i = 0; i < ht->size; i++) {
            size_t index2 = (index + i) % ht->size;
            if (ht->records[index2] == NULL) {
                ht->records[index2] = &record;
                ht->used++;
                return;
            }
        }
    }
}

// Define the linked list structure
typedef struct {
    Record* head;
} LinkedList;

// Create a new linked list
LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    list->head = NULL;
    return list;
}

// Insert a record into the linked list
void insert_record_linked(LinkedList* list, Record* record) {
    record->next = list->head;
    list->head = record;
}

// Define the complex data structure
typedef struct {
    long offset;
    int key;
    Record* record;
    LinkedList* linked_list;
    HashTable* hash_table;
} DataStructure;

// Create a new data structure
DataStructure* create_data_structure() {
    DataStructure* ds = malloc(sizeof(DataStructure));
    ds->offset = 0;
    ds->key = 0;
    ds->record = NULL;
    ds->linked_list = create_linked_list();
    ds->hash_table = create_hash_table(16);
    return ds;
}

// Define the main function
int main() {
    // Create a new data structure and allocate memory from the pool
    DataStructure* ds = create_data_structure();
    MemoryPool* pool = create_memory_pool(1024);

    // Allocate records and insert them into the hash table and linked list
    for (int i = 0; i < 16; i++) {
        Record* record = mem_pool_alloc(pool, sizeof(Record));
        record->value = i;
        record->hash_table = ds->hash_table;
        insert_record(ds->hash_table, record);
        insert_record_linked(ds->linked_list, record);
    }

    // Free the allocated memory and data structures
    mem_pool_free(pool, NULL, 0);
    free(ds->hash_table->records);
    free(ds->hash_table);
    free(ds->linked_list);
    free(ds);

    return 0;
}

