    coll->nodes = (Node**)malloc(capacity * sizeof(Node*));
    coll->size = 0;
    pthread_mutex_init(&coll->lock, NULL);
}

int insert_node(Collection* coll, Node* node) {
    pthread_mutex_lock(&coll->lock);

    // Check if the collection has reached its capacity
    if (coll->size >= coll->nodes[0]->size) {
        // Reallocate memory to accommodate more nodes
        coll->nodes = (Node**)realloc(coll->nodes, (coll->size * 2 + 1) * sizeof(Node*));
    }

    coll->nodes[coll->size] = node;
    coll->size++;

    pthread_mutex_unlock(&coll->lock);
    return 0;
}

int remove_node(Collection* coll, int index) {
    pthread_mutex_lock(&coll->lock);

    if (index < 0 || index >= coll->size) {
        // Handle error: invalid node index
        pthread_mutex_unlock(&coll->lock);
        return -1;
    }

    for (int i = index; i < coll->size - 1; i++) {
        coll->nodes[i] = coll->nodes[i + 1];
    }

    free(coll->nodes[coll->size - 1]);
    coll->size--;

    pthread_mutex_unlock(&coll->lock);
    return 0;
}

int update_node(Collection* coll, int index, char key[], void* record) {
    pthread_mutex_lock(&coll->lock);

    if (index < 0 || index >= coll->size) {
        // Handle error: invalid node index
        pthread_mutex_unlock(&coll->lock);
        return -1;
    }

    coll->nodes[index]->key = key;
    coll->nodes[index]->record = record;

    pthread_mutex_unlock(&coll->lock);
    return 0;
}

void destroy_collection(Collection* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->nodes[i]);
    }

    free(coll->nodes);
    pthread_mutex_destroy(&coll->lock);
}
