// Dynamic memory allocation function
void* dynamicResourceManager(size_t size) {
    // Allocate memory using a combination of mmap and malloc
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (ptr == MAP_FAILED) {
        ptr = malloc(size);
        if (!ptr) {
            return NULL;
        }
    }

    // Initialize the memory
    memset(ptr, 0, size);

    return ptr;
}

// Helper function to read integers from standard input and determine the largest integer
int findLargestInteger() {
    int maxInt = INT_MIN;
    while (1) {
        int num;
        scanf("%d", &num);
        if (num == EOF)
            break;
        if (num > maxInt)
            maxInt = num;
    }
    return maxInt;
}

// Function to modify the extension of a given filename
void modifyExtension(const char *filename, const char *newExt) {
    // Determine the number of digits and file type based on the existing filename components
    int i, j, k;
    for (i = strlen(filename); i > 0; i--) {
        if (filename[i] == '.')
            break;
    }
    for (j = i - 1; j >= 0; j--) {
        if (!isalnum(filename[j]))
            break;
        k = j;
    }

    // Modify the extension
    char newFilename[k + strlen(newExt) + 1];
    strcpy(newFilename, filename);
    strcat(strcat(strcpy(&newFilename[0], &filename[0]), "."), newExt);

    printf("%s\n", newFilename);
}
