package com.inventory.management;

import java.time.LocalDateTime;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class InventoryManagementSystem {
    private static final int INITIAL_CAPACITY = 1000;
    private static final int GROWTH_FACTOR = 2;

    private final Lock lock = new ReentrantLock();
    private final AtomicInteger capacity = new AtomicInteger(INITIAL_CAPACITY);
    private final Product[] products = new Product[INITIAL_CAPACITY];
    private final Sale[] sales = new Sale[INITIAL_CAPACITY];

    public void addProduct(String productName, double price, int quantity, long supplierId) {
        lock.lock();
        try {
            if (products.length * 2 > capacity.get()) {
                growCapacity();
            }
            products[getInsertIndex()] = new Product(productName, price, quantity, supplierId);
        } finally {
            lock.unlock();
        }
    }

    public void addSale(int productId, int quantitySold, long customerId) {
        lock.lock();
        try {
            if (sales.length * 2 > capacity.get()) {
                growCapacity();
            }
            sales[getInsertIndex()] = new Sale(productId, quantitySold, LocalDateTime.now(), customerId);
        } finally {
            lock.unlock();
        }
    }

    public void updateProduct(int productId, double price) {
        lock.lock();
        try {
            for (int i = 0; i < products.length; i++) {
                if (products[i] != null && products[i].getId() == productId) {
                    products[i].setPrice(price);
                    return;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public void updateSale(int saleId, int quantitySold) {
        lock.lock();
        try {
            for (int i = 0; i < sales.length; i++) {
                if (sales[i] != null && sales[i].getId() == saleId) {
                    sales[i].setQuantitySold(quantitySold);
                    return;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public void removeProduct(int productId) {
        lock.lock();
        try {
            for (int i = 0; i < products.length; i++) {
                if (products[i] != null && products[i].getId() == productId) {
                    products[i] = null;
                    return;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public void removeSale(int saleId) {
        lock.lock();
        try {
            for (int i = 0; i < sales.length; i++) {
                if (sales[i] != null && sales[i].getId() == saleId) {
                    sales[i] = null;
                    return;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    private int getInsertIndex() {
        for (int i = 0; i < products.length; i++) {
            if (products[i] == null) {
                return i;
            }
        }
        growCapacity();
        return products.length - 1;
    }

    private void growCapacity() {
        capacity.set(capacity.get() * GROWTH_FACTOR);
        Product[] newProducts = new Product[capacity.get()];
        System.arraycopy(products, 0, newProducts, 0, products.length);
        products = newProducts;

        Sale[] newSales = new Sale[capacity.get()];
        System.arraycopy(sales, 0, newSales, 0, sales.length);
        sales = newSales;
    }
}

