```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void handleFileProcessing(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Invalid file path\n");
        return;
    }

    char* buffer = NULL;
    size_t buffer_size = 0;

    int word_count = 0;
    int unique_words = 0;
    int max_freq = 0;
    char** words = NULL;

    clock_t start_time = clock();

    while (1) {
        size_t read_size = fread(buffer + buffer_size, 1, 4096, file);
        if (read_size == 0) break; // end of file
        buffer_size += read_size;
        char* p = buffer;
        char* end = buffer + read_size;

        while (p < end) {
            if (*p == ' ') {
                *p++ = '\0';
                word_count++;
            } else if (*p == '\n' || *p == '\0') {
                *p-- = '\0'; // include the newline
                word_count++;
                p++; // skip the newline
            }
            p++;
        }

        free(buffer);
        buffer = (char*)malloc(read_size + 1);
        memcpy(buffer, p - read_size, read_size);
        buffer[read_size] = '\0';
    }

    fclose(file);

    if (word_count == 0) {
        printf("No valid words found.\n");
        return;
    }

    words = (char**)malloc(word_count * sizeof(char*));
    for (int i = 0; i < word_count; i++) {
        char* word = strtok(buffer, " ");
        if (word == NULL) break;
        words[i] = strdup(word);
    }

    int max_index = -1;
    for (int i = 0; i < word_count; i++) {
        int freq = 0;
        for (int j = 0; j < word_count; j++) {
            if (strcmp(words[j], words[i]) == 0) freq++;
        }
        if (freq > max_freq) {
            max_freq = freq;
            max_index = i;
        }
    }

    printf("Top 5 most frequent words:\n");
    for (int i = 0; i < 5 && i < word_count; i++) {
        printf("%s (%d)\n", words[max_index - i], max_freq);
    }

    free(buffer);
    free(words);

    clock_t end_time = clock();
    double elapsed_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("File processing time: %f seconds\n", elapsed_time);
}

int main() {
    handleFileProcessing("path/to/large/text/file.txt");
    return 0;
}
