#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent an event (memory allocation or deallocation)
typedef struct {
    int tid; // thread ID
    char *msg; // error message (if any)
    void *ptr; // pointer to allocated/deallocated memory
} Event;

// Structure for a record
typedef struct {
    int val;
    time_t timestamp;
    int error_flag;
} Record;

// Structure to represent the custom memory pool
typedef struct {
    void **mem_pool;
    size_t capacity;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool with a specified capacity
MemoryPool *init_memory_pool(size_t capacity) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->mem_pool = (void **)calloc(capacity, sizeof(void *));
    pool->capacity = capacity;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to allocate memory from the custom pool
void *malloc_from_pool(MemoryPool *pool) {
    void **mem_pool = pool->mem_pool;
    size_t used_size = pool->used_size;

    // Check if the pool is exhausted
    if (used_size >= pool->capacity) {
        // Dynamically resize the pool if necessary
        size_t new_capacity = pool->capacity * 2;
        mem_pool = realloc(mem_pool, sizeof(void *) * new_capacity);
        pool->mem_pool = mem_pool;
        pool->capacity = new_capacity;
    }

    // Allocate memory from the pool
    void *ptr = mem_pool[used_size];
    mem_pool[used_size] = NULL; // mark as free
    pool->used_size++;
    return ptr;
}

// Function to deallocate memory and update the event list
void free_and_log(Event *event, MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    void *ptr = malloc_from_pool(pool);

    if (ptr == NULL) {
        // Handle allocation failure
        event->msg = "Memory allocation failed";
    } else {
        // Update the event list with successful deallocation
        event->tid = pthread_self();
        event->msg = "Memory deallocated successfully";
        event->ptr = ptr;
    }

    pthread_mutex_unlock(&pool->lock);
}

// Function to release all allocated memory and update the event list
void cleanup_and_log(MemoryPool *pool, Event *event) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->used_size; i++) {
        free_and_log(event + i, pool);
    }

    pthread_mutex_unlock(&pool->lock);
}

int main() {
    // Initialize the memory pool with a capacity of 10
    MemoryPool *pool = init_memory_pool(10);

    // Initialize three arrays: long offset values, int keys, and record structures
    size_t arr_size = 100;
    long *offsets = (long *)malloc(arr_size * sizeof(long));
    int *keys = (int *)malloc(arr_size * sizeof(int));
    Record *records = (Record *)malloc(arr_size * sizeof(Record));

    // Initialize the event list with an initial capacity of 10
    Event *events = (Event *)malloc(10 * sizeof(Event));
    size_t events_capacity = 10;
    pthread_mutex_init(&events->lock, NULL);

    // Set random values for each record's int field and update the event list
    for (size_t i = 0; i < arr_size; i++) {
        Record *record = &records[i];
        int val = rand() % 100;
        record->val = val;
        record->timestamp = time(NULL);
        record->error_flag = 0;

        // Update the event list with successful allocation
        Event *event = events + i % events_capacity;
        event->tid = pthread_self();
        event->msg = "Memory allocated successfully";
        event->ptr = &records[i];
    }

    // Clean up and log memory usage statistics and any errors encountered during operation
    cleanup_and_log(pool, events);

    return 0;
}
