public class LogProcessor {
    private static final int RECORDS_PER_WINDOW = 100;
    private static final long MAX_BYTE_LIMIT = 1024 * 1024 * 50; // 50MB

    public void processLogFile(String logFilePath) throws IOException {
        try (BufferedReader br = new BufferedReader(new FileReader(logFilePath))) {
            List<LogRecord> records = new ArrayList<>();
            Map<String, LogRecord> recordMap = new ConcurrentHashMap<>();

            long totalBytesAllocated = 0;
            AtomicLong lastRecordId = new AtomicLong(0);

            long startProcessingTime = System.currentTimeMillis();

            String line;
            int windowCount = 0;

            while ((line = br.readLine()) != null) {
                LogRecord record = parseLogRecord(line);
                if (record == null) continue;

                totalBytesAllocated += record.getSizeInBytes();
                if (totalBytesAllocated > MAX_BYTE_LIMIT) {
                    // Handle memory allocation failure
                    System.out.println("Memory limit exceeded. Releasing unused records...");
                    records.clear();
                    recordMap.clear();
                    totalBytesAllocated = 0;
                }

                if (records.size() >= RECORDS_PER_WINDOW) {
                    processWindow(records, recordMap);
                    records.clear();
                    recordMap = new ConcurrentHashMap<>();
                    windowCount++;
                } else {
                    records.add(record);
                }
            }

            if (!records.isEmpty()) {
                processWindow(records, recordMap);
            }

            long endProcessingTime = System.currentTimeMillis();
            System.out.println("Processed " + windowCount + " windows in " + (endProcessingTime - startProcessingTime) + " milliseconds.");
        }
    }

    private LogRecord parseLogRecord(String line) {
        // Implement JSON parsing logic here
    }

    private void processWindow(List<LogRecord> records, Map<String, LogRecord> recordMap) {
        for (int i = 0; i < RECORDS_PER_WINDOW && i < records.size(); i++) {
            LogRecord record = records.get(i);
            recordMap.put(record.getActionType(), record);

            if (i >= 100) {
                recordMap.remove(records.get(i - 100).getActionType());
            }
        }

        System.out.println("Window processed. Count: " + recordMap.size());

        for (LogRecord record : records.subList(0, RECORDS_PER_WINDOW)) {
            System.out.println(record);
        }
    }
}

