    if (size < 0 || !pool) {
        return;
    }

    record_t** new_pool = realloc(pool, (size + 1) * sizeof(record_t*));
    if (!new_pool) {
        // Handle memory allocation failure
        return;
    }
    pool = new_pool;

    pool[size] = new_rec;
    size++;
}

