        }
    }
    return NULL;
}

void record_pool_serialize(record_t** pool, int size, FILE* file) {
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        record_t* rec = pool[i];
        fwrite(&rec->value, sizeof(int), 1, file);
        fwrite(&rec->timestamp, sizeof(long), 1, file);
