class DynamicEventManager {
public:
    class Event {
    public:
        std::string timestamp;
        std::string eventType;
        std::string metadata;
        std::pair<double, double> locationCoords;
        std::vector<std::string> userIdentifiers;

        Event(const std::string& ts, const std::string& et,
              const std::string& md, const std::pair<double, double>& lc,
              const std::vector<std::string>& uids)
            : timestamp(ts), eventType(et), metadata(md),
              locationCoords(lc), userIdentifiers(uids) {}
    };

    DynamicEventManager() {}

    ~DynamicEventManager() {
        for (auto& it : events_) {
            delete it.second;
        }
    }

    void addEvent(const Event& e) {
        events_[e.timestamp] = new Event(e);
    }

    std::shared_ptr<Event> getEvent(const std::string& timestamp) {
        auto it = events_.find(timestamp);
        if (it != events_.end()) {
            return std::make_shared<Event>(*it->second);
        }
        return nullptr;
    }

private:
    std::unordered_map<std::string, Event*> events_;
};
