typedef struct {
    float* values;
    int size;
} vector;

typedef struct {
    int rows;
    int cols;
    vector** data;
} matrix;

matrix* initMatrix(int rows, int cols, int maxMem) {
    matrix* mat = (matrix*)malloc(sizeof(matrix));
    if (!mat) return NULL; // allocation failed

    mat->rows = rows;
    mat->cols = cols;
    mat->data = (vector**)calloc(rows, sizeof(vector*));

    for (int i = 0; i < rows; i++) {
        vector* row = (vector*)malloc(sizeof(vector));
        if (!row) return NULL; // allocation failed

        int size = min(cols, maxMem / sizeof(float)); // ensure memory usage doesn't exceed limit
        row->values = (float*)calloc(size, sizeof(float));
        row->size = size;
        mat->data[i] = row;
    }

    return mat;
}

vector* initVector(int size, int maxMem) {
    vector* vec = (vector*)malloc(sizeof(vector));
    if (!vec) return NULL; // allocation failed

    vec->values = (float*)calloc(size, sizeof(float));
    vec->size = size;

    return vec;
}

double dotProduct(matrix* mat1, matrix* mat2, int row) {
    double sum = 0.0;
    vector* row1 = mat1->data[row];
    vector* row2 = mat2->data[row];

    for (int i = 0; i < min(row1->size, row2->size); i++) {
        sum += row1->values[i] * row2->values[i];
    }

    return sum;
}

void updateVector(matrix* mat, int row, vector* newVec) {
    if (row >= mat->rows || newVec->size != mat->data[row]->size) return; // invalid index or size mismatch

    free(mat->data[row]->values);
    mat->data[row]->values = newVec->values;
}

void updateMatrix(matrix* mat, int row, matrix* newMat) {
    if (row >= mat->rows || newMat->rows != 1 || newMat->cols != mat->cols) return; // invalid index or size mismatch

    for (int i = 0; i < mat->data[row]->size; i++) {
        free(mat->data[row]->values);
        mat->data[row]->values = ((float*)newMat->data[0]->values + i * newMat->data[0]->size);
    }
}

void freeMatrix(matrix* mat) {
    for (int i = 0; i < mat->rows; i++) {
        free(mat->data[i]->values);
        free(mat->data[i]);
    }
    free(mat->data);
    free(mat);
}
