int manageMemory(int* offsets, int* keys, record** records, int capacity, int limit) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for offset and key arrays
    if (*offsets == NULL && *keys == NULL) {
        *offsets = (int*)malloc(capacity * sizeof(int));
        *keys = (int*)malloc(capacity * sizeof(int));
    }

    // Initialize record array
    if (*records == NULL) {
        *records = initRecords(capacity);
