    for (int i = 0; i < capacity; i++) {
        (*records)[i].key = rand() % 100;
        printf("Record %d: key = %d\n", i, (*records)[i].key);

        // Check memory usage and resize if necessary
        int total_size = (int)sizeof(int) * (capacity + capacity);
        if (total_size > limit) {
            printf("Memory usage exceeded! Resizing...\n");
            capacity *= 2;
            *offsets = realloc(*offsets, capacity * sizeof(int));
            *keys = realloc(*keys, capacity * sizeof(int));
            *records = realloc(*records, capacity * sizeof(record));
            printf("Resized arrays: offsets=%p, keys=%p, records=%p\n", *offsets, *keys, *records);
        }
    }

    return 0;
}

