#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define RECORD_SIZE 100
#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 10000

typedef struct {
    int key;
    int value;
    char *str;
} record;

record *load_records(const char *filename, long *total_count) {
    // Load records from file
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    long total_count_val = 0;
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    record *records = (record *)malloc((MAX_RECORDS + 1) * sizeof(record));
    long *keys = (long *)malloc((MAX_KEY + 1) * sizeof(long));

    for (int i = 0; i <= MAX_KEY; i++) {
        keys[i] = -1;
    }

    record temp;
    while (fread(&temp, RECORD_SIZE, 1, file)) {
        if (temp.key < MIN_KEY || temp.key > MAX_KEY) {
            // Invalid key
            fclose(file);
            free(records);
            free(keys);
            return NULL;
        }
        records[total_count_val].key = temp.key;
        records[total_count_val].value = temp.value;
        records[total_count_val].str = (char *)malloc(strlen(temp.str) + 1);
        strcpy(records[total_count_val].str, temp.str);

        if (keys[temp.key] != -1) {
            // Duplicate key
            fclose(file);
            free(records);
            free(keys);
            return NULL;
        }
        keys[temp.key] = total_count_val;
        total_count_val++;
    }

    *total_count = total_count_val;

    fclose(file);

    return records;
}

void free_records(record *records, long total_count) {
    for (int i = 0; i < total_count; i++) {
        if (records[i].str) {
            free(records[i].str);
        }
    }

    free(records);
    free((long *)keys); // Assuming keys is declared globally
}

void save_records(const char *filename, record *records, long total_count) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    for (int i = 0; i < total_count; i++) {
        fwrite(&records[i], RECORD_SIZE, 1, file);
    }

    fclose(file);
}

record *create_records(long total_count, long keys_count) {
    record *records = (record *)malloc(total_count * sizeof(record));

    for (int i = 0; i < total_count; i++) {
        records[i].key = rand() % (keys_count - MIN_KEY + 1) + MIN_KEY;
        records[i].value = rand();
        char buf[RECORD_SIZE];
        sprintf(buf, "Record %d", i);
        records[i].str = strdup(buf);
    }

    return records;
}

int main() {
    record *records = create_records(1000, 10000);
    long total_count = 0;

    // Load and validate records
    record *loaded_records = load_records("testfile.bin", &total_count);
    if (!loaded_records) {
        printf("Error loading records.\n");
        free_records(records, 1000);
        return 1;
    }

    // Process and modify records as needed

    // Save modified records back to file
    save_records("testfile.bin", loaded_records, total_count);

    free_records(loaded_records, total_count);
    free_records(records, 1000);
    return 0;
}
