// Define structure for record
typedef struct {
    int key;
    long offset;
    struct {
        int value;
        time_t timestamp;
    } record;
} Record;

// Function to manage dynamic pool of records
Record* allocateRecords(int size, const char* filename) {
    // Initialize record pool
    Record* records = (Record*)malloc(size * sizeof(Record));

    if (!records) {
        printf("Memory allocation failed for %s.\n", filename);
        return NULL;
    }

    // Initialize timestamp for each record
    time_t current_time = time(NULL);

    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].offset = i * sizeof(Record);
        records[i].record.value = i;
        records[i].record.timestamp = current_time;
    }

    return records;
}

// Function to generate new filename
const char* generateNewFilename(const char* original_filename, int max_base_name_length) {
    // Extract base name and extension from input filename
    const char* base_name = strrchr(original_filename, '/');
    if (!base_name) {
        base_name = original_filename;
    } else {
        *base_name = '\0';
    }

    // Get length of base name
    int base_name_length = strlen(base_name);

    // Determine new extension based on base name length
    char* new_extension = (char*)malloc(10 + 1); // Allocate space for numeric suffix and null terminator
    sprintf(new_extension, ".%d", base_name_length);

    // Create new filename by combining base name and new extension
    const char* new_filename = malloc(strlen(base_name) + strlen(new_extension) + 1);
    strcpy(new_filename, base_name);
    strcat(new_filename, ".");
    strcat(new_filename, new_extension);

    free(new_extension);

    return new_filename;
}

// Function to handle filenames with no extension
const char* appendDefaultExtension(const char* filename, const char* default_extension) {
    if (strrchr(filename, '.') == NULL) {
        // No extension found, append default extension
        char* new_filename = malloc(strlen(filename) + strlen(default_extension) + 1);
        strcpy(new_filename, filename);
        strcat(new_filename, ".");
        strcat(new_filename, default_extension);

        free(filename);
        return new_filename;
    } else {
        return filename;
    }
}

// Function to handle filenames longer than 255 characters
const char* truncateFilename(const char* filename) {
    // Check if filename exceeds maximum length
    if (strlen(filename) > 255) {
        // Truncate filename to fit within limit
        char* new_filename = malloc(256);
        strncpy(new_filename, filename, 255);
        new_filename[255] = '\0';

        free(filename);
        return new_filename;
    } else {
        return filename;
    }
}

// Function to handle filenames with custom prefix
const char* prependPrefix(const char* filename, const char* prefix) {
    // Check if prefix is too long for the filename
    int total_length = strlen(prefix) + strlen(filename);

    if (total_length > 255) {
        // Truncate filename to fit within limit
        char* new_filename = malloc(256);
        strncpy(new_filename, filename, 255 - strlen(prefix));
        strcpy(new_filename + 255 - strlen(prefix), prefix);

        free(filename);
        return new_filename;
    } else {
        return malloc(total_length);
    }
}

