record* processList(int** records, size_t* count) {
    *count = 0;
    *records = NULL;

    record* currentRecord = NULL;
    record* lastRecord = NULL;

    int temp;
    while (scanf("%d", &temp) == 1) {
        if (*count >= 1000000) {
            printf("Error: Too many integers. Limit exceeded.\n");
            exit(1);
        }

        currentRecord = (record*)malloc(sizeof(record));
        if (!currentRecord) {
            printf("Error: Out of memory.\n");
            exit(1);
        }
        lastRecord->value = temp;
        *count += 1;

        if (!*records) {
            *records = currentRecord;
        } else {
            lastRecord = currentRecord;
        }
    }

    return *records;
}

void freeRecords(record* records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(records + i);
    }
    free(records);
}

