    record* array = (record*)malloc(count * sizeof(record));
    if (!array) {
        printf("Error: Out of memory.\n");
        exit(1);
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; i++) {
        array[i].value = rand() % (max - min + 1) + min;
    }

    return array;
