        return new System.Random();
    }
}

public class MemoryManager
{
    private int _size;
    private Record[] _records;

    public MemoryManager(int size, Dictionary<string, string> environmentVariables)
    {
        if (size <= 0)
            throw new ArgumentException("Size must be a positive integer.");
        try
        {
            if (!int.TryParse(environmentVariables["MEMORY_SIZE"], out _size))
                throw new ArgumentException("Invalid memory size specified in environment variables.");
        }
        catch (Exception e)
        {
            Console.WriteLine(e.Message);
            // fallback strategy to reduce memory usage
        }

        if (_size > Environment.MachineName.Length)
            _size = Environment.MachineName.Length;
    }

    public void InitializeMemory(RandomValueGenerator valueGenerator, Random random)
    {
        try
        {
            _records = new Record[_size];
            for (int i = 0; i < _size; i++)
                _records[i] = new Record { Key = i, Offset = new Random().Next(), Value = valueGenerator.GetRandomValue(random) };
        }
        catch (Exception e)
        {
            Console.WriteLine(e.Message);
            // fallback mechanism to minimize memory usage when allocation fails
        }
    }
}
