typedef enum {CAT_A, CAT_B, CAT_C} category;

struct data_element {
    unsigned int counter;
    char buffer[16];
    category* ptr;
};

void* manage_memory(size_t budget) {
    size_t total_size = 0;
    struct data_element* elements = NULL;
    category* categories = NULL;

    while (total_size < budget) {
        if (elements == NULL && categories == NULL) {
            // Allocate memory for arrays of double, unsigned long, and enum category
            double* doubles = malloc(8);
            size_t* unsigned_long = malloc(4);
            category* cat_array = malloc(2);

            // Initialize arrays
            for (int i = 0; i < 4; i++) {
                *(doubles + i) = 1.5;
                *(unsigned_long + i) = 42;
                *(*(cat_array + i) + 0) = CAT_A;
                *(*(cat_array + i) + 1) = CAT_B;
            }

            // Allocate memory for arrays of struct data_element
            elements = malloc(8);
            categories = malloc(2);

            // Initialize arrays
            for (int i = 0; i < 4; i++) {
                ((struct data_element*)elements + i)->counter = 5;
                strcpy(((struct data_element*)elements + i)->buffer, "Hello");
                ((struct data_element*)elements + i)->ptr = &cat_array[i];
            }

            // Allocate memory for category array
            categories[0] = CAT_A;
            categories[1] = CAT_B;

            total_size += 8 * sizeof(double) + 4 * sizeof(size_t) + 2 * sizeof(category);
        }
    }

    return elements;
}

void free_memory(void* ptr, size_t budget) {
    if (ptr != NULL) {
        free(ptr);
        // Release unused memory back to the operating system
        munmap(ptr, budget);
    }
}

size_t find_smallest(double* array) {
    double smallest = array[0];
    for (int i = 1; i < 4; i++) {
        if (array[i] < smallest) {
            smallest = array[i];
        }
