typedef struct node {
    int key;
    long offset;
    int value;
    struct node* prev;
    struct node* next;
} Node;

void manage_dataset(int num_records) {
    // Initialize arrays for offset values, keys, and record structures
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    Node* records = (Node*)malloc(num_records * sizeof(Node));

    // Initialize doubly linked list of nodes
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < num_records; i++) {
        // Dynamically allocate memory for each record's int field
        records[i].value = rand() % 100 + 1;

        // Set node's predecessor and successor pointers
        if (i == 0) {
            head = &records[i];
            tail = &records[i];
        } else {
            tail->next = &records[i];
            &records[i]->prev = tail;
            tail = &records[i];
        }
    }

    // Read list of integers from standard input and store them in an array
    int* values = (int*)malloc(10000 * sizeof(int));
    for (int i = 0; i < 10000; i++) {
        scanf("%d", &values[i]);
    }

    // Find and print the largest integer in the array using a helper function
    int max_value = find_max(values, 10000);
    printf("Largest integer: %d\n", max_value);

    // Free all allocated memory to prevent memory leaks
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(&records[i]);
    }
    free(records);
}

int find_max(int* values, int size) {
    int max_value = values[0];
    for (int i = 1; i < size; i++) {
        if (values[i] > max_value)
            max_value = values[i];
    }
    return max_value;
}
