#include <string.h>
#include <stdint.h>
#include <md5.h>

typedef struct {
    int key;
} Record;

void* generateDataRecords(int recordCount, int minValue, int maxValue, size_t bufferSize) {
    // Check for invalid input values
    if (recordCount <= 0 || minValue > maxValue) {
        return NULL;
    }

    size_t totalBytes = sizeof(long) * recordCount + sizeof(Record) * recordCount;

    // Calculate the actual buffer size limit
    size_t maxBufferCapacity = bufferSize - sizeof(md5_state_t);

    if (totalBytes > maxBufferCapacity) {
        return NULL;  // Insufficient buffer space
    }

    long* offsets = (long*)malloc(sizeof(long) * recordCount);
    Record* records = (Record*)malloc(sizeof(Record) * recordCount);

    for (int i = 0; i < recordCount; i++) {
        int randomInt = rand() % ((maxValue - minValue + 1)) + minValue;
        records[i].key = randomInt;
        offsets[i] = (long)randomInt;
    }

    // Calculate the MD5 hash of concatenated offsets and keys
    char* buffer = (char*)malloc(totalBytes);
    for (int i = 0; i < recordCount; i++) {
        sprintf(buffer + strlen(buffer), "%ld_%d", offsets[i], records[i].key);
    }
    md5_state_t state;
    md5_init(&state);
    md5_append(&state, buffer, strlen(buffer));
    char hash[33];
    md5_finish(&state, hash);

    free(offsets);
    free(records);
    free(buffer);

    return (void*)hash;
}
