#define BUFFER_POOL_SIZE 1024
#define RECORD_SIZE sizeof(record)

struct record {
    int value;
};

void* allocate_buffer(int size) {
    void* buffer = malloc(size);
    if (buffer == NULL) {
        printf("Memory allocation failed. Trying again...\n");
        return allocate_buffer(size);
    }
    return buffer;
}

int free_buffer(void* buffer, int size) {
    free(buffer);
    return 0;
}

void manage_memory(int num_offsets, int num_keys, int record_size) {
    // Initialize offset and key arrays
    long** offsets = (long**)malloc(num_offsets * sizeof(long*));
    int** keys = (int**)malloc(num_keys * sizeof(int*));

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = allocate_buffer(sizeof(long));
        *(offsets[i]) = i;
    }

    for (int i = 0; i < num_keys; i++) {
        keys[i] = allocate_buffer(sizeof(int));
        *(keys[i]) = i;
    }

    // Initialize buffer pool
    void** buffer_pool = (void**)malloc(BUFFER_POOL_SIZE * RECORD_SIZE);
    int buffer_idx = 0;

    for (int i = 0; i < num_offsets; i++) {
        record r;
        r.value = rand() % 10000;
        void* buffer = allocate_buffer(RECORD_SIZE);
        memcpy(buffer, &r, RECORD_SIZE);
        buffer_pool[buffer_idx] = buffer;
        buffer_idx++;
    }

    // Report memory usage
    printf("Peak memory consumption: %lu KB\n", (unsigned long)(num_offsets * sizeof(long) + num_keys * sizeof(int)) / 1024);
    printf("Current allocation status: %d records and %d keys allocated.\n", buffer_idx, num_keys);

    free_buffer(buffer_pool[0], RECORD_SIZE); // Free the first buffer
}

void* thread_func(void* arg) {
    manage_memory(10, 5, sizeof(struct record));
    return NULL;
}

int main() {
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
