    // Initialize file pointer and read configuration
    FILE* file = fopen(filePath, "r");
    if (!file) {
        return NULL;
    }

    // Read configuration settings
    int threshold = 0; // Read from file
    bool useDeterministic = false; // Read from file

    // Allocate memory for arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record_t* records = (record_t*)malloc(size * sizeof(record_t));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        if (useDeterministic) {
            long offset = lrand48();
            int key = drand48() * (maxVal - minVal) + minVal;
        } else {
            offsets[i] = rand();
            keys[i] = rand() % (maxVal - minVal) + minVal;
        }
    }

    // Initialize record array
    for (int i = 0; i < size; i++) {
        records[i].value = keys[i];
    }

    // Concatenate arrays into byte buffer
    uint8_t* buffer = (uint8_t*)malloc(size * sizeof(uint8_t));
    memcpy(buffer, offsets, size * sizeof(long));
    memcpy(buffer + size * sizeof(long), keys, size * sizeof(int));

    // Compute hash using SHA-256
    unsigned char* hash = (unsigned char*)malloc(32);
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, buffer, size * 8);
    SHA256_Final(hash, &sha256);

    // Convert hash to hexadecimal and free memory
    char* hexHash = malloc(65);
    for (int i = 0; i < 32; i++) {
        sprintf(hexHash + i * 2, "%02x", hash[i]);
    }
    free(buffer);
    free(hash);

    return records;
}
