#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SESSION_MAX 1000
#define LOG_FILE "session.log"
#define CONFIG_FILE "config.conf"

// Configuration structure
typedef struct {
    int session_max;
    char log_file[20];
} config_t;

// Session structure
typedef struct {
    int id;
    void* data; // Dynamically allocated memory for session data
} session_t;

// Function prototypes
void* handle_request(void* arg);
int load_config(config_t* config);
void save_config(config_t* config);
session_t* create_session(int id);
void free_session(session_t* session);

config_t config;
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Initialize configuration
    load_config(&config);

    // Create a socket for listening
    int sockfd, connfd;
    struct sockaddr_in servaddr, cliaddr;
    socklen_t clientlen = sizeof(cliaddr);
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }
    memset(&servaddr, '0', sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(8080);
    if (bind(sockfd, (struct sockaddr*) &servaddr, sizeof(servaddr)) < 0) {
        perror("bind failed");
        return -1;
    }
    listen(sockfd, 3);
    printf("Listening on port 8080...\n");

    // Handle incoming requests concurrently
    pthread_t tid[SESSION_MAX];
    for (int i = 0; i < SESSION_MAX; i++) {
        if (pthread_create(&tid[i], NULL, handle_request, NULL) != 0) {
            perror("thread creation failed");
            return -1;
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < SESSION_MAX; i++) {
        pthread_join(tid[i], NULL);
    }

    // Close the socket
    close(sockfd);

    return 0;
}

void* handle_request(void* arg) {
    int sockfd, connfd;
    struct sockaddr_in cliaddr;
    socklen_t clientlen = sizeof(cliaddr);

    // Accept a connection
    if ((connfd = accept(sockfd, (struct sockaddr*) &cliaddr, &clientlen)) < 0) {
        perror("accept failed");
        return NULL;
    }

    int session_id;
    char request[1024];
    read(connfd, request, sizeof(request));

    // Verify session ID and update session data as needed
    pthread_mutex_lock(&session_mutex);
    session_t* session = get_session(session_id);
    if (session == NULL) {
        // Create a new session or handle an invalid session ID
        session = create_session(session_id);
    }
    pthread_mutex_unlock(&session_mutex);

    // Log the request and update session data
    log_request(request, session->id);

    // Close the connection
    close(connfd);

    return NULL;
}

int load_config(config_t* config) {
    FILE* f = fopen(CONFIG_FILE, "r");
    if (f == NULL) {
        perror("configuration file missing or corrupted");
        // Attempt to restore default settings from backup directory
        config->session_max = 1000;
        strcpy(config->log_file, LOG_FILE);
        return -1;
    }
    fread(config, sizeof(config_t), 1, f);
    fclose(f);

    return 0;
}

void save_config(config_t* config) {
    FILE* f = fopen(CONFIG_FILE, "w");
    fwrite(config, sizeof(config_t), 1, f);
    fclose(f);
}
