#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct node {
    int key;
    double value;
    time_t timestamp;
    struct node* next;
} Node;

Node* create_node(int key, double value, time_t timestamp) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->value = value;
    new_node->timestamp = timestamp;
    new_node->next = NULL;
    return new_node;
}

void update_node(Node** head, int index, double new_value) {
    Node* current = *head;
    for (int i = 0; i < index; i++) {
        if (!current) break;
        current = current->next;
    }
    if (current) current->value = new_value;
}

double average_float(Node* head) {
    double sum = 0.0;
    Node* current = head;
    while (current) {
        sum += current->value;
        current = current->next;
    }
    return sum / (sizeof(Node*) / sizeof(Node));
}

int main() {
    const int min_records = 1000, max_records = 10000;
    int num_records;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);
    if (num_records < min_records || num_records > max_records) {
        printf("Invalid record count. Using default (%d).\n", min_records);
        num_records = min_records;
    }

    Node* head = NULL;
    int keys[max_records];
    double values[max_records];
    time_t timestamps[max_records];

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand();
        values[i] = (double)rand() / RAND_MAX;
        timestamps[i] = time(NULL);
    }

    // Create linked list of nodes
    Node* current_node = NULL;
    for (int i = 0; i < num_records; i++) {
        Node* new_node = create_node(keys[i], values[i], timestamps[i]);
        if (!head) head = new_node;
        else current_node->next = new_node;
        current_node = new_node;
    }

    // Print average float value
    printf("Average float value: %.2f\n", average_float(head));

    return 0;
}
