        Record(std::string timestamp, int sourceID, std::string eventType, std::string payload)
            : timestamp(timestamp), sourceID(sourceID), eventType(eventType), payload(payload) {}
    };

private:
    // Thread pool for data processing
    std::thread_pool threadPool;

    // Queue for incoming records
    std::queue<Record> recordQueue;

    // Map of distributed nodes and their respective roles
    std::map<std::string, NodeRole> nodeRoles;

public:
    // Constructor
    DataIngestionPipeline() {
        // Initialize thread pool with 4 threads
        threadPool.init(4);

        // Create nodes for processing stages
        createNode("node1", NodeRole::INGESTION);
        createNode("node2", NodeRole::PROCESSING);
        createNode("node3", NodeRole::STORAGE);

        // Start node threads
        startNodeThreads();
    }

private:
    // Function to create a new node with the specified role
    void createNode(std::string nodeName, NodeRole role) {
        // Create a new thread for the node
        std::thread nodeThread([this, nodeName, role]() {
            processRecords(nodeName, role);
        });

        // Add node to the map of roles
        nodeRoles[nodeName] = role;

        // Start the node thread
        nodeThread.start();
    }

public:
