package log4j;

import org.apache.log4j.*;

public class EventLogger {
    private static final Logger logger = LogManager.getLogger(EventLogger.class);

    public static void main(String[] args) {
        // Configure the logging framework
        PropertyConfigurator.configure("log4j.properties");

        // Start logging events
        startLogging();
    }

    public static void startLogging() {
        // Initialize the event queue and worker threads
        EventQueue eventQueue = new EventQueue();
        Thread[] workerThreads = new Thread[10];
        for (int i = 0; i < workerThreads.length; i++) {
            workerThreads[i] = new Thread(new LogWorker(eventQueue));
            workerThreads[i].start();
        }

        // Start accepting events
        Runtime.getRuntime().addShutdownHook(new ShutdownThread());
    }

    private static class LogWorker implements Runnable {
        private EventQueue eventQueue;

        public LogWorker(EventQueue queue) {
            this.eventQueue = queue;
        }

        @Override
        public void run() {
            while (true) {
                Event event = eventQueue.dequeue();
                if (event != null) {
                    // Process the event and log it
                    processEvent(event);
                } else {
                    break;
                }
            }
        }
    }

    private static class ShutdownThread implements Runnable {
        @Override
        public void run() {
            // Shut down the worker threads
            for (Thread thread : workerThreads) {
                thread.interrupt();
            }
        }
    }
}

