void manage_records(int num_records, int max_value, double max_timestamp, int byte_limit) {
    // Allocate memory for records and initialize them with random values
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % max_value + 1;
        records[i].timestamp = (double)rand() / RAND_MAX * max_timestamp;
    }

    // Print the largest integer in the array using a helper function
    int largest_value = find_largest(records, num_records);
    printf("Largest value: %d\n", largest_value);

    free(records);
}

// Helper function to find and print the largest integer in an array of records
int find_largest(Record* records, int num_records) {
    int max_value = records[0].value;
    for (int i = 1; i < num_records; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

// Main function to read a list of integers from standard input and manage the records
