#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    double value;
    char status;
} data_point;

// Function to compute new value based on timestamp
double (*value_func)(time_t, double);

data_point *data_points = NULL; // Dynamic array of data points
size_t data_points_size = 0; // Size of the dynamic array

int add_data_point(time_t timestamp, double value) {
    if (!data_points || (data_points_size == size_t(-1))) {
        // Allocate memory for a new array with double capacity
        void *new_memory = realloc(data_points, sizeof(data_point *) * 2);
        if (!new_memory) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            return -1; // or some other status code indicating failure
        }
        data_points = new_memory;
        data_points_size *= 2; // Double the size for future expansions
    }

    // Allocate memory for a new data_point structure
    void *new_data = malloc(sizeof(data_point));
    if (!new_data) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1; // or some other status code indicating failure
    }

    data_point *new_dp = (data_point *)new_data;
    new_dp->timestamp = timestamp;
    new_dp->value = value;
    new_dp->status = ' '; // Initialize with a default status

    // Add the new data point to the dynamic array
    void **new_array = realloc((void **)&data_points, sizeof(void *) * ++data_points_size);
    if (!new_array) {
        free(new_data); // Reclaim the memory for the new data point if allocation fails
        return -1; // or some other status code indicating failure
    }
    data_points = new_array;
    *(data_points + data_points_size - 1) = new_data;

    return 0; // Success
}

void update_data_point(time_t timestamp, double (*value_func)(time_t, double)) {
    for (size_t i = 0; i < data_points_size; ++i) {
        if ((data_points + i)->timestamp <= timestamp) {
            double new_value = value_func(timestamp, (data_points + i)->value);
            if (new_value != (data_points + i)->value) {
                (data_points + i)->value = new_value;
            }
        }
    }
}

void *get_data_point(time_t timestamp) {
    for (size_t i = 0; i < data_points_size; ++i) {
        if ((data_points + i)->timestamp == timestamp) {
            return data_points + i;
        }
    }
    return NULL; // No matching data point found
}

void clean_up_unused_data_points() {
    size_t new_size = 0;
    for (size_t i = 0; i < data_points_size; ++i) {
        if (((data_points + i)->timestamp <= time(NULL)) && ((data_points + i)->status == ' ')) {
            free(data_points + i);
        } else {
            new_size++;
        }
    }

    // Shrink the dynamic array to the new size
    void **new_array = realloc((void **)&data_points, sizeof(void *) * new_size);
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed: %s\n", strerror(errno));
        return; // or some other status code indicating failure
    }
    data_points = new_array;
    data_points_size = new_size;

    return;
}

void free_data_points() {
    for (size_t i = 0; i < data_points_size; ++i) {
        free(data_points + i);
    }
    free(data_points);

    data_points = NULL;
    data_points_size = 0;
}
