int add_data_point(data_point_collection* collection, time_t timestamp, double value, char status, void* metadata) {
    data_point* dp = (data_point*)malloc(sizeof(data_point));
    init_data_point(dp);
    dp->timestamp = timestamp;
    dp->value = value;
    dp->status = status;
    dp->metadata = metadata;

