        collection->points = (data_point**)malloc(sizeof(data_point*));
        collection->size = 1;
    } else {
        data_point** new_points = (data_point**)realloc(collection->points, (collection->size + 1) * sizeof(data_point*));
        collection->points = new_points;
        collection->size++;
    }
    collection->points[collection->size - 1] = dp;

    return 0; // Successful addition
}

