#include <time.h>

typedef struct {
    double timestamp;
    int status;
    char* message;
} logEntry;

void dynamicLogManagement(int capacity) {
    srand(time(NULL));

    // Initialize the random number generator
    int i, j, k;
    double arr[capacity];
    for (i = 0; i < capacity; i++) {
        arr[i] = rand() / (double)RAND_MAX * (100.0 - 1.0) + 1.0;
    }

    // Generate log entries
    int logEntryCount = 0;
    while (logEntryCount < capacity) {
        logEntry* logEntries = realloc(logEntries, (logEntryCount + 1) * sizeof(logEntry));
        if (!logEntries) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Generate random message
        char buffer[256];
        for (i = 0; i < (int)(arr[logEntryCount] * 10.0); i++) {
            buffer[i] = rand() % 128 + 32;
        }
        buffer[i] = '\0';

        // Create a new log entry
        logEntries[logEntryCount].timestamp = arr[logEntryCount];
        logEntries[logEntryCount].status = rand() % 2;
        logEntries[logEntryCount].message = strdup(buffer);

        logEntryCount++;
    }

    // Output the generated log entries
    for (i = 0; i < capacity; i++) {
        printf("Timestamp: %.4f, Status: %d, Message: %s\n", logEntries[i].timestamp, logEntries[i].status, logEntries[i].message);
        free(logEntries[i].message);
    }

    // Free memory
    for (i = 0; i < capacity; i++) {
        free(logEntries[i].message);
    }
    free(logEntries);

    return;
}
