['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORD_SIZE sizeof(record)
#define MAX_CONCURRENT_THREADS 1000
#define LOG_FILE "log.txt"
#define TOTAL_MEMORY_LIMIT (1 << 20) // 1MB

typedef struct {
    int value;
} record;

record* allocate_array(size_t size);
void free_array(record* array, size_t size);
void update_record(record** array, size_t size, int index, int key, int value);
int read_record(const record* array, size_t size, int index, int key);
void write_record(record** array, size_t size, int index, int key, int value);
void log_operation(int op_type, double time_taken);

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

record* g_array = NULL;
size_t g_size = 0;
int g_active_readers = 0;
int g_active_writers = 0;
FILE* log_file = NULL;

void* thread_function(void* arg) {
    int tid = (int)arg;
    for (;;) {
        pthread_mutex_lock(&lock);
        while (g_active_writers > 0 || (tid < g_size && (g_active_readers > 0))) {
            pthread_cond_wait(&cond, &lock);
        }

        // Perform read or write operation based on tid
        if (tid < g_size) {
            int index = tid % g_size;
            int key = rand() % 100; // Simulate a random key

            if (rand() % 2 == 0) { // Read
                printf("Thread %d reading record at index %zu with key %d...\n", tid, index, key);
                log_operation(1, clock());
                read_record(g_array, g_size, index, key);
                printf("Record read successfully.\n");
            } else { // Write
                int value = rand() % 100; // Simulate a random value
                printf("Thread %d writing record at index %zu with key %d and value %d...\n", tid, index, key, value);
                log_operation(2, clock());
                update_record(&g_array, g_size, index, key, value);
                printf("Record written successfully.\n");
            }
        } else {
            pthread_cond_signal(&cond);
        }

        pthread_mutex_unlock(&lock);
    }
}

int main() {
    srand(time(NULL));

    // Initialize the array and set the size based on TOTAL_MEMORY_LIMIT
    g_size = (TOTAL_MEMORY_LIMIT / RECORD_SIZE) + 1;
    g_array = allocate_array(g_size);

    // Create threads
    pthread_t threads[MAX_CONCURRENT_THREADS];
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_function, (void*)i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    free_array(g_array, g_size);

    return 0;
}

record* allocate_array(size_t size) {
    record* array = (record*)malloc(size * RECORD_SIZE);
    if (!array) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return array;
}

void free_array(record* array, size_t size) {
    free(array);
}

void update_record(record** array, size_t size, int index, int key, int value) {
    record* ptr = &((*array)[index]);
    // Update the record
    ptr->value = value;
}

int read_record(const record* array, size_t size, int index, int key) {
    const record* ptr = &(*array)[index];
    // Read the record
    return ptr->value;
}

void write_record(record** array, size_t size, int index, int key, int value) {
    record* ptr = &((*array)[index]);
    // Write the record
    ptr->value = value;
}

void log_operation(int op_type, double time_taken) {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            printf("Failed to open log file.\n");
            return;
        }
    }

    fprintf(log_file, "%s operation took %f seconds.\n", op_type == 1 ? "read" : "write", time_taken);
}
