function generatePEMCertificate(request) {
  const { certificate, privateKey } = request;

  const crypto = require('crypto');
  const fs = require('fs');
  const path = require('path');

  function decryptFile(file, password) {
    return new Promise((resolve, reject) => {
      const decipher = crypto.createDecipher('aes-256-cbc', password);
      const buffer = Buffer.alloc(0);

      file.on('data', (chunk) => {
        buffer = Buffer.concat([buffer, decipher.update(chunk)]);
      });

      file.on('end', () => {
        resolve(decipher.final());
      });

      file.on('error', (err) => {
        reject(err);
      });
    });
  }

  function generatePEM(certificate, privateKey) {
    const pemCertificate = `-----BEGIN CERTIFICATE-----
${certificate.toString()}
-----END CERTIFICATE-----`;

    const pemPrivateKey = `-----BEGIN RSA PRIVATE KEY-----
${privateKey.toString()}
-----END RSA PRIVATE KEY-----`;

    return `-----BEGIN CERTIFICATE CHAIN-----
${pemCertificate}
${pemPrivateKey}
-----END CERTIFICATE CHAIN-----`;
  }

  async function processStream(stream) {
    const buffer = Buffer.alloc(0);
    let paused = false;

    stream.on('data', (chunk) => {
      if (paused) {
        return;
      }

      buffer = Buffer.concat([buffer, chunk]);
    });

    stream.on('pause', () => {
      paused = true;
    });

    stream.on('resume', () => {
      paused = false;
    });

    stream.on('end', () => {
      const certificateBuffer = buffer.subarray(0, buffer.indexOf('\n-----END CERTIFICATE-----'));
      const privateKeyBuffer = buffer.subarray(buffer.indexOf('\n-----BEGIN RSA PRIVATE KEY-----') + '\n-----BEGIN RSA PRIVATE KEY-----'.length, buffer.length - 1);

      return { certificate: certificateBuffer.toString(), privateKey: privateKeyBuffer.toString() };
    });

    stream.on('error', (err) => {
      throw err;
    });
  }

  async function generatePEMCertificateAsync(request) {
    const { certificateFile, privateKeyFile } = request;
    let certificate, privateKey;

    try {
      certificate = await fs.readFileSync(certificateFile);
      privateKey = await decryptFile(fs.createReadStream(privateKeyFile), 'mySecretPassword');
    } catch (err) {
      throw err;
    }

    const { certificate: cert, privateKey: pkey } = processStream(fs.createReadStream(certificateFile));

    return generatePEM(cert, pkey);
  }

  exports.generatePEMCertificateAsync = generatePEMCertificateAsync;
}

