void update_theme_cache(Summary** summary, Record*** records, int* num_records) {
    // Update summary statistics based on the number of records
    (*summary)->total_records += *num_records;
    (*summary)->sum_value += *num_records;
    (*summary)->average_value = (double)(*summary)->sum_value / (*summary)->total_records;

