        // Evict older themes by clearing the record count and updating the summary statistics
        *num_records = 0;
        (*summary)->total_records = 0;
        (*summary)->sum_value = 0;
        (*summary)->average_value = 0.0;

        // Update the cache to ensure data consistency between in-memory records and the storage layer
    }
