    std::string sourceId;
    std::string eventType;
    std::string payload;

    Record(int64_t t, const std::string& s, const std::string& e, const std::string& p)
        : timestamp(t), sourceId(s), eventType(e), payload(p) {}
};

class Pipeline {
public:
    class Node {
    public:
        virtual void process(const Record& record) = 0;
        virtual ~Node() {}
    };

    Pipeline(size_t numNodes) {
        nodes_.reserve(numNodes);
        for (size_t i = 0; i < numNodes; ++i) {
            nodes_.emplace_back(std::make_shared<Node>());
        }
    }

    void process(const Record& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!nodes_.empty()) {
            auto node = nodes_[0];
            node->process(record);
            nodes_.pop_front();
        }
    }

private:
    std::vector<std::shared_ptr<Node>> nodes_;
    std::mutex mutex_;
};

class IngestionNode : public Pipeline::Node {
public:
    void process(const Record& record) override {
        // Ingest data from diverse sources
