    DataEntry* entry = (DataEntry*)malloc(sizeof(DataEntry));
    entry->timestamp = timestamp;
    entry->key = strdup(snprintf(NULL, 0, "%s", seed));
    return entry;
}

void printEntries(DataEntry** records, size_t count) {
    for (size_t i = 0; i < count; ++i)
        printf("Timestamp: %ld, Key: %s, Value: %d\n",
            ((DataEntry*)records[i])->timestamp,
            ((DataEntry*)records[i])->key,
            ((DataEntry*)records[i])->value);
}

int main() {
    size_t recordCount = 0;
    char* seed = NULL;

    printf("Enter the number of records to allocate (max: 10,000): ");
    scanf("%zu", &recordCount);

    if (recordCount > 10000) {
        fprintf(stderr, "Record count exceeds maximum limit.\n");
        return -1;
    }

    DataEntry** records = allocateMemory(recordCount);
    if (!records) {
        printf("Failed to allocate memory. Check for sufficient resources.\n");
        return -2;
    }

    printf("Enter the seed value for generating unique keys: ");
    scanf("%ms", &seed);

    if (!*seed) {
        fprintf(stderr, "Seed value cannot be null or empty.\n");
        freeMemory(records, recordCount);
        return -3;
    }

    for (size_t i = 0; i < recordCount; ++i)
        records[i] = createNewEntry(seed);

    printEntries(records, recordCount);

    freeMemory(records, recordCount);
    free(seed);
    return 0;
}
