// Custom error handling mechanism
typedef enum {
    MEMORY_ALLOCATION_FAILURE,
    INVALID_INPUT,
    SUCCESS
} ErrorType;

ErrorType manageMemory(int *offsetDim, int *keysDim, int *recordDim, int *initRangeMin, int *initRangeMax, int *pointerInitIndices, long **records, long ***recordPointers) {
    // Allocate memory for the offset array
    int* offsets = (int*)aligned_alloc(sizeof(long), *offsetDim * sizeof(int));
    if (!offsets) return MEMORY_ALLOCATION_FAILURE;
    for (int i = 0; i < *offsetDim; i++) offsets[i] = 0;

    // Allocate memory for the keys array
    int* keys = (int*)aligned_alloc(sizeof(long), *keysDim * sizeof(int));
    if (!keys) return MEMORY_ALLOCATION_FAILURE;
    for (int i = 0; i < *keysDim; i++) keys[i] = -1;

    // Generate random record values and allocate memory
    int* recordsData = (int*)aligned_alloc(sizeof(long), *recordDim * sizeof(int));
    if (!recordsData) return MEMORY_ALLOCATION_FAILURE;
    srand(time(NULL)); // Seedable random number generator
    for (int i = 0; i < *recordDim; i++) {
        int recordValue = rand() % (*initRangeMax - *initRangeMin + 1) + *initRangeMin;
        recordsData[i] = recordValue;
    }

    // Allocate memory for the long pointer array
    long* pointers = (long*)aligned_alloc(sizeof(long), *recordDim * sizeof(long));
    if (!pointers) return MEMORY_ALLOCATION_FAILURE;

    // Initialize record structures and pointers
    for (int i = 0; i < *recordDim; i++) {
        int offsetIndex = pointerInitIndices[0] + i;
        int keysIndex = pointerInitIndices[1] + i;
        if (offsetIndex >= *offsetDim || keysIndex >= *keysDim) return INVALID_INPUT;
        records[i].intVal = recordsData[i];
        records[i].offsetPtr = &offsets[offsetIndex];
        records[i].keysPtr = &keys[keysIndex];
    }

    // Initialize record pointers
    for (int i = 0; i < *recordDim; i++) {
        recordPointers[0][i] = &records[i];
    }

    return SUCCESS;
}

