use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

struct Node {
    url: String,
    neighbors: Vec<String>,
    metadata: HashMap<String, String>,
}

struct Graph {
    nodes: Vec<Node>,
}

impl Graph {
    fn new() -> Self {
        Graph { nodes: vec![] }
    }

    fn build_graph_client(&mut self, config_file_path: &str) -> Result<(), std::io::Error> {
        let file = File::open(Path::new(config_file_path))?;
        let reader = BufReader::new(file);
        for line in reader.lines() {
            let line = line.unwrap();
            let parts: Vec<_> = line.split('\t').collect();
            if parts.len() < 3 {
                continue;
            }
            let node = Node {
                url: parts[0].to_string(),
                neighbors: parts[1..].iter().map(|s| s.to_string()).collect(),
                metadata: HashMap::new(),
            };
            self.nodes.push(node);
        }
        Ok(())
    }

    fn update_metadata(&mut self, node_url: &str, key: &str, value: &str) {
        if let Some(mut node) = self.nodes.iter_mut().find(|n| n.url == *node_url) {
            node.metadata.insert(key.to_string(), value.to_string());
        }
    }

    fn get_node(&self, url: &str) -> Option<&Node> {
        self.nodes.iter().find(|n| n.url == url)
    }

    fn handle_request(&mut self, request_url: &str, key: &str, value: &str) {
        if let Some(node) = self.get_node(request_url) {
            node.metadata.insert(key.to_string(), value.to_string());
        }
    }
}

fn main() {}
