// Define structure for node in doubly linked list
typedef struct Node {
    int offset;
    int key;
    int record;
    int status;
    struct Node* prev;
    struct Node* next;
    int ref_count;
} Node;

// Function to dynamically allocate memory for arrays and initialize them
Node** init_arrays(int limit) {
    // Allocate memory for arrays of 'long', 'int', and 'record' structures
    long* offsets = (long*)malloc(10000 * sizeof(long));
    int* keys = (int*)malloc(10000 * sizeof(int));
    int* records = (int*)malloc(10000 * sizeof(int));
    int* statuses = (int*)malloc(10000 * sizeof(int));

    // Initialize arrays with random values
    for (int i = 0; i < 10000; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i] = rand() % 10000;
        statuses[i] = 1; // Initialize all records as available
    }

    // Allocate memory for doubly linked list nodes and initialize them
    Node** nodes = (Node**)malloc(10000 * sizeof(Node*));
    for (int i = 0; i < 10000; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        nodes[i]->offset = offsets[i];
        nodes[i]->key = keys[i];
        nodes[i]->record = records[i];
        nodes[i]->status = statuses[i];
        nodes[i]->prev = nodes[i-1]; // Initialize predecessor node
        nodes[i]->next = nodes[i+1]; // Initialize successor node
        nodes[i]->ref_count = 0; // Initialize reference count to 0
    }

    return nodes;
}

// Function to read integers from standard input, store them in an array, and find the largest integer
int* read_and_find_largest(int limit) {
    int n = (rand() % 10000) + 1; // Random number of integers to read
    int* arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return arr;
}

// Function to update the value of a specific node based on its index and key
void update_node(Node** nodes, int idx, int key, int val) {
    Node* curr = nodes[idx];
    if (curr->key == key) {
        curr->record = val; // Update record value
    }
}

// Function to insert a new node at the beginning of the doubly linked list
void insert_node(Node** nodes, int offset, int key, int record, int status) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->offset = offset;
    new_node->key = key;
    new_node->record = record;
    new_node->status = status;
    if (!nodes[0]) { // Handle empty list
        nodes[0] = new_node;
        return;
    }
    new_node->next = nodes[0];
    nodes[0]->prev = new_node;
    nodes[0] = new_node;
}

// Function to delete a node from the doubly linked list
void delete_node(Node** nodes, int idx) {
    if (idx == 0) { // Handle head node deletion
        Node* temp = nodes[0];
        nodes[0] = temp->next;
        temp->next->prev = NULL;
        free(temp);
        return;
    }
    Node* curr = nodes[idx];
    curr->prev->next = curr->next; // Update predecessor's successor
    curr->next->prev = curr->prev; // Update successor's predecessor
    free(curr);
}

int main() {
    srand(time(NULL)); // Initialize random seed

    int limit = 1000000; // Set memory allocation limit in bytes

    Node** nodes = init_arrays(limit);

    int* arr = read_and_find_largest(limit);
    printf("Largest integer: %d\n", *max_element(arr));

    update_node(nodes, 5, 42, 1234); // Update node value

    insert_node(nodes, 1000, 21, 789, 1); // Insert new node
    delete_node(nodes, 3); // Delete node

    return 0;
}
