        records[i].str = str;
    }
    pthread_mutex_unlock(&lock);
}

void* findMaxValue(void*) {
    long maxOffset = records[0].offset;
    for (int i = 1; i < MAX_RECORDS; i++) {
        if (records[i].offset > maxOffset) {
            maxOffset = records[i].offset;
        }
    }
    return (void*)maxOffset;
}

