#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_NAME_LENGTH 50
#define SERIALIZATION_BUFFER_SIZE 1024

typedef struct {
    int primaryKey;
    char name[MAX_NAME_LENGTH];
    double value;
} Record;

typedef struct {
    Record* records;
    int size;
    pthread_mutex_t lock;
} Database;

void database_init(Database* db) {
    db->records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    db->size = 0;
    pthread_mutex_init(&db->lock, NULL);
}

void add_record(Database* db, Record record) {
    pthread_mutex_lock(&db->lock);

    if (record.primaryKey >= db->size) {
        for (int i = db->size; i <= record.primaryKey; i++) {
            strcpy(db->records[i].name, "");
            db->records[i].value = 0.0;
        }
    }

    for (int i = 0; i < db->size; i++) {
        if (db->records[i].primaryKey == record.primaryKey) {
            pthread_mutex_unlock(&db->lock);
            return;
        }
    }

    strcpy(db->records[db->size].name, record.name);
    db->records[db->size].value = record.value;
    db->size++;

    pthread_mutex_unlock(&db->lock);
}

void serialize_database(Database* db, FILE* file) {
    fwrite(&db->size, sizeof(int), 1, file);

    for (int i = 0; i < db->size; i++) {
        Record record = db->records[i];
        fwrite(&record.primaryKey, sizeof(int), 1, file);
        fwrite(record.name, strlen(record.name) + 1, 1, file);
        fwrite(&record.value, sizeof(double), 1, file);
    }
}

Database deserialize_database(FILE* file) {
    Database db;
    int size;

    fread(&size, sizeof(int), 1, file);

    db.records = (Record*)malloc(size * sizeof(Record));
    db.size = size;

    for (int i = 0; i < size; i++) {
        Record record;
        fread(&record.primaryKey, sizeof(int), 1, file);
        char buffer[SERIALIZATION_BUFFER_SIZE];
        fgets(buffer, SERIALIZATION_BUFFER_SIZE, file);
        strcpy(record.name, buffer);
        fseek(file, -strlen(buffer) - 1, SEEK_CUR);
        fread(&record.value, sizeof(double), 1, file);

        db.records[i] = record;
    }

    pthread_mutex_init(&db.lock, NULL);

    return db;
}

void free_database(Database* db) {
    free(db->records);
    pthread_mutex_destroy(&db->lock);
}
