#define MAX_RECORDS 10000
#define MAX_STRING_LENGTH 256

typedef struct {
    int key;
    double value;
    char *string;
} Record;

Record *records = NULL;
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int max_records) {
    records = (Record *)malloc(max_records * sizeof(Record));
    for (int i = 0; i < max_records; i++) {
        records[i].key = rand() % 1000;
        records[i].value = (double)rand() / RAND_MAX;
        records[i].string = malloc(MAX_STRING_LENGTH);
        sprintf(records[i].string, "Record %d", i);
    }
}

void print_records() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        printf("Key: %d, Value: %.2f, String: %s\n", records[i].key, records[i].value, records[i].string);
    }
    pthread_mutex_unlock(&lock);
}

void cleanup_records(int max_idle_time) {
    int current_time = time(NULL);
    for (int i = 0; i < record_count; i++) {
        if (current_time - records[i].access_time > max_idle_time) {
            free(records[i].string);
            // Implement logic to remove the record from the collection
        }
    }
}

void *thread_function(void *arg) {
    int my_key = *(int *)arg;
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == my_key) {
            // Update the record's value and string
            records[i].value = (double)rand() / RAND_MAX;
            sprintf(records[i].string, "Updated Record %d", my_key);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    srand(time(NULL));
    int max_records = 10000;
    initialize_records(max_records);

    pthread_t threads[max_records];
    for (int i = 0; i < max_records; i++) {
        int *key = malloc(sizeof(int));
        *key = i;
        pthread_create(&threads[i], NULL, thread_function, key);
    }

    for (int i = 0; i < max_records; i++) {
        pthread_join(threads[i], NULL);
    }

    print_records();

    return 0;
}
