    free_node(node->next);
    free(node);
}

typedef struct EventList {
    Node* head;
    int size;
} EventList;

EventList* create_event_list() {
    EventList* event_list = (EventList*)malloc(sizeof(EventList));
    event_list->head = NULL;
    event_list->size = 0;
    return event_list;
}

void free_event_list(EventList* event_list) {
    Node* node = event_list->head;
    while(node != NULL) {
        EventList* temp = event_list;
        event_list = node->next;
        free_node(temp);
    }
    free(event_list);
}

typedef struct NodeList {
    EventList* head;
} NodeList;

NodeList* create_nodelist() {
    NodeList* nodelist = (NodeList*)malloc(sizeof(NodeList));
    nodelist->head = NULL;
    return nodelist;
}

void free_nodelist(NodeList* nodelist) {
    EventList* event_list = nodelist->head;
    while(event_list != NULL) {
        nodelist->head = event_list->next;
        free_event_list(event_list);
        event_list = nodelist->head;
