    if(node == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the node with default values
    node->timestamp = 0;
    node->data = 0.0f;
    node->next = NULL;

    // Return the allocated memory
    return (void*)node;
