Record** record_manager(int* num_records) {
    // Initialize variables for dynamic memory allocation
    int chunk_size = 10; // Adjust this value based on system constraints
    Record** records = NULL;
    int size = *num_records;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (size > chunk_size) {
        // Dynamically allocate records in chunks to improve cache utilization
        records = realloc(records, sizeof(Record*) * (size + 1));
        memset(&records[size], 0, sizeof(Record*));

        // Lock and unlock for thread safety
        pthread_mutex_lock(&lock);
        size += chunk_size;
        pthread_mutex_unlock(&lock);
    }

    return records;
}

