// Structure to represent a record
typedef struct {
    int value;
    time_t timestamp;
    int id;
} Record;

// Function to dynamically allocate memory for and initialize an array of integers and a linked list of 'record' structures
void* manage_memory(int limit) {
    // Initialize variables
    int size = 0;
    Record** records = NULL;
    Record* current_record = NULL;

    // Allocate initial chunk of memory
    void* temp = malloc(limit);
    if(temp == NULL)
        return NULL;
    records = (Record**)temp;

    // Initialize first record
    current_record = (Record*)malloc(sizeof(Record));
    if(current_record == NULL) {
        free(temp);
        return NULL;
    }
    current_record->value = 0;
    current_record->timestamp = time(NULL);
    current_record->id = 1;
    records[0] = current_record;

    // Track size of allocated memory
    size += sizeof(Record*) + sizeof(Record);

    // Manage memory chunks and deallocations
    while(size < limit) {
        int new_size = (int)(size * 1.5);
        if(new_size > limit)
            break;

        void* temp2 = realloc(temp, new_size);
        if(temp2 == NULL) {
            free(temp);
            return NULL;
        }
        temp = temp2;

        // Allocate new chunk of memory
        Record** new_records = (Record**)malloc((new_size / sizeof(Record)) * sizeof(Record*));
        if(new_records == NULL) {
            free(temp);
            return NULL;
        }
        memcpy(new_records, records, size / sizeof(Record*) * sizeof(Record*));

        // Free old chunk
        for(int i = 0; i < (size / sizeof(Record)); i++)
            free(records[i]);
        free(records);

        // Update record pointers
        records = new_records;

        // Initialize new record
        current_record = (Record*)malloc(sizeof(Record));
        if(current_record == NULL) {
            free(temp);
            return NULL;
        }
        current_record->value = 0;
        current_record->timestamp = time(NULL);
        current_record->id = size / sizeof(Record) + 1;
        records[size / sizeof(Record)] = current_record;

        // Update size
        size = new_size;
    }

    return (void*)records;
}
