#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

struct record {
    int key;
    long offset;
    time_t timestamp;
};

typedef struct {
    pthread_mutex_t lock;
    struct record* records;
    int num_records;
    int chunk_size;
} cache_node;

cache_node* create_cache_node(int chunk_size) {
    cache_node* node = (cache_node*)malloc(sizeof(cache_node));
    node->records = (struct record*)malloc(chunk_size * sizeof(struct record));
    node->num_records = 0;
    node->chunk_size = chunk_size;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void add_record(cache_node* node, struct record* record) {
    pthread_mutex_lock(&node->lock);
    if (node->num_records < node->chunk_size) {
        node->records[node->num_records] = *record;
        node->num_records++;
    } else {
        // reallocate and move existing records
        int new_chunk_size = node->chunk_size * 2;
        cache_node* new_node = create_cache_node(new_chunk_size);
        for (int i = 0; i < node->chunk_size; i++) {
            new_node->records[i] = node->records[i];
        }
        for (int i = 0; i < node->num_records - i; i++) {
            node->records[i] = node->records[i + 1];
        }
        node->num_records--;
        pthread_mutex_unlock(&node->lock);
    }
    pthread_mutex_unlock(&node->lock);
}

void* serialize_record(void* record) {
    struct record* rec = (struct record*)record;
    unsigned char buf[12];
    memcpy(buf, &rec->key, sizeof(int));
    memcpy(buf + 4, &rec->offset, sizeof(long));
    time_t ts = rec->timestamp;
    memcpy(buf + 8, &ts, sizeof(time_t));
    return buf;
}

void* deserialize_record(void* serialized) {
    unsigned char* buf = (unsigned char*)serialized;
    struct record* rec = (struct record*)malloc(sizeof(struct record));
    memcpy(&rec->key, buf, sizeof(int));
    memcpy(&rec->offset, buf + 4, sizeof(long));
    time_t ts;
    memcpy(&ts, buf + 8, sizeof(time_t));
    rec->timestamp = ts;
    return rec;
}

void cache_node_garbage_collect(cache_node* node) {
    // asynchronous garbage collection
    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < node->num_records; i++) {
        if (node->records[i].timestamp + 1 < time(NULL)) {
            free(node->records[i]);
            node->num_records--;
            i--; // recheck the same index
        }
    }
    pthread_mutex_unlock(&node->lock);
}

void* largest_integer_helper(void* array) {
    int max = ((int*)array)[0];
    for (int i = 1; i < ((int*)array)[2]; i++) {
        if (((int*)array)[i] > max) {
            max = ((int*)array)[i];
        }
    }
    return &max;
}

void find_largest_integer(int* array, int size) {
    pthread_t thread;
    pthread_create(&thread, NULL, largest_integer_helper, (void*)array);
    void* result = NULL;
    pthread_join(thread, &result);
    printf("Largest integer: %d\n", *(int*)result);
}

cache_node* node1 = create_cache_node(10);
cache_node* node2 = create_cache_node(20);

pthread_t thread;
pthread_create(&thread, NULL, cache_node_garbage_collect, (void*)node1);

int main() {
    struct record rec1 = {1, 0x10000000, time(NULL)};
    add_record(node1, &rec1);
    int* array = (int*)malloc(sizeof(int) * 10);
    for (int i = 0; i < 10; i++) {
        array[i] = i;
    }
    find_largest_integer(array, 10);

    return 0;
}
