const asyncReduce = (arr, initialValue, callback, timeout, concurrencyLimit) => {
  if (!Array.isArray(arr)) throw new Error('Invalid array');
  if (!isFunction(callback)) throw new Error('Invalid callback');

  let result = initialValue;
  const log = [];
  const queue = [];

  const processQueue = () => {
    while (queue.length > 0 && queue[0].timeout <= Date.now()) {
      const { element, metadata } = queue.shift();
      try {
        result = callback(result, element, metadata);
      } catch (error) {
        log.push({ type: 'error', message: `Error processing ${metadata.type}: ${error.message}` });
      }
    }

    if (queue.length < concurrencyLimit && arr.length > 0) {
      const nextElement = arr.shift();
      if (!isObject(nextElement)) {
        queue.push({ element: nextElement, metadata: { type: 'number' } });
      } else {
        asyncReduceForObject(nextElement, callback, timeout, concurrencyLimit);
      }
    }
  };

  const asyncReduceForObject = (obj, callback, timeout, concurrencyLimit) => {
    const traverse = (object, path = []) => {
      Object.keys(object).forEach((key) => {
        if (!isObject(object[key])) {
          queue.push({ element: object[key], metadata: { type: 'number', position: path.concat(key) } });
        } else {
          asyncReduceForObject(object[key], callback, timeout, concurrencyLimit);
        }
      });
    };

    traverse(obj);

    if (queue.length > 0) {
      setTimeout(processQueue, 0);
    }
  };

  const handleElement = (element) => {
    if (!isObject(element)) {
      queue.push({ element, metadata: { type: 'number' } });
    } else {
      asyncReduceForObject(element, callback, timeout, concurrencyLimit);
    }
  };

  arr.forEach(handleElement);

  processQueue();

  return result;
};

const isFunction = (fn) => typeof fn === 'function';
const isObject = (obj) => typeof obj === 'object' && !Array.isArray(obj);

