class Character {
public:
    enum AttackType { LIGHTNING, FIREBALL, HEAL };
};

std::map<Character::AttackType, int> cooldowns = {{Character::LIGHTNING, 3}, {Character::FIREBALL, 10}, {Character::HEAL, 20}};

void manageAttacks() {
    std::mutex mtx;
    std::condition_variable cv;

    bool attackQueued = false;
    Character currentAttackType = Character::LIGHTNING;

    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return !attackQueued; });

        if (currentAttackType != Character::LIGHTNING && cooldowns[currentAttackType] > 0) {
            // Attack not ready yet
            continue;
        }

        currentAttackType = Character::LIGHTNING;

        lock.unlock();

        std::this_thread::sleep_for(std::chrono::seconds(cooldowns[Character::LIGHTNING]));

        attackQueued = false;
    }
}
