#include <stdio.h>
#include <stdlib.h>
#include <float.h>

// Define a structure for vertices in the circularly linked list
typedef struct Vertex {
    float value;
    float coordX, coordY;
    struct Vertex* predecessor;
    struct Vertex* successor;
} Vertex;

// Function to insert a new vertex into the dynamic list
void insertVertex(Vertex** head_ref, float value, float coordX, float coordY) {
    Vertex* new_vertex = (Vertex*)malloc(sizeof(Vertex));
    new_vertex->value = value;
    new_vertex->coordX = coordX;
    new_vertex->coordY = coordY;
    new_vertex->predecessor = NULL;
    new_vertex->successor = *head_ref;

    if (*head_ref != NULL) {
        (*head_ref)->successor = new_vertex;
        new_vertex->predecessor = (*head_ref);
    } else {
        new_vertex->predecessor = new_vertex;
        new_vertex->successor = new_vertex;
    }

    *head_ref = new_vertex;
}

// Function to delete a vertex from the dynamic list
void deleteVertex(Vertex** head_ref, Vertex* node) {
    if (node == NULL)
        return;

    if (node->predecessor != NULL && node->successor != NULL) {
        node->predecessor->successor = node->successor;
        node->successor->predecessor = node->predecessor;
    } else if (node->predecessor == NULL && node->successor != NULL) {
        node->successor->predecessor = NULL;
        *head_ref = node->successor;
    } else if (node->predecessor != NULL && node->successor == NULL) {
        node->predecessor->successor = NULL;
        *head_ref = node->predecessor;
    }

    free(node);
}

// Function to find the minimum value in the vertex list
float findMinValue(Vertex* head) {
    Vertex* current = head;

    if (current == NULL)
        return FLT_MAX; // Return positive infinity for empty list

    float min_value = current->value;

    while (current != NULL) {
        if (current->value < min_value)
            min_value = current->value;
        current = current->successor;
    }

    return min_value;
}

// Example usage:
int main() {
    Vertex* head = NULL; // Initialize the circularly linked list

    float values[] = {1.0f, 2.5f, 3.0f, 4.0f, 5.0f};
    int num_values = sizeof(values) / sizeof(float);

    for (int i = 0; i < num_values; i++) {
        insertVertex(&head, values[i], 1.0f + i, 2.0f + i);
    }

    float min_value = findMinValue(head);
    printf("Minimum value: %.2f\n", min_value);

    return 0;
}
