#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_NODES 1000
#define MAX_FLOATS 10
#define TIME_WINDOW 1000 // in milliseconds
#define CATEGORY_LABEL_SIZE 20

typedef struct node {
    int timestamp;
    char category_label[CATEGORY_LABEL_SIZE];
    float values[MAX_FLOATS];
} Node;

typedef struct event_manager {
    pthread_mutex_t lock;
    Node* head;
    Node* tail;
    unsigned int max_timestamp;
    int memory_limit;
    int current_memory_usage;
} EventManager;

EventManager* create_event_manager(int memory_limit) {
    EventManager* em = (EventManager*) malloc(sizeof(EventManager));
    em->head = NULL;
    em->tail = NULL;
    em->max_timestamp = 0;
    em->memory_limit = memory_limit;
    em->current_memory_usage = 0;
    pthread_mutex_init(&em->lock, NULL);
    return em;
}

void insert_node(EventManager* em, int timestamp, const char* category_label, float values[]) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->timestamp = timestamp;
    strcpy(new_node->category_label, category_label);
    memcpy(new_node->values, values, sizeof(float) * MAX_FLOATS);

    pthread_mutex_lock(&em->lock);
    if (em->head == NULL) {
        em->head = new_node;
        em->tail = new_node;
    } else {
        Node* prev_tail = em->tail;
        prev_tail->next = new_node;
        new_node->prev = prev_tail;
        em->tail = new_node;
    }
    pthread_mutex_unlock(&em->lock);

    if (timestamp > em->max_timestamp) {
        em->max_timestamp = timestamp;
    }

    // Update memory usage
    int node_size = sizeof(Node);
    em->current_memory_usage += node_size;
}

void delete_node(EventManager* em, int timestamp, const char* category_label) {
    pthread_mutex_lock(&em->lock);

    Node* current = em->head;
    while (current != NULL) {
        if (current->timestamp == timestamp && strcmp(current->category_label, category_label) == 0) {
            if (current == em->head) {
                em->head = current->next;
            } else {
                current->prev->next = current->next;
            }

            if (current == em->tail) {
                em->tail = current->prev;
            } else {
                current->next->prev = current->prev;
            }
        }
    }

    pthread_mutex_unlock(&em->lock);
}

void compute_average(float values[], int count, float* average) {
    float sum = 0.0f;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    *average = sum / count;
}

int main() {
    EventManager* em = create_event_manager(1024); // Initialize with a memory limit of 1MB

    // Read and process events from standard input
    int timestamp, category_label_size;
    float values[MAX_FLOATS];
    while (scanf("%d %s", &timestamp, &category_label) == 2) {
        scanf("%f%f%f%f%f%f%f", &values[0], &values[1], &values[2], &values[3], &values[4], &values[5], &values[6]);
        category_label_size = strlen(category_label);

        // Check for memory allocation failures
        if (em->current_memory_usage + sizeof(Node) > em->memory_limit) {
            printf("Memory limit exceeded. Unable to process further events.\n");
            break;
        }

        insert_node(em, timestamp, category_label, values);
    }

    // Compute average float value within a specified time window and category
    int window_start = 0;
    float window_average[MAX_FLOATS];
    for (int i = 0; i < MAX_FLOATS; i++) {
        window_average[i] = 0.0f;
    }
    while (1) {
        // Read timestamps from standard input
        if (scanf("%d", &timestamp) != 1) break;

        // Compute average float value within the current time window and category
        Node* current = em->head;
        while (current != NULL && current->timestamp < timestamp - TIME_WINDOW) {
            current = current->next;
        }
        if (current == NULL) continue; // No events in the time window

        int count = 0;
        float sum[MAX_FLOATS] = {0.0f};
        for (; current != NULL && current->timestamp >= timestamp - TIME_WINDOW; current = current->next) {
            for (int j = 0; j < MAX_FLOATS; j++) {
                sum[j] += current->values[j];
                count++;
            }
        }

        // Compute and print the average float value
        for (int i = 0; i < MAX_FLOATS; i++) {
            compute_average(sum[i], count, &window_average[i]);
            printf("Average %f: %.2f\n", i, window_average[i]);
        }
    }

    return 0;
}

