#define MAX_RECORDS 15000
#define RECORD_SIZE 256
#define MEMORY_THRESHOLD 1000000

typedef struct record {
    int key;
    int value;
    char buffer[RECORD_SIZE];
} Record;

Record* dataset = NULL;
int num_records = 0;

void insert_node(int key, int value) {
    // Allocate memory for new node
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        printf("Memory exhausted!\n");
        return;
    }

    // Initialize record fields
    new_record->key = key;
    new_record->value = value;
    memset(new_record->buffer, 0, RECORD_SIZE);

    // Insert node into dataset (doubly linked list)
    if (!dataset) {
        dataset = new_record;
    } else {
        Record* current = dataset;
        while (current->key < key && current->next != NULL) {
            current = current->next;
        }
        if (current->key == key) {
            // Update existing node
            current->value = value;
        } else {
            new_record->prev = current->prev;
            current->prev->next = new_record;
            current->prev = new_record;
            new_record->next = current;
        }
    }

    num_records++;
}

void delete_node(int key) {
    // Find node to be deleted
    Record* current = dataset;
    while (current && current->key < key) {
        current = current->next;
    }
    if (!current || current->key != key) {
        printf("Node not found!\n");
        return;
    }

    // Remove node from dataset
    if (current == dataset) {
        dataset = current->next;
    } else {
        current->prev->next = current->next;
    }
    if (current->next) {
        current->next->prev = current->prev;
    }

    free(current);
    num_records--;
}

void set_value(int key, int value) {
    // Find node and update its value
    Record* current = dataset;
    while (current && current->key < key) {
        current = current->next;
    }
    if (!current || current->key != key) {
        printf("Node not found!\n");
        return;
    }

    current->value = value;
}

void print_largest_value() {
    Record* current = dataset;
    int max_value = current->value;
    while (current->next) {
        if (current->next->value > max_value) {
            max_value = current->next->value;
        }
        current = current->next;
    }

    printf("Largest value: %d\n", max_value);
}

int main() {
    int i, key, value;

    // Initialize random number generator
    srand(time(NULL));

    for (i = 0; i < MAX_RECORDS; i++) {
        key = rand() % (MAX_RECORDS - 1) + 1;
        value = rand() % 100 + 1;

        if (!dataset || dataset->key > key) {
            // Allocate memory and insert new node
            Record* new_record = (Record*)malloc(sizeof(Record));
            new_record->key = key;
            new_record->value = value;
            memset(new_record->buffer, 0, RECORD_SIZE);
            if (!dataset) {
                dataset = new_record;
            } else {
                Record* current = dataset;
                while (current->key < key && current->next != NULL) {
                    current = current->next;
                }
                if (current->key == key) {
                    // Update existing node
                    current->value = value;
                } else {
                    new_record->prev = current->prev;
                    current->prev->next = new_record;
                    current->prev = new_record;
                    new_record->next = current;
                }
            }
        }

        if (num_records > MEMORY_THRESHOLD) {
            printf("Memory usage exceeds threshold!\n");
            break;
        }
    }

    print_largest_value();

    return 0;
}
