    for (int i = 0; i < numRecords; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
        if (!records[i]) {
            // Handle memory exhaustion
            free(records);
            return NULL;
        }
    }
    return records;
}

void initializeRecords(record_t** records, int numRecords) {
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < numRecords; i++) {
        records[i]->key = rand() % 100; // Randomly assign an integer key
        records[i]->offset = rand() % 10000000L; // Randomly assign a long offset value
    }
}

void freeRecords(record_t** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);
}

record_t** manageMemory(int* numRecords) {
    record_t** records = NULL;
    while (1) {
        int maxRecords = 10; // Initial capacity
        int newNumRecords = *numRecords + maxRecords;
        records = allocateRecords(newNumRecords);
        if (!records) {
            // Handle memory exhaustion
            printf("Memory exhausted. Cannot allocate more records.\n");
            break;
        }
        initializeRecords(records, newNumRecords);
        freeRecords(records - *numRecords, *numRecords); // Free previously allocated records
        *numRecords = newNumRecords;
    }
    return records;
}
