typedef struct Node {
    double data;
    struct Node* next;
} Node;

// Define structure for 'char' strings
typedef struct {
    char* str;
    int len;
} StringStruct;

// Function to dynamically manage memory for and initialize three types of structures
void init_and_manage_memory(int num_nodes) {
    // Initialize random number generator
    srand(time(NULL));

    // Initialize linked list of 'struct node' instances
    Node* head = NULL;
    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        nodes[i]->data = (double)(rand() / (RAND_MAX + 1.0)) * 100;
        nodes[i]->next = NULL;

        // If the list is empty, set it to be the head
        if (!head) {
            head = nodes[i];
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = nodes[i];
        }
    }

    // Initialize 'FloatStruct' instances and add them to the linked list
    FloatStruct* float_nodes = (FloatStruct*)malloc(num_nodes * sizeof(FloatStruct));
    for (int i = 0; i < num_nodes; i++) {
        float_nodes[i].value = (double)(rand() / (RAND_MAX + 1.0)) * 100;
        nodes[i]->data = float_nodes[i].value;
    }

    // Initialize 'StringStruct' instances and add them to the linked list
    StringStruct* string_nodes = (StringStruct*)malloc(num_nodes * sizeof(StringStruct));
    for (int i = 0; i < num_nodes; i++) {
        char buffer[20];
        sprintf(buffer, "Node %d", i);
        string_nodes[i].str = strdup(buffer);
        string_nodes[i].len = strlen(string_nodes[i].str);

        // Add the 'StringStruct' instance to the linked list
        nodes[i]->next = (Node*)malloc(sizeof(Node));
        nodes[i]->next->data = float_nodes[i].value;
        nodes[i]->next->str = strdup(buffer);
        nodes[i]->next->len = strlen(string_nodes[i].str);
    }

    // Free memory upon function exit
    for (int i = 0; i < num_nodes; i++) {
        free(nodes[i]);
        free(float_nodes[i].value);
        free(string_nodes[i].str);
    }
    free(nodes);
    free(float_nodes);
    free(string_nodes);
}
