    return &records[idx];
}

int add_record(record_t* record) {
    int i, j;
    for (i = 0; i < num_records; i++) {
        if (records[i].id == record->id) return -1; // Record already exists
    }
    records[num_records] = *record;
    num_records++;
    return 0;
}

void serialize_records() {
    int i, size = sizeof(record_t);
    FILE* f = fopen("transactions.bin", "wb");
    fwrite(&size, sizeof(int), 1, f); // Write the record size
    for (i = 0; i < num_records; i++) {
        fwrite(&records[i], size, 1, f);
    }
    fclose(f);
}

int deserialize_records() {
    int size;
    FILE* f = fopen("transactions.bin", "rb");
    if (f == NULL) return -1; // File not found
    fread(&size, sizeof(int), 1, f); // Read the record size
    records = (record_t*)malloc(size * num_records * sizeof(record_t));
    for (int i = 0; i < num_records; i++) {
        fread(&records[i], size, 1, f);
    }
    fclose(f);
    return 0;
}

void clean_up() {
    int i;
    for (i = num_records - 1; i >= 0; i--) {
        if (records[i].status == 0) { // Remove deleted records
            memmove(&records[i], &records[i + 1], sizeof(record_t) * (num_records - i - 1));
            num_records--;
        }
    }
}

int main() {
    init_records();
    serialize_records();
    return 0;
}
