#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int load_resource_bundle(const char *path) {
    FILE *fp = fopen(path, "rb");
    if (!fp) return -1; // Error opening file

    int count = 0;
    char buffer[1024];

    fseek(fp, 0, SEEK_END);
    long fileSize = ftell(fp);
    rewind(fp);

    for (long offset = 0; offset < fileSize; offset += strlen(buffer) + 1) {
        fread(buffer, 1, sizeof(buffer), fp);
        buffer[1024] = '\0';

        // Validate item metadata and format
        if (!strchr(buffer, '[')) continue;

        count++;
    }

    fclose(fp);
    return count;
}
