#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Transaction {
    int id;
    time_t timestamp;
    char* description;
    double amount;
    int status;
} Transaction;

typedef struct Node {
    Transaction* transaction;
    struct Node* left;
    struct Node* right;
} Node;

Node* create_node(Transaction* transaction) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->transaction = transaction;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void insert_node(Node** root, Transaction* transaction) {
    if (*root == NULL) {
        *root = create_node(transaction);
    } else {
        Node* current = *root;
        Node* previous = NULL;

        while (current != NULL) {
            previous = current;
            if (transaction->id < current->transaction->id)
                current = current->left;
            else
                current = current->right;
        }

        transaction->id % 2 == 0 ? previous->left : previous->right;
    }
}

void print_tree(Node* root) {
    if (root != NULL) {
        print_tree(root->left);
        printf("%d\n", root->transaction->id);
        print_tree(root->right);
    }
}

int main() {
    Node* root = NULL;

    // Initialize and insert transactions
    for (int i = 0; i < 5000; i++) {
        Transaction transaction;
        transaction.id = rand();
        time(&transaction.timestamp);
        char* description = malloc(rand() % 50 + 1);
        strcpy(description, "Transaction #");
        strcat(description, itoa(transaction.id));
        transaction.description = description;
        transaction.amount = (double)rand() / RAND_MAX;
        transaction.status = rand() % 2;

        insert_node(&root, &transaction);

        // Randomly update the amount of some transactions
        if (i > 1000 && i < 3000)
            transaction.amount += (double)(rand() % 10 - 5) / RAND_MAX;
    }

    print_tree(root);
    return 0;
}
