Node* processNodeDataset(Node* root, long sizeLimit, char* selector, int numRecords) {
    // Dynamic memory allocation
    Node** nodes = (Node**)malloc(numRecords * sizeof(Node*));
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    for (int i = 0; i < numRecords; i++) {
        // Initialize node structure
        Node* node = (Node*)malloc(sizeof(Node));
        node->key = i;
        node->value = rand() % 100 + 1;

        // Set offset and key values
        offsets[i] = i * sizeof(Node);
        keys[i] = i;

        nodes[i] = node;
    }

    // Recursively traverse the DOM tree
    Node* current = root;
    char** modifiedTexts = (char**)malloc(current->recordCount * sizeof(char*));
    for (int i = 0; i < current->recordCount; i++) {
        if (current->elementMatches(selector) && strlen(current->innerText) <= sizeLimit) {
            // Modify inner text
            char* modifiedText = (char*)malloc(strlen(current->innerText) + 2);
            strcpy(modifiedText, current->innerText);
            strcat(modifiedText, "/");

            modifiedTexts[i] = modifiedText;
        } else {
            modifiedTexts[i] = NULL;
        }

        // Update node's record value
        for (Node* node = nodes[0]; node != NULL; node = node->next) {
            if (node->key == i) {
                node->value += rand() % 100 + 1;
            }
        }
    }

    free(nodes);
    free(offsets);
    free(keys);

    // Free all allocated memory
    for (int i = 0; i < current->recordCount; i++) {
        if (modifiedTexts[i] != NULL) {
            free(modifiedTexts[i]);
        }
    }

    return modifiedTexts;
}
