#include <string.h>
#include <time.h>

#define MAX_RECORDS 15000
#define BUFFER_SIZE 256
#define KEY_RANGE 1000

typedef struct node {
    long offset;
    int key;
    char buffer[BUFFER_SIZE];
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
long* offsets;
int* keys;
Node** records;

void init_dataset() {
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->offset = i;
        new_node->key = rand() % KEY_RANGE;
        strcpy(new_node->buffer, "Record buffer ");
        new_node->prev = NULL;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }
}

void update_node(int index, int key) {
    Node* current = head;
    for (int i = 0; i < index; i++) {
        if (!current)
            break;
        current = current->next;
    }
    if (current && current->key != key) {
        current->key = key;
    }
}

void free_dataset() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}
