// Function to generate random value within a configurable range
int rand_val(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Function to initialize the cipher with given password
AES_CTX* init_cipher(const char* password) {
    // Initialize cipher context
    AES_CTX* ctx = EVP_AEAD_CTX_new();
    if (!ctx) {
        ERR_error_fp(stderr, "Failed to create cipher context");
        return NULL;
    }

    // Set IV length and key length
    int iv_len = 16;
    int key_len = 32;

    // Derive the encryption key from password using SHA-256 hash function
    unsigned char* key = OPENSSL_md5(password, strlen(password), NULL);
    EVP_AEAD_CTX_set_key(ctx, key, key_len);

