typedef struct {
    int field;
    char buffer[100];
} record_t;

struct allocation_result {
    long* offsets;
    int size_offsets;
    int* keys;
    int size_keys;
    record_t** records;
    int size_records;
    char** temp_buffers;
    int size_temp_buffers;
};

allocation_result_t allocate_memory(int size) {
    allocation_result_t result = (allocation_result_t)malloc(sizeof(struct allocation_result));
    if (!result) return NULL;

    result->offsets = (long*)calloc(size, sizeof(long));
    if (!result->offsets) {
        free(result);
        return NULL;
    }
    for (int i = 0; i < size; ++i)
        result->offsets[i] = 0;

    result->keys = (int*)calloc(size, sizeof(int));
    if (!result->keys) {
        free(result->offsets);
        free(result);
        return NULL;
    }
    for (int i = 0; i < size; ++i)
        result->keys[i] = 0;

    result->records = (record_t**)calloc(size, sizeof(record_t*));
    if (!result->records) {
        free(result->offsets);
        free(result->keys);
        free(result);
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        result->records[i] = (record_t*)malloc(sizeof(record_t));
        if (!result->records[i]) {
            while (i > 0) {
                free(result->records[--i]->buffer);
                free(result->records[i]);
            }
            for (int j = 0; j < i; ++j)
                free((void*)result->keys[j]);
            free((void*)result->keys);
            free((void*)result->offsets);
            free(result);
            return NULL;
        }
        result->records[i]->field = rand() % 201 - 100;
        char seed[] = "seed_string";
        int segment_length = strlen(seed) / 100 + 1;
        for (int j = 0; j < 100; ++j)
            strcpy((char*)&result->records[i]->buffer[j * segment_length], &seed[j % segment_length]);
    }

    result->size_offsets = size;
    result->size_keys = size;
    result->size_records = size;
    result->size_temp_buffers = size;

    return result;
}
