#define RECORD_COUNT_MIN 1000
#define RECORD_COUNT_MAX 10000
#define FLOAT_VALUE_RANGE 10.0

typedef struct node {
    struct node* next;
    int key;
    double value;
    time_t timestamp;
} Node;

Node* create_node(int key, double value, time_t timestamp) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;  // Handle allocation failure
    node->next = NULL;
    node->key = key;
    node->value = value;
    node->timestamp = timestamp;
    return node;
}

void free_node(Node* node) {
    if (node) {
        Node* temp = node;
        while (temp) {
            Node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
}

void manage_dataset(const char* filename, long offset, int key_type) {
    // Initialize arrays and linked list
    double* values = (double*)malloc(RECORD_COUNT_MAX * sizeof(double));
    int* keys = (int*)malloc(RECORD_COUNT_MAX * sizeof(int));
    time_t* timestamps = (time_t*)malloc(RECORD_COUNT_MAX * sizeof(time_t));
    Node** nodes = (Node**)malloc(RECORD_COUNT_MAX * sizeof(Node*));

    FILE* file = fopen(filename, "r");
    if (!file) return;  // Handle file open failure

    for (int i = 0; i < RECORD_COUNT_MIN && !feof(file); i++) {
        fscanf(file, "%d %lf %lld", &keys[i], &values[i], &timestamps[i]);
    }

    for (int i = 0; i < RECORD_COUNT_MIN; i++) {
        Node* node = create_node(keys[i], values[i] * RAND() / RAND_MAX, timestamps[i]);
        if (!node) return;  // Handle allocation failure
        nodes[i] = node;
    }

    // ... (omitted for brevity)

    fclose(file);
    free(values);
    free(keys);
    free(timestamps);
    free_node(nodes);

    return;
}

int main() {
    manage_dataset("data.txt", 0, 1);
    return 0;
}
