#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

#define MAX_PRODUCTS 1000
#define MAX_REVIEWS 10
#define REVIEW_LENGTH 256

typedef struct {
    int id;
    char name[64];
    double price;
    int quantity;
    struct review *reviews[MAX_REVIEWS];
} Product;

typedef struct {
    int rating;
    char feedback[REVIEW_LENGTH];
} Review;

Product* products = NULL;
int product_count = 0;

void read_products_from_file(const char* filename) {
    json_object *json_obj = json_object_from_file(filename);
    if (!json_obj) {
        printf("Error reading JSON file.\n");
        return;
    }

    json_object_iter *iter = json_object_iter_begin(json_obj);
    while (iter) {
        json_object *product_obj = iter->value;
        int id = json_object_get_int(product_obj, "id");
        char name[64];
        strcpy(name, json_object_get_string(product_obj, "name"));
        double price = json_object_get_double(product_obj, "price");
        int quantity = json_object_get_int(product_obj, "quantity");

        if (product_count >= MAX_PRODUCTS) {
            printf("Product count exceeds limit.\n");
            return;
        }

        products[product_count].id = id;
        strcpy(products[product_count].name, name);
        products[product_count].price = price;
        products[product_count].quantity = quantity;

        json_object_iter *review_iter = json_object_iter_begin(product_obj);
        int review_index = 0;
        while (review_iter) {
            json_object *review_obj = review_iter->value;
            int rating = json_object_get_int(review_obj, "rating");
            char feedback[REVIEW_LENGTH];
            strcpy(feedback, json_object_get_string(review_obj, "feedback"));
            products[product_count].reviews[review_index] = (Review*)malloc(sizeof(Review));
            products[product_count].reviews[review_index]->rating = rating;
            strcpy(products[product_count].reviews[review_index]->feedback, feedback);
            review_index++;
            review_iter = json_object_iter_next(review_iter);
        }

        product_count++;

        iter = json_object_iter_next(iter);
    }
}

int main() {
    read_products_from_file("products.json");
    return 0;
}
