// Function to calculate Euclidean distance between two points
float euclidean_distance(Point p1, Point p2) {
    return sqrtf(powf(p2.x - p1.x, 2.0) + powf(p2.y - p1.y, 2.0));
}

// Function to populate point coordinates with values derived from a user-provided seed and range
void generate_points(int* num_points, double* min_range, double* max_range, Point** points) {
