    *min_range = 0.0;
    *max_range = 10.0;

    *points = (Point*)malloc(*num_points * sizeof(Point));
    for(int i = 0; i < *num_points; i++) {
        (*points)[i].x = (*min_range) + ((double)rand() / RAND_MAX) * (*max_range - *min_range);
        (*points)[i].y = (*min_range) + ((double)rand() / RAND_MAX) * (*max_range - *min_range);
    }
}

// Function to allocate and initialize arrays of 'report' structures
void* alloc_reports(int num_reports, Report*** reports, pthread_mutex_t* mutex) {
    *reports = (Report**)malloc(num_reports * sizeof(Report));
    for(int i = 0; i < num_reports; i++) {
        (*reports)[i]->value = 1.0;
        (*reports)[i]->identifier = (char*)malloc(strlen("report_") + strlen(to_string(i)) + 1);
        sprintf((*reports)[i]->identifier, "report_%d", i);
        (*reports)[i]->point = NULL;
        (*reports)[i]->timestamp = time(NULL);
        (*reports)[i]->reference_count = 0;

        pthread_mutex_init(mutex, NULL);
    }
}

// Function to read coordinates from standard input and store them in an array
void read_coordinates(int num_points, Point** points) {
    *points = (Point*)malloc(num_points * sizeof(Point));
    for(int i = 0; i < num_points; i++) {
        scanf("%lf %lf", &(*points)[i].x, &(*points)[i].y);
    }
}

// Function to calculate and print Euclidean distance between the first and last points in the array
void calculate_distance(Point* points, int num_points) {
    float distance = euclidean_distance(points[0], points[num_points - 1]);
    printf("Euclidean distance: %f\n", distance);
}
