void* manage_dataset(size_t max_records, size_t max_floats_per_record) {
    // Initialize custom allocator for efficient memory management
    void* pool = custom_allocator_init(max_records * sizeof(Record));

    // Array to store record pointers
    Record** records = (Record**)malloc(sizeof(Record*) * max_records);

    // Initialize dataset
    size_t record_count = 0;

    // Fetch data from remote service and allocate memory for each record
    while (record_count < max_records) {
        // Fetch next batch of records from remote service
        Record* new_records = fetch_records_from_service(max_floats_per_record);
        if (!new_records || record_count + strlen(new_records) >= max_records) {
            // Handle error or network failure
            free(new_records);
            break;
        }

        // Allocate memory for each record using custom allocator
        for (size_t i = 0; i < strlen(new_records); i++) {
            Record* new_record = malloc(sizeof(Record));
            new_record->key = new_records[i].key;
            new_record->length = new_records[i].length;
            new_record->data = (float*)malloc(sizeof(float) * new_records[i].length);
            for (size_t j = 0; j < new_records[i].length; j++) {
                new_record->data[j] = new_records[i].data[j];
            }
            records[record_count++] = new_record;
        }

        // Release memory allocated by remote service
        free(new_records);
    }

    // Free memory and release any remaining resources
    for (size_t i = 0; i < record_count; i++) {
        if (records[i]->data) {
            free(records[i]->data);
        }
        free(records[i]);
    }
    free(records);

    return pool;
}
