void serialize_records(Summary *summaries, FILE *fp) {
    for (int i = 0; i < summaries[0].max_size; i++) {
        Record *record = summaries[i].record;
        fwrite(&record->key, sizeof(int), 1, fp);
        fwrite(&record->value, sizeof(int), 1, fp);
        fwrite(record->data, strlen(record->data) + 1, 1, fp);
    }
}

