#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Event structure with timestamp, type, and priority level
typedef struct {
    long timestamp;
    int type;
    int priority;
} Event;

// Dynamic list of events, sorted by timestamp
typedef struct {
    Event* events;
    size_t capacity;
    size_t length;
} EventList;

EventList* event_list_init(size_t initial_capacity) {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    list->events = (Event*)calloc(initial_capacity, sizeof(Event));
    list->capacity = initial_capacity;
    list->length = 0;
    return list;
}

void event_list_free(EventList* list) {
    if (!list) return;
    free(list->events);
    free(list);
}

int event_list_insert(EventList* list, Event* new_event) {
    // Check for out-of-range or invalid timestamps
    if (new_event->timestamp < 0 || new_event->timestamp > INT_MAX) return -1;

    // Search for the correct position to insert the new event
    size_t i = 0;
    while (i < list->length && list->events[i].timestamp <= new_event->timestamp) {
        i++;
    }

    // Shift events to make room for the new one, and move back to the original position
    memmove(&list->events[i + 1], &list->events[i], (list->length - i) * sizeof(Event));
    list->length++;

    if (i < list->capacity && list->length <= i + 1) {
        // No reallocation needed; we have enough space
        return i;
    }

    // Reallocate the event list with a larger capacity
    Event* new_events = (Event*)realloc(list->events, (i * 2 + 1) * sizeof(Event));
    if (!new_events) return -1;

    list->events = new_events;
    list->capacity *= 2;
    list->length = i + 1;
    return i;
}

int event_list_get_index_by_timestamp(EventList* list, long timestamp) {
    size_t i = 0;
    while (i < list->length && list->events[i].timestamp != timestamp) {
        i++;
    }
    return i;
}

Event* event_list_get_event_by_timestamp(EventList* list, long timestamp) {
    int index = event_list_get_index_by_timestamp(list, timestamp);
    if (index == -1 || index >= list->length) return NULL;
    return &list->events[index];
}
