typedef struct {
    char* name;
    int age;
    char* address;
} Person;

// Function prototypes
void init_person(Person* person);
int insert_person(Person** people, int size, Person* new_person);
Person* find_person(Person** people, int size, const char* name);
void display_people(Person** people, int size);

// Initialize a person record with default values
void init_person(Person* person) {
    person->name = NULL;
    person->age = 0;
    person->address = NULL;
}

// Insert a new person record into the collection
int insert_person(Person** people, int size, Person* new_person) {
    // Dynamically resize the array if necessary
    if (size == 0 || size > 10000) {
        size *= 2;
        *people = realloc(*people, size * sizeof(Person));
    }

    // Validate and copy the new person record
    if (new_person->name != NULL && strlen(new_person->name) > 0 &&
        new_person->age >= 0 && new_person->address != NULL && strlen(new_person->address) > 0) {
        (*people)[size - 1] = *new_person;
        return size;
    } else {
        printf("Error: Invalid person record.\n");
        return size; // or exit with error code
    }
}

// Find a person record by name and display its details
Person* find_person(Person** people, int size, const char* name) {
    for (int i = 0; i < size; i++) {
        if (strcmp(people[i]->name, name) == 0) {
            printf("Found: %s, Age: %d, Address: %s\n", people[i]->name, people[i]->age, people[i]->address);
            return people[i];
        }
    }
    printf("Not found.\n");
    return NULL;
}

// Display all person records
void display_people(Person** people, int size) {
    for (int i = 0; i < size; i++) {
        printf("Name: %s, Age: %d, Address: %s\n", people[i]->name, people[i]->age, people[i]->address);
    }
}
