    if (!transactions) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        transactions[i].id = i;
        transactions[i].timestamp = time(NULL);
        strcpy(transactions[i].account, "Account");
        transactions[i].amount = (float)rand() / RAND_MAX;
        transactions[i].status = rand() % 2;
        strcpy(transactions[i].payment_method, "Credit Card");
    }

    return transactions;
}

void* transaction_handler(void* arg) {
    record* transactions = (record*)arg;
    int i = pthread_getspecific(pthread_mutex_t);
    printf("Transaction ID: %d\n", transactions[i].id);
    // handle transaction logic here
}

int main() {
    int n = 100000; // maximum number of transactions
    record* transactions = init_transactions(n);

    if (!transactions) {
        return -1;
    }

    pthread_t threads[n];

    for (int i = 0; i < n; i++) {
        pthread_create(&threads[i], NULL, transaction_handler, &transactions[i]);
    }

    for (int i = 0; i < n; i++) {
        pthread_join(threads[i], NULL);
    }

    free(transactions);
    return 0;
}
