    int* keys = NULL;

    init_arrays(size, &offsets, &keys);

    record_t* records = NULL;
    init_records(size, &records);

    for (int i = 0; i < size; i++) {
        records[i].offset = &(offsets[i]);
    }

    set_record_value(size, records);

    free(keys);
    free(offsets);
    free(records);

    return 0;
}

int main() {
    int size = 1000000;
    allocate_memory(size);
    return 0;
}
