typedef struct product {
    char* name;
    int priority;
    double price;
} product;

product* head = NULL;
int products_count = 0;

void add_product(product* new_product) {
    if (head == NULL || strcmp(new_product->name, head->name) <= 0) {
        new_product->next = head;
        head = new_product;
    } else {
        product* temp = head;
        while (temp->next && strcmp(temp->next->name, new_product->name) < 0) {
            temp = temp->next;
        }
        new_product->next = temp->next;
        temp->next = new_product;
    }
    products_count++;
}

void remove_product(const char* name) {
    product* temp = head;
    product* prev = NULL;
    while (temp && strcmp(temp->name, name) != 0) {
        prev = temp;
        temp = temp->next;
    }
    if (temp == NULL) return; // Product not found
    if (prev == NULL) { // Remove the head
        head = temp->next;
    } else {
        prev->next = temp->next;
    }
    free(temp);
    products_count--;
}

product* find_product(const char* name) {
    product* temp = head;
    while (temp && strcmp(temp->name, name) != 0) {
        temp = temp->next;
    }
    return temp;
}

void sort_products() {
    product* temp = head;
    product* prev = NULL;
    product* next = NULL;
    product* new_head = NULL;
    for (int i = 0; i < products_count; i++) {
        next = temp->next;
        if (new_head == NULL || temp->priority <= new_head->priority) {
            prev->next = temp->next;
            temp->next = new_head;
            new_head = temp;
        } else {
            prev = temp;
            temp = next;
        }
    }
    head = new_head;
}

void fetch_products_from_api() {
    // API code here
    int retries = 0;
    int max_retries = 5;
    while (retries < max_retries) {
        // Fetch products from API
        product* temp = NULL;
        product* prev = NULL;
        int count = 0;
        // Parse the API response...
        for (int i = 0; i < count; i++) {
            temp = malloc(sizeof(product));
            // Set product fields...
            add_product(temp);
        }
        if (temp) free(temp);
        retries++;
    }
}

void print_products() {
    product* temp = head;
    while (temp) {
        printf("Name: %s, Priority: %d, Price: %.2f\n", temp->name, temp->priority, temp->price);
        temp = temp->next;
    }
}
