#include <pthread.h>

// Define the structures for transactions, accounts, and batches
typedef struct {
    int tid;
    time_t timestamp;
    struct transaction* account;
    struct batch* batch;
} transaction;

typedef struct {
    int balance;
    pthread_mutex_t lock;
    transaction** transactions;
    int num_transactions;
} account;

typedef struct {
    int status;
    transaction** transactions;
    int num_transactions;
} batch;

// Function to manage the allocation and initialization of data structures
void* initialize_data_structures(size_t limit) {
    // Allocate memory for arrays of 'transaction', 'account', and 'batch' structs
    size_t num_transactions = (size_t) (limit / sizeof(transaction));
    size_t num_accounts = (size_t) (num_transactions / 10); // Assume approximately 1/10 transactions per account
    size_t num_batches = (size_t) (num_transactions / 50); // Assume approximately 1/2 batches per transaction

    transaction* transactions = malloc(num_transactions * sizeof(transaction));
    account* accounts = malloc(num_accounts * sizeof(account));
    batch* batches = malloc(num_batches * sizeof(batch));

    // Initialize arrays
    for (size_t i = 0; i < num_transactions; i++) {
        transactions[i].tid = i;
        transactions[i].timestamp = time(NULL);
        transactions[i].account = &accounts[i % num_accounts];
        transactions[i].batch = &batches[i % num_batches];
    }

    // Initialize account and batch arrays
    for (size_t i = 0; i < num_accounts; i++) {
        accounts[i].balance = 0;
        pthread_mutex_init(&accounts[i].lock, NULL);
        accounts[i].transactions = malloc(num_transactions / num_accounts * sizeof(transaction*));
        accounts[i].num_transactions = 0;
    }

    for (size_t i = 0; i < num_batches; i++) {
        batches[i].status = 0;
        batches[i].transactions = malloc(num_transactions / num_batches * sizeof(transaction*));
        batches[i].num_transactions = 0;
    }

    return transactions;
}

// Function to free the allocated memory
void finalize_data_structures(void* data) {
    transaction* transactions = (transaction*) data;

    // Free account and batch arrays first, then 'transactions' array
    for (size_t i = 0; i < num_accounts; i++) {
        free(accounts[i].transactions);
        pthread_mutex_destroy(&accounts[i].lock);
    }
    free(batches);

    free(transactions);
}
