#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int type;
    int priority;
    int id;
} event;

typedef struct {
    event* events;
    int size;
    int capacity;
} event_list;

event_list* new_event_list() {
    event_list* list = (event_list*)malloc(sizeof(event_list));
    list->size = 0;
    list->capacity = 10; // Initial cache capacity
    return list;
}

void add_event(event_list* list, long timestamp, int type, int priority) {
    if (list->size >= list->capacity) {
        // Reallocate and resize the cache
        event* new_events = (event*)realloc(list->events, (list->capacity + 10) * sizeof(event));
        list->capacity += 10;
        list->events = new_events;
    }

    event* new_event = &list->events[list->size];
    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->priority = priority;

    // Assign unique identifier
    if (list->size > 0) {
        new_event->id = list->events[list->size - 1].id + 1;
    } else {
        new_event->id = 0; // First event gets ID 0
    }

    // Insert new event in sorted order by timestamp
    int i = list->size - 1;
    while (i > 0 && list->events[i].timestamp < timestamp) {
        memmove(&list->events[i + 1], &list->events[i], sizeof(event));
        i--;
    }
    memmove(&list->events[i + 1], &new_event, sizeof(event));
    list->size++;
}

event* get_event_by_id(event_list* list, int id) {
    for (int i = 0; i < list->size; i++) {
        if (list->events[i].id == id) {
            return &list->events[i];
        }
    }
    return NULL;
}

void iterate_events(event_list* list, void (*callback)(event*)) {
    for (int i = 0; i < list->size; i++) {
        callback(list->events[i]);
    }
}

void iterate_events_reverse(event_list* list, void (*callback)(event*)) {
    for (int i = list->size - 1; i >= 0; i--) {
        callback(list->events[i]);
    }
}

// Caching mechanism
pthread_mutex_t cache_lock;
int cache_hit_count = 0;
int cache_miss_count = 0;

event* get_event(event_list* list, int id) {
    pthread_mutex_lock(&cache_lock);
    event* cached_event = (event*)malloc(sizeof(event));
    // Check if the event is in the cache
    for (int i = 0; i < list->size; i++) {
        if (list->events[i].id == id) {
            *cached_event = list->events[i];
            free(cached_event);
            pthread_mutex_unlock(&cache_lock);
            return &list->events[i]; // Return the cached event
        }
    }

    event* result = get_event_by_id(list, id);
    if (result != NULL) {
        // Cache hit!
        cache_hit_count++;
        pthread_mutex_unlock(&cache_lock);
        return result;
    }

    // Cache miss!
    cache_miss_count++;
    free(cached_event); // Free the temporary cached event
    pthread_mutex_unlock(&cache_lock);
    return result; // Return the event retrieved from the list
}
