#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int type;
    int priority;
} Event;

Event* create_event(time_t timestamp, int type, int priority);
void add_event(Event** events, int* size, Event* new_event);
Event* get_event(Event** events, int* size, time_t timestamp, int type);

Event* create_event(time_t timestamp, int type, int priority) {
    Event* event = (Event*)malloc(sizeof(Event));
    event->timestamp = timestamp;
    event->type = type;
    event->priority = priority;
    return event;
}

void add_event(Event** events, int* size, Event* new_event) {
    if (*size == 0 || new_event->timestamp < (*events)[*size - 1]->timestamp) {
        // If the list is empty or the new event has an earlier timestamp, prepend it.
        *events = (Event*)realloc(*events, ++*size * sizeof(Event));
        (*events)[*size - 1] = new_event;
    } else {
        int i;
        for (i = 0; i < *size; i++) {
            if ((*events)[i]->timestamp <= new_event->timestamp) {
                // Find the correct position to insert the event.
                break;
            }
        }
        // Shift existing events forward and add the new event.
        Event* temp_events = (Event*)malloc((i + 1) * sizeof(Event));
        for (int j = 0; j < i; j++) {
            temp_events[j] = (*events)[j];
        }
        temp_events[i] = new_event;
        free(*events);
        *events = temp_events;
        *size += 1;
    }
}

Event* get_event(Event** events, int* size, time_t timestamp, int type) {
    for (int i = 0; i < *size; i++) {
        if ((*events)[i]->timestamp == timestamp && (*events)[i]->type == type) {
            return &((*events)[i]);
        }
    }
    return NULL;
}
