int initArrays(FILE* file, double** doubles, char*** chars, point_t*** points) {
    if (file == NULL || !fseek(file, 0, SEEK_END)) {
        return -1; // File error
    }

    long fileSize = ftell(file);
    rewind(file);

    *doubles = malloc(sizeof(double) * fileSize / sizeof(double));
    *chars = malloc(sizeof(char) * fileSize / sizeof(char));
    *points = malloc(sizeof(point_t) * fileSize / sizeof(point_t));

    if (*doubles == NULL || *chars == NULL || *points == NULL) {
        return -2; // Memory allocation error
    }

    for (int i = 0; i < fileSize / (sizeof(double)); i++) {
        if (fread(&((*doubles)[i]), sizeof(double), 1, file) != 1) {
            free(*doubles);
            *doubles = NULL;
            return -3; // File read error
        }
    }

    for (int i = 0; i < fileSize / (sizeof(char)); i++) {
        if (fread(&((*chars)[i]), sizeof(char), 1, file) != 1) {
            free(*doubles);
            *doubles = NULL;
            free(*chars);
            *chars = NULL;
            return -4; // File read error
        }
    }

    for (int i = 0; i < fileSize / (sizeof(point_t)); i++) {
        if (fread(&((*points)[i]), sizeof(point_t), 1, file) != 1) {
            free(*doubles);
            *doubles = NULL;
            free(*chars);
            *chars = NULL;
            return -5; // File read error
        }
    }

    return 0; // Success
}

void freeArrays(double* doubles, char** chars, point_t* points) {
    free(doubles);
    for (char* c : chars) {
        free(c);
    }
    free(chars);
    free(points);
}
