['Here is the C code block for managing a dynamic collection of `entity` records:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Define the structure for an entity record
typedef struct {
    int id;
    char *name;
    char *description;
    json_object *metadata;
} Entity;

// Define a linked list to manage dynamic collection of entities
typedef struct Node {
    Entity data;
    struct Node *next;
} Node;

// Function to create a new node with the given entity record
Node* newNode(Entity data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new entity record to the collection
void addEntity(Entity* entity, Node** head_ref) {
    Node* newNode = newNode(*entity);
    if (*head_ref == NULL || (*head_ref)->data.id > newNode->data.id) {
        newNode->next = *head_ref;
        *head_ref = newNode;
    } else {
        Node* current = *head_ref;
        while (current->next && current->next->data.id <= newNode->data.id) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to update an existing entity record
void updateEntity(int id, Entity* updated_entity, Node** head_ref) {
    Node* current = *head_ref;
    while (current) {
        if (current->data.id == id) {
            current->data = *updated_entity;
            return;
        }
        current = current->next;
    }
}

// Function to delete an entity record by its identifier
void deleteEntity(int id, Node** head_ref) {
    if (*head_ref == NULL)
        return;

    if ((*head_ref)->data.id == id) {
        Node* temp = *head_ref;
        *head_ref = (*head_ref)->next;
        free(temp);
        return;
    }

    Node* current = *head_ref;
    while (current->next) {
        if (current->next->data.id == id) {
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
            return;
        }
        current = current->next;
    }
}

// Function to retrieve an entity record by its identifier
Entity* getEntity(int id, Node* head) {
    while (head) {
        if (head->data.id == id)
            return &head->data;
        head = head->next;
    }
    return NULL;
}

// Function to iterate over the collection and display details
void printEntities(Node* head) {
    printf("Entity Collection:\n");
    while (head) {
        printf("ID: %d, Name: %s, Description: %s, Metadata: %s\n", 
               head->data.id, head->data.name, head->data.description, json_object_to_json_string(head->data.metadata));
        head = head->next;
    }
}

// Function to free the memory allocated for the entity collection
void freeEntities(Node** head_ref) {
    Node* current = *head_ref;
    Node* next_node;

    while (current) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    *head_ref = NULL;
}
