    size_t current_size; // current allocated size
    size_t max_size; // maximum allowed size (MAX_MEMORY)
} memory_pool;

memory_pool mp;

// function to initialize the memory pool and allocate initial memory
void init_memory_pool() {
    mp.pointers = (void**)malloc(RECORD_COUNT * sizeof(void*));
    mp.current_size = 0;
    mp.max_size = MAX_MEMORY;
}

// function to dynamically allocate a new record structure
void* alloc_record() {
    if (mp.current_size + sizeof(struct record) > mp.max_size) {
        // reallocate memory if necessary, adding MEMORY_STEP_SIZE bytes at a time
        size_t old_size = mp.current_size;
        void** temp_pointers = (void**)realloc(mp.pointers, (old_size + MEMORY_STEP_SIZE / sizeof(void*)));
        if (!temp_pointers) {
            // handle memory allocation failure
            printf("Memory allocation failed!\n");
            return NULL;
        }
        mp.pointers = temp_pointers;
        mp.max_size += MEMORY_STEP_SIZE;
    }
    struct record* new_record = (struct record*)malloc(sizeof(struct record));
    if (!new_record) {
        // handle memory allocation failure
        printf("Memory allocation failed!\n");
        return NULL;
    }
    *mp.pointers++ = (void*)new_record; // increment the pointer array
    mp.current_size += sizeof(struct record);
    return new_record;
}

// function to populate a record structure with a random integer value
void* fill_record(void* ptr) {
    struct record* record = (struct record*)ptr;
    record->value = rand() % 100; // adjust this line for different range
    return ptr;
}

