#include <time.h>

typedef struct node {
    int key;
    long offset;
    int value;
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(long offset, int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    new_node->offset = offset;
    new_node->key = key;
    new_node->value = rand() % 100; // Initialize with a random value
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

int main() {
    int num_records = 0; // Initialize with a default value
    scanf("%d", &num_records);

    Node* nodes[num_records];
    long offsets[num_records];
    int keys[num_records];

    for (int i = 0; i < num_records; i++) {
        long offset = (long)i;
        int key = rand() % 10000; // Generate a random key
        Node* new_node = create_node(offset, key);
        nodes[i] = new_node;
        offsets[i] = offset;
        keys[i] = key;
    }

    return 0;
}

