// event_log.go
package main

import (
	"database/sql"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/go-sql-driver/mysql"
)

const (
	maxEntriesPerBatch = 1000
	batchSize          = 5000
	// Storage configuration
	storagePath = "./logs/"
	logFile     = "log.txt"
)

type Event struct {
	Timestamp time.Time `json:"timestamp"`
	SrcID      string   `json:"src_id"`
	Message    string   `json:"message"`
	Severity   int8     `json:"severity"`
}

// LogWriter is responsible for writing events to disk.
type LogWriter struct {
	mu       sync.Mutex
	batch    []*Event
	logFile  *os.File
	logCount int64
}

func NewLogWriter(storagePath string) (*LogWriter, error) {
	logFile, err := os.OpenFile(filepath.Join(storagePath, logFile), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0666)
	if err != nil {
		return nil, err
	}
	return &LogWriter{
		logFile: logFile,
	}, nil
}

func (lw *LogWriter) Write(event *Event) error {
	lw.mu.Lock()
	defer lw.mu.Unlock()
	lw.batch = append(lw.batch, event)
	if len(lw.batch) >= batchSize {
		err := lw.flushBatch()
		if err != nil {
			return err
		}
		lw.batch = []*Event{}
	}
	return nil
}

func (lw *LogWriter) flushBatch() error {
	if len(lw.batch) > 0 {
		n, err := fmt.Println(time.Now(), "Writing batch of", len(lw.batch), "events")
		if n > 0 || err != nil {
			return err
		}
		_, err = lw.logFile.WriteString(strings.Join(formatEvents(lw.batch), "\n"))
		if err != nil {
			return err
		}
		lw.logCount++
		lw.batch = []*Event{}
	}
	return nil
}

func formatEvents(events []*Event) []string {
	var formattedEvents []string
	for _, event := range events {
		formattedEvents = append(formattedEvents, fmt.Sprintf(`{"timestamp": "%s", "src_id": "%s", "message": "%s", "severity": %d}`, event.Timestamp.Format(time.RFC3339), event.SrcID, event.Message, event.Severity))
	}
	return formattedEvents
}

// LogReader is responsible for reading events from disk.
type LogReader struct {
	db *sql.DB
}

func NewLogReader(storagePath string) (*LogReader, error) {
	dsn := "user:password@tcp(" + storagePath + ")/events?parseTime=true"
	db, err := sql.Open("mysql", dsn)
	if err != nil {
		return nil, err
	}
	return &LogReader{
		db: db,
	}, nil
}

func (lr *LogReader) Read(severity int8, keyword string) ([]*Event, error) {
	rows, err := lr.db.Query(`SELECT timestamp, src_id, message, severity FROM events WHERE severity = ? AND message LIKE ?`, severity, `%%`+keyword+`%`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var events []*Event
	for rows.Next() {
		event := &Event{}
		err := rows.Scan(&event.Timestamp, &event.SrcID, &event.Message, &event.Severity)
		if err != nil {
			return nil, err
		}
		events = append(events, event)
	}
	return events, nil
}

func main() {
	lw, err := NewLogWriter(storagePath)
	if err != nil {
		log.Fatal(err)
	}

	for _, event := range []*Event{
		{Timestamp: time.Now(), SrcID: "foo", Message: "bar", Severity: 1},
	} {
		err = lw.Write(event)
		if err != nil {
			log.Fatal(err)
		}
	}

	lr, err := NewLogReader(storagePath)
	if err != nil {
		log.Fatal(err)
	}

	events, err := lr.Read(1, "keyword")
	if err != nil {
		log.Fatal(err)
	}

	for _, event := range events {
		fmt.Println(event.Timestamp, event.Message, event.Severity)
	}
