    Record* records = NULL;
    size_t totalBytes = sizeof(Record) * numRecords;

    if (totalBytes > maxMemory) {
        // Handle memory allocation failure gracefully
        return NULL;
    }

    records = malloc(totalBytes);
    if (!records) {
        // Handle memory allocation failure gracefully
        return NULL;
    }

    srand(time(NULL)); // Set the seed for reproducible record initialization

    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        record->offset = i * sizeof(Record);
        record->key = rand() % 100; // Initialize within a given range
        record->timestamp = time(NULL); // Use system timestamp or default if unavailable
        record->id = i + 1;
    }

    return records;
