    pthread_mutex_lock(&recordMutex); // Assume a global mutex is available

    if (idx < 0 || idx >= numRecords) {
        // Handle invalid record index gracefully
        return;
    }

    Record* record = &records[idx];
    record->key = key; // Update the record value

    pthread_mutex_unlock(&recordMutex);
}

// Serialize the entire list of records to disk
void serializeRecords(Record** records, FILE* file) {
    size_t totalBytes = sizeof(Record) * numRecords;

    fwrite(records, sizeof(Record), numRecords, file); // Write the record data

    fclose(file);
}

// Deserialize the record data from a file back into memory
void deserializeRecords(Record*** records, FILE* file) {
    Record* newRecords = malloc(sizeof(Record) * numRecords);

    if (!newRecords) {
        // Handle memory allocation failure gracefully
        return;
    }

    fread(newRecords, sizeof(Record), numRecords, file); // Read the record data

    *records = newRecords;

    fclose(file);
}

// Prune old records to maintain optimal memory usage without affecting system performance
void pruneRecords(Record** records, size_t maxMemory) {
    size_t totalBytes = 0; // Calculate the total memory usage of the remaining records

    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        if (record->key > 50) { // Prune records with keys exceeding a certain threshold
            continue;
        }

        totalBytes += sizeof(Record);
    }

    if (totalBytes <= maxMemory) {
        return; // No pruning necessary
