        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public void ManageConfig(string configJson, Uri endpointUri, Action<Exception> onError)
    {
        if (string.IsNullOrEmpty(configJson))
            throw new ArgumentException("Config string cannot be null or empty.");

        var config = JsonConvert.DeserializeObject<Configuration>(configJson);
        if (config == null)
            throw new ArgumentException("Invalid configuration format.");

        if (!endpointUri.IsAbsoluteUri)
            throw new ArgumentException("Endpoint URL must be absolute.");

        _httpClient.DefaultRequestOptions = new HttpRequestMessage(HttpMethod.Get, endpointUri);

        try
        {
            var response = _httpClient.GetAsync(endpointUri).Result;
            if (response.IsSuccessStatusCode)
                _logger.LogInformation($"Connected to {endpointUri} successfully.");
            else
                onError(new Exception($"Failed to connect to {endpointUri}: {response.StatusCode}"));
        }
        catch (Exception ex)
        {
            onError(ex);
        }

        // Additional error handling and retry logic can be implemented here.
    }
}

public class Configuration
{
    public string JsonConfig { get; set; }
    public Uri EndpointUrl { get; set; }
}

public interface ILogger
{
    void LogInformation(string message);
}
