        printf("Invalid port number: %d\n", config.port);
        return false;
    }

    // Validate server name
    if (!strlen(config.server_name)) {
        printf("Server name cannot be empty\n");
        return false;
    }

    // Validate document root path
    if (!access(config.document_root, F_OK)) {
        printf("Document root path does not exist or is a directory: %s\n", config.document_root);
        return false;
    }

    // Validate SSL certificate paths (if present)
    if (config.ssl_enabled) {
        if (!config.ssl_cert_path || !config.ssl_key_path) {
            printf("SSL certificate and key files are missing\n");
            return false;
        }
        if (access(config.ssl_cert_path, F_OK) != 0 || access(config.ssl_key_path, F_OK) != 0) {
            printf("SSL certificate or key file does not exist: %s, %s\n", config.ssl_cert_path, config.ssl_key_path);
            return false;
        }
    }

    // Validate logging settings
    if (strcmp(config.log_level, "DEBUG") && strcmp(config.log_level, "INFO") && strcmp(config.log_level, "ERROR")) {
        printf("Invalid log level: %s\n", config.log_level);
        return false;
    }
    if (!config.log_file) {
        printf("Log file path is missing\n");
        return false;
    }

    // Validate allowed IP addresses
    for (int i = 0; i < config.num_allowed_ips; i++) {
        char* ip_addr = config.allowed_ips[i];
        struct in_addr in_addr;
        if (inet_pton(AF_INET, ip_addr, &in_addr) <= 0 || inet_pton(AF_INET6, ip_addr, &in_addr) <= 0) {
            printf("Invalid IP address: %s\n", ip_addr);
            return false;
        }
    }

    // Validate custom error handling mechanisms
    if (config.http_status_codes > 0) {
        for (int i = 0; i < config.http_status_codes; i++) {
            char* message = config.error_messages[i];
            if (!strlen(message)) {
                printf("Error message cannot be empty\n");
                return false;
            }
        }
    }

    // If all validations pass, the configuration is valid
    printf("Configuration is valid\n");
    return true;
}

