    std::map<std::string, std::vector<int>*> stringToVectorMap;
    std::vector<std::string> objectNames;
    std::vector<double> values;
    std::thread::id currentThreadId;

    DynamicMemoryAllocator(size_t memoryLimit) : memoryLimit_(memoryLimit) {}

    void allocateMemory() {
        // Check if the total memory usage does not exceed the limit
        size_t totalBytes = sizeof(objectNames) + sizeof(values);
        if (totalBytes > memoryLimit_) {
            std::cout << "Memory allocation failed. Aborting." << std::endl;
            return;
        }

        // Dynamically allocate memory for object names and values
        objectNames.reserve(100);  // Initialize with a reasonable size
        values.resize(objectNames.size());

        // Populate each vector with a sequence of random integers
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        for (size_t i = 0; i < objectNames.size(); ++i) {
            objectNames.push_back(std::to_string(i));
            values[i] = static_cast<double>(dis(gen));

            // Initialize each vector with a sequence of random integers
            std::vector<int> tempVector;
            tempVector.reserve(10);  // Initialize with a reasonable size
            for (size_t j = 0; j < 10; ++j) {
                tempVector.push_back(dis(gen));
            }
            stringToVectorMap[objectNames[i]] = &tempVector;
        }

        std::cout << "Memory allocated successfully." << std::endl;
    }

    void updateVector(int index, const std::string& name) {
        // Check if the name exists in the map
        auto it = stringToVectorMap.find(name);
        if (it == stringToVectorMap.end()) {
            std::cout << "Vector not found for name: " << name << std::endl;
            return;
        }

        // Update the value of specific vectors based on their index and name
        (*it->second)[index] = static_cast<int>(values[index]);
    }

private:
    size_t memoryLimit_;
};

int main() {
    DynamicMemoryAllocator allocator(1024 * 1024);  // Initialize with a reasonable limit

    allocator.allocateMemory();

    // Example usage: update the value of a specific vector
    allocator.updateVector(5, "vector-123");

    return 0;
}
