// Structure for 'record' node in doubly linked list
typedef struct {
    int value;
} Record;

// Node structure with pointers to predecessor and successor nodes, offset, key, record, availability flag, and concurrent access count
typedef struct node {
    struct node* prev;
    struct node* next;
    long offset;
    int key;
    Record record;
    int avail;
    int access_count;
} Node;

// Function to dynamically allocate memory for the flexible number of data structures: arrays for storing 'offset' values (long), 'keys' (int), 'record' structures (each containing 'int' values), 'availability' status flags, and 'concurrent access' status flags
void* dynamic_allocation(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(1); // Exit the program with an error code
    }
    return ptr;
}

// Function to initialize the doubly linked list of 'node' structures
void init_doubly_linked_list(int num_nodes, long* offsets, int* keys, size_t max_memory_usage) {
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < num_nodes; i++) {
        Node* node = (Node*)dynamic_allocation(sizeof(Node));
        node->prev = (i == 0) ? NULL : tail;
        node->next = (i == num_nodes - 1) ? NULL : &head;
        node->offset = offsets[i];
        node->key = keys[i];
        node->record.value = rand() % 100; // Set the record's int field to a random value within the specified range
        node->avail = 1; // Initialize availability flag as available (1)
        node->access_count = 0;

        if (i == 0) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;

        if ((size_t)(node + 1 - head) > max_memory_usage) {
            printf("Memory usage exceeded the specified limit.\n");
            exit(1); // Exit the program with an error code
        }
    }

    // Initialize the doubly linked list nodes
    for (Node* node = head; node != NULL; node = node->next) {
        node->prev = &node;
        node->next = node + 1;
    }
}

// Function to update the value of specific nodes based on their index and key, ensuring thread safety during these updates
void update_node(int idx, int new_key) {
    // Lock the doubly linked list for thread-safe access
    pthread_mutex_lock(&mutex);

    Node* current = head;
    while (current != NULL && current->key != new_key) {
        current = current->next;
    }

    if (current != NULL && idx < num_nodes) {
        Record record;
        // Update the record's int field with a random value within the specified range
        record.value = rand() % 100; // Set the record's int field to a random value within the specified range

        // Update the node's key and record
        current->key = new_key;
        current->record = record;

        // Release the lock after updating the node
        pthread_mutex_unlock(&mutex);
    } else {
        printf("Node not found.\n");
        exit(1); // Exit the program with an error code
    }
}

// Helper function to read a list of integers from standard input, store them in an array, and then find and print the largest integer in the array
void read_integers(int num_ints) {
    int* ints = (int*)dynamic_allocation(num_ints * sizeof(int));

    for (int i = 0; i < num_ints; i++) {
        scanf("%d", &ints[i]);
    }

