class ScalableDataPipeline {
public:
    // Constructor
    ScalableDataPipeline() : load(0), nodes({}), db({}) {}

    // Add node to the pipeline
    void addNode(int id, int capacity) {
        nodes[id] = capacity;
    }

    // Process data record
    void processRecord(std::string metadata) {
        // Extract timestamp, source ID, event type, and payload content from metadata
        std::string timestamp, sourceID, eventType, payload;
        // ...

        // Distribute processing across nodes based on current load and resource availability
        int nodeId = determineNodeId();
        if (nodeId != -1) {
            processRecordOnNode(nodeId, metadata);
        } else {
            // Handle failure or overload condition
            std::cout << "Error: No available node to process record." << std::endl;
        }
    }

    // Process data record on a specific node
    void processRecordOnNode(int nodeId, std::string metadata) {
        if (nodes.find(nodeId) != nodes.end()) {
            int capacity = nodes[nodeId];
            if (capacity > 0) {
                capacity--;
                nodes[nodeId] = capacity;
                // Process the record on this node
                // ...
            } else {
                // Handle overload condition
                std::cout << "Error: Node " << nodeId << " is overloaded." << std::endl;
            }
        } else {
            // Handle unknown node ID
            std::cout << "Error: Unknown node ID " << nodeId << "." << std::endl;
        }
    }

    // Determine the next available node for processing a record
    int determineNodeId() {
        int load = 0;
        for (auto& node : nodes) {
            if (node.second > 0) {
                load++;
                if (load == this->load) {
                    return node.first;
                }
            } else {
                // Handle node failure or overload
                std::cout << "Error: Node " << node.first << " is not available." << std::endl;
            }
        }
        return -1; // No available nodes
    }

private:
    int load;
    std::unordered_map<int, int> nodes;
    std::unordered_map<std::string, std::string> db;
};

int main() {
    ScalableDataPipeline pipeline;
    pipeline.addNode(0, 10);
    pipeline.addNode(1, 15);
    pipeline.processRecord("timestamp=2022-01-01 00:00:00;sourceID=A;eventType=EVENT_A;payload=PAYLOAD_A");
    return 0;
}
