        printf("Error opening file.\n");
        return NULL;
    }

    item* items = (item*)malloc(numItems * sizeof(item));
    metadata* metadataArray = (metadata*)malloc(numItems * sizeof(metadata));

    for (int i = 0; i < numItems; i++) {
        if (fscanf(file, "%lf", &items[i].value) != 1 || items[i].value < 0.0 || items[i].value > 100.0) {
            printf("Error reading file.\n");
            free(items);
            free(metadataArray);
            return NULL;
        }

        metadataArray[i].index = i;
        if (i >= 0) {
            metadataArray[i].string = strdup("Positive index");
        } else {
            metadataArray[i].string = strdup("Negative index");
        }
    }

    fclose(file);

    for (int i = 0; i < numItems; i++) {
        items[i].description = metadataArray[i].string;
    }

    if (logEnabled) {
        printf("Initialized %d items.\n", numItems);
    }

    free(metadataArray);
    return items;
}
