#include <string.h>
#include <openssl/evp.h>

#define RECORD_SIZE 256
#define MAX_RECORDS 15000
#define MIN_RECORDS 5000
#define RANDOM_VALUE_RANGE 1000

typedef struct node {
    long offset;
    int key;
    int value;
    struct node* prev;
    struct node* next;
} Node;

Node* insert_node(Node** head, long offset, int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL; // Handle memory allocation failure
    new_node->offset = offset;
    new_node->key = key;
    new_node->value = rand() % RANDOM_VALUE_RANGE;

    if (*head == NULL) {
        *head = new_node;
        new_node->prev = new_node->next = NULL;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
        new_node->next = NULL;
    }

    return *head;
}

void update_node(Node** head, int index, int key, int value) {
    Node* current = (*head);
    for (int i = 0; i < index && current != NULL; i++) {
        if (current->key == key) {
            current->value = value;
            return;
        }
        current = current->next;
    }
}

Node* delete_node(Node** head, int key) {
    Node* current = *head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current == NULL) return *head; // Not found

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    Node* temp = current;
    current = NULL;

    free(temp);

    return *head;
}

void print_largest_value(Node* head) {
    Node* current = head;
    int max_value = 0;
    while (current != NULL) {
        if (current->value > max_value) {
            max_value = current->value;
        }
        current = current->next;
    }

    printf("Largest value: %d\n", max_value);
}

int main() {
    Node* head = NULL;

    int record_count = 0;
    while (scanf("%d", &record_count) == 1 && record_count >= MIN_RECORDS && record_count <= MAX_RECORDS) {
        for (int i = 0; i < record_count; i++) {
            long offset = rand() % RANDOM_VALUE_RANGE;
            int key = rand() % RANDOM_VALUE_RANGE;

            Node* new_node = insert_node(&head, offset, key);

            // Handle memory allocation failure
            if (!new_node) break;

            // Update the value of specific nodes based on their index and key
            update_node(&head, i, key, (rand() % RANDOM_VALUE_RANGE));
        }

        printf("Records processed: %d\n", record_count);
    }

    Node* temp = head;
    while (temp != NULL) {
        temp = delete_node(&head, temp->key);
    }

    EVP_add_cipher(EVP_CIPHER_new());
    EVP_add_digest(EVP_DIGEST_new());

    return 0;
}

