// Synchronization mechanism using locks
#include <pthread.h>

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Data structure containing records
typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

Record* initialize_data_structure(int num_records, void** data) {
    Record* records = (Record*)allocate(num_records * sizeof(Record));
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        long offset = rand() % 1001;
        int key = rand() % 1000 + 1;
        double timestamp = (double)time(NULL) - (rand() % 101) / 1000.0;
        records[i].offset = offset;
        records[i].key = key;
        records[i].timestamp = timestamp;
    }
    pthread_mutex_unlock(&lock);
    *data = records;
    return records;
}

void verify_data_structure(int num_records, Record* records) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Offset = %ld, Key = %d, Timestamp = %f\n", i, records[i].offset, records[i].key, records[i].timestamp);
    }
    pthread_mutex_unlock(&lock);
}

void record_access(int num_records, Record* records) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_records; i++) {
        printf("Accessing record %d...\n", i);
        // Simulate some operation on the record
        sleep(1);
    }
    pthread_mutex_unlock(&lock);
}

void log_performance_metrics() {
    printf("Frequency of lock acquisitions: %f\n", (double)rand() / RAND_MAX);
    printf("Duration of record accesses: %f\n", (double)time(NULL) - (rand() % 1000) / 1000.0);
}

int main() {
    int num_records = 10;
    Record* records = NULL;

    // Initialize data structure
    initialize_data_structure(num_records, &records);

    // Verify integrity of the data structure
    verify_data_structure(num_records, records);

    // Simulate concurrent access to the data structure
    record_access(num_records, records);

    // Log performance metrics
    log_performance_metrics();

    // Free memory allocated for the data structure
    free_memory(records);

    return 0;
}
