    for (int i = 0; i < num_records; i++) {
        if (!func(&records[i]->p, &records[i]->s)) {
            // Remove the record from the array
            free(records[i]);
            records[i] = records[--num_records];
            i--;
        }
    }
}

void clear_old_records(record** records, int* num_records, time_t threshold) {
    while (*num_records > 0 && records[(*num_records)-1]->t < threshold) {
