using System;
using UnityEngine;

public class DynamicValueGenerator<T> where T : struct
{
    private double minValue;
    private double maxValue;

    public DynamicValueGenerator(double min, double max)
    {
        if (min > max)
        {
            throw new ArgumentException("Min value must be less than or equal to Max value.");
        }
        if (max - min == 0)
        {
            throw new ArgumentException("Range cannot be zero or negative.");
        }

        this.minValue = min;
        this.maxValue = max;
    }

    public double GetRandomFloat()
    {
        return Random.Range(minValue, maxValue + 1);
    }

    public int GetRandomInt()
    {
        return (int)Random.Range(minValue, maxValue + 1);
    }

    public Vector2 GetRandomVector2()
    {
        return new Vector2(GetRandomFloat(), GetRandomFloat());
    }

    public Color GetRandomColor()
    {
        return new Color(
            Random.Range(minValue, maxValue + 1),
            Random.Range(minValue, maxValue + 1),
            Random.Range(minValue, maxValue + 1),
            Random.Range(minValue, maxValue + 1)
        );
    }

    public T[] GetRandomArray(int length)
    {
        T[] array = new T[length];
        for (int i = 0; i < length; i++)
        {
            if (typeof(T) == typeof(double))
                array[i] = (T)(object)GetRandomFloat();
            else
                array[i] = (T)(object)GetRandomInt();
        }
        return array;
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue})";
    }
}
