public static byte[] DecryptAESGCM(byte[] ciphertext, byte[] encryptionKey, byte[] iv, byte[] aad, byte[] hmacKey)
{
    using (Aes aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = iv;
        using (GcmCryptor gcm = GcmCryptor.Create(aes))
        {
            gcm.InputBlockSize = 128;
            gcm.OutputBlockSize = 128;

            byte[] decrypted = new byte[ciphertext.Length];
            int bytesRead = gcm.Decrypt(ciphertext, 0, ciphertext.Length, decrypted, 0);
            return decrypted;
        }
    }
}

