// Define custom memory allocator
typedef struct {
    void* addr;
    size_t size;
} MemBlock;

MemBlock* mem_pool = NULL;
size_t pool_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* my_malloc(size_t size) {
    if (mem_pool == NULL || mem_pool->size < size) {
        // Allocate new block
        MemBlock* new_block = (MemBlock*)malloc(sizeof(MemBlock));
        new_block->addr = malloc(size);
        new_block->size = size;
        pool_size += size;

        // Replace previous block if it's smaller than the new one
        if (mem_pool != NULL && mem_pool->size < size) {
            MemBlock* old_block = mem_pool;
            mem_pool = new_block;
            free(old_block->addr);
            free(old_block);
        } else {
            mem_pool = new_block;
        }
    }

    return mem_pool->addr;
}

void my_free(void* ptr) {
    if (mem_pool != NULL && ptr == mem_pool->addr) {
        MemBlock* old_block = mem_pool;
        mem_pool = (MemBlock*)malloc(sizeof(MemBlock));
        mem_pool->addr = ptr;
        mem_pool->size = old_block->size;
        pool_size -= old_block->size;

        free(old_block->addr);
        free(old_block);

        if (pool_size < 1024) {
            // Shrink the pool
            MemBlock* new_block = mem_pool;
            mem_pool = NULL;
            pool_size = 0;

            free(new_block->addr);
            free(new_block);
        }
    } else {
        // Pointer not in our pool, just free it
        free(ptr);
    }
}

// Define record structure and array
