    for (size_t i = 0; i < 100; i++) {
        offset_values[i] = i;
        keys[i] = i;
        measurements[i] = (float)i / 10.0f;
    }

    // Allocate memory for records array
    Record* new_records = (Record*)my_malloc(sizeof(Record) * 100);
    for (size_t i = 0; i < 100; i++) {
        new_records[i].key = keys[i];
        new_records[i].hash_entry = NULL;
        new_records[i].measurement = measurements[i];
    }

    records = new_records;
    num_records = 100;
}

// Implement real-time logging and monitoring
void log_memory_usage() {
    printf("Memory usage: %zu bytes\n", pool_size);
}

void log_allocation_success(size_t size) {
    printf("Allocated %zu bytes successfully!\n", size);
}

void log_error(void* ptr, int status) {
    printf("Error allocating memory at %p with status %d\n", ptr, status);
}

// Define external logging and monitoring system
