#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define OFFSET_MAX 10000
#define KEY_ID_MAX 5000
#define RECORD_STRUCT_SIZE 200

typedef struct {
    int offset;
    char key_id[KEY_ID_MAX];
    char record_struct[RECORD_STRUCT_SIZE];
} RecordStruct;

RecordStruct* memory_pool = NULL;
size_t memory_pool_size = 0;
pthread_mutex_t memory_pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* init_memory_pool(size_t size) {
    memory_pool = (RecordStruct*)malloc(size * sizeof(RecordStruct));
    memory_pool_size = size;
    return NULL;
}

void* allocate_record_struct() {
    pthread_mutex_lock(&memory_pool_lock);
    RecordStruct* result = NULL;
    if (memory_pool != NULL && memory_pool_size > 0) {
        result = &memory_pool[0];
        // Initialize the record structure with random values
        srand(time(NULL));
        result->offset = rand() % OFFSET_MAX;
        // Initialize key identifier and record struct with random characters
        for (int i = 0; i < KEY_ID_MAX; i++) {
            result->key_id[i] = (char)(rand() % 26 + 'a');
        }
        for (int i = 0; i < RECORD_STRUCT_SIZE; i++) {
            result->record_struct[i] = (char)(rand() % 256);
        }
    } else {
        // Handle memory pool exhaustion
        printf("Memory pool exhausted!\n");
    }
    pthread_mutex_unlock(&memory_pool_lock);
    return result;
}

void deallocate_record_struct(void* record) {
    pthread_mutex_lock(&memory_pool_lock);
    if (record != NULL && memory_pool != NULL) {
        RecordStruct* allocated = (RecordStruct*)record;
        // Reuse the allocated memory block
        memmove(allocated, &memory_pool[1], memory_pool_size - 1 * sizeof(RecordStruct));
        // Reset the record structure to zero for future reuse
        allocated->offset = 0;
        for (int i = 0; i < KEY_ID_MAX; i++) {
            allocated->key_id[i] = '\0';
        }
        for (int i = 0; i < RECORD_STRUCT_SIZE; i++) {
            allocated->record_struct[i] = '\0';
        }
    } else {
        // Handle null or invalid record
        printf("Invalid record deallocation!\n");
    }
    pthread_mutex_unlock(&memory_pool_lock);
}

void log_memory_event(const char* event) {
    printf("%s: Memory pool size: %zu\n", event, memory_pool_size);
}

int main() {
    init_memory_pool(1000); // Initialize the memory pool with 1000 records
    for (int i = 0; i < 10; i++) {
        RecordStruct* record = allocate_record_struct();
        if (record != NULL) {
            deallocate_record_struct(record);
        }
    }
    return 0;
}
