#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
} Record;

// Function to manage dynamic collection of record structures
Record* recordManager(int initialCapacity) {
    // Initialize array with initial capacity and set current size
    Record* records = (Record*)malloc(initialCapacity * sizeof(Record));
    int currentSize = 0;

    // Mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    return &records;
}

// Function to resize the record array when necessary
void resizeArray(Record** records, int newSize) {
    // Lock the mutex before resizing
    pthread_mutex_lock(&mutex);

    // Allocate new memory with the desired size
    *records = (Record*)realloc(*records, newSize * sizeof(Record));

    // Update the current size and unlock the mutex
    currentSize = newSize;
    pthread_mutex_unlock(&mutex);
}

// Function to add a record to the collection
void addRecord(Record** records, int key, long offset) {
    // Lock the mutex before adding a new record
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (currentSize == initialCapacity) {
        resizeArray(records, initialCapacity * 2);
    }

    // Add the new record and update the current size
    records[currentSize].key = key;
    records[currentSize].offset = offset;
    currentSize++;

    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record by its key
Record* getRecord(Record** records, int key) {
    // Lock the mutex before accessing the array
    pthread_mutex_lock(&mutex);

    // Search for the requested record in the cache (first 50% of the array)
    for (int i = 0; i < currentSize / 2; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&mutex);
            return &records[i];
        }
    }

    // Search for the requested record in the rest of the array
    for (int i = currentSize / 2; i < currentSize; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&mutex);
            return &records[i];
        }
    }

    // If the record is not found, allocate a new slot and add it to the end
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->offset = 0; // Initialize with default offset

    records[currentSize] = newRecord;
    currentSize++;

    pthread_mutex_unlock(&mutex);
    return newRecord;
}

// Function to release memory and cleanup
void destroyRecords(Record** records) {
    free(records);
}
