#define MAX_FRAMES 1000
#define MAX_PIXELS 1024 * 1024 * 3 // Assuming 1024x1024 pixels with 3-color channels (RGB)

typedef struct {
    int* pixels;
    size_t num_pixels;
} Frame;

Frame process_image_data(int max_memory, FILE* input) {
    Frame frames[MAX_FRAMES];
    for (int i = 0; i < MAX_FRAMES; i++) {
        char buffer[1024];
        if (!fgets(buffer, sizeof(buffer), input)) break;
        // Assuming the frame is represented as a grid of pixels in the format:
        // "R1 G1 B1 R2 G2 B2 ... RN GN BN"
        size_t num_pixels = strlen(buffer) / 3; // Divide by 3 to account for RGB values
        frames[i].num_pixels = num_pixels;
        frames[i].pixels = (int*)malloc(num_pixels * sizeof(int));
        memcpy(frames[i].pixels, buffer, num_pixels * sizeof(int));
    }

    Frame largest_frame = {0};
    double max_luminance = 0.0;

    for (int i = 0; i < MAX_FRAMES; i++) {
        if (!frames[i].num_pixels) break;
        int* pixels = frames[i].pixels;
        double luminance_sum = 0.0;
        size_t num_pixels = frames[i].num_pixels;
        for (size_t j = 0; j < num_pixels; j++) {
            int rgb = pixels[j];
            int red = (rgb >> 16) & 0xFF;
            int green = (rgb >> 8) & 0xFF;
            int blue = rgb & 0xFF;
            double luminance = 0.299 * red + 0.587 * green + 0.114 * blue;
            luminance_sum += luminance;
        }
        if (luminance_sum > max_luminance) {
            largest_frame = frames[i];
            max_luminance = luminance_sum;
        }
    }

    for (int i = 0; i < MAX_FRAMES; i++) {
        free(frames[i].pixels);
    }

    return largest_frame;
}

void print_largest_frame(Frame frame) {
    printf("Largest frame by luminance:\n");
    int* pixels = frame.pixels;
    size_t num_pixels = frame.num_pixels;
    for (size_t j = 0; j < num_pixels; j++) {
        int rgb = pixels[j];
        int red = (rgb >> 16) & 0xFF;
        int green = (rgb >> 8) & 0xFF;
        int blue = rgb & 0xFF;
        printf("%d %d %d\n", red, green, blue);
    }
}
