    // Check for overflow and limit
    if (checkOverflow(offsetSize + keySize + recordSize)) {
        printf("Array size exceeds 1 MB. Reducing size...\n");
        offsetSize = keySize = recordSize = 1024 * 1024 / sizeof(long);
    }

    // Allocate memory and initialize arrays
