void initArrays(int* keys, long* offsets, int size) {
    // Initialize arrays
    for (int i = 0; i < size; i++) {
        keys[i] = i;
        offsets[i] = i * sizeof(Record);
    }
}

bool isValidOffset(long offset) {
    return offset > 0;
}

void* allocateRecords(int size, long* offsets) {
    Record* records = (Record*) malloc(size * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Assign unique random values to each record's integer field
    for (int i = 0; i < size; i++) {
        int val = rand() % 100; // Replace with desired range
        records[i].key = val;
        records[i].offset = offsets[val];
        if (!isValidOffset(records[i].offset)) {
            printf("Invalid offset at record %d.\n", i);
            free(records);
            return NULL;
        }
    }

    return records;
}

void releaseMemory(void* ptr) {
    free(ptr);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    int size = 10; // Adjust the size as needed
    int* keys = (int*) malloc(size * sizeof(int));
    long* offsets = (long*) malloc(size * sizeof(long));

    initArrays(keys, offsets, size);

    Record* records = allocateRecords(size, offsets);
    if (!records) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Process the records here...

    releaseMemory((void*) records); // Release memory when done
    free(keys);
    free(offsets);

    return 0;
}

