// Function to initialize and manage heterogeneous collection of data structures
data_element* init_data_element(int capacity, enum category* categories) {
    data_element* de = (data_element*)malloc(sizeof(data_element));
    if (!de) {
        return NULL;
    }

    de->arr_long = (long*)malloc(capacity * sizeof(long));
    if (!de->arr_long) {
        free(de);
        return NULL;
    }

    de->arr_int = (int*)malloc(capacity * sizeof(int));
    if (!de->arr_int) {
        free(de->arr_long);
        free(de);
        return NULL;
    }

    de->arr_record = (record*)malloc(capacity * sizeof(record));
    if (!de->arr_record) {
        free(de->arr_long);
        free(de->arr_int);
        free(de);
        return NULL;
    }

    de->categories = categories;
    de->size = capacity;

    return de;
}

// Function to read floating-point numbers from standard input and store them in an array
float* read_input(int capacity) {
    float* arr = (float*)malloc(capacity * sizeof(float));
    if (!arr) {
        return NULL;
    }

    for (int i = 0; i < capacity; i++) {
        scanf("%f", &arr[i]);
    }

    return arr;
}

