Node* create_node(Node* head, size_t index) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    new_node->key = 'a' + (index % 26); // dynamic initialization of double field
    new_node->value = index * 10; // update value according to mathematical expression
    new_node->is_set = true;
    new_node->timestamp = time(NULL);
    new_node->next = head;

    return new_node;
}

Node* init_array(size_t size) {
    Node* arr = (Node*)malloc(sizeof(Node) * size);
    if (!arr) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        arr[i] = create_node(NULL, i);
    }

    return arr;
}

void free_array(Node* arr, size_t size) {
    for (size_t i = 0; i < size; i++) {
        if (arr[i]) {
            Node* temp = &arr[i];
            while (temp->next) {
                Node* next_node = temp->next;
                free(temp);
                temp = next_node;
            }
            free(temp);
        }
    }

    free(arr);
}
