const { spawn } = require('child_process');
const { schema } = require('./command-schema');
const { api1, api2, api3 } = require('./apis');
const { cache } = require('./cache');
const { log } = require('./logger');

function executeCommand(command, params) {
  const validatedParams = validateParameters(params);
  if (!validatedParams) return Promise.reject(new Error('Invalid command parameters'));

  const cachedResult = cache.get(command);
  if (cachedResult) return Promise.resolve(cachedResult);

  const childProcess = spawn('bash', ['-c', command]);

  childProcess.on('exit', (code, signal) => {
    if (code || signal) {
      log.error(`Command execution failed: ${command}`);
      handleApiErrors();
    }
  });

  childProcess.stdout.on('data', (data) => {
    const result = data.toString();
    cache.set(command, result);
  });

  return new Promise((resolve, reject) => {
    childProcess.stderr.on('data', (data) => {
      log.error(`Command execution error: ${data.toString()}`);
      reject(new Error('Command execution failed'));
    });
    childProcess.on('close', (code) => {
      if (code === 0) resolve();
      else reject(new Error('Command execution failed'));
    });
  }).then((result) => {
    return result;
  }).catch((error) => {
    handleApiErrors();
    throw error;
  });
}

function validateParameters(params) {
  const validatedParams = schema.validate(params);
  if (!validatedParams) return null;
  return validatedParams;
}

function handleApiErrors() {
  // retry logic here
}

module.exports = executeCommand;
