    int* keys = (int*)malloc(record_count * sizeof(int));
    Node** records = (Node**)malloc(record_count * sizeof(Node));

    // Initialize doubly linked list of nodes
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < record_count; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        node->key = keys[i];
        node->offset = offsets[i];
        node->value = rand() % max_value;
        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Read list of integers from standard input and store in array
    int* arr = (int*)malloc(record_count * sizeof(int));
    for (int i = 0; i < record_count; i++) {
        scanf("%d", &arr[i]);
    }

    // Find and print the largest integer in the array
    int max_val = find_max(arr, record_count);
    printf("Largest integer: %d\n", max_val);

    // Free allocated memory
    free(offsets);
    free(keys);
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);

    return;
}

// Helper function to find the largest integer in an array
int find_max(int* arr, int size) {
    int max_val = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    return max_val;
}
