#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000
#define MAX_CURRENCY 10
#define MAX_LINE_LENGTH 1024

typedef struct {
    int timestamp;
    double amount;
    char currency[3];
} transaction;

transaction* transactions = NULL;
int transaction_count = 0;
pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    double total_amount;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
} currency_map;

currency_map* currency_maps[MAX_CURRENCY];
pthread_mutex_t currency_map_lock = PTHREAD_MUTEX_INITIALIZER;

void read_transactions_csv(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    transaction* new_transaction = (transaction*)malloc(sizeof(transaction));
    pthread_mutex_lock(&transaction_lock);
    for (int i = 0; i < MAX_TRANSACTIONS && fgets(new_transaction, sizeof(*new_transaction), file); ++i) {
        char* line_copy = strdup(new_transaction);
        if (!line_copy) {
            printf("Error allocating memory\n");
            continue;
        }
        char* token = strtok(line_copy, ",");
        if (token == NULL || sscanf(token, "%d", &new_transaction->timestamp) != 1) {
            printf("Invalid timestamp format: %s\n", line_copy);
            free(line_copy);
            continue;
        }
        token = strtok(NULL, ",");
        if (!token) {
            printf("Error parsing line: %s\n", line_copy);
            free(line_copy);
            continue;
        }
        if (sscanf(token, "%lf", &new_transaction->amount) != 1 || new_transaction->amount < 0.0) {
            printf("Invalid amount format: %s\n", line_copy);
            free(line_copy);
            continue;
        }
        token = strtok(NULL, ",");
        if (!token) {
            printf("Error parsing line: %s\n", line_copy);
            free(line_copy);
            continue;
        }
        strncpy(new_transaction->currency, token, 3);
        new_transaction->currency[2] = '\0';

        pthread_mutex_unlock(&transaction_lock);

        // Handle concurrent transactions
        for (int j = 0; j < transaction_count; ++j) {
            if (strncasecmp(transactions[j].currency, new_transaction->currency, 3) == 0) {
                pthread_mutex_lock(&currency_map_lock);
                currency_maps[atoi(new_transaction->currency)].total_amount += new_transaction->amount;
                pthread_mutex_unlock(&currency_map_lock);
                break;
            }
        }

        // Update transaction count
        transaction_count++;

        if (transaction_count >= MAX_TRANSACTIONS) {
            printf("Maximum number of transactions reached: %d\n", transaction_count);
            break;
        }

        transactions = realloc(transactions, sizeof(transaction) * (transaction_count + 1));
        memcpy(&transactions[transaction_count - 1], new_transaction, sizeof(transaction));
        free(new_transaction);

        pthread_mutex_lock(&transaction_lock);
    }
    fclose(file);

    if (!transaction_count) {
        printf("No valid transactions found\n");
    }

    // Print transaction data
    for (int i = 0; i < transaction_count; ++i) {
        printf("%d,%.2f,%s\n", transactions[i].timestamp, transactions[i].amount, transactions[i].currency);
    }
}
