#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>

#define MAX_MEMORY 1024*1024 // 1MB maximum memory
#define HASH_TABLE_SIZE 1000 // adjust according to the number of expected entries
#define FILE_ENTRY_SIZE sizeof(file_entry)

typedef struct {
    int id;
    char path[256];
    int ref_count;
} file_entry;

// hash table with doubly linked list implementation
typedef struct {
    file_entry* entries[HASH_TABLE_SIZE];
    int size;
} file_cache;

file_cache* cache = NULL;
int cache_size = 0;

void init_file_cache() {
    if (cache != NULL) return; // already initialized

    cache = malloc(sizeof(file_cache));
    cache->size = 0;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        cache->entries[i] = NULL;
    }
}

void free_file_cache() {
    if (cache == NULL) return; // not initialized

    file_entry* temp;
    file_entry** entries = cache->entries;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        while (entries[i] != NULL) {
            temp = entries[i];
            entries[i] = entries[i]->next;
            free(temp);
        }
    }

    free(cache);
    cache = NULL;
}

void* allocate_memory(int size) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        // memory allocation failed
        return NULL;
    }
    return ptr;
}

void deallocate_memory(void* ptr, int size) {
    munmap(ptr, size);
}

file_entry* find_file_entry(file_cache* cache, int id) {
    int i = id % HASH_TABLE_SIZE;
    if (cache->entries[i] == NULL || cache->entries[i]->id != id) return NULL;

    file_entry* entry = cache->entries[i];
    while (entry != NULL && entry->id != id) entry = entry->next;
    return entry;
}

int find_and_update_ref_count(file_cache* cache, int id, int increment) {
    file_entry* entry = find_file_entry(cache, id);
    if (entry == NULL) return -1; // not found

    if (increment > 0) {
        entry->ref_count++;
    } else {
        if (--entry->ref_count == 0) {
            // remove least recently used entries when memory usage exceeds the limit
            int free_entry_id = -1;
            file_entry* temp;
            for (int i = 0; i < HASH_TABLE_SIZE; i++) {
                while ((temp = cache->entries[i]) != NULL) {
                    if (free_entry_id == -1 || getpagesize() * temp->ref_count > getpagesize() * entry->ref_count) {
                        free_entry_id = temp->id;
                        break;
                    }
                    temp = temp->next;
                }
            }

            if (free_entry_id != -1) {
                file_entry* free_entry = find_file_entry(cache, free_entry_id);
                if (free_entry != NULL) {
                    // update the least recently used entry's reference count
                    free_entry->ref_count++;
                    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
                        while ((temp = cache->entries[i]) != NULL) {
                            if (temp == free_entry) {
                                temp->next = NULL;
                                break;
                            }
                            temp = temp->next;
                        }
                    }

                    // remove the least recently used entry
                    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
                        while ((temp = cache->entries[i]) != NULL) {
                            if (temp == free_entry) {
                                cache->entries[i] = temp->next;
                                break;
                            }
                            temp = temp->next;
                        }
                    }
                }
            }
        }
    }

    return 0; // success
}

void update_file_cache() {
    int total_size = 0;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        file_entry* entry = cache->entries[i];
        while (entry != NULL) {
            if (entry->ref_count == 1) {
                // remove least recently used entries when memory usage exceeds the limit
                int free_entry_id = -1;
                file_entry* temp;
                for (int j = 0; j < HASH_TABLE_SIZE; j++) {
                    while ((temp = cache->entries[j]) != NULL) {
                        if (free_entry_id == -1 || getpagesize() * temp->ref_count > getpagesize() * entry->ref_count) {
                            free_entry_id = temp->id;
                            break;
                        }
                        temp = temp->next;
                    }
                }

                if (free_entry_id != -1) {
                    file_entry* free_entry = find_file_entry(cache, free_entry_id);
                    if (free_entry != NULL) {
                        // update the least recently used entry's reference count
                        free_entry->ref_count++;
                        for (int j = 0; j < HASH_TABLE_SIZE; j++) {
                            while ((temp = cache->entries[j]) != NULL) {
                                if (temp == free_entry) {
                                    temp->next = NULL;
                                    break;
                                }
                                temp = temp->next;
                            }
                        }

                        // remove the least recently used entry
                        for (int j = 0; j < HASH_TABLE_SIZE; j++) {
                            while ((temp = cache->entries[j]) != NULL) {
                                if (temp == free_entry) {
                                    cache->entries[j] = temp->next;
                                    break;
                                }
                                temp = temp->next;
                            }
                        }
                    }
                }
            }

            entry = entry->next;
        }
    }
}

int main() {
    int limit = MAX_MEMORY / FILE_ENTRY_SIZE; // calculate the maximum number of entries
    char line[256];

    while (fgets(line, sizeof(line), stdin)) {
        file_entry* new_entry = allocate_memory(FILE_ENTRY_SIZE);
        if (new_entry == NULL) continue;

        // parse and validate the file path
        // ...

        // update the reference count
        int id = new_entry->id;
        find_and_update_ref_count(cache, id, 1);

        // add to least recently used entry's list
        for (int i = 0; i < HASH_TABLE_SIZE; i++) {
            while ((new_entry->next = cache->entries[i]) != NULL) {
                new_entry->next = new_entry->next->next;
                break;
            }
        }

        // update the size of the file cache
        total_size += FILE_ENTRY_SIZE;

        if (total_size > limit) {
            update_file_cache();
            total_size -= FILE_ENTRY_SIZE; // subtract the freed memory
        }
    }

    free_file_cache();

    return 0;
}

