#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the custom Item structure
typedef struct {
    int id;
    char* str;
    double metric;
} Item;

// Define the resource manager data structure
typedef struct {
    Item** items;
    int capacity;
    int size;
    pthread_mutex_t lock;
} ResourceManager;

// Initialize and allocate memory for multiple instances of an Item structure
ResourceManager* initResourceManager(int capacity) {
    ResourceManager* rm = (ResourceManager*)malloc(sizeof(ResourceManager));
    rm->items = (Item**)malloc(capacity * sizeof(Item*));
    rm->capacity = capacity;
    rm->size = 0;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

// Allocate and initialize a new Item instance in the resource manager
void addItem(ResourceManager* rm) {
    if (rm->size >= rm->capacity) {
        // Handle memory allocation failure, fallback mechanism
        printf("Memory allocation failed. Cannot add more items.\n");
        return;
    }

    Item* item = (Item*)malloc(sizeof(Item));
    item->id = rand();
    item->str = (char*)malloc(10);  // Initialize with a default string size
    sprintf(item->str, "Item-%d", item->id);
    item->metric = 0.0;

    rm->items[rm->size] = item;
    rm->size++;
}

// Update the metric and identifier values of an Item instance based on its index and identifier
void updateItem(ResourceManager* rm, int idx, int newId, double newMetric) {
    pthread_mutex_lock(&rm->lock);

    if (idx < rm->size && rm->items[idx]) {
        rm->items[idx]->id = newId;
        rm->items[idx]->metric = newMetric;
    }

    pthread_mutex_unlock(&rm->lock);
}

// Reclaim unused memory in the resource manager
void reclaimMemory(ResourceManager* rm) {
    for (int i = 0; i < rm->size; i++) {
        if (!rm->items[i]) {
            // Remove and free the unused item instance
            Item* item = rm->items[i];
            rm->items[i] = NULL;
            free(item->str);
            free(item);
            rm->size--;
        }
    }
}

// Search for an Item by its ASCII string identifier and return the corresponding Item
Item* findItem(ResourceManager* rm, char* str) {
    pthread_mutex_lock(&rm->lock);

    for (int i = 0; i < rm->size; i++) {
        if (!strcmp(rm->items[i]->str, str)) {
            // Found matching item, return a copy
            Item* result = (Item*)malloc(sizeof(Item));
            *result = *rm->items[i];
            free(rm->items[i]->str);
            rm->items[i]->str = NULL;
            pthread_mutex_unlock(&rm->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&rm->lock);

    // Item not found, return a null pointer
    return NULL;
}

// Demonstrate the usage of the resource manager and its functions
int main() {
    ResourceManager* rm = initResourceManager(10);

    for (int i = 0; i < 5; i++) {
        addItem(rm);
    }

    updateItem(rm, 1, 42, 3.14);

    reclaimMemory(rm);

    Item* foundItem = findItem(rm, "Item-1");

    if (foundItem) {
        printf("Found item: %d, '%s', %.2f\n", foundItem->id, foundItem->str, foundItem->metric);
        free(foundItem);
    } else {
        printf("Item not found.\n");
    }

    // Clean up resources
    for (int i = 0; i < rm->size; i++) {
        if (rm->items[i]) {
            free(rm->items[i]->str);
            free(rm->items[i]);
        }
    }
    free(rm->items);
    free(rm);

    return 0;
}

