// Function to manage sensor data structures
int manageSensorData(struct SensorData** sensorData, int* sensorCount, int memoryLimit) {
    if (*sensorCount >= MAX_SENSOR_COUNT || (size_t)sensorData[0] > memoryLimit) return -1;

    void* allocation = malloc(SENSOR_DATA_SIZE);
    if (!allocation) {
        // Handle memory allocation failure
        perror("Memory allocation failed");
        return -2;
    }

    struct SensorData* newSensorData = (struct SensorData*)allocation;

    int foundIndex = -1; // Initialize to indicate not found
    for (int i = 0; i < *sensorCount; i++) {
        if ((size_t)sensorData[i] == allocation) {
            foundIndex = i;
            break;
        }
    }

    if (foundIndex != -1) { // Update existing sensor data structure
        printf("Updating sensor data at index %d...\n", foundIndex);
        *sensorData[foundIndex] = *newSensorData; // Assign updated values
    } else { // Add new sensor data structure
        (*sensorCount)++;
        sensorData = realloc(sensorData, sizeof(struct SensorData*) * (*sensorCount + 1));
        if (!sensorData) {
            // Handle memory allocation failure for dynamic array
            perror("Memory allocation failed");
            return -3;
        }
        sensorData[*sensorCount - 1] = newSensorData;
    }

    return 0; // Success
}

// Function to log changes to sensor data
void logSensorChanges(struct SensorData** sensorData, int* sensorCount) {
    FILE* logFile = fopen("sensor_log.txt", "a");
    if (!logFile) {
        perror("Failed to open log file");
        return;
    }

    for (int i = 0; i < *sensorCount; i++) {
        fprintf(logFile, "%f %f %c\n", sensorData[i]->precision, sensorData[i]->timestamp, sensorData[i]->identifier);
    }
    fclose(logFile);
}

// Function to concurrently update multiple sensors
void* updateSensors(void* arg) {
    struct SensorData** sensorData = (struct SensorData**)arg;
    int* sensorCount = (int*)sensorData;

    // Simulate concurrent updates
    for (int i = 0; i < *sensorCount; i++) {
        manageSensorData(sensorData, sensorCount, MAX_LOG_ENTRY_SIZE);
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_SENSOR_COUNT]; // Create an array of thread IDs

    struct SensorData* sensorData = (struct SensorData*)malloc(MAX_SENSOR_COUNT * sizeof(struct SensorData));
    if (!sensorData) {
        perror("Memory allocation failed");
        return -1;
    }

    int sensorCount = 0; // Initialize sensor count to zero
    pthread_create(&threads[0], NULL, updateSensors, &sensorData);
    pthread_join(threads[0], NULL); // Wait for the thread to finish

    logSensorChanges(sensorData, &sensorCount);

    free(sensorData); // Release dynamically allocated memory
    return 0;
}
