    int num_records = 100;
    int byte_limit = 1000000; // Adjust this value according to your system's memory constraints
    record** records = initialize_and_manage_records(num_records, byte_limit);

    if (!records) {
        printf("Initialization failed. Exiting.\n");
        return -1;
    }

    // Perform concurrent updates
    pthread_t threads[200];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, update_record_func, records);
    }
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i]);
    }

    // Serialize the record collection to disk
    FILE* file = fopen("record_collection.bin", "wb");
    if (!file) {
        printf("Error: Unable to open file for serialization.\n");
    } else {
        fwrite(records, sizeof(record*), num_records + 1, file);
        fclose(file);
    }

    // Deserialize the record collection from disk
    FILE* file = fopen("record_collection.bin", "rb");
    if (!file) {
        printf("Error: Unable to open file for deserialization.\n");
    } else {
        fread(records, sizeof(record*), num_records + 1, file);
        fclose(file);

        // Perform lookups and garbage collection
        for (int i = 0; i < num_records; ++i) {
            record* r = records[i];
            if (!r->ref_count--) {
                free(r);
            }
        }
    }

    return 0;
}

void update_record_func(void* arg) {
    // Update the record based on the provided index and key
    record** records = (record**)arg;
    int index = rand() % num_records; // Adjust this value according to your system's memory constraints
    int key = rand() % 100; // Adjust this value according to your system's memory constraints
    update_record(records, index, key);
}
