record** initialize_and_manage_records(int num_records, int max_value_range, int max_memory_limit) {
    // Calculate the total memory required for the records
    int total_memory_required = sizeof(record*) * 3 + sizeof(record) * num_records;

    // Check if the total memory exceeds the limit
    if (total_memory_required > max_memory_limit) {
        printf("Error: Total memory required exceeds the specified limit.\n");
        return NULL;
