    // Dynamically allocate memory for the arrays
    record** records = (record**)malloc(sizeof(record*) * 3);
    record* record_array = (record*)malloc(sizeof(record) * num_records);

    // Initialize the arrays
    records[0] = &record_array[0];
    records[1] = &record_array[num_records];
    records[2] = &record_array[2 * num_records];

