#include <iostream>
#include <map>
#include <mutex>
#include <thread>

class NetworkConnection {
public:
    int id;
    bool status;
    long lastActiveTimestamp;
    int referenceCount;

    NetworkConnection(int newId) : id(newId), status(false), lastActiveTimestamp(0), referenceCount(1) {}
};

class NetworkManager {
private:
    std::map<int, NetworkConnection*> connections;
    size_t maxMemoryUsage;
    size_t maxReferenceCount;
    std::mutex connectionMutex;

public:
    NetworkManager(size_t newMaxMemoryUsage, size_t newMaxReferenceCount)
        : maxMemoryUsage(newMaxMemoryUsage), maxReferenceCount(newMaxReferenceCount) {}

    void addConnection(int id) {
        if (connections.size() >= maxMemoryUsage / sizeof(NetworkConnection*))
            return; // Out of memory

        connections[id] = new NetworkConnection(id);
    }

    void removeConnection(int id) {
        if (connections.erase(id) != nullptr)
            delete connections.at(id);
    }

    void updateStatus(int id, bool status) {
        std::unique_lock<std::mutex> lock(connectionMutex);

        auto it = connections.find(id);
        if (it == connections.end())
            return; // Connection not found

        it->second->status = status;
    }

    void updateLastActiveTimestamp(int id, long timestamp) {
        std::unique_lock<std::mutex> lock(connectionMutex);

        auto it = connections.find(id);
        if (it == connections.end())
            return; // Connection not found

        it->second->lastActiveTimestamp = timestamp;
    }
};

