// Define a struct to represent an international transaction record
typedef struct {
    int id;
    time_t timestamp;
    char account[20];
    float amount;
    int status; // 0 for debit, 1 for credit
    int payment_method;
} TransactionRecord;

// Function to initialize and manage dynamic list of transaction records
TransactionRecord* init_transaction_records(int initial_size) {
    TransactionRecord* records = (TransactionRecord*)malloc(initial_size * sizeof(TransactionRecord));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < initial_size; i++) {
        records[i].id = i;
        records[i].timestamp = time(NULL);
        sprintf(records[i].account, "Account %d", i);
        records[i].amount = (float)rand() / RAND_MAX;
        if ((rand() % 2) == 0)
            records[i].status = 1; // credit
        else
            records[i].status = 0; // debit
        records[i].payment_method = rand() % 3; // random payment method

        printf("Initialized transaction record %d: %p\n", i, &records[i]);
    }

    return records;
}

// Function to add a new transaction record to the dynamic list
void add_transaction_record(TransactionRecord** records, int* size) {
    TransactionRecord* new_records = (TransactionRecord*)realloc(*records, (*size + 1) * sizeof(TransactionRecord));
    if (!new_records) {
        printf("Memory allocation failed.\n");
        return;
    }
    *records = new_records;

    (*records)[*size].id = *size;
    (*records)[*size].timestamp = time(NULL);
    sprintf((*records)[*size].account, "Account %d", *size);
    (*records)[*size].amount = (float)rand() / RAND_MAX;
    if ((rand() % 2) == 0)
        (*records)[*size].status = 1; // credit
    else
        (*records)[*size].status = 0; // debit
    (*records)[*size].payment_method = rand() % 3; // random payment method

    printf("Added new transaction record: %p\n", &(*records)[*size]);
    (*size)++;
}

// Function to print all transaction records in the dynamic list
void print_transaction_records(TransactionRecord** records, int size) {
    for (int i = 0; i < size; i++) {
        printf("Transaction record %d: id = %d, timestamp = %ld, account = %s, amount = %.2f, status = %d, payment_method = %d\n",
            i, (*records)[i].id, (*records)[i].timestamp, (*records)[i].account, (*records)[i].amount,
            (*records)[i].status, (*records)[i].payment_method);
    }
}

int main() {
    int initial_size = 10;
    TransactionRecord* records = init_transaction_records(initial_size);

    if (!records)
        return -1;

    for (int i = 0; i < initial_size; i++) {
        printf("Iteration %d: printing transaction records...\n", i);
        print_transaction_records(&records, initial_size);
        add_transaction_record(&records, &initial_size);
    }

    free(records);

    return 0;
}

