#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BLOCKS 100
#define MAX_ELEMENTS_PER_BLOCK 10
#define MEMORY_LIMIT 1024 * 1024 // 1MB
#define FLOAT_VALUE_RANGE -100.0f, 100.0f

typedef struct {
    float value;
    char* string;
} element_t;

void* data_block_new(size_t block_size) {
    void* ptr = malloc(block_size);
    if (!ptr) return NULL;

    int num_elements = (int)block_size / sizeof(element_t*);
    element_t** elements = (element_t**)malloc(num_elements * sizeof(element_t*));
    for (int i = 0; i < num_elements; i++) {
        elements[i] = (element_t*)malloc(sizeof(element_t));
        if (!elements[i]) return NULL;
    }

    *(void**)ptr = elements;

    return ptr;
}

void data_block_free(void* block) {
    element_t** elements = (element_t**)block;
    int num_elements = sizeof(elements) / sizeof(elements[0]);
    for (int i = 0; i < num_elements; i++) {
        free(elements[i]);
    }
    free(block);
}

pthread_mutex_t lock;

void update_element(void* block, size_t index, const char* identifier) {
    pthread_mutex_lock(&lock);

    element_t** elements = (element_t**)block;
    if (index >= sizeof(elements) / sizeof(elements[0])) {
        printf("Invalid index: %zu\n", index);
        return;
    }

    element_t* element = elements[index];
    // Update the value based on the identifier
    // For demonstration purposes, simply increment the value
    element->value += atof(identifier);

    pthread_mutex_unlock(&lock);
}

void generate_random_elements(void* block) {
    pthread_mutex_lock(&lock);

    element_t** elements = (element_t**)block;
    int num_elements = sizeof(elements) / sizeof(elements[0]);
    for (int i = 0; i < num_elements; i++) {
        element_t* element = elements[i];
        float value = (float)rand() / RAND_MAX * (FLOAT_VALUE_RANGE.second - FLOAT_VALUE_RANGE.first) + FLOAT_VALUE_RANGE.first;
        element->value = value;

        // Generate a random string
        char buffer[32];
        sprintf(buffer, "Element %d: %.2f", i, value);
        int len = strlen(buffer);
        element->string = (char*)malloc(len + 1);
        memcpy(element->string, buffer, len);
        element->string[len] = '\0';
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));

    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < MAX_BLOCKS; i++) {
        size_t block_size = sizeof(element_t*) * MIN(MAX_ELEMENTS_PER_BLOCK, i + 1);
        if (block_size > MEMORY_LIMIT) break;

        void* block = data_block_new(block_size);
        generate_random_elements(block);

        // Use the updated elements
        for (size_t j = 0; j < i + 1; j++) {
            element_t* element = *(element_t**)block + j;
            printf("Block %zu, Element %zu: value=%f, string='%s'\n", i, j, element->value, element->string);
        }

        data_block_free(block);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}

