typedef struct node {
    char data[257]; // +1 for null-terminator
    int priority;
} node_t;

node_t* allocate_nodes(int limit_bytes) {
    int num_nodes = (limit_bytes / sizeof(node_t)) * 0.8; // calculate number of nodes that can fit within the given memory limit
    num_nodes = (num_nodes < 10000) ? 10000 : num_nodes; // ensure at least 10,000 nodes are allocated

    node_t* nodes = malloc(num_nodes * sizeof(node_t));
    if (!nodes) {
        printf("Memory allocation failed. Reducing number of nodes.\n");
        num_nodes /= 2;
        nodes = realloc(nodes, num_nodes * sizeof(node_t));
    }

    for (int i = 0; i < num_nodes; i++) {
        char* alphanumeric_sequence = malloc(257);
        sprintf(alphanumeric_sequence, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_%s", 
            (char*)malloc(256)); // generate a unique alphanumeric sequence
        srand(time(NULL) + i); // ensure randomness for each node's priority level
        int priority = rand() % 100; // assign a random priority level within the range [0, 99]

        strcpy(nodes[i].data, alphanumeric_sequence);
        nodes[i].priority = priority;

