// Function to allocate and initialize memory for multiple data structures
int manage_memory(int max_capacity_offset, int max_capacity_keys, int max_capacity_records) {
    // Allocate memory for offset values array
    long* offset_values = (long*) malloc(max_capacity_offset * sizeof(long));
    if (!offset_values) {
        fprintf(stderr, "Error: Failed to allocate memory for offset values.\n");
        return -1;
    }

    // Initialize offset values array with zeros
    memset(offset_values, 0, max_capacity_offset * sizeof(long));

    // Allocate memory for keys array
    int* keys = (int*) malloc(max_capacity_keys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offset_values);
        return -1;
    }

    // Initialize keys array with zeros
    memset(keys, 0, max_capacity_keys * sizeof(int));

    // Allocate memory for records array
    Record* records = (Record*) malloc(max_capacity_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(offset_values);
        free(keys);
        return -1;
    }

    // Initialize records array with zeros
    memset(records, 0, max_capacity_records * sizeof(Record));

    // Populate each record with a random value within the given range
    srand(time(NULL));
    for (int i = 0; i < max_capacity_records; i++) {
        records[i].value = rand() % 100;
    }

    // Validate the integrity of all allocated memory
    if (!offset_values || !keys || !records) {
        fprintf(stderr, "Error: Memory validation failed.\n");
        free(offset_values);
        free(keys);
        return -1;
    }

    // Log errors and warnings to a specified file descriptor (optional)
    FILE* log_file = fopen("memory_allocation_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Unable to open log file.\n");
        free(offset_values);
        free(keys);
        return -1;
    }
    fprintf(log_file, "Memory allocation successful for offset values (%p), keys (%p), and records (%p).\n", offset_values, keys, records);
    fclose(log_file);

    // Free allocated memory upon successful completion
    free(offset_values);
    free(keys);
    free(records);

    return 0;
}

int main() {
    int max_capacity_offset = 100;
    int max_capacity_keys = 50;
    int max_capacity_records = 200;

    manage_memory(max_capacity_offset, max_capacity_keys, max_capacity_records);

    return 0;
}
