#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} record_t;

record_t* create_records(int size, int min_value, int max_value) {
    record_t* records = (record_t*)malloc(size * sizeof(record_t));
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

void free_records(record_t* records, int size) {
    free(records);
}

void sort_records(record_t* records, int size) {
    qsort(records, size, sizeof(record_t), record_compare);
}

int record_compare(const void* a, const void* b) {
    record_t* r1 = (record_t*)a;
    record_t* r2 = (record_t*)b;
    return r1->key - r2->key;
}

void log_operation() {
    printf("Operation completed.\n");
}

int main(int argc, char** argv) {
    int offset_size, key_size, record_count, min_value, max_value;

    if (argc != 6) {
        fprintf(stderr, "Usage: %s <offset_size> <key_size> <record_count> <min_value> <max_value>\n", argv[0]);
        return -1;
    }

    if (sscanf(argv[1], "%d", &offset_size) != 1 ||
        sscanf(argv[2], "%d", &key_size) != 1 ||
        sscanf(argv[3], "%d", &record_count) != 1 ||
        sscanf(argv[4], "%d", &min_value) != 1 ||
        sscanf(argv[5], "%d", &max_value) != 1) {
        fprintf(stderr, "Invalid input format.\n");
        return -1;
    }

    record_t* records = create_records(record_count, min_value, max_value);
    sort_records(records, record_count);
    free_records(records, record_count);

    log_operation();

    return 0;
}
