    int userId;
    char* sessionId;
    char* userAgent;
    char* ipAddress;
    int authenticated;
    int attempts[5]; // max 5 attempts
} Session;

Session* sessions = NULL;
int sessionCount = 0;
int sessionBufferIndex = 0;
int logLevel = 1; // 0: error, 1: warning, 2: info

void initSessions() {
    if (sessionCount > 0) return;
    sessions = (Session*)malloc(MAX_SESSIONS * sizeof(Session));
    if (!sessions) {
        printf("Error allocating memory for sessions.\n");
        exit(1);
    }
}

int getSessionIndex(const char* sessionId) {
    for (int i = 0; i < sessionCount; i++) {
        if (strcmp(sessions[i].sessionId, sessionId) == 0) return i;
    }
    return -1;
}

void logMessage(int level, const char* message) {
    switch (level) {
        case 0:
            printf("Error: %s\n", message);
            break;
        case 1:
            printf("Warning: %s\n", message);
            break;
        case 2:
            printf("Info: %s\n", message);
            break;
    }
}

void addSession(const char* sessionId, int userId, const char* userAgent, const char* ipAddress) {
    Session newSession;
    newSession.timestamp = time(NULL);
    newSession.userId = userId;
    newSession.sessionId = strdup(sessionId);
    newSession.userAgent = strdup(userAgent);
    newSession.ipAddress = strdup(ipAddress);
    newSession.authenticated = 0;
    for (int i = 0; i < 5; i++) {
        newSession.attempts[i] = 0;
    }
    if (sessionCount >= MAX_SESSIONS) {
        logMessage(0, "Maximum number of sessions reached.");
        return;
    }
    if (sessionBufferIndex >= SESSION_BUFFER_SIZE) {
        sessionBufferIndex = 0;
    }
    sessions[sessionCount++] = newSession;
}

void removeExpiredSessions() {
    for (int i = 0; i < sessionCount; i++) {
        if ((time(NULL) - sessions[i].timestamp) > 3600) { // 1 hour
            free(sessions[i].sessionId);
            free(sessions[i].userAgent);
            free(sessions[i].ipAddress);
            for (int j = i; j < sessionCount - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            sessionCount--;
        }
    }
}

