void* allocate_and_init_arrays(int max_capacity, int** keys_ptr, long** offsets_ptr) {
    int* keys = NULL;
    long* offsets = NULL;
    size_t capacity = 0;
    size_t current_size = 0;

    while (1) {
        if (current_size >= max_capacity) {
            break;
        }

        capacity *= 2;
        keys = realloc(keys, sizeof(int) * capacity);
        offsets = realloc(offsets, sizeof(long) * capacity);

        if (!keys || !offsets) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
    }

    for (int i = 0; i < max_capacity; i++) {
        keys[i] = rand() % 100;
        offsets[i] = (long)i;
    }

    *keys_ptr = keys;
    *offsets_ptr = offsets;

    return NULL;
}

void* allocate_and_init_records(int max_capacity, record** records_ptr) {
    record* records = NULL;
    size_t capacity = 0;
    size_t current_size = 0;

    while (1) {
        if (current_size >= max_capacity) {
            break;
        }

        capacity *= 2;
        records = realloc(records, sizeof(record) * capacity);

        if (!records) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
    }

    for (int i = 0; i < max_capacity; i++) {
