#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum size per block
#define MAX_SIZE 10000

// Define the memory alignment
#define ALIGNMENT 64

// Define the structure for an element
typedef struct {
    float value;
    char* str;
    int id;
} element;

// Define the structure for a data block
typedef struct {
    int size;
    element** elements;
    pthread_mutex_t lock;
} data_block;

// Function to create a new data block with initial capacity
data_block* create_data_block(int initial_capacity) {
    data_block* block = (data_block*)malloc(sizeof(data_block));
    block->size = 0;
    block->elements = (element**)calloc(initial_capacity, sizeof(element*));
    pthread_mutex_init(&block->lock, NULL);
    return block;
}

// Function to resize a data block
void resize_data_block(data_block* block, int new_size) {
    element** new_elements = (element**)realloc(block->elements, new_size * sizeof(element*));
    if (!new_elements) {
        printf("Memory allocation failed!\n");
        exit(-1);
    }
    block->size = new_size;
    block->elements = new_elements;
}

// Function to update an element in a data block
void update_element(data_block* block, int index, float value, const char* str, int id) {
    pthread_mutex_lock(&block->lock);
    if (index < block->size && block->elements[index]) {
        block->elements[index]->value = value;
        free(block->elements[index]->str);
        block->elements[index]->str = strdup(str);
        block->elements[index]->id = id;
    }
    pthread_mutex_unlock(&block->lock);
}

// Function to generate random float values
float* generate_random_floats(int count, int range) {
    float* floats = (float*)malloc(count * sizeof(float));
    for (int i = 0; i < count; i++) {
        floats[i] = ((float)rand() / RAND_MAX) * range;
    }
    return floats;
}

// Function to create a random element
element* generate_random_element(int id, const char* str, int size) {
    element* elem = (element*)malloc(sizeof(element));
    elem->value = *(generate_random_floats(size, 100.0f));
    elem->str = strdup(str);
    elem->id = id;
    return elem;
}

// Function to add an element to a data block
void add_element(data_block* block, int index, float value, const char* str, int id) {
    pthread_mutex_lock(&block->lock);
    if (index < block->size) {
        block->elements[index]->value = value;
        free(block->elements[index]->str);
        block->elements[index]->str = strdup(str);
        block->elements[index]->id = id;
    } else {
        if (block->size >= MAX_SIZE) {
            printf("Block full! Cannot add more elements.\n");
        } else {
            resize_data_block(block, block->size + 1);
            block->elements[block->size++]->value = value;
            block->elements[block->size-1]->str = strdup(str);
            block->elements[block->size-1]->id = id;
        }
    }
    pthread_mutex_unlock(&block->lock);
}

// Function to print the elements of a data block
void print_elements(data_block* block) {
    pthread_mutex_lock(&block->lock);
    for (int i = 0; i < block->size; i++) {
        printf("Index %d: Value %.2f, String %s, ID %d\n", i, block->elements[i]->value, block->elements[i]->str, block->elements[i]->id);
    }
    pthread_mutex_unlock(&block->lock);
}

int main() {
    // Create a new data block
    data_block* block = create_data_block(10);

    // Add some elements to the block
    add_element(block, 0, 1.5f, "Hello", 1);
    add_element(block, 1, 2.7f, "World", 2);
    add_element(block, 2, 3.4f, "Foo", 3);

    // Print the elements of the block
    print_elements(block);

    // Update an element in the block
    update_element(block, 0, 5.6f, "Bar", 1);

    // Print the updated block
    print_elements(block);

    return 0;
}
