#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 100000
#define MAX_MEMORY 500 // in kilobytes

typedef struct {
    int key;
    char status;
    double timestamp;
} Record;

Record* records = NULL;
int record_count = 0;
int max_records = 0;
long offset[MAX_RECORDS];
int keys[MAX_RECORDS];
double timestamps[MAX_RECORDS];

// Function to initialize the data structures
void init_data_structures() {
    if (records != NULL) return; // Data structures already initialized

    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed. Aborting.\n");
        exit(-1);
    }

    record_count = 0;
    max_records = MAX_RECORDS;

    for (int i = 0; i < MAX_RECORDS; i++) {
        offset[i] = i * sizeof(Record);
        keys[i] = -1; // Initialize all keys to -1
        timestamps[i] = 0.0; // Initialize all timestamps to 0.0
    }
}

// Function to insert a new record into the linked list
void insert_record(int key, char status, double timestamp) {
    if (record_count >= max_records) {
        printf("Memory limit exceeded. Aborting.\n");
        exit(-1);
    }

    Record* new_record = records + record_count;
    new_record->key = key;
    new_record->status = status;
    new_record->timestamp = timestamp;

    keys[record_count] = key; // Update the key array
    timestamps[record_count] = timestamp; // Update the timestamp array

    record_count++;
}

// Function to remove a record from the linked list
void remove_record(int key) {
    for (int i = 0; i < record_count; i++) {
        if (keys[i] == key) {
            // Shift records down after removal
            if (i + 1 < record_count) {
                memmove((void*)&records[i], (const void*)&records[i+1], sizeof(Record) * (record_count - i - 1));
            }

            record_count--;
            keys[i] = -1; // Reset the key array
            timestamps[i] = 0.0; // Reset the timestamp array

            return;
        }
    }
}

// Function to retrieve a record by its key and update its timestamp
Record* get_record(int key) {
    for (int i = 0; i < record_count; i++) {
