#define MAX_RECORDS 1000000
#define MAX_MEMORY_USAGE 1024 // in kilobytes

// record structure
typedef struct {
    int key;
    char status;
    double timestamp;
} Record;

// metadata structure
typedef struct {
    bool active;
    size_t usage_frequency;
} Metadata;

// linked list node structure
typedef struct Node {
    Record record;
    Metadata metadata;
    struct Node* next;
} Node;

Node* head = NULL; // initialize the linked list

int recordCount = 0; // count of records in the linked list

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && recordCount > 0) {
        // handle memory allocation failure
        printf("Memory allocation failed. Reducing memory usage.\n");
        freeRecords();
        return allocateMemory(size);
    }
    return ptr;
}

void freeRecords() {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    recordCount = 0;
}

void insertRecord(int key, char status, double timestamp) {
    Record record = {key, status, timestamp};
    Metadata metadata = {true, 1}; // initialize metadata with active flag and usage frequency

    Node* newNode = (Node*)allocateMemory(sizeof(Node));
    if (newNode == NULL) return; // handle memory allocation failure

    newNode->record = record;
    newNode->metadata = metadata;
    newNode->next = head;
    head = newNode;

    recordCount++;
}

void updateRecord(int key, char status, double timestamp) {
    Node* current = head;
    while (current != NULL) {
        if (current->record.key == key) {
            // found the record; update timestamp and metadata
            current->record.timestamp = timestamp;
            current->metadata.usage_frequency++;
            return;
        }
        current = current->next;
    }
}

void removeRecord(int key) {
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->record.key == key) {
            // found the record; remove it
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            recordCount--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

Record* getRecord(int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->record.key == key) {
            // found the record; update timestamp and metadata
            current->record.timestamp = time(NULL);
            current->metadata.usage_frequency++;
            return &current->record;
        }
        current = current->next;
    }
    return NULL; // not found
}

void printRecords() {
    Node* current = head;
    while (current != NULL) {
        printf("Key: %d, Status: %c, Timestamp: %f, Metadata: {active: %d, usage_frequency: %zu}\n",
               current->record.key, current->record.status, current->record.timestamp,
               current->metadata.active, current->metadata.usage_frequency);
        current = current->next;
    }
}

int main() {
    // initialize memory pool
    for (int i = 0; i < MAX_RECORDS; i++) {
        insertRecord(i, 'A', time(NULL));
    }

    printRecords();

    return 0;
}
