// Define the record structure
typedef struct {
    int key;
    time_t timestamp;
    char status;
} Record;

// Define the custom hash table structure
typedef struct {
    size_t capacity;
    size_t size;
    Record** records;
    pthread_mutex_t mutex;
} HashTable;

// Function to create a new hash table with the given initial size and maximum capacity
HashTable* init_hash_table(size_t initial_size, size_t max_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = initial_size;
    table->size = 0;
    table->records = (Record**)calloc(initial_size, sizeof(Record*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to insert a new record into the hash table
void insert_record(HashTable* table, Record* record) {
    pthread_mutex_lock(&table->mutex);
    size_t index = record->key % table->capacity;
    if (table->records[index] == NULL || strcmp(table->records[index]->status, record->status) != 0) {
        table->records[index] = record;
        table->size++;
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to delete a record from the hash table
void delete_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = key % table->capacity;
    if (table->records[index] != NULL && table->records[index]->key == key) {
        free(table->records[index]);
        table->records[index] = NULL;
        table->size--;
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to retrieve a record by its key
Record* lookup_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = key % table->capacity;
    Record* record = table->records[index];
    pthread_mutex_unlock(&table->mutex);
    return record;
}

// Function to update the timestamp of a record
void update_timestamp(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = key % table->capacity;
    if (table->records[index] != NULL && table->records[index]->key == key) {
        table->records[index]->timestamp = time(NULL);
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to mark a record as inactive
void deactivate_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = key % table->capacity;
    if (table->records[index] != NULL && table->records[index]->key == key) {
        table->records[index]->status = 'I';
    }
    pthread_mutex_unlock(&table->mutex);
}

// Function to bulk import records from a file or database
