#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_KEY_LENGTH 50
#define INITIAL_CAPACITY 16
#define GROWTH_FACTOR 2

typedef struct {
    char key[MAX_KEY_LENGTH];
    unsigned int timestamp;
    float value;
} data_entry;

void* malloc_checked(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return ptr;
}

data_entry** create_data_array(size_t capacity) {
    data_entry** array = (data_entry**)malloc_checked(sizeof(data_entry*) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        array[i] = NULL;
    }
    return array;
}

void resize_data_array(data_entry*** array, size_t new_capacity) {
    data_entry** temp = (data_entry**)malloc_checked(sizeof(data_entry*) * new_capacity);
    for (size_t i = 0; i < (*array)->capacity; ++i) {
        temp[i] = (*array)[i];
    }
    free(*array);
    *array = temp;
}

void delete_data_array(data_entry** array, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        if (array[i]) {
            free(array[i]);
        }
    }
    free(array);
}

data_entry* create_data_entry(const char* key, unsigned int timestamp, float value) {
    data_entry* entry = (data_entry*)malloc_checked(sizeof(data_entry));
    strcpy(entry->key, key);
    entry->timestamp = timestamp;
    entry->value = value;
    return entry;
}

void insert_data_entry(data_entry*** array, size_t capacity, const char* key, unsigned int timestamp, float value) {
    for (size_t i = 0; i < capacity; ++i) {
        if (!array[i]) {
            data_entry* entry = create_data_entry(key, timestamp, value);
            array[i] = entry;
            return;
        }
    }
    // resize the array if it's full
    size_t new_capacity = capacity * GROWTH_FACTOR;
    data_entry** temp_array = create_data_array(new_capacity);
    for (size_t i = 0; i < capacity; ++i) {
        if (array[i]) {
            temp_array[i] = array[i];
        }
    }
    free(*array);
    *array = temp_array;
    insert_data_entry(array, new_capacity, key, timestamp, value);
}

data_entry* find_data_entry(const data_entry** array, size_t capacity, const char* key) {
    for (size_t i = 0; i < capacity; ++i) {
        if (array[i] && strcmp(array[i]->key, key) == 0) {
            return array[i];
        }
    }
    return NULL;
}

int main() {
    // Initialize the data structure
    data_entry** array = create_data_array(INITIAL_CAPACITY);

    // Populate the data structure with randomly generated data
    for (size_t i = 0; i < 100; ++i) {
        const char* key = malloc_checked(strlen("key") + 1);
        strcpy(key, "key");
        unsigned int timestamp = time(NULL);
        float value = (float)i / 10.0;
        insert_data_entry(&array, INITIAL_CAPACITY, key, timestamp, value);
    }

    // Clean up all allocated resources
    delete_data_array(array, INITIAL_CAPACITY);

    return 0;
}
