    time_t timestamp;
    long* offset_ptr;
} Record;

// Function to dynamically allocate memory for and initialize multiple data structures
int allocate_memory(int num_records, int max_offset_values, int max_keys, size_t max_memory_limit) {
    // Initialize pointers to null
    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;

    // Dynamically allocate memory for offset array and validate allocation
    if ((offsets = (long*)malloc(max_offset_values * sizeof(long))) == NULL) {
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Dynamically allocate memory for key array and validate allocation
    if ((keys = (int*)malloc(max_keys * sizeof(int))) == NULL) {
        free(offsets);
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Dynamically allocate memory for record array and validate allocation
    if ((records = (Record*)malloc(num_records * sizeof(Record))) == NULL) {
        free(keys);
        free(offsets);
        return MEMORY_ALLOCATION_FAILURE;
    }

    // Initialize arrays with default values
    for (int i = 0; i < max_offset_values; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < max_keys; i++) {
        keys[i] = i;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100; // Set random value within range
        records[i].timestamp = time(NULL); // Initialize timestamp
        records[i].offset_ptr = &offsets[rand() % max_offset_values]; // Associate record with offset
    }

    // Check if total memory allocated exceeds the limit
    size_t total_memory_allocated = sizeof(long) * max_offset_values + sizeof(int) * max_keys + sizeof(Record) * num_records;
    if (total_memory_allocated > max_memory_limit) {
        // Free previously allocated memory and return error
        free(records);
        free(keys);
        free(offsets);
        return MEMORY_ALLOCATION_FAILURE;
    }

    return 0; // Success
}
