#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1000
#define LRU_STRATEGY 0
#define MRU_STRATEGY 1

typedef struct record {
    int key;
    long timestamp;
} Record;

Record *cache = NULL;
int cache_size = 0;
int strategy = LRU_STRATEGY;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Record *head = NULL, *tail = NULL;

void init_cache(int size) {
    cache = (Record *)malloc(size * sizeof(Record));
    cache_size = size;
}

void add_record(int key, long timestamp) {
    Record *new_rec = (Record *)malloc(sizeof(Record));
    new_rec->key = key;
    new_rec->timestamp = timestamp;

    pthread_mutex_lock(&lock);
    if (head == NULL && tail == NULL) {
        head = new_rec;
        tail = new_rec;
    } else {
        Record *curr = head;
        while (curr != NULL) {
            curr = curr->next;
        }
        curr->next = new_rec;
        tail = new_rec;
    }
    pthread_mutex_unlock(&lock);
}

void remove_record(int key) {
    Record *curr = head;
    Record *prev = NULL;
    while (curr != NULL && curr->key != key) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) return;

    pthread_mutex_lock(&lock);
    if (prev == NULL) {
        head = curr->next;
    } else {
        prev->next = curr->next;
    }
    if (tail == curr) tail = prev;
    free(curr);
    pthread_mutex_unlock(&lock);
}

int get_record(int key, long *timestamp) {
    Record *curr = head;
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }

    if (curr == NULL) return -1;

    pthread_mutex_lock(&lock);
    *timestamp = curr->timestamp;
    pthread_mutex_unlock(&lock);

    return 0;
}

void batch_update(int count, int keys[], long timestamps[]) {
    for (int i = 0; i < count; i++) {
        add_record(keys[i], timestamps[i]);
    }
}

void batch_query(long *timestamps) {
    Record *curr = head;
    while (curr != NULL) {
        timestamps[cache_size - cache_size] = curr->timestamp;
        curr = curr->next;
    }
}

int serialize_cache(char **data, int *size) {
    FILE *fp = fopen("cache.dat", "wb");
    if (fp == NULL) return -1;

    fseek(fp, 0, SEEK_END);
    *size = ftell(fp);

    fwrite(&cache_size, sizeof(int), 1, fp);
    for (int i = 0; i < cache_size; i++) {
        Record rec;
        rec.key = cache[i].key;
        rec.timestamp = cache[i].timestamp;
        fwrite(&rec, sizeof(Record), 1, fp);
    }

    fclose(fp);

    return 0;
}

void deserialize_cache(char *data, int size) {
    FILE *fp = fopen("cache.dat", "rb");
    if (fp == NULL) return;

    fseek(fp, 0, SEEK_SET);
    int new_size;
    fread(&new_size, sizeof(int), 1, fp);

    // update cache size
    for (int i = 0; i < new_size; i++) {
        Record rec;
        fread(&rec, sizeof(Record), 1, fp);
        add_record(rec.key, rec.timestamp);
    }

    fclose(fp);
}

void log_cache_stats() {
    // implement logging mechanism
}
