    // Implementation of custom memory pool goes here
    return malloc(size);
}

data_entry* init_entries(int count) {
    data_entry* entries = (data_entry*)my_malloc(count * sizeof(data_entry));
    if (!entries) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        // Initialize random data
        entries[i].timestamp = rand();
        entries[i].value = (float)rand() / RAND_MAX;
        char* key = (char*)malloc(MAX_KEY_LENGTH);
        sprintf(key, "Key_%d", i);
        strcpy(entries[i].key, key);
        free(key);
    }
    return entries;
}

void entry_destructor(void* ptr) {
    data_entry* entry = (data_entry*)ptr;
    // Free any dynamically allocated memory within the entry
    free(entry->key);
}

// Synchronization mechanism for concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    int count = 1000; // Number of entries to initialize
    data_entry* entries = init_entries(count);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, process_data, &entries);
    }
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory
    free(entries);

    return 0;
}

void process_data(void* ptr) {
    data_entry* entries = (data_entry*)ptr;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < count; i++) {
        // Process the entry here
        printf("%s: %u - %.2f\n", entries[i].key, entries[i].timestamp, entries[i].value);
    }
    pthread_mutex_unlock(&mutex);

    // Free any dynamically allocated memory within the entry
    entry_destructor(ptr);
}
