#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct log_message {
    char buffer[64];
    int priority;
} log_message;

typedef struct entry {
    char buffer[16];
    time_t timestamp;
    log_message* messages;
    int message_count;
} entry;

entry* create_entry() {
    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) return NULL;  // allocation failed
    strcpy(new_entry->buffer, rand_str(16));
    new_entry->timestamp = time(NULL);
    new_entry->messages = NULL;
    new_entry->message_count = 0;
    return new_entry;
}

log_message* create_log_message() {
    log_message* new_msg = (log_message*)malloc(sizeof(log_message));
    if (!new_msg) return NULL;  // allocation failed
    strcpy(new_msg->buffer, rand_str(64));
    new_msg->priority = rand() % 10 + 1;
    return new_msg;
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    entry* entries = (entry*)malloc(sizeof(entry) * 16);
    if (!entries) {
        printf("Memory allocation failed\n");
        return -1;  // or some appropriate error code
    }

    for (int i = 0; i < 16; i++) {
        entries[i] = *create_entry();
    }

    // Insert log messages into linked list and sort by priority
    for (int i = 0; i < 16; i++) {
        entry* e = &entries[i];
        while (1) {
            log_message* msg = *create_log_message();
            if (!e->messages) {
                e->messages = msg;
                break;
            }
            // Sort the linked list based on priority
            log_message* temp = e->messages;
            log_message* prev = NULL;
            while (temp && temp->priority < msg->priority) {
                prev = temp;
                temp = temp->next;
            }
            if (prev) {
                msg->next = prev->next;
                prev->next = msg;
            } else {
                e->messages = msg;
            }
        }
    }

    // Free allocated memory
    for (int i = 0; i < 16; i++) {
        free(entries[i].messages);
        free(&entries[i]);
    }
    free(entries);

    return 0;
}

char* rand_str(int length) {
    char* str = (char*)malloc((length + 1)*sizeof(char));
    if (!str) return NULL;  // allocation failed
    for (int i = 0; i < length; i++) {
        str[i] = (char)(rand() % 26 + 'a');
    }
    str[length] = '\0';
    return str;
}
