```javascript
const { LRUCache } = require('lru-cache');
const redis = require('redis');

class PersistentCache {
  constructor(options) {
    this.options = options;
    this.cache = new LRUCache({
      max: options.maxEntries,
      ttl: options.ttl,
      disableGc: true
    });
    this.redisClient = redis.createClient({
      host: options.host,
      port: options.port,
      password: options.password
    });
  }

  async get(key) {
    const cacheHit = this.cache.get(key);
    if (cacheHit) return cacheHit;

    try {
      const value = await this.redisClient.getAsync(key);
      if (value) {
        this.cache.set(key, value);
        return value;
      }
    } catch (err) {
      console.error(err);
    }

    return null;
  }

  async set(key, value, expirationTime) {
    try {
      this.cache.set(key, value);

      await this.redisClient.setAsync(key, value, 'EX', expirationTime);
    } catch (err) {
      console.error(err);
    }
  }

  async delete(key) {
    try {
      this.cache.delete(key);
      await this.redisClient.delAsync(key);
    } catch (err) {
      console.error(err);
    }
  }

  async batchSet(keys, values, expirationTime) {
    const promises = keys.map((key) => this.set(key, values[keys.indexOf(key)], expirationTime));
    return Promise.all(promises);
  }

  async batchGet(keys) {
    const promises = keys.map((key) => this.get(key));
    return Promise.all(promises);
  }
}

module.exports = PersistentCache;
