    struct Node* predecessor;
    struct Node* successor;
    Record record;
} Node;

void initArrays(Node** nodes, long** offsets, int** keys, int size) {
    *nodes = (Node*)malloc(size * sizeof(Node));
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i % 100 + 1;
    }
}

void randomizeRecords(Node* nodes, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        nodes[i].record.record = rand() % 1000;
    }
}

void printArrays(long* offsets, int* keys, Node* nodes, int size) {
    for (int i = 0; i < size; i++) {
        printf("Offset: %ld, Key: %d, Record: %d\n", offsets[i], keys[i], nodes[i].record.record);
    }
}

void freeArrays(long** offsets, int** keys, Node** nodes, int size) {
    free(*offsets);
    free(*keys);
    for (int i = 0; i < size; i++) {
        free((void*)&nodes[i]);
    }
    free(*nodes);
