#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 1000
#define MAX_STRING_LENGTH 256
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct node {
    struct node* predecessor;
    struct node* successor;
    double value;
    struct entry entry;
} node;

typedef struct entry {
    char string[MAX_STRING_LENGTH];
    int counter;
} entry;

node* nodes = NULL;
int num_nodes = 0;

// Thread-safe function to initialize and allocate memory for the linked list
void init_linked_list() {
    srand(time(NULL));

    if (nodes != NULL) {
        // Free existing nodes to prevent memory leaks
        node* temp = nodes;
        while (temp != NULL) {
            node* next = temp->successor;
            free(temp);
            temp = next;
        }
        num_nodes = 0;
    }

    nodes = (node*) malloc(sizeof(node));
    if (nodes == NULL || (nodes->predecessor = (node*) malloc(sizeof(node))) == NULL || (nodes->successor = (node*) malloc(sizeof(node))) == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return;
    }

    nodes->value = 0.5; // Initialize value for the first node
    strcpy(nodes->entry.string, "Initial string"); 
    nodes->entry.counter = rand() % (MEMORY_LIMIT / sizeof(node)); 

    num_nodes = 1;

    for (int i = 1; i < MAX_NODES; i++) {
        node* new_node = (node*) malloc(sizeof(node));
        if (new_node == NULL) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return;
        }

        new_node->predecessor = nodes;
        new_node->successor = nodes->successor;

        nodes->successor = new_node;

        nodes = new_node;

        new_node->value = 0.5; // Initialize value for the new node
        strcpy(new_node->entry.string, "Random string"); 
        new_node->entry.counter = rand() % (MEMORY_LIMIT / sizeof(node)); 

        num_nodes++;
    }
}

// Helper function to find and print the longest string in an array of strings
void find_longest_string(char** strings, int size) {
    char* longest = NULL;
    int max_length = 0;

    for (int i = 0; i < size; i++) {
        if (strlen(strings[i]) > max_length) {
            longest = strings[i];
            max_length = strlen(longest);
        }
    }

    printf("Longest string: %s\n", longest);
}

// Thread-safe function to update the value of a node based on its index and string content
void update_node(int index, char* string) {
    if (index < 0 || index >= num_nodes) {
        // Handle out-of-bounds error
        printf("Invalid node index.\n");
        return;
    }

    node* target = nodes;

    for (int i = 0; i < index; i++) {
        target = target->successor;
    }

    strcpy(target->entry.string, string);
    target->entry.counter = rand() % (MEMORY_LIMIT / sizeof(node));
}

// Thread-safe function to read a list of strings from standard input and store them in an array
void read_input(char*** input_strings) {
    int size = 0;

    char* line = NULL;
    size_t length = 0;
    ssize_t read = 0;

    while ((read = getline(&line, &length, stdin)) != -1) {
        (*input_strings) = (char**) realloc(*input_strings, (size + 1) * sizeof(char*));
        (*input_strings)[size] = line;
        size++;

        free(line);
        line = NULL;
        length = 0;
    }

    if (line != NULL) {
        free(line);
    }

    (*input_strings) = (char**) realloc(*input_strings, (size + 1) * sizeof(char*));
    (*input_strings)[size] = NULL;

    printf("Input strings read: %d\n", size);
}

int main() {
    char** input_strings = NULL;
    int num_input_strings = 0;

    read_input(&input_strings);

    find_longest_string(input_strings, num_input_strings);

    return 0;
}
