#include <time.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

record* init_records(int num_records) {
    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;
    size_t key_array_size;

    // Calculate the size of the 'keys' array, 15% larger than 'num_records'
    key_array_size = (size_t)(1.15 * num_records);

    // Dynamically allocate memory for the 'offsets' and 'keys' arrays
    offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        return NULL;
    }

    keys = (int*)malloc(key_array_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize the 'keys' array
    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = i;  // Initialize with unique values
    }

    // Allocate memory for the 'records' array
    records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the 'records' array
    for (size_t i = 0; i < num_records; ++i) {
        record* record_ptr = &records[i];
        record_ptr->offset = offsets[i];
        record_ptr->key = keys[i];
        record_ptr->timestamp = time(NULL);  // Initialize with current timestamp
    }

    // Free the temporary arrays
    free(offsets);
    offsets = NULL;
    free(keys);
    keys = NULL;

    return records;
}
