typedef struct {
    char* command;
    pid_t pid;
    double priority;
} Task;

typedef struct {
    Task* tasks;
    int capacity;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} TaskList;

TaskList* task_list_init(int initial_capacity) {
    TaskList* list = (TaskList*) malloc(sizeof(TaskList));
    list->tasks = (Task*) malloc(initial_capacity * sizeof(Task));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void task_list_add(TaskList* list, Task task) {
    if (list->size >= list->capacity) {
        // Resize the list
        list->tasks = (Task*) realloc(list->tasks, 2 * list->capacity * sizeof(Task));
        list->capacity *= 2;
    }
    list->tasks[list->size] = task;
    list->size++;
}

void task_list_remove(TaskList* list) {
    if (list->size > 0) {
        free(list->tasks[--list->size]);
    }
}

int task_list_update(TaskList* list, Task task) {
    for (int i = 0; i < list->size; i++) {
        if (task.command == list->tasks[i].command) {
            // Update the existing task
            list->tasks[i] = task;
            return 1; // Updated successfully
        }
    }
    return 0; // Task not found
}

void* thread_function(void* arg) {
    TaskList* list = (TaskList*) arg;
    // Monitor system resource usage and adjust concurrency level accordingly
    while (1) {
