void init_nodes(Node** head, Node** tail, long* offsets, int* keys, char*** strings, int count) {
    for (int i = 0; i < count; i++) {
        Node* node = (Node*) malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed!\n");
            exit(1);
        }
        node->key = keys[i];
        node->offset = offsets[i];
        int str_len = rand() % 50 + 1;
        char* str = (char*) malloc((str_len + 1) * sizeof(char));
        if (!str) {
            printf("Memory allocation failed!\n");
            exit(1);
        }
        for (int j = 0; j < str_len; j++) {
            str[j] = 'A' + rand() % 26;
        }
        str[str_len] = '\0';
        node->string = str;
        if (!(*head)) {
            *head = node;
            *tail = node;
        } else {
            node->prev = (*tail);
            (*tail)->next = node;
            *tail = node;
        }
    }
}

