#include <string.h>

typedef struct {
    float value;
    char status;
    double *data;
    void *log;
} Entry;

typedef struct {
    Entry *entry;
    struct Node *next;
} CircularQueue;

void *malloc_and_init(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

CircularQueue *queue_new() {
    CircularQueue *q = malloc_and_init(sizeof(CircularQueue));
    q->entry = NULL;
    q->next = q;
    return q;
}

void queue_insert(CircularQueue *q, Entry *new_entry) {
    new_entry->next = q->entry;
    q->entry = new_entry;
    CircularQueue *prev = q;
    while (prev->next != q) prev = prev->next;
    prev->next = new_entry;
}

Entry *new_entry() {
    Entry *entry = malloc_and_init(sizeof(Entry));
    entry->data = malloc_and_init(sizeof(double));
    return entry;
}

double compute_average(float values[], int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) sum += values[i];
    return sum / count;
}

void print_queue(CircularQueue *q) {
    CircularQueue *current = q;
    do {
        Entry *entry = current->entry;
        printf("Entry: %.2f, %c, %p, %p\n", entry->value, entry->status, entry->data, entry->log);
        current = current->next;
    } while (current != q);
}

int main() {
    int num_entries;
    scanf("%d", &num_entries);

    CircularQueue *queue = queue_new();

    float values[num_entries];
    for (int i = 0; i < num_entries; i++) {
        scanf("%f", &values[i]);
    }

    double avg = compute_average(values, num_entries);
    printf("Average: %.2lf\n", avg);

    // Insert entries into queue
    for (int i = 0; i < num_entries; i++) {
        Entry *entry = new_entry();
        entry->value = values[i];
        queue_insert(queue, entry);
    }

    print_queue(queue);

    return 0;
}
