        records[i].key = rand() % INT_MAX;
        records[i].offset = (long)rand();
    }
    return records;
}

void* read_input(void*) {
    int num_inputs;
    scanf("%d", &num_inputs);
    int* inputs = (int*)malloc(num_inputs * sizeof(int));
    for (int i = 0; i < num_inputs; i++) {
        scanf("%d", &inputs[i]);
    }
    return (void*)inputs;
}

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

struct entry {
    char* key;
    void* value;
};

struct hash_table {
    int size;
    struct entry** table;
    pthread_mutex_t mutex;
};

void initialize_hash_table(struct hash_table* table, int size) {
    table->size = size;
    table->table = (struct entry**)malloc(size * sizeof(struct entry*));
    for (int i = 0; i < size; i++) {
        table->table[i] = NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
}

void serialize_hash_table(struct hash_table* table, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return;
    }
    fwrite(table->size, sizeof(int), 1, file);
    for (int i = 0; i < table->size; i++) {
        struct entry* entry = table->table[i];
        if (entry && entry->value) {
            int type = ((struct custom*)entry->value)->type;
            fwrite(&type, sizeof(int), 1, file);
            switch (type) {
                case 0:
                    fwrite(entry->key, strlen(entry->key) + 1, 1, file);
                    fwrite(((int*)entry->value), sizeof(int), 1, file);
                    break;
                case 1:
                    fwrite(entry->key, strlen(entry->key) + 1, 1, file);
                    fwrite(((char*)entry->value), strlen((char*)entry->value) + 1, 1, file);
                    break;
            }
        }
    }
    fclose(file);
}

void deserialize_hash_table(struct hash_table* table, char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return;
    }
    int size;
    fread(&size, sizeof(int), 1, file);
    initialize_hash_table(table, size);
    for (int i = 0; i < table->size; i++) {
        struct entry* entry = NULL;
        int type;
        fread(&type, sizeof(int), 1, file);
        if (type) {
            char* key = malloc(strlen(" ") + 1);
            fread(key, strlen(key) + 1, 1, file);
            void* value = malloc(type == 0 ? sizeof(int) : strlen(key));
            switch (type) {
                case 0:
                    fread(value, sizeof(int), 1, file);
                    break;
                case 1:
                    fread(value, strlen((char*)value) + 1, 1, file);
                    break;
            }
            entry = malloc(sizeof(struct entry));
            entry->key = key;
            entry->value = value;
        }
        table->table[i] = entry;
    }
    fclose(file);
}

void update_value(void* database, char* key, void* value) {
    pthread_mutex_lock(&((struct hash_table*)database)->mutex);
    struct entry* entry = find_entry(database, key);
    if (entry && entry->value) {
        free(entry->value);
    }
    entry->value = value;
    pthread_mutex_unlock(&((struct hash_table*)database)->mutex);
}

int main() {
    // Create records
    int num_records;
    scanf("%d", &num_records);
    record* records = create_records(num_records);

    // Read input
    void* inputs = read_input(NULL);
    int size = *(int*)inputs;

    // Find largest integer in the array
    int largest = find_largest((int*)inputs, size);

    // Initialize hash table
    struct hash_table database;
    initialize_hash_table(&database, MAX_DB_ENTRIES);

    // Serialize and deserialize database
    char filename[20];
    sprintf(filename, "config.json");
    serialize_hash_table(&database, filename);
    deserialize_hash_table(&database, filename);

    return 0;
}
