#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_MESSAGES 1000
#define MAX_MESSAGE_SIZE 1024
#define MESSAGE_STATUS_PENDING 1
#define MESSAGE_STATUS_DELIVERED 2

typedef struct {
    char* body;
    int sender_id;
    int status;
    time_t delivery_timestamp;
} message;

message* messages;
int num_messages = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* generate_random_string(void* arg) {
    const int length = rand() % MAX_MESSAGE_SIZE + 1;
    char* body = (char*)malloc(length);
    if(body == NULL) {
        return NULL; // Handle allocation failure
    }
    for(int i=0; i<length; i++) {
        body[i] = 'a' + rand() % 26;
    }
    body[length-1] = '\0';
    return (void*)body;
}

int create_message_array(int max_messages) {
    if(max_messages > MAX_MESSAGES) {
        // Handle error: maximum number of messages exceeded
        return -1;
    }

    if(num_messages != 0) {
        for(int i=0; i<num_messages; i++) {
            free(messages[i].body);
        }
        free(messages);
    }

    num_messages = max_messages;
    messages = (message*)malloc(num_messages * sizeof(message));
    return 0;
}

int add_message(int sender_id, int message_status) {
    if(num_messages >= MAX_MESSAGES) {
        // Handle error: maximum number of messages reached
        return -1;
    }

    pthread_mutex_lock(&lock);

    message* new_message = (message*)malloc(sizeof(message));
    new_message->body = generate_random_string(NULL);
    new_message->sender_id = sender_id;
    new_message->status = message_status;
    new_message->delivery_timestamp = time(NULL);

    messages[num_messages] = *new_message;
    num_messages++;

    pthread_mutex_unlock(&lock);

    return 0;
}

int mark_delivered(int message_index) {
    if(message_index >= num_messages) {
        // Handle error: invalid message index
        return -1;
    }

    pthread_mutex_lock(&lock);

    messages[message_index].status = MESSAGE_STATUS_DELIVERED;

    pthread_mutex_unlock(&lock);

    return 0;
}

int cleanup_inactive_messages(int timeout_seconds) {
    time_t current_time = time(NULL);
    int i, j=0;

    pthread_mutex_lock(&lock);

    for(i=0; i<num_messages; i++) {
        if(messages[i].status == MESSAGE_STATUS_DELIVERED && (current_time - messages[i].delivery_timestamp > timeout_seconds)) {
            free(messages[i].body);
            // Shift remaining messages to maintain index continuity
            memmove(&messages[j], &messages[i+1], (num_messages-i-1)*sizeof(message));
            num_messages--;
            i--; // Re-check the current index
        } else {
            j++;
        }
    }

    pthread_mutex_unlock(&lock);

    return 0;
}

void* thread_operation(void* arg) {
    int sender_id = *(int*)arg;
    for(int i=0; i<10; i++) { // Simulate multiple message operations
        add_message(sender_id, MESSAGE_STATUS_PENDING);
        mark_delivered(i % num_messages); // Mark a random message as delivered
        cleanup_inactive_messages(60); // Cleanup messages older than 1 minute
    }
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_THREADS];
    int client_ids[] = {0, 1, 2}; // Simulate multiple clients

    for(int i=0; i<sizeof(client_ids)/sizeof(client_ids[0]); i++) {
        pthread_create(&threads[i], NULL, thread_operation, &client_ids[i]);
    }

    for(int i=0; i<sizeof(threads)/sizeof(threads[0]); i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

