    tasks[idx].status = new_status;
    tasks[idx].deadline = new_deadline;
    pthread_mutex_unlock(&lock);
}

int compare_tasks(const void* a, const void* b) {
    task* ta = *(task**)a;
    task* tb = *(task**)b;
    if (ta->deadline < tb->deadline) return -1;
    else if (ta->deadline > tb->deadline) return 1;
    else return ta->priority - tb->priority;
}

void schedule_tasks() {
    int i, j;
    task* temp;

    pthread_mutex_lock(&lock);
    qsort(tasks, num_tasks, sizeof(task), compare_tasks);

    for (i = 0; i < num_tasks; i++) {
        printf("Task %d: Priority %d, Status %c, Deadline %ld\n", i + 1, tasks[i].priority, tasks[i].status, tasks[i].deadline);
        // Update task status and deadline here
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    FILE* file = fopen("config.txt", "r");
    if (file == NULL) {
        printf("Error opening configuration file.\n");
        return 1;
    }

    fscanf(file, "%d %d", &max_tasks, &budget);

    init_tasks(max_tasks, budget);

    // Read tasks from input
    task* t = create_task(priority, status, deadline);
    tasks[num_tasks++] = t;

    // Process and print the earliest task to be completed
    schedule_tasks();

    return 0;
}
