record_manager* create_record_manager(int num_records) {
    record_manager* manager = (record_manager*)malloc(sizeof(record_manager));
    if (!manager) return NULL;

    manager->offset = 0;
    for (int i = 0; i < 3; i++) {
        manager->keys[i] = -1;
    }

    manager->records = (struct record*)calloc(num_records, sizeof(struct record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void update_record(record_manager* manager, int key, int value) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < 3; i++) {
        if (manager->keys[i] == key) {
            manager->records[manager->keys[i]].value = value;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

void print_largest_integer(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) max = arr[i];
    }
    printf("%d\n", max);
}

