    // Allocate memory for keys (int type)
    int** keys = (int**)malloc(1 * sizeof(int*));
    *keys = (int*)malloc(1000000 * sizeof(int));

    // Allocate memory for record instances
    Record** records = (Record**)malloc(1000000 * sizeof(Record));
    for (int i = 0; i < 1000000; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
    }

    // Initialize and allocate memory for tracking maximum size of records
    RecordStats* stats = (RecordStats*)malloc(sizeof(RecordStats));
    pthread_mutex_init(&stats->lock, NULL);

    return stats;
}

// Function to read input integers from standard input and store them in an array
void read_input(int** keys, int* size) {
