    int max_val = 0;
    for (int i = 0; i < *size; i++) {
        if (keys[0][i] > max_val)
            max_val = keys[0][i];
    }
    printf("Largest integer: %d\n", max_val);
}

// Function to manage and print performance metrics
void log_metrics(RecordStats* stats) {
    pthread_mutex_lock(&stats->lock);
    printf("Maximum size of records: %d bytes\n", stats->max_size);
    pthread_mutex_unlock(&stats->lock);
}

