#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define RECORDS_PER_BLOCK 10
#define MAX_RECORDS 1000
#define MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int value;
} record;

record* initialize_and_manage_records(size_t min_value, size_t max_value) {
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;
    size_t total_used_bytes = 0;
    size_t peak_used_bytes = 0;
    int allocation_count = 0;

    size_t memory_limit = MEMORY_LIMIT;
    size_t current_memory_usage = 0;

    while (1) {
        // Allocate block of records
        record* new_records = realloc(records, sizeof(record) * RECORDS_PER_BLOCK);
        if (!new_records) {
            // Re-allocation failed, free previously allocated memory and exit
            for (int i = 0; i < allocation_count; i++) {
                free(new_records - i * RECORDS_PER_BLOCK);
            }
            free(new_records);
            return NULL;
        }

        records = new_records;

        // Initialize and randomize the values of newly allocated records
        for (size_t i = 0; i < RECORDS_PER_BLOCK; i++) {
            record* current_record = &records[i];
            current_record->value = rand() % ((max_value - min_value) + 1) + min_value;
        }

        total_used_bytes += sizeof(record) * RECORDS_PER_BLOCK;
        if (total_used_bytes > peak_used_bytes)
            peak_used_bytes = total_used_bytes;

        // Update memory usage statistics
        current_memory_usage += total_used_bytes;
        if (current_memory_usage >= (memory_limit * 0.8)) {
            // Memory pressure, re-allocate and prune records as needed
            for (int i = 0; i < allocation_count; i++) {
                free(records - i * RECORDS_PER_BLOCK);
            }
            free(records);
            memory_limit /= 2;
        } else if (current_memory_usage > peak_used_bytes) {
            // Update the maximum used bytes
            peak_used_bytes = current_memory_usage;
        }

        // Re-allocation and record initialization loop continues until desired number of records is reached
        if (allocation_count >= MAX_RECORDS)
            break;

        allocation_count++;
    }

    return records;
}

// Function to retrieve memory usage statistics
int get_memory_usage(record* records, size_t* total_used_bytes, size_t* peak_used_bytes, int* allocation_count) {
    *total_used_bytes = sizeof(record) * RECORDS_PER_BLOCK * (MAX_RECORDS / RECORDS_PER_BLOCK);
    *peak_used_bytes = *total_used_bytes;
    *allocation_count = MAX_RECORDS;

    return 0;
}
