import java.io.*;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;

public class EventManager {
    private static final int EVENT_BUFFER_SIZE = 1000;
    private static final int MAX_EVENTS_PER_FILE = 10000;

    private Path fileSystemPath;
    private FileOutputStream fileOutputStream;
    private DataOutputStream dataOutputStream;
    private Logger logger;

    private Map<String, Event> eventsMap;
    private List<Event> eventList;
    private boolean isInitializing = true;

    public EventManager(String fileSystemRoot) {
        fileSystemPath = Paths.get(fileSystemRoot);
        eventsMap = new HashMap<>();
        eventList = new ArrayList<>();

        init();
    }

    private void init() {
        try {
            File file = fileSystemPath.resolve("events").toFile();
            if (!file.exists()) {
                file.mkdir();
            }

            fileOutputStream = new FileOutputStream(fileSystemPath.resolve("events.dat"), true);
            dataOutputStream = new DataOutputStream(new BufferedOutputStream(fileOutputStream));

            logger = Logger.getLogger(EventManager.class.getName());
        } catch (IOException e) {
            logger.severe("Error initializing event manager: " + e.getMessage());
        }
    }

    public void addEvent(Event event) {
        if (!isInitializing && eventList.size() >= EVENT_BUFFER_SIZE) {
            flushEvents();
        }

        eventsMap.put(event.getEventId(), event);
        eventList.add(event);

        if (eventList.size() % MAX_EVENTS_PER_FILE == 0) {
            saveEvents();
        }
    }

    private void flushEvents() {
        try {
            for (Event event : eventList) {
                dataOutputStream.writeUTF(event.getEventType());
                dataOutputStream.writeLong(event.getTimestamp());
                DataInputStream metadataStream = new DataInputStream(new ByteArrayInputStream(event.getMetadata()));
                int metadataLength = metadataStream.readInt();
                for (int i = 0; i < metadataLength; i++) {
                    dataOutputStream.writeUTF(metadataStream.readUTF());
                }
            }

            eventList.clear();
        } catch (IOException e) {
            logger.severe("Error flushing events: " + e.getMessage());
        }
    }

    private void saveEvents() {
        try {
            fileOutputStream.flush();

            Path filePath = fileSystemPath.resolve(eventList.size() / MAX_EVENTS_PER_FILE + ".dat");
            File eventFile = filePath.toFile();
            eventFile.createNewFile();

            dataOutputStream.close();
            fileOutputStream.close();

            fileOutputStream = new FileOutputStream(filePath, true);
            dataOutputStream = new DataOutputStream(new BufferedOutputStream(fileOutputStream));

            logger.info("Events saved to file: " + filePath);
        } catch (IOException e) {
            logger.severe("Error saving events: " + e.getMessage());
        }
    }

    public void close() {
        try {
            flushEvents();
            dataOutputStream.close();
            fileOutputStream.close();

            isInitializing = false;
        } catch (IOException e) {
            logger.severe("Error closing event manager: " + e.getMessage());
        }
    }
}

class Event implements Serializable {
    private String eventId;
    private long timestamp;
    private byte[] metadata;

    public Event(String eventType, long timestamp, byte[] metadata) {
        this.eventId = UUID.randomUUID().toString();
        this.timestamp = timestamp;
        this.metadata = metadata;
    }

    public String getEventId() {
        return eventId;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public byte[] getMetadata() {
        return metadata;
    }
}

class Logger {
    private static final Logger LOGGER = Logger.getLogger(EventManager.class.getName());

    public void severe(String message) {
        LOGGER.severe(message);
    }

    public void info(String message) {
        LOGGER.info(message);
    }
}
