void insert_node(Node** head, Node* new_node, int pos) {
    if (!(*head)) *head = new_node;
    else {
        Node* prev = NULL;
        Node* curr = *head;
        for (int i = 0; i < pos && curr; i++) {
            prev = curr;
            curr = curr->next;
        }
        if (curr) {
            new_node->next = curr;
            prev ? prev->next = new_node : (*head) = new_node;
        } else {
            printf("Invalid position for insertion.\n");
            return;
        }
    }
}

