// Define structure for record
typedef struct {
    float f;
    char *s;
} Record;

// Define hash table structure
typedef struct {
    int size;
    int capacity;
    Record **table;
} HashTable;

// Initialize hash table with initial capacity and load factor
void initHashTable(HashTable *ht, int capacity) {
    ht->size = 0;
    ht->capacity = capacity;
    ht->table = (Record **)malloc(capacity * sizeof(Record *));
}

// Insert record into hash table with given key
void insertRecord(HashTable *ht, char *key, Record *record) {
    // Hash function implementation
    int index = hash(key) % ht->capacity;
    Record **slot = &ht->table[index];

    if (*slot == NULL || strcmp(key, (*slot)->s) != 0) {
        // Rehashing or new key, update slot and increment size
        *slot = record;
        ht->size++;

        // Dynamic resizing mechanism
        if (ht->size >= ht->capacity / 2) {
            int newCapacity = ht->capacity * 2;
            Record **newTable = (Record **)realloc(ht->table, newCapacity * sizeof(Record *));
            ht->table = newTable;
            ht->capacity = newCapacity;
        }
    }
}

// Hash function implementation
int hash(char *key) {
    int result = 0;
    for (int i = 0; key[i]; i++) {
        result = (result * 31 + key[i]) % ht->capacity;
    }
    return result;
}

// Serialize database to JSON or binary format with optional compression
