#define MAX_RESOURCE_POINTERS 2500
#define MAX_METADATA_STRINGS 4000

typedef struct {
    int timestamp;
    char status;
    int priority;
    char location[20];
    char metadata1[20], metadata2[20];
} Event;

void largest_integer(int* ints, int size) {
    int max = ints[0];
    for (int i = 1; i < size; i++) {
        if (ints[i] > max)
            max = ints[i];
    }
    printf("Largest integer: %d\n", max);
}

void file_info(char** file_paths, struct stat* sb, int size) {
    for (int i = 0; i < size; i++) {
        printf("%s - Modified: %ld, Size: %lu\n",
               file_paths[i], sb[i].st_mtime, sb[i].st_size);
    }
}

void* allocate(int size) {
    return malloc(size);
}

void deallocate(void* ptr) {
    free(ptr);
}

int main() {
    int ints[MAX_INTS];
    char** file_paths = (char**)malloc(MAX_FILE_PATHS * sizeof(char*));
    for (int i = 0; i < MAX_FILE_PATHS; i++)
        file_paths[i] = malloc(100);

    Event* events = (Event*)allocate(sizeof(Event) * MAX_EVENT_STRUCTURES);
    double* doubles = (double*)allocate(sizeof(double) * MAX_DOUBLE_PRECISION);
    char* chars = (char*)allocate(sizeof(char) * MAX_CHAR_IDENTIFIERS);

    FILE* input_file = stdin;
    int num_ints, num_file_paths;
    fscanf(input_file, "%d %d", &num_ints, &num_file_paths);

    for (int i = 0; i < num_ints; i++)
        fscanf(input_file, "%d", &ints[i]);

    largest_integer(ints, num_ints);

    for (int i = 0; i < num_file_paths; i++) {
        fscanf(input_file, "%s", file_paths[i]);
    }

    struct stat sb[MAX_FILE_PATHS];
    for (int i = 0; i < num_file_paths; i++) {
        int fd = open(file_paths[i], O_RDONLY);
        fstat(fd, &sb[i]);
        close(fd);
    }

    file_info(file_paths, sb, num_file_paths);

    deallocate(events);
    deallocate(doubles);
    deallocate(chars);
    for (int i = 0; i < num_file_paths; i++)
        deallocate(file_paths[i]);

    return 0;
}

