#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
} Record;

void manageMemory(int numOffsets, int numKeys) {
    // Initialize OffsetArray with a given number of elements
    OffsetArray* offsets = (OffsetArray*)malloc(numOffsets * sizeof(OffsetArray));
    if (!offsets) {
        // Handle memory allocation failure dynamically resizing
        while (!offsets) {
            numOffsets *= 2;
            offsets = (OffsetArray*)realloc(NULL, numOffsets * sizeof(OffsetArray));
        }
    }
    for (int i = 0; i < numOffsets; i++) {
        offsets[i].initialized = false;
    }

    // Initialize KeyArray with a given number of elements
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int* keys = (int*)malloc(numKeys * sizeof(int));
    if (!keys) {
        // Handle memory allocation failure dynamically resizing
        while (!keys) {
            numKeys *= 2;
            keys = (int*)realloc(NULL, numKeys * sizeof(int));
        }
    }
    for (int i = 0; i < numKeys; i++) {
        pthread_mutex_lock(&mutex);
        keys[i] = i + 1;
        pthread_mutex_unlock(&mutex);
    }

    // Initialize RecordArray with a given number of elements
    Record* records = (Record*)malloc(numOffsets * sizeof(Record));
    if (!records) {
        // Handle memory allocation failure dynamically resizing
        while (!records) {
            numOffsets *= 2;
            records = (Record*)realloc(NULL, numOffsets * sizeof(Record));
        }
    }
    for (int i = 0; i < numOffsets; i++) {
        srand(time(NULL));  // Ensure uniform randomization
        records[i].offset = rand() % 10000 + 1;
        records[i].key = keys[i];
    }
}
