    // allocate memory for records and offsets
    Record* records = (Record*)malloc(n * sizeof(Record));
    long* offsets = (long*)malloc((n + 1) * sizeof(long)); // extra offset for the last record

    if (!records || !offsets) {
        return NULL; // allocation failed
    }

    // initialize default offsets
    for (int i = 0; i <= n; i++) {
        offsets[i] = rand() % ((max - min) + 1) + min;
