#include <stdio.h>
#include <stdlib.h>
#include <time.h>

struct Record {
    long offset;
    int key;
};

void manageMemory(int size, int threshold) {
    // Initialize OffsetArray with a power-of-two size for optimal performance
    int* OffsetArray = (int*)malloc((1 << 10) * sizeof(int));
    memset(OffsetArray, 0, (1 << 10) * sizeof(int));

    // Initialize KeyArray with unique integers starting from 1
    int* KeyArray = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        KeyArray[i] = i + 1;
    }

    // Initialize RecordArray and balance key sums
    struct Record** RecordArray = (struct Record**)malloc(size * sizeof(struct Record*));
    for (int i = 0; i < size; i++) {
        RecordArray[i] = (struct Record*)malloc(sizeof(struct Record));
        RecordArray[i]->key = KeyArray[i];
        if (i > 0) {
            RecordArray[i-1]->offset += (long)(KeyArray[i] - (size/2));
            while (RecordArray[i]->offset >= threshold) {
                RecordArray[i-1]->offset -= (long)(KeyArray[i] - (size/2));
                i--;
            }
        }
    }

    // Populate RecordArray with random offsets and handle duplicates
    int maxOffset = RAND_MAX;
    srand(time(NULL));  // Re-seed the random number generator for uniqueness
    for (int i = 0; i < size; i++) {
        int offset = rand() % maxOffset;
        if (i > 0) {
            while (offset == RecordArray[i-1]->offset) {
                offset = rand() % maxOffset;
            }
        }
        RecordArray[i]->offset = (long)offset;
    }

    // Return the initialized RecordArray
    printf("RecordArray initialized with size: %d\n", size);
    for (int i = 0; i < size; i++) {
        printf("Record[%d]: offset=%ld, key=%d\n", i, RecordArray[i]->offset, RecordArray[i]->key);
    }
}
