// Define the structure for RecordArray
typedef struct {
    long offset;
    int key;
} Record;

// Function to manage memory for OffsetArray, KeyArray, and RecordArray
void* manage_memory(int size) {
    // Initialize OffsetArray with given number of elements
    int *offset_array = (int *)malloc(size * sizeof(int));
    if (!offset_array) {
        printf("Memory allocation failed for OffsetArray.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        offset_array[i] = 0;
    }

    // Initialize KeyArray with given number of elements
    int *key_array = (int *)malloc(size * sizeof(int));
    if (!key_array) {
        printf("Memory allocation failed for KeyArray.\n");
        free(offset_array);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        key_array[i] = i + 1;
    }

    // Initialize RecordArray with given number of elements
    Record *record_array = (Record *)malloc(size * sizeof(Record));
    if (!record_array) {
        printf("Memory allocation failed for RecordArray.\n");
        free(offset_array);
        free(key_array);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        record_array[i].offset = rand() % 100 + 1;
        record_array[i].key = key_array[i];
    }

    // Handle memory deallocation gracefully
    free(key_array);
    free(offset_array);

    return record_array;
}

int main(int argc, char *argv[]) {
    int size = atoi(argv[1]);

    Record *record_array = manage_memory(size);

    if (!record_array) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Use the initialized array
    // ...

    free(record_array);

    return 0;
}
