#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define LOAD_FACTOR 0.7
#define RESIZE_THRESHOLD 8000
#define CACHE_SIZE 1024

typedef struct {
    char *key;
    void *value;
} Entry;

typedef struct {
    int size;
    double loadFactor;
    pthread_mutex_t mutex;
    Entry **table;
} HashTable;

typedef struct {
    int capacity;
    int used;
    Entry **entries;
} Cache;

HashTable *hash_table_create() {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = RESIZE_THRESHOLD / LOAD_FACTOR;
    ht->loadFactor = LOAD_FACTOR;
    pthread_mutex_init(&ht->mutex, NULL);
    ht->table = calloc(ht->size, sizeof(Entry *));
    return ht;
}

void hash_table_resize(HashTable *ht) {
    int newSize = ht->size * 2;
    Entry **newTable = realloc(ht->table, newSize * sizeof(Entry *));
    for (int i = ht->size; i < newSize; i++) {
        newTable[i] = NULL;
    }
    ht->table = newTable;
    ht->size = newSize;
}

void hash_table_insert(HashTable *ht, Entry *entry) {
    int index = entry->key_hash % ht->size;
    pthread_mutex_lock(&ht->mutex);
    if (ht->table[index] == NULL || strcmp(ht->table[index]->key, entry->key) != 0) {
        ht->table[index] = entry;
    } else {
        for (int i = index; ht->table[i] != NULL; i++) {
            ht->table[i] = ht->table[i + 1];
        }
        ht->table[i] = entry;
    }
    pthread_mutex_unlock(&ht->mutex);
}

Entry *hash_table_search(HashTable *ht, char *key) {
    int index = key_hash(key) % ht->size;
    pthread_mutex_lock(&ht->mutex);
    Entry *entry = ht->table[index];
    while (entry != NULL && strcmp(entry->key, key) != 0) {
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->mutex);
    return entry;
}

int main() {
    // Initialize the hash table
    HashTable *ht = hash_table_create();

    // Initialize the cache
    Cache *cache = malloc(sizeof(Cache));
    cache->capacity = CACHE_SIZE;
    cache->used = 0;
    cache->entries = calloc(cache->capacity, sizeof(Entry));

    // Add entries to the hash table and cache
    for (int i = 0; i < MAX_ENTRIES; i++) {
        Entry *entry = malloc(sizeof(Entry));
        entry->key = malloc(strlen("setting") + 1);
        strcpy(entry->key, "setting");
        entry->value = malloc(sizeof(int));
        *(int *)entry->value = i;
        hash_table_insert(ht, entry);
    }

    // Search for an entry in the cache
    Entry *found = hash_table_search(ht, "setting");
    printf("%d\n", *(int *)found->value);

    return 0;
}

