    table->numEntries = 0;
    table->entries = (UserDatabaseEntry**)malloc(size * sizeof(UserDatabaseEntry*));
    for (int i = 0; i < size; i++) {
        table->entries[i] = NULL;
    }
    table->predecessor = NULL;
    table->successor = NULL;
    return table;
}

// Insert a new user database entry into the hash table
void insertEntry(HashTable* table, double value, char* name) {
    // Calculate the hash index for the entry
    int hashIndex = (int)value % table->size;

    // Find the next available slot in the linked list
    UserDatabaseEntry* current = table->predecessor;
    while (current && current->successor != NULL) {
        current = current->successor;
    }

    // Create a new user database entry and initialize its transactions array
    UserDatabaseEntry* entry = (UserDatabaseEntry*)malloc(sizeof(struct UserDatabaseEntry));
    entry->value = value;
    entry->name = name;
    entry->transactions = (Transaction*)malloc(1 * sizeof(Transaction));
    Transaction transaction;
    transaction.value = value;
    transaction.logEntry = NULL;
    entry->transactions[0] = transaction;

    // Add the new entry to the hash table and linked list
    if (table->numEntries == 0) {
        table->predecessor = entry;
        table->successor = entry;
    } else {
        current->successor = entry;
        entry->predecessor = current;
        table->successor->predecessor = entry;
        table->successor = entry;
    }

    table->entries[hashIndex] = entry;
    table->numEntries++;
}

// Update the value of a specific transaction
void updateTransaction(HashTable* table, char* name, double newValue) {
    // Find the user database entry for the given name
    UserDatabaseEntry* current = table->predecessor;
    while (current && strcmp(current->name, name) != 0) {
        current = current->successor;
    }

    if (!current) return; // Entry not found

    // Update the transaction value
    Transaction* transactions = current->transactions;
    for (int i = 0; i < table->numEntries; i++) {
        if (transactions[i].value == newValue) {
            transactions[i].value = newValue;
            break;
        }
    }
}

// Calculate and print the average value of all transactions
void calculateAverage(HashTable* table) {
    double sum = 0.0;

    // Traverse the linked list to calculate the average value
    UserDatabaseEntry* current = table->predecessor;
    while (current) {
        Transaction* transactions = current->transactions;
        for (int i = 0; i < table->numEntries; i++) {
            sum += transactions[i].value;
        }
        current = current->successor;
    }

    // Calculate and print the average value
    double average = sum / (double)table->numEntries;
    printf("Average value: %.2f\n", average);
}

int main() {
    int size = 10000; // Maximum number of unique user entries

    // Initialize the hash table
    HashTable table = initializeHashTable(size);

    // Read input and store user database entries in the hash table
    while (1) {
        double value;
        char* name = malloc(256 * sizeof(char));
        fgets(name, 256, stdin);
        value = atof(name);
        insertEntry(&table, value, name);
    }

    // Calculate and print the average value of all transactions
    calculateAverage(&table);

    return 0;
}
