#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LENGTH 256
#define MEMORY_LIMIT (1024 * 1024) // 1MB

typedef struct {
    double value;
    char string[MAX_LENGTH];
    int flag;
} item;

item* items = NULL;
size_t items_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* alloc_item() {
    item* item = (item*)malloc(sizeof(item));
    if (!item) return NULL;
    return item;
}

int read_file(const char* file_name, FILE** file_ptr) {
    *file_ptr = fopen(file_name, "r");
    if (*file_ptr == NULL) {
        printf("Failed to open the file.\n");
        return 1;
    }
    return 0;
}

void update_item(int index) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < items_count; i++) {
        if (i == index) {
            // Update item logic
            printf("Updated item at index %d.\n", i);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void print_items() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < items_count; i++) {
        printf("Item %zu: value=%f, string='%s', flag=%d\n", i, items[i].value, items[i].string, items[i].flag);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Read file
    FILE* file;
    if (read_file("input.txt", &file)) return 1;

    // Initialize memory
    while (items_count < MEMORY_LIMIT) {
        item* new_item = alloc_item();
        if (!new_item) break;
        items[items_count++] = *new_item;
    }

    // Read and populate items from file
    char line[MAX_LENGTH];
    while (fgets(line, MAX_LENGTH, file)) {
        double value = atof(strtok(line, " "));
        char* string = strtok(NULL, " ");
        int flag = atoi(strtok(NULL, " "));
        if (!string || strlen(string) > MAX_LENGTH - 1) {
            printf("Invalid input: %s\n", line);
            continue;
        }
        strcpy(items[items_count - 1].string, string);
        items[items_count - 1].value = value;
        items[items_count - 1].flag = flag;
    }

    // Close file
    fclose(file);

    return 0;
}
