#define MAX_RECORDS 1024
#define RECORD_SIZE sizeof(struct record)
#define JSON_FORMAT "json"

typedef struct {
    long offset;
    int key;
} record;

record* records = NULL;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("memory.log", "w");

void initialize_records(int max_records) {
    pthread_mutex_lock(&mutex);
    if (max_records > MAX_RECORDS) {
        max_records = MAX_RECORDS;
    }
    records = malloc(max_records * RECORD_SIZE);
    num_records = 0;
    pthread_mutex_unlock(&mutex);
}

record* get_record(long offset, int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset && records[i].key == key) {
            record* result = &records[i];
            pthread_mutex_unlock(&mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void update_record(long offset, int key, long new_offset, int new_key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        if (records[i].offset == offset && records[i].key == key) {
            records[i].offset = new_offset;
            records[i].key = new_key;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&mutex);
    if (num_records >= MAX_RECORDS) {
        // Dynamic resize
        record* new_records = realloc(records, (MAX_RECORDS * 2 + 1) * RECORD_SIZE);
        records = new_records;
        num_records *= 2;
    }
    record* new_record = &records[num_records++];
    new_record->offset = offset;
    new_record->key = key;
    pthread_mutex_unlock(&mutex);
}

void export_to_json() {
    // Serialize and write to file
    FILE* json_file = fopen("output.json", "w");
    fprintf(json_file, "[\n");
    for (int i = 0; i < num_records; i++) {
        record* current_record = &records[i];
        fprintf(json_file, "{\"offset\": %ld, \"key\": %d},\n", current_record->offset, current_record->key);
    }
    fclose(json_file);
}

void* thread_func(void* arg) {
    long offset = *((long*)arg);
    int key = *((int*)arg);
    pthread_mutex_lock(&mutex);
    add_record(offset, key);
    pthread_mutex_unlock(&mutex);
    free(arg);
    return NULL;
}

void log_memory_event(const char* message) {
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
}

int main() {
    initialize_records(MAX_RECORDS);
    // Example usage
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        long offset = i * 100;
        int key = i % 10;
        int* arg = malloc(sizeof(int) + sizeof(long));
        *(long*)arg = offset;
        *(int*)arg = key;
        pthread_create(&threads[i], NULL, thread_func, arg);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    export_to_json();
    fclose(log_file);
    return 0;
}
