#include <time.h>

// Define the structure of a transaction
typedef struct Transaction {
    float amount;
    char type;
    struct Operation* operations;
    int size;
} Transaction;

// Define the structure of an operation
typedef struct Operation {
    double value;
    time_t timestamp;
    struct Operation* next;
} Operation;

// Function to create and initialize transactions
Transaction* create_transactions(int num_transactions) {
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].amount = (float)rand() / RAND_MAX;
        transactions[i].type = (char)(rand() % 2);
        transactions[i].operations = NULL;
        transactions[i].size = 0;
    }
    return transactions;
}

// Function to create and initialize operations
Operation* create_operations(int num_operations) {
    Operation* operations = (Operation*)malloc(num_operations * sizeof(Operation));
    for (int i = 0; i < num_operations; i++) {
        operations[i].value = (double)rand() / RAND_MAX;
        operations[i].timestamp = time(NULL);
        operations[i].next = NULL;
    }
    return operations;
}

// Function to update transaction amounts and timestamps
void update_transactions(Transaction* transactions, int start_index, int end_index, double amount_change, time_t timestamp_change) {
    for (int i = start_index; i <= end_index; i++) {
        transactions[i].amount += amount_change;
        transactions[i].operations = NULL;
        transactions[i].size = 0;
        // Update operations
        Operation* current_operation = transactions[i].operations;
        while (current_operation) {
            current_operation->value += amount_change;
            current_operation->timestamp = timestamp_change;
            current_operation = current_operation->next;
        }
    }
}

// Function to track and report on memory usage
void track_memory_usage(Transaction* transactions, int num_transactions) {
    // Calculate total memory usage
    size_t total_memory = sizeof(Transaction) * num_transactions + sizeof(Operation);
    printf("Total memory usage: %zu bytes\n", total_memory);
}
