    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    printf("Average: %f\n", sum / size);
}

// Function to read a list of floating-point numbers from standard input and store them in an array
void readAndStoreDoubles(memManager* mm) {
