           fread(buffer, sizeof(char), 31, file) != 31 ||
           !buffer[31]) break;

        item* item = items + bytesRead / (sizeof(item) + sizeof(double));
        item->value = value;
        item->name = malloc(strlen(buffer)+2);
        strcpy(item->name, buffer);
        item->name[strlen(buffer)] = '\0';
        item->flag = rand() % 100; // Random flag value
        item->offset = bytesRead / (sizeof(item) + sizeof(double));

