int records_capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record_t *find_record(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i].key == key) {
            pthread_mutex_unlock(&mutex);
            return &records[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_record(int key, int value, char *buffer) {
    record_t *new_record = malloc(sizeof(record_t));
    new_record->key = key;
    new_record->value = value;
    strcpy(new_record->buffer, buffer);

    pthread_mutex_lock(&mutex);
    if (records_count >= records_capacity) {
        // Reallocate memory pool
        int new_capacity = records_capacity * 2;
        record_t *new_records = realloc(records, sizeof(record_t) * new_capacity);
        if (!new_records) {
            free(new_record);
            pthread_mutex_unlock(&mutex);
            return;
        }
        records = new_records;
        records_capacity = new_capacity;
    }

    records[records_count] = *new_record;
    records_count++;
    pthread_mutex_unlock(&mutex);
}

void update_record(int key, int value) {
    record_t *record = find_record(key);
    if (record) {
        record->value = value;
    }
}

void free_records() {
    for (int i = 0; i < records_count; i++) {
        free(&records[i]);
    }
    free(records);
    records = NULL;
    records_count = 0;
