#include <pthread.h>

// Define a struct for each record
typedef struct {
    int key;
    long offset;
} Record;

// Function to manage dynamic collection of records
Record** createRecords(int* capacity, int maxMemory) {
    *capacity = 0;
    size_t totalBytes = sizeof(Record*) * (1);
    size_t bytesPerRecord = sizeof(Record);

    while (*capacity < maxMemory / bytesPerRecord && totalBytes <= maxMemory) {
        Record** records = realloc(NULL, totalBytes);
        if (!records) return NULL;  // allocation failure
        *capacity = *capacity + 1;
        totalBytes += bytesPerRecord;
    }

    return records;
}

// Function to add a new record to the collection
int addRecord(Record** records, int capacity, int key, long offset) {
    for (int i = 0; i < *capacity; ++i) {
        if (records[i]->key == key) return -1; // duplicate key found
    }

    Record* newRecord = malloc(sizeof(Record));
    if (!newRecord) return -2;  // allocation failure
    newRecord->key = key;
    newRecord->offset = offset;

    int newCapacity = *capacity + 1;
    records = realloc(records, sizeof(Record*) * newCapacity);
    if (!records) return -3;  // allocation failure

    for (int i = *capacity; --i >= 0;) {
        records[i] = records[i-1];
    }
    records[0] = &newRecord;
    (*capacity)++;

    return 1; // successful addition
}

// Function to update a specific record in the collection
int updateRecord(Record** records, int capacity, int key, long offset) {
    for (int i = 0; i < capacity; ++i) {
        if (records[i]->key == key) {
            free(records[i]);
            records[i] = malloc(sizeof(Record));
            if (!records[i]) return -2; // allocation failure
            records[i]->offset = offset;
            return 1; // successful update
        }
    }

    return -1; // record not found
}

// Function to destroy the dynamic collection of records
void destroyRecords(Record** records, int capacity) {
    for (int i = 0; i < capacity; ++i) {
        free(records[i]);
    }
    free(records);
}
