void* allocate_arrays(int num_measurements, double min_reading, double max_reading, int memory_budget) {
    // Calculate total array size (3 arrays x 1 byte per measurement + 2 bytes for double and 1 byte for char)
    int total_bytes = sizeof(double) * num_measurements + sizeof(char) * num_measurements;

    if ((size_t)total_bytes > memory_budget) {
        printf("Memory budget exceeded. Reducing array size.\n");
        // Reduce array size by half
        num_measurements /= 2;
        total_bytes = sizeof(double) * num_measurements + sizeof(char) * num_measurements;
    }

    double* readings = (double*)malloc(sizeof(double) * num_measurements);
    char* flags = (char*)malloc(sizeof(char) * num_measurements);
    measurement* measurements = (measurement*)malloc(total_bytes);

    if (!readings || !flags || !measurements) {
        printf("Memory allocation failed. Exitting.\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < num_measurements; i++) {
        readings[i] = (double)(min_reading + (max_reading - min_reading) * rand() / (RAND_MAX));
        flags[i] = 'U';
    }

    free(readings);
    free(flags);

    return measurements;
}

void update_measurement(measurement* measurements, int index) {
    pthread_mutex_lock();

    if (measurements[index].status == 'N') {
        // Update measurement value and status
        measurements[index].value += 1.0; // Example: increment the reading by 1.0
        measurements[index].status = 'U';
    }

    pthread_mutex_unlock();
}

int main() {
    int num_measurements = 100;
    double min_reading = 0.0, max_reading = 10.0;
    int memory_budget = 1024 * 64; // 64KB

    measurement* measurements = allocate_arrays(num_measurements, min_reading, max_reading, memory_budget);

    // Create a thread to concurrently update the measurements
    pthread_t thread;
    pthread_create(&thread, NULL, &update_measurement, measurements);

    // Simulate other tasks running concurrently
    for (int i = 0; i < num_measurements; i++) {
        measurement m = measurements[i];
        printf("Measurement %d: Value=%f Status='%c'\n", i, m.value, m.status);

        // Update the measurement status to 'N' occasionally
        if (rand() % 10 == 0) {
            measurements[i].status = 'N';
        }
    }

    pthread_join(thread, NULL);

    free(measurements);

    return 0;
}
