['Here is the C library function for managing a dynamically expandable dataset:

```c
#include <stdlib.h>
#include <stdio.h>

// Structure representing a node in the doubly linked list
typedef struct Node {
    int key;
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to allocate and initialize memory for 'long' offset values, 'int' keys, and 'record' structures
Node* init_node(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL; // Handle memory allocation failure

    node->key = key;
    node->value = 0;

    node->prev = NULL;
    node->next = NULL;

    return node;
}

// Function to manage the dynamically expandable dataset
void* dataset_manager(int threshold, int (*update_node)(Node*, int), void (*compress_data)(int**, int)) {
    // Initialize the dataset with a starting capacity of 5,000 records
    Node* head = init_node(0);
    Node* tail = head;
    for (int i = 1; i < 5000; i++) {
        tail->next = init_node(i);
        tail->next->prev = tail;
        tail = tail->next;
    }

    // Initialize the dataset size
    int capacity = 5000;

    // Initialize the memory usage statistics
    long total_memory_usage = 0;
    int max_memory_usage = 0;
    long last_gc_time = 0;

    // Function to periodically garbage collect unused nodes and free memory
    void gc() {
        if ((time(NULL) - last_gc_time) > 10 && capacity * sizeof(Node) > (1024 * 1024)) {
            Node* current = head;
            while (current != NULL) {
                if (current->key == 0) { // Unused node
                    Node* temp = current;
                    current = current->next;
                    free(temp);
                } else {
                    current = current->next;
                }
            }

            // Update the memory usage statistics
            long new_total_memory_usage = 0;
            Node* current = head;
            while (current != NULL) {
                new_total_memory_usage += sizeof(Node);
                current = current->next;
            }
            total_memory_usage = new_total_memory_usage;

            // Log the memory usage and performance metrics
            printf("Memory usage: %ld bytes\n", total_memory_usage);
            printf("Peak memory usage: %d MB\n", max_memory_usage);

            last_gc_time = time(NULL);
        }
    }

    // Function to update node values based on index and key, ensuring thread safety during updates
