record* create_record(int key, int value) {
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_record->key = key;
    new_record->value = value;
    memset(new_record->buffer, 0, sizeof(new_record->buffer));
    return new_record;
}

// Function to allocate memory for a new node
node* create_node(record *record) {
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->record = record;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

// Function to insert a node into the doubly linked list
void insert_node(node **head, node *new_node) {
    if (!*head) {
        *head = new_node;
    } else {
        (*head)->prev = new_node;
        new_node->next = *head;
        *head = new_node;
    }
}

// Function to update a record value based on index and key
void update_record(node **head, int index, int key, int value) {
    node *current = *head;
    while (current && current->record->key != key) {
        current = current->next;
    }
    if (!current) {
        printf("Record not found\n");
        return;
    }
    if (index == 0) {
        current->record->value = value;
    } else {
        // Handle record update logic based on index
    }
}

// Function to update a node value based on index and key
void update_node(node **head, int index, int key, int value) {
    node *current = *head;
    while (current && current->record->key != key) {
        current = current->next;
    }
    if (!current) {
        printf("Node not found\n");
        return;
    }
    if (index == 0) {
        current->record->value = value;
    } else {
        // Handle node update logic based on index
    }
}

// Function to free memory occupied by unused nodes
void garbage_collection(node **head, int threshold) {
    node *current = *head;
    node *prev = NULL;
    while (current) {
        if (current->record->value == 0 && current->next) {
            prev = current;
            current = current->next;
        } else if (current->record->value > 0) {
            prev = current;
            current = current->next;
        } else {
            node *temp = current;
            current = current->next;
            free(temp);
        }
    }
}

// Function to track memory usage and performance metrics
void log_memory_usage(node **head, int threshold) {
    // Implement logging mechanism here
}

int main() {
