    _cache: Dict[str, str] = {}

    def __init__(self):
        self._logger = logging.getLogger(__name__)

    @lru_cache(maxsize=128)
    def to_string(self, xml: ET.ElementTree) -> str:
        return ET.tostring(xml.getroot(), encoding='unicode')

    @classmethod
    def from_string(cls, xml_str: str) -> 'XMLTransformer':
        root = ET.fromstring(xml_str)
        obj_id = root.attrib.get('id')
        if not obj_id:
            raise ValueError("Invalid XML")
        return cls._registry.get(obj_id).create_from_xml(root)

    @classmethod
    def register(cls, obj_id: str, factory_func: Any):
        cls._registry[obj_id] = factory_func

    @staticmethod
    def _parse_xml(xml_str: str) -> ET.ElementTree:
        try:
            return ET.fromstring(xml_str)
        except ET.ParseError as e:
            raise ValueError(f"Invalid XML: {e}")

    @lru_cache(maxsize=128)
    def parse_xml(self, xml_str: str) -> ET.ElementTree:
        return self._parse_xml(xml_str)

    @staticmethod
    def _transform_xml(xml_tree: ET.ElementTree) -> str:
        try:
            return ET.tostring(xml_tree.getroot(), encoding='unicode')
        except ET.ParseError as e:
            raise ValueError(f"Invalid XML: {e}")

    @lru_cache(maxsize=128)
    def transform_xml(self, xml_tree: ET.ElementTree) -> str:
