#define RECORD_COUNT 10000000
#define MAX_RECORD_SIZE 1024
#define THREADSAFE_MUTEX NULL
#define LOG_FILE "/dev/null"

typedef struct {
    int key;
    long offset;
} Record;

Record* records = NULL;
int record_count = 0;
int max_record_size = MAX_RECORD_SIZE;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen(LOG_FILE, "a+");

void init_records() {
    if (records != NULL) return;
    pthread_mutex_lock(&mutex);
    records = malloc(RECORD_COUNT * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }
    record_count = 0;
    pthread_mutex_unlock(&mutex);
}

int get_record_key() {
    static int key = 0;
    return key++;
}

long get_record_offset() {
    // Initialize the offset value
    long offset = (long) time(NULL);
    return offset;
}

void add_record() {
    init_records();
    Record new_record;
    new_record.key = get_record_key();
    new_record.offset = get_record_offset();
    pthread_mutex_lock(&mutex);
    records[record_count] = new_record;
    record_count++;
    pthread_mutex_unlock(&mutex);
}

void serialize_records_to_file(const char* filename, int format) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for writing.\n", filename);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&mutex);
    fwrite(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
    }
    pthread_mutex_unlock(&mutex);
    fclose(file);
}

void deserialize_records_from_file(const char* filename, int format) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open %s for reading.\n", filename);
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&mutex);
    fread(&record_count, sizeof(int), 1, file);
    records = realloc(records, record_count * sizeof(Record));
    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->offset, sizeof(long), 1, file);
    }
    pthread_mutex_unlock(&mutex);
    fclose(file);
}

void log_message(const char* message) {
    fprintf(log_file, "%s\n", message);
}

void finalize() {
    pthread_mutex_lock(&mutex);
    free(records);
    records = NULL;
    record_count = 0;
    pthread_mutex_unlock(&mutex);
    fclose(log_file);
}
