        size_t new_capacity = ht->capacity * 2;
        void** new_keys = realloc(ht->keys, new_capacity * sizeof(void*));
        void** new_values = realloc(ht->values, new_capacity * sizeof(void*));
        ht->keys = new_keys;
        ht->values = new_values;
        ht->capacity = new_capacity;
