#include <string.h>
#include <pthread.h>

// Define a struct for each record
typedef struct {
    long offset;
    int key;
    float precision;
    char field[255];
} Record;

// Define the linked list node structure
typedef struct Node {
    Record *record;
    struct Node* next;
} Node;

// Initialize the global head pointer to NULL
Node* head = NULL;

// Function to add a record to the end of the linked list
void addRecord(Record* newRecord) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->record = newRecord;
    newNode->next = NULL;

    if(head == NULL){
        head = newNode;
    } else {
        Node* lastNode = head;
        while(lastNode->next != NULL){
            lastNode = lastNode->next;
        }
        lastNode->next = newNode;
    }
}

// Function to remove a record from the linked list
void removeRecord(Record* oldRecord) {
    if(head == NULL) return;

    Node* current = head;
    Node* previous = NULL;

    while(current != NULL && current->record != oldRecord){
        previous = current;
        current = current->next;
    }

    if(current != NULL){
        if(previous == NULL){
            head = head->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
}

// Function to print all records
void printRecords() {
    Node* current = head;

    while(current != NULL) {
        printf("Offset: %ld, Key: %d, Precision: %f, Field: %s\n", 
            current->record->offset, current->record->key, current->record->precision, 
            current->record->field);
        current = current->next;
    }
}

// Thread-safe function to add a record
void* addRecordThread(void* arg) {
    Record* newRecord = (Record*)arg;
    pthread_mutex_lock(&mutex);
    addRecord(newRecord);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Initialize the mutex for thread safety
pthread_mutex_t mutex;

int main() {
    // Create a thread pool to handle concurrent record additions
    int numThreads = 4;
    pthread_t threads[numThreads];

    for(int i = 0; i < numThreads; i++) {
        Record* newRecord = (Record*)malloc(sizeof(Record));
        // Initialize the new record fields...
        pthread_create(&threads[i], NULL, addRecordThread, newRecord);
    }

    // Wait for all threads to finish
    for(int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
