            printf("Error: Invalid value or offset in record %d.\n", i);
            return NULL;
        }
    }

    // Return a pointer to the first element of the records array
    return &records[0];
}

int find_key(int keys[], int index, int key) {
    for (int i = 0; i < index; i++) {
        if (keys[i] == key) {
            return 1;
        }
    }
    return 0;
}

int isValidValue(int value, int min, int max) {
    return (value >= min && value <= max);
}

int isValidOffset(long offset, long min, long max) {
    return (offset >= min && offset <= max);
}
