void initArraysAndRecords(int *keys, long *offsets, Record **records, int numRecords) {
    // Dynamically allocate memory for keys array
    keys = (int *)malloc(numRecords * sizeof(int));

    // Dynamically allocate memory for offsets array
    offsets = (long *)malloc(numRecords * sizeof(long));

    // Dynamically allocate memory for records array
