    // Handle events
    handleEvents(&keys, &offsets, &records);

    // Periodically clean up unused events
    cleanupEvents(&keys, &offsets, &records);

    // Handle any memory allocation failures
    handleError(&keys, &offsets, &records);

    return 0;
}
