    public void execute(Call<Object> call) throws IOException, InterruptedException {
        if (!circuitBreaker.open()) {
            try {
                // Validate response against predefined schema
                Object response = call.execute().body();
                if (validateResponse(response)) {
                    // Log successful request
                    logRequestSuccess(endpoint);
                } else {
                    // Log discrepancy for troubleshooting
                    logRequestFailure(endpoint, response);
                }
            } catch (IOException e) {
                // Handle network failure and retries
                handleNetworkError(e, call);
            }
        }
