using System.Xml;
using System.Environment;
using System.Threading;

public class XmlParser
{
    public static void ParseXml(string xmlFilepath)
    {
        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(xmlFilepath);

            XmlElement root = doc.DocumentElement;
            XmlNodeList elements = root.SelectNodes("//element");

            if (elements == null || elements.Count == 0) return;

            foreach (XmlNode element in elements)
            {
                string name = element.Attributes["name"].Value;

                if (Environment.GetEnvironmentVariable("XML_DIR_PATH") == null)
                {
                    // Initialize arrays
                    int[] longArray = new int[100];
                    int[] intArray = new int[100];
                    record[] recordArray = new record[100];

                    for (int i = 0; i < 100; i++)
                    {
                        recordArray[i] = new record { Key = i, Value = new Random().Next(1, 100) };
                    }

                    // Set environment variable
                    Environment.SetEnvironmentVariable("XML_DIR_PATH", Path.Combine(Directory.GetCurrentDirectory(), name));

                    Directory.CreateDirectory(name);

                    // Serialize data structure to file
                    using (FileStream fs = File.Create(Path.Combine(Environment.GetEnvironmentVariable("XML_DIR_PATH"), "data.bin")))
                    {
                        BinaryFormatter formatter = new BinaryFormatter();
                        formatter.Serialize(fs, recordArray);
                    }
                }

                else
                {
                    // Load data from file
                    using (FileStream fs = File.OpenRead(Path.Combine(Environment.GetEnvironmentVariable("XML_DIR_PATH"), "data.bin")))
                    {
                        BinaryFormatter formatter = new BinaryFormatter();
                        record[] recordArray = (record[])formatter.Deserialize(fs);

                        foreach (record r in recordArray)
                        {
                            Console.WriteLine($"Key: {r.Key}, Value: {r.Value}");
                        }
                    }
                }

                break;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error parsing XML file: " + ex.Message);
        }
    }

    public class record
    {
        public int Key { get; set; }
        public int Value { get; set; }
    }
}

class Program
{
    static void Main(string[] args)
    {
        XmlParser.ParseXml("path_to_your_xml_file.xml");
    }
}
