        return NULL;
    }

    long* offsets = malloc(sizeof(long) * size);
    int* keys = malloc(sizeof(int) * size);
    record_t* records = malloc(sizeof(record_t) * size);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to allocate memory for arrays\n");
        return NULL;
    }

    // Initialize offsets array
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;
    }

    // Initialize keys array with unique values between 1 and size
    for (size_t i = 0; i < size; ++i) {
        int key = rand() % (size - 1) + 1;
        while (key != 0 && contains_key(keys, i)) {
            key = rand() % (size - 1) + 1;
        }
        keys[i] = key;
    }

    // Initialize records array with random values
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        int value = rand() % (size * 2);
        record_t record = {value};
        records[i] = record;
    }

    return records;
}

int contains_key(int* keys, size_t index) {
    for (size_t i = 0; i < index; ++i) {
        if (keys[i] == keys[index]) {
            return 1;
        }
    }
    return 0;
}
