int* chunks = NULL;
time_t* timestamps = NULL;
int chunkCount = 0;

void evictLRU() {
    int oldestIndex = -1;
    time_t oldestTimestamp = 0;

    for (int i = 0; i < chunkCount; i++) {
        if (timestamps[i] <= oldestTimestamp) {
            oldestIndex = i;
            oldestTimestamp = timestamps[i];
        }
    }

    if (oldestIndex != -1) {
        free(chunks[oldestIndex]);
        chunks[oldestIndex] = NULL;
        timestamps[oldestIndex] = 0;
        chunkCount--;
    }
}

DataChunk* getChunk(int key) {
    for (int i = 0; i < chunkCount; i++) {
        if (chunks[i]->data == key) {
            return chunks[i];
        }
    }

    return NULL;
}

void storeChunk(long data, time_t timestamp) {
    DataChunk* newChunk = realloc(chunks, (chunkCount + 1) * sizeof(DataChunk));
    if (!newChunk) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    chunks[chunkCount] = (DataChunk*)malloc(sizeof(DataChunk));
    chunks[chunkCount]->data = data;
    timestamps[chunkCount] = timestamp;

    if (chunkCount >= MAX_CHUNKS) {
        evictLRU();
    } else {
        chunkCount++;
    }
}

