@SpringBootApplication
@Configuration
public class MessageQueueCacheServiceApplication {

    @Value("${message.queue.broker.url}")
    private String messageQueueBrokerUrl;

    @Value("${cache.instance.size}")
    private int cacheInstanceSize;

