from collections import defaultdict
from typing import List, Dict, Any
from lru_cache import LRUcache  # Assume this is an existing LRU cache implementation

class Task:
    def __init__(self, project: str, due_date: int, dependencies: List[str], resources: List[str]):
        self.project = project
        self.due_date = due_date
        self.dependencies = dependencies
        self.resources = resources

def schedule_tasks(tasks: List[Task]) -> Dict:
    task_cache = LRUcache(1000)  # Set a reasonable cache size
    project_deps = defaultdict(dict)
    for task in tasks:
        if not task.project or not all(dep in task_cache for dep in task.dependencies):
            continue
        project_deps[task.project][task.due_date] = task

    scheduled_tasks: Dict = {}
    while project_deps:
        project, due_dates = next(iter(project_deps.items()))
        due_dates.sort()
        for date in due_dates:
            if date <= int(datetime.now().strftime('%Y%m%d%H%M%S')):
                continue
            tasks = [task for task in project_deps[project][date].values()]
            for task in sorted(tasks, key=lambda t: len(t.dependencies)):
                if all(dep in scheduled_tasks or dep in task_cache for dep in task.dependencies):
                    scheduled_tasks[task.project] = scheduled_tasks.get(task.project, [])
                    scheduled_tasks[task.project].append(task)

    return scheduled_tasks
