function processAndTransform(filePath, encryptionKey, plaintextMessage, keyword, loggingLevel) {
  const whitelistedDirs = ['allowed/directory/path1', 'allowed/directory/path2'];
  const cache = {};
  let retryCount = 0;

  async function readfile() {
    if (!whitelistedDirs.includes(new URL(filePath, ' ').href.split('/').shift())) {
      console.error(`Unauthorized access attempt: ${filePath}`);
      return null;
    }

    try {
      const fileContent = await fsPromises.readFile(filePath);
      return fileContent.toString();
    } catch (error) {
      if (retryCount < 3) {
        retryCount++;
        setTimeout(() => readfile(), Math.pow(2, retryCount));
      } else {
        console.error(`File reading failed: ${filePath}`);
        return null;
      }
    }
  }

  async function processContent(fileContent) {
    const transformedLines = fileContent.split('\n').map(line => line.includes(keyword) ? line.toUpperCase() : line);
    return transformedLines.join('\n');
  }

  async function encodeAndEncrypt(plainText) {
    const compressedMessage = await zlib.gzip(JSON.stringify({ message: plainText }));
    const encryptedMessage = await crypto.createCipher('aes-256-cbc', encryptionKey).update(compressedMessage, 'utf8', 'hex');
    return encryptedMessage;
  }

  async function cacheAndLog(key, value) {
    if (!cache[key]) {
      cache[key] = value;
    }

    console.log(`Cache hit: ${key}`);
  }

  async function processFile() {
    const fileContent = await readfile();

    if (!fileContent) return null;

    try {
      const processedContent = await processContent(fileContent);

      const encodedMessage = encodeAndEncrypt(plaintextMessage);
      const encryptedMessage = await encodeAndEncrypt(encodedMessage);

      cacheAndLog('processed', processedContent);
      cacheAndLog('encoded', encodedMessage);
      cacheAndLog('encrypted', encryptedMessage);
    } catch (error) {
      console.error(`Error processing file: ${fileContent}`);
    }
  }

  async function sendLogs() {
    const logEntries = Object.entries(cache);

    await axios.post('https://your-logging-service.com/logs', { data: logEntries }, {
      headers: {
        'Authorization': 'Bearer YOUR_LOGGING_TOKEN',
        'Content-Type': 'application/json'
      }
    });
  }

  processFile();

  if (loggingLevel === 'debug') {
    console.log('Logs sent to external service');
    await sendLogs();
  } else if (loggingLevel === 'info' || loggingLevel === 'warning' || loggingLevel === 'error') {
    // Configure the logging level
  }
}
