        free(offsets);
        return NULL;
    }

    // Allocate memory for record structures
    Node** recordsPtr = (Node**)malloc(numRecords * sizeof(Node*));
    if (!recordsPtr) {
        free(keys);
        free(offsets);
        return NULL;
    }

    int i;
    for(i = 0; i < numRecords; i++) {
        // Initialize record with random key and value
        Node* record = (Node*)malloc(sizeof(Node));
        if (!record) {
            for(int j = 0; j < i; j++)
                free(recordsPtr[j]);
            free(keys);
            free(offsets);
            return NULL;
        }
        record->key = rand() % 10000;
        record->value = rand();
        // Create doubly linked list node
        Node* current = (Node*)malloc(sizeof(Node));
        if (!current) {
            for(int j = 0; j < i + 1; j++)
                free(recordsPtr[j]);
            free(keys);
            free(offsets);
            return NULL;
        }
        record->prev = current;
        record->next = current;
    }

    // Perform DOM traversal and text modification
    // ... (omitting implementation details for brevity)

    return records;
}
