typedef struct {
    int sample_rate;
    unsigned char bits_per_sample;
    int channels;
} AudioInfo;

AudioInfo* extract_audio_info(FILE *file, int chunk_size) {
    AudioInfo *info = (AudioInfo*)malloc(sizeof(AudioInfo));
    if (!info) return NULL;  // Error: memory allocation failed

    fseek(file, 0x12, SEEK_SET);  // Move to the "Subchunk2" section
    fread(&info->sample_rate, sizeof(int), 1, file);
    fseek(file, 0x14, SEEK_SET);  // Move to the "Bits per sample" section
    info->bits_per_sample = (unsigned char)fread(NULL, 1, 1, file);

    int channels;
    switch (info->bits_per_sample) {
        case 8:
            channels = 2;  // Assuming stereo for 8-bit audio
            break;
        case 16:
        case 24:
        case 32:
            fread(&channels, sizeof(int), 1, file);
            break;
    }

    info->channels = channels;

    return info;
}

int main() {
    FILE *file = fopen("audio_file.wav", "rb");
    if (!file) return -1;  // Error: file not found

    AudioInfo *info = extract_audio_info(file, 1024);
    if (!info) return -2;  // Error: memory allocation failed

    printf("Sample rate: %d\n", info->sample_rate);
    printf("Bits per sample: %u\n", info->bits_per_sample);
    printf("Channels: %d\n", info->channels);

    free(info);
    fclose(file);

    return 0;
}

