        case JSON_SUCCESS:
            printf("JSON configuration is valid.\n");
            break;
        case JSON_INVALID_FORMAT:
            printf("Invalid JSON format. Please check the file for errors.\n");
            break;
        case JSON_REQUIRED_FIELD_MISSING:
            printf("Required field missing in JSON configuration.\n");
            break;
        case JSON_OPTIONAL_FIELD_INVALID:
            printf("Optional field contains invalid value in JSON configuration.\n");
            break;
    }
}

int validate_json_config(char *json_str) {
    json_object *config = NULL;

    // Parse the JSON string
    config = json_parse_string(json_str);

    if (!config) {
        return JSON_INVALID_FORMAT;
    }

    // Check for required fields (port, server name, and document root path)
    if (!json_object_object_get(config, "port") || !json_object_object_get(config, "server_name") || !json_object_object_get(config, "document_root")) {
        json_object_put(config);
        return JSON_REQUIRED_FIELD_MISSING;
    }

    // Validate port number
    int port = json_object_get_int(config, "port");
    if (port < 1 || port > 65535) {
        json_object_put(config);
        return JSON_OPTIONAL_FIELD_INVALID;
    }

    // Validate server name
    char *server_name = json_object_get_string(config, "server_name");
    if (!server_name || strlen(server_name) > 64) {
        json_object_put(config);
        return JSON_OPTIONAL_FIELD_INVALID;
    }

    // Validate document root path
    char *document_root = json_object_get_string(config, "document_root");
    if (!document_root || !stat(document_root, NULL)) {
        json_object_put(config);
        return JSON_OPTIONAL_FIELD_INVALID;
    }

    // Check for optional fields (SSL certificate paths, logging settings, allowed IP addresses, and custom error handling mechanisms)
    // ... implement logic to validate these fields

    json_object_put(config);
    return JSON_SUCCESS;
}

