public class JsonProcessor
{
    public void ProcessJson(string jsonPayload, bool isReading)
    {
        if (isReading)
        {
            ReadJson(jsonPayload);
        }
        else
        {
            WriteJson(jsonPayload);
        }
    }

    private void ReadJson(string jsonPayload)
    {
        try
        {
            dynamic jsonData = JsonConvert.DeserializeObject(jsonPayload);

            // Apply filtering and updating based on configuration settings
            UpdateJsonFields(jsonData);

            // Validate JSON structure before returning
            JsonConvert.SerializeObject(jsonData, Formatting.Indented);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error reading JSON: " + ex.Message);
        }
    }

    private void WriteJson(string jsonPayload)
    {
        try
        {
            dynamic jsonData = JsonConvert.DeserializeObject(jsonPayload);

            // Apply filtering and updating based on configuration settings
            UpdateJsonFields(jsonData);

            // Validate JSON structure before writing
            JsonConvert.SerializeObject(jsonData, Formatting.Indented);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error writing JSON: " + ex.Message);
        }
    }

    private void UpdateJsonFields(dynamic jsonData)
    {
        // Apply filtering and updating based on configuration settings
        // For example:
        jsonData.OrderDetails.ForEach((order) =>
        {
            order.Status = order.Status.ToLower();
        });

        // Validate schema constraints after updates
        JsonConvert.DeserializeObject(jsonData.ToString());
    }
}
