namespace FileHashing
{
    public class FileHasher
    {
        public Dictionary<string, string> ProcessFiles(List<string> filePaths, bool skipInvalidFiles)
        {
            var fileHashes = new ConcurrentDictionary<string, string>();
            var lockObject = new object();
            var skippedFilesCount = 0;

            foreach (var filePath in filePaths)
            {
                if (File.Exists(filePath))
                {
                    using (var stream = File.OpenRead(filePath))
                    {
                        using (var hashProvider = SHA256.Create())
                        {
                            byte[] hashBytes;
                            try
                            {
                                hashBytes = hashProvider.ComputeHash(stream);
                                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                                fileHashes.Add(filePath, hashString);
                            }
                            catch (IOException ex)
                            {
                                if (!skipInvalidFiles)
                                    throw;

                                skippedFilesCount++;
                                Console.WriteLine($"Skipping file '{filePath}' due to I/O error: {ex.Message}");
                            }
                        }
                    }
                }
                else
                {
                    if (!skipInvalidFiles)
                        throw new FileNotFoundException("File not found", filePath);

                    skippedFilesCount++;
                    Console.WriteLine($"Skipping file '{filePath}' as it does not exist");
                }
            }

            return fileHashes;
        }
    }
}
