import java.io.*;
import java.net.*;

public class DnsResolver {
    private static final Map<InetAddress, InetAddress> cache = new ConcurrentHashMap<>();
    private static final int CACHE_EXPIRATION = 3600; // 1 hour in seconds

    public static InetAddress resolve(String hostname) throws UnknownHostException {
        InetAddress address;
        if ((address = cache.get(InetAddress.getByName(hostname))) != null) {
            if (System.currentTimeMillis() - cache.putIfAbsent(address, System.currentTimeMillis()) > CACHE_EXPIRATION * 1000) {
                // Cache entry is stale, remove and re-resolve
                cache.remove(address);
                address = InetAddress.getByName(hostname);
            }
        } else {
            // Perform DNS lookup
            address = InetAddress.getByName(hostname);
            cache.put(address, System.currentTimeMillis());
        }
        return address;
    }
}

