use std::collections::{HashSet, HashMap};
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::process::id;
use std::time::SystemTime;
use log::{info, error};

struct Storage {
    path: String,
    data: HashMap<String, String>,
}

impl Storage {
    fn new(name: &str) -> Self {
        let mut path = match env::var("STORAGE_PATH") {
            Ok(path) => PathBuf::from(path),
            Err(_) => {
                let pid = id::id();
                let timestamp = SystemTime::now().unwrap().as_millis();
                format!("/tmp/service-{}-{}.dat", pid, timestamp).to_string()
            }
        };

        Storage { path: path.to_str().unwrap().into(), data: HashMap::new() }
    }

    fn validate_name(&self) -> Result<(), String> {
        if self.path.contains('/') || self.path.contains('\\') {
            return Err("Invalid storage name. It should not contain any directory separators.".to_string());
        }
        let mut set = HashSet::new();
        for c in self.path.chars() {
            match c {
                'a'..='z',
                'A'..='Z',
                '0'..='9',
                '_'
                | '-'
                | '.'
                | '/'
                => {}
                _ => return Err(format!("Invalid character '{}' in storage name.", c)),
            }
        }
        if set.len() > 1 {
            return Err("Storage name should be unique.".to_string());
        }
        Ok(())
    }

    fn read(&self, key: &str) -> Result<String, String> {
        let file = File::open(self.path.clone())?;
        let mut reader = Read::read_to_string(file)?;
        if !reader.contains(key) {
            return Err("Key not found in storage.".to_string());
        }
        Ok(reader.split_whitespace().find(|s| s == key).unwrap().clone())
    }

    fn write(&mut self, key: &str, value: &str) -> Result<(), String> {
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .open(self.path.clone())?;
        let mut writer = Write::writeln(file)?;
        writer.push_str(key);
        writer.push(' ');
        writer.write_all(value.as_bytes())?;
        writer.flush()?;
        Ok(())
    }
}

fn main() {
    env_logger::init();
    let storage = Storage::new("my_storage");
    if let Err(err) = storage.validate_name() {
        error!("Storage name validation failed: {}", err);
        return;
    }
    info!("Storage initialized at path: {}", storage.path);

    // Concurrent access testing
    let handles = vec![
        std::thread::spawn(move || storage.write("key1", "value1")),
        std::thread::spawn(move || storage.read("key2").unwrap()),
    ];
    for handle in handles {
        handle.join().unwrap();
    }

    info!("Storage accessed concurrently without issues.");
}
