// Function to free all allocated memory blocks
void free_memory(void** memory_blocks, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (memory_blocks[i] != NULL) {
            free(memory_blocks[i]);
            memory_blocks[i] = NULL;
        }
    }
}

// Function to manage the allocation and initialization of multiple memory blocks
int main() {
    // Read and parse "offsets.txt" file
    FILE* file = fopen("offsets.txt", "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return 1;
    }

    // Initialize offsets array with default values
    long offsets[1000];
    int count = 0;

    while (!feof(file)) {
        char buffer[20];
        fgets(buffer, sizeof(buffer), file);

        if (sscanf(buffer, "%ld", &offsets[count]) != 1) {
            printf("Invalid input in file\n");
            fclose(file);
            return 1;
        }

        ++count;
    }

    // Close the file
    fclose(file);

    if (count == 0) {
        // Initialize offsets array with default values
        for (int i = 0; i < 1000; ++i) {
            offsets[i] = -1;
        }
    }

    // Allocate memory for an array of int keys, sized to half the number of long integers in the offsets array
    int* keys = malloc(count / 2 * sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Initialize record array
    record_t* records = malloc(min(count, 1000) * sizeof(record_t));
    if (records == NULL) {
        printf("Memory allocation failed\n");
        free(keys);
        return 1;
    }

    // Populate the records array using a loop that sets each record's int field to a random value between -1000 and 1000
    srand(time(NULL));
    for (int i = 0; i < min(count, 1000); ++i) {
        records[i].key = rand() % 2001 - 1000;
    }

    // Free all allocated memory blocks
    free_memory(&keys, 1);
    free_memory(&records, 1);

    return 0;
}
