#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define RECORD_CAPACITY 100
#define VALUE_CAPACITY 500
#define OFFSET_RANGE 1000
#define KEY_RANGE 256
#define VALUE_RANGE 1.0

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    double value;
} value;

// Memory management for arrays of records and values
record* records = NULL;
value* values = NULL;
size_t record_count = 0;
size_t value_count = 0;

// Dynamic array resizing functions
void resize_records(size_t capacity) {
    if (records != NULL && record_count >= capacity)
        return; // No need to resize

    size_t new_capacity = capacity + RECORD_CAPACITY;
    record* new_records = realloc(records, new_capacity * sizeof(record));
    if (!new_records) {
        printf("Memory allocation error for records.\n");
        exit(1);
    }
    records = new_records;

    value_count = 0; // Reset value array count
}

void resize_values(size_t capacity) {
    if (values != NULL && value_count >= capacity)
        return; // No need to resize

    size_t new_capacity = capacity + VALUE_CAPACITY;
    value* new_values = realloc(values, new_capacity * sizeof(value));
    if (!new_values) {
        printf("Memory allocation error for values.\n");
        exit(1);
    }
    values = new_values;
}

// Populate arrays with random data
void init_data() {
    for (size_t i = 0; i < RECORD_CAPACITY; i++) {
        records[i].offset = rand() % OFFSET_RANGE;
        records[i].key = rand() % KEY_RANGE;
    }

    for (size_t i = 0; i < VALUE_CAPACITY; i++) {
        values[i].value = ((double)rand()) / RAND_MAX * VALUE_RANGE;
    }
}

// Update data from an external source
void update_data(const record* new_records, size_t count) {
    if (!new_records || count == 0)
        return;

    // Check for overflow and resize arrays as needed
    if (record_count + count > RECORD_CAPACITY) {
        resize_records(record_count + count);
    }

    memcpy(&records[record_count], new_records, count * sizeof(record));
    record_count += count;
}

void update_values(const value* new_values, size_t count) {
    if (!new_values || count == 0)
        return;

    // Check for overflow and resize arrays as needed
    if (value_count + count > VALUE_CAPACITY) {
        resize_values(value_count + count);
    }

    memcpy(&values[value_count], new_values, count * sizeof(value));
    value_count += count;
}
