// Define a struct for element of linked list
typedef struct {
    double value;
    char* symbol;
    double volume;
    int timestamp;
    struct element* next;
} Element;

// Function to calculate weighted average trade volume over a specified time frame
double weightedAverageTradeVolume(Element* head, int startTimestamp, int endTimestamp) {
    // Initialize sum and count variables for calculation
    double sum = 0.0;
    int count = 0;

    // Traverse the linked list and calculate the weighted average
    Element* current = head;
    while (current != NULL) {
        if (current->timestamp >= startTimestamp && current->timestamp <= endTimestamp) {
            sum += current->value * current->volume;  // Calculate weighted value
            count++;  // Increment count for valid trades within the time frame
        }
        current = current->next;
    }

    // Check for edge cases (empty list, invalid pointers)
    if (count == 0) {
        return 0.0;  // Return 0.0 when no relevant trade data is found
    } else {
        return sum / count;  // Calculate and return the weighted average
    }
}
