```c
#include <stdlib.h>
#include <stdio.h>

// Define a struct to represent a node in the doubly linked list
typedef struct Node {
    int offset;
    int key;
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

// Define a function to initialize memory for nodes, offsets, keys, and records
Node* initMemory(size_t limit) {
    // Initialize pointers for the doubly linked list
    Node* head = NULL;
    Node* tail = NULL;

    // Allocate memory for nodes within the specified limit
    size_t totalMemoryNeeded = sizeof(Node);
    while (totalMemoryNeeded <= limit) {
        Node* newNode = malloc(totalMemoryNeeded);
        if (!newNode) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed. Exiting program.\n");
            exit(1);
        }
        newNode->prev = tail;
        if (head == NULL) {
            head = newNode;
        } else {
            tail->next = newNode;
        }
        tail = newNode;
        totalMemoryNeeded *= 2; // Double memory needed for next allocation
    }

    return head;
}

// Define a function to update the value of specific nodes based on their index and key
void updateNodeValue(Node* head, int index, int key, int newValue) {
    Node* current = head;
    while (current != NULL) {
        if (current->key == key && index-- == 0) {
            current->value = newValue; // Update the value of the node
            break;
        }
        current = current->next;
    }
}

// Define a helper function to read integers from standard input and find the largest integer in an array
int* readIntegersAndFindMax(int limit) {
    int count = 0;
    int max = INT_MIN;

    // Read integers from standard input until the specified limit is reached
    while (scanf("%d", &max) == 1 && ++count < limit);

    // Allocate memory for an array of integers
    int* arr = malloc(count * sizeof(int));
    if (!arr) {
        printf("Memory allocation failed. Exiting program.\n");
        exit(1);
    }

    // Read and store the integers in the array
    for (int i = 0; i < count; ++i) {
        scanf("%d", &arr[i]);
    }

    return arr;
}

// Define a function to execute an external command, capturing output and error streams
void runExternalCommand(char* cmd) {
    try {
        // Execute the external command using Runtime.getRuntime().exec()
        Process process = Runtime.getRuntime().exec(cmd);

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }

        reader.close();

        reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        while ((line = reader.readLine()) != null) {
            System.err.println(line);
        }
    } catch (IOException e) {
        // Handle any potential exceptions effectively
        System.exit(1);
    }
}

// Define a function to delete a file if it exists before command execution
void prepareForCommandExecution() {
