    if (pool_size >= max_records) {
        return NULL; // memory exhausted
    }

    Record* new_record = malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->identifier = strdup(identifier);

    record_pool[pool_size] = new_record;

    pool_size++;
    return NULL;
}

void* update_record(int key, float offset, const char* identifier) {
    for (int i = 0; i < pool_size; i++) {
        if (record_pool[i]->key == key) {
            free(record_pool[i]->identifier);
            record_pool[i]->offset = offset;
            record_pool[i]->identifier = strdup(identifier);
            return NULL;
        }
    }

    return NULL; // record not found
}

void* remove_record(int key) {
    for (int i = 0; i < pool_size; i++) {
        if (record_pool[i]->key == key) {
            free(record_pool[i]->identifier);
            record_pool[i] = NULL;
            pool_size--;
            return NULL;
        }
    }

    return NULL; // record not found
}

void* get_record(int key) {
    for (int i = 0; i < pool_size; i++) {
        if (record_pool[i]->key == key) {
            return record_pool[i];
        }
    }

    return NULL; // record not found
