// Define structure for record
typedef struct {
    int key;
    long* offset;
    int reference_count;
} record;

record** records;
long* offsets;
int* keys;
int n, m;

// Lock for synchronization
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void cleanup() {
    pthread_mutex_lock(&lock);
    if (records != NULL) {
        for (int i = 0; i < n; i++) {
            free(records[i]);
        }
        free(records);
    }
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    pthread_mutex_unlock(&lock);
}

void* record_init(void* keyptr) {
    int key = *(int*)keyptr;
    for (int i = 0; i < m; i++) {
        if (keys[i] == key) {
            return NULL;
        }
    }
    keys[m++] = key;
    return NULL;
}

long hash(int i) {
    // Implement your hash function here
    return (long)(i * 1103515245 + 12345);
}

record* access_record(int key) {
    pthread_mutex_lock(&lock);
    record* result = NULL;
    for (int i = 0; i < n; i++) {
        if ((result = records[i]) != NULL && result->key == key) {
            result->reference_count++;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return result;
}

void record_free(record* r) {
    pthread_mutex_lock(&lock);
    if (r != NULL) {
        r->reference_count--;
        if (r->reference_count == 0) {
            free(r->offset);
            free(r);
        }
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize arrays
    offsets = (long*)malloc(n * sizeof(long));
    for (int i = 0; i < n; i++) {
        offsets[i] = hash(i);
    }

    keys = (int*)malloc(m * sizeof(int));

    records = (record**)malloc(n * sizeof(record*));
    for (int i = 0; i < n; i++) {
        record* r = (record*)malloc(sizeof(record));
        r->key = -1;
        r->offset = &offsets[hash(i) % n];
        r->reference_count = 0;
        records[i] = r;
    }

    // Register cleanup function
    atexit(cleanup);

    return 0;
}

