record* initialize_data_structures(const char* config_file_path, int max_memory_usage) {
    FILE *config_file = fopen(config_file_path, "r");
    if (config_file == NULL) {
        return NULL;
    }

    // Initialize arrays
    long *offset_values = NULL;
    int *keys = NULL;
    record **records = NULL;

    int num_records = 0;
    while (fscanf(config_file, "%ld %d %d\n", &num_records, &max_memory_usage) != 3) {
        if (feof(config_file)) {
            break;
        }
        if (ferror(config_file)) {
            fclose(config_file);
            return NULL;
        }
    }

    offset_values = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record*));

    for (int i = 0; i < num_records; i++) {
        if (fscanf(config_file, "%ld %d %s %d\n", &offset_values[i], &keys[i], &records[i]->str, &records[i]->size) != 4) {
            // Error handling
            for (int j = 0; j < i; j++) {
                free(offset_values[j]);
                free(keys[j]);
                free(records[j]->str);
            }
            free(offset_values);
            free(keys);
            free(records);
            fclose(config_file);
            return NULL;
        }
