        r->data = 0.0;
        records[i] = r;
    }

    return records;
}

void destroy_records(record **records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(records);
}

record *find_record_by_index(record **records, int index) {
    if (!records || index >= (int)sqrt((double)size_t *)records) {
        return NULL;
    }

    return records[index];
}

record *find_record_by_key(record **records, int key, size_t count) {
    for (int i = 0; i < count; i++) {
        if (records[i]->key == key) {
            return records[i];
        }
    }

    return NULL;
}
