// Define a struct to represent an element in the node array
typedef struct {
    float val;
    size_t index;
} element;

// Define a struct to represent a node in the doubly linked list
typedef struct Node {
    struct Node* prev;
    struct Node* next;
    element data;
} Node;

// Allocate memory for and initialize three arrays: one for double precision floating-point numbers, 
// another for char character strings, and a third for struct element objects
void initArrays(double** arr1, int size1, char*** arr2, int size2, element*** arr3, int size3) {
    *arr1 = (double*)malloc(size1 * sizeof(double));
    *arr2 = (char**)malloc(size2 * sizeof(char*));
    *arr3 = (element**)malloc(size3 * sizeof(element));

    // Initialize the arrays with random values
    for (int i = 0; i < size1; i++) {
        (*arr1)[i] = rand() / (double)RAND_MAX;
    }
    for (int j = 0; j < size2; j++) {
        (*arr2)[j] = (char*)malloc(10 * sizeof(char));
        sprintf((*arr2)[j], "String %d", j);
    }
    for (int k = 0; k < size3; k++) {
        (*arr3)[k] = (element*)malloc(sizeof(element));
        (*arr3)[k]->val = rand() / (float)RAND_MAX;
        (*arr3)[k]->index = k;
    }
}

// Function to populate the float values in each struct element within the node array with random values
void populateNodeArray(Node** nodes, int size) {
    for (int i = 0; i < size; i++) {
        nodes[i]->data.val = rand() / (float)RAND_MAX;
    }
}

// Function to traverse the list and print all values
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Value: %f, Index: %zu\n", current->data.val, current->data.index);
        current = current->next;
    }
}

// Function to dynamically allocate memory for and initialize a node array
Node* initNodeArray(int size, int limit) {
    Node* nodes = (Node*)malloc(size * sizeof(Node));

    if (nodes == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Populate the float values in each struct element within the node array with random values
    for (int i = 0; i < size; i++) {
        nodes[i].prev = &nodes[i-1];
        nodes[i].next = &nodes[(i+1)%size];
        nodes[i].data.val = rand() / (float)RAND_MAX;
        nodes[i].data.index = i;
    }

    return nodes;
}

// Function to delete a node from the doubly linked list
void freeNode(Node* node, Node** head) {
    if (*head == NULL || *head == node) {
        // Handle case where the head needs to be updated
        if (node != NULL && node->next == *head) {
            *head = node->next;
            node->prev = NULL;
            node->next = NULL;
        } else {
            if (*head != NULL) {
                (*head)->prev = NULL;
            }
            *head = node;
        }
    } else {
        if (node->prev != NULL) {
            node->prev->next = node->next;
        } else {
            *head = node->next;
        }
        if (node->next != NULL) {
            node->next->prev = node->prev;
        }
    }

    // Update the prev and next pointers of adjacent nodes
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    // Deallocate memory for the deleted node
    if (node != NULL) {
        free(node);
    }
}

int main() {
    srand(time(NULL));

    int size1 = 100, size2 = 10, size3 = 5, limit = 1024;
    double* arr1 = NULL;
    char** arr2 = NULL;
    element* arr3 = NULL;

    initArrays(&arr1, size1, &arr2, size2, &arr3, size3);

    // Create a doubly linked list with the given number of nodes
    Node* head = initNodeArray(size3, limit);
    if (head == NULL) {
        printf("Failed to create node array.\n");
    } else {
        printList(head);
    }

    // Free memory for the arrays and the node array
    free(arr1);
    for (int i = 0; i < size2; i++) {
        free(arr2[i]);
    }
    free(arr2);
    for (int j = 0; j < size3; j++) {
        free((void*)arr3[j]);
    }
    free(arr3);
    freeNode(head, &head); // Free the node array

    return 0;
}

