#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of resources that can be managed
#define MAX_RESOURCES 1000

// Define the maximum total memory usage in bytes
#define MAX_MEMORY_USAGE 1024 * 1024 * 10 // 10MB

// Define the structure for a resource
typedef struct {
    float priority;
    char* name;
    void* payload;
} Resource;

// Function to manage resources
Resource** resourceManager = NULL; // Handle the dynamic array of resources
int numResources = 0; // Number of managed resources
int totalMemoryUsage = 0; // Total memory usage in bytes

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for synchronization

// Allocate new memory and update statistics
void* allocateResource(int size) {
    void* allocation = malloc(size);
    if (allocation == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }
    totalMemoryUsage += size;
    return allocation;
}

// Deallocate memory and update statistics
void deallocateResource(void* ptr) {
    free(ptr);
    totalMemoryUsage -= sizeof(Resource); // Remove the resource's size from the total
}

// Function to add a new resource
int addResource(float priority, char* name, void* payload) {
    Resource* resource = allocateResource(sizeof(Resource));
    if (resource == NULL)
        return -1; // Allocation failed

    resource->priority = priority;
    resource->name = name;
    resource->payload = payload;

    pthread_mutex_lock(&mutex);
    resourceManager[numResources++] = resource;
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to find a resource by its name
Resource* findResourceByName(char* name) {
    for (int i = 0; i < numResources; i++) {
        if (strcmp(resourceManager[i]->name, name) == 0)
            return resourceManager[i];
    }
    return NULL;
}

// Function to find a resource by its priority
Resource* findResourceByPriority(float priority) {
    for (int i = 0; i < numResources; i++) {
        if (resourceManager[i]->priority == priority)
            return resourceManager[i];
    }
    return NULL;
}

// Periodic integrity validation of resources
void validateResources() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numResources; i++) {
        if (resourceManager[i] == NULL) {
            fprintf(stderr, "Resource %d is invalid\n", i);
            deallocateResource(resourceManager[i]);
            resourceManager[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Function to handle memory limit exceeded
void handleMemoryLimitExceeded() {
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory limit exceeded: %d bytes\n", totalMemoryUsage);
        // Release resources until the limit is met or a resource is found that can be deallocated
        while (totalMemoryUsage > MAX_MEMORY_USAGE && numResources > 0) {
            Resource* lastResource = resourceManager[numResources - 1];
            if (lastResource != NULL) {
                deallocateResource(lastResource);
                numResources--;
            }
        }
    }
}

// Function to handle allocation failure
void handleAllocationFailure() {
    fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
    // Release resources until the limit is met or a resource is found that can be deallocated
    while (totalMemoryUsage > MAX_MEMORY_USAGE && numResources > 0) {
        Resource* lastResource = resourceManager[numResources - 1];
        if (lastResource != NULL) {
            deallocateResource(lastResource);
            numResources--;
        }
    }
}
