#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the structure for a single record
typedef struct {
    int int_field;
} record_t;

// Define the structure for a transaction
typedef struct {
    long transaction_id;
    time_t timestamp;
    char description[256];
    double amount;
    int status;
    struct node* next;
} transaction_t;

// Define the structure for a node in the binary search tree
typedef struct node {
    transaction_t* data;
    struct node* left;
    struct node* right;
} node_t;

// Function to initialize the dataset and BST
void init_dataset(int* size, int** timestamps, long** ids, record_t*** records) {
    // Initialize arrays
    *size = 5000;
    *timestamps = (int*)malloc(*size * sizeof(int));
    *ids = (long*)malloc(*size * sizeof(long));
    *records = (record_t**)malloc(*size * sizeof(record_t*));

    // Initialize records with random values
    for (int i = 0; i < *size; i++) {
        record_t* r = (record_t*)malloc(sizeof(record_t));
        r->int_field = rand() % 100;
        (*records)[i] = r;
    }
}

// Function to insert a transaction into the BST
void insert_transaction(transaction_t* trans, node_t** root) {
    // Create new node and initialize it with the transaction data
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->data = trans;
    new_node->left = NULL;
    new_node->right = NULL;

    // Find the correct position for the new node in the BST
    if (*root == NULL || (*root)->data->transaction_id < trans->transaction_id) {
        if ((*root)->data->transaction_id > trans->transaction_id) {
            if ((*root)->left == NULL) {
                (*root)->left = new_node;
            } else {
                insert_transaction(trans, &((*root)->left));
            }
        } else {
            if ((*root)->right == NULL) {
                (*root)->right = new_node;
            } else {
                insert_transaction(trans, &((*root)->right));
            }
        }
    } else {
        // Transaction ID already exists in the BST
        printf("Error: Duplicate transaction ID\n");
    }
}

// Function to delete a transaction from the BST
void delete_transaction(long id, node_t** root) {
    // Find the correct position for the transaction to be deleted in the BST
    if (*root == NULL || (*root)->data->transaction_id > id) {
        if ((*root)->left != NULL) {
            delete_transaction(id, &((*root)->left));
        } else {
            node_t* temp = *root;
            *root = (*root)->right;
            free(temp);
        }
    } else if (*root->data->transaction_id < id) {
        if ((*root)->right != NULL) {
            delete_transaction(id, &((*root)->right));
        } else {
            node_t* temp = *root;
            *root = (*root)->left;
            free(temp);
        }
    } else {
        // Transaction found; delete it
        if ((*root)->left == NULL && (*root)->right == NULL) {
            free(*root);
            *root = NULL;
        } else if ((*root)->left == NULL) {
            node_t* temp = *root;
            *root = (*root)->right;
            free(temp);
        } else if ((*root)->right == NULL) {
            node_t* temp = *root;
            *root = (*root)->left;
            free(temp);
        } else {
            // Find the minimum value in the right subtree
            node_t* min_node = (*root)->right;
            while (min_node->data->transaction_id > id) {
                min_node = min_node->left;
            }
            (*root)->data = min_node->data;
            free(min_node);
        }
    }
}

// Function to print the transactions in the BST
void print_transactions(node_t* root) {
    if (root != NULL) {
        print_transactions(root->left);
        printf("Transaction ID: %ld, Timestamp: %lu, Description: %s, Amount: %.2f, Status: %d\n",
               root->data->transaction_id, root->data->timestamp, root->data->description,
               root->data->amount, root->data->status);
        print_transactions(root->right);
    }
}

int main() {
    int size;
    int* timestamps;
    long* ids;
    record_t** records;

    init_dataset(&size, &timestamps, &ids, &records);

    // Initialize the BST
    node_t* root = NULL;

    // Insert transactions into the BST
    for (int i = 0; i < size; i++) {
        transaction_t* trans = (transaction_t*)malloc(sizeof(transaction_t));
        trans->transaction_id = ids[i];
        trans->timestamp = time(NULL);
        sprintf(trans->description, "Transaction %ld", ids[i]);
        trans->amount = (double)rand() / RAND_MAX;
        trans->status = rand() % 2;

        insert_transaction(trans, &root);
    }

    // Print the transactions in the BST
    print_transactions(root);

    return 0;
}

