#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* read_records(const char* filename, int* num_records);
void update_records(Record** records, int num_records);
void serialize_data(Record** records, int num_records, const char* filename);
Record* deserialize_data(const char* filename, int* num_records);

int main() {
    // Load data from multiple files
    Record* all_records = NULL;
    int total_num_records = 0;

    for (int i = 1; i <= 5; ++i) {
        Record* records = read_records(sprintf("file_%d.txt", i), &total_num_records);
        if (records != NULL) {
            // Update records based on condition
            update_records(&records, total_num_records);

            // Merge with existing data
            all_records = realloc(all_records, sizeof(Record*) * (total_num_records + records));
            memcpy(&all_records[total_num_records], records, sizeof(Record*) * records);
            free(records);
        }
    }

    // Serialize and deserialize for persistent storage
    serialize_data(&all_records, total_num_records, "unified_data.txt");
    Record* deserialized = deserialize_data("unified_data.txt", &total_num_records);

    printf("Deserialized data: \n");
    for (int i = 0; i < total_num_records; ++i) {
        printf("Offset: %ld, Key: %d, Value: %d\n", deserialized[i].offset, deserialized[i].key, deserialized[i].value);
    }

    // Free allocated memory
    free(all_records);
    free(deserialized);

    return 0;
}

Record* read_records(const char* filename, int* num_records) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s.\n", filename);
        return NULL;
    }

    *num_records = 0;

    Record* records = NULL;

    while (1) {
        Record record;
        if (fscanf(file, "%ld %d %d\n", &record.offset, &record.key, &record.value) != 3) break;

        record = realloc(records, sizeof(Record*) * (*num_records + 1));
        memcpy(&records[*num_records], &record, sizeof(record));
        ++*num_records;
    }

    fclose(file);
    return records;
}

void update_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        // Update condition based on key and offset values
        if ((records[i]->key % 2 == 0 && records[i]->offset > 1000000) || (records[i]->key % 3 == 0 && records[i]->offset < 500000)) {
            records[i]->value = records[i]->value * 2;
        }
    }
}

void serialize_data(Record** records, int num_records, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error opening file %s.\n", filename);
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        fprintf(file, "%ld %d %d\n", records[i]->offset, records[i]->key, records[i]->value);
    }

    fclose(file);
}

Record* deserialize_data(const char* filename, int* num_records) {
    Record* records = NULL;
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s.\n", filename);
        return NULL;
    }

    *num_records = 0;

    while (1) {
        Record record;
        if (fscanf(file, "%ld %d %d\n", &record.offset, &record.key, &record.value) != 3) break;

        Record* new_record = malloc(sizeof(Record));
        memcpy(new_record, &record, sizeof(record));

        records = realloc(records, sizeof(Record*) * (*num_records + 1));
        memcpy(&records[*num_records], new_record, sizeof(*new_record));
        ++*num_records;
    }

    fclose(file);
    return records;
}
