#define MAX_ENDPOINTS 100

typedef struct {
    char* endpoint;
    int timeout;
    int retry_interval;
} APIEndpoint;

typedef struct {
    char* user_id;
    long timestamp;
    char* location;
} JSONData;

int main() {
    FILE *fp = fopen("config.json", "r");
    if (fp == NULL) {
        fp = fopen("default_config.json", "r");
        if (fp == NULL) {
            printf("Error: Configuration file not found.\n");
            return 1;
        }
    }

    json_object* config = json_object_from_file(fp);
    fclose(fp);

    // Initialize third-party library
    lib_init();

    APIEndpoint endpoints[MAX_ENDPOINTS];
    int num_endpoints = 0;

    // Parse configuration file
    for (int i = 0; i < MAX_ENDPOINTS; i++) {
        if (json_object_object_get_ex(config, "endpoint", &endpoints[i].endpoint) &&
            json_object_object_get_ex(config, "timeout", &endpoints[i].timeout) &&
            json_object_object_get_ex(config, "retry_interval", &endpoints[i].retry_interval)) {
            num_endpoints++;
        } else {
            break;
        }
    }

    // Send HTTP requests
    for (int i = 0; i < num_endpoints; i++) {
        lib_send_request(endpoints[i].endpoint);
    }

    // Calculate average response time
    double avg_response_time = 0.0;
    int total_responses = 0;

    // Aggregate responses and calculate average response time
    for (int i = 0; i < num_endpoints; i++) {
        json_object* response = lib_get_response();
        if (response != NULL) {
            JSONData data;
            json_object_object_get_ex(response, "user_id", &data.user_id);
            json_object_object_get_ex(response, "timestamp", &data.timestamp);
            json_object_object_get_ex(response, "location", &data.location);

            // Print response in formatted table
            printf("%-20s %-15d %-10s\n", data.user_id, data.timestamp, data.location);

            total_responses++;
            avg_response_time += lib_get_response_time();
        }
    }

    if (total_responses > 0) {
        printf("Average Response Time: %.2f seconds\n", avg_response_time / total_responses);
    } else {
        printf("No responses received.\n");
    }

    // Clean up
    for (int i = 0; i < num_endpoints; i++) {
        free(endpoints[i].endpoint);
    }
    free(config);

    return 0;
}

