    if (!records) {
        return NULL;
    }

    int num_records = sizes[0] < sizes[1] ? sizes[0] : sizes[1];

    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets + i;
        records[i].index = i;
    }

    // Calculate memory usage and check against threshold
    size_t total_memory_usage = max_size * sizeof(record);
    if (total_memory_usage > threshold) {
        free(records);
