#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    char *name;
    int key;
    int value;
} Record;

// Define the structure for the collection of records
typedef struct {
    pthread_mutex_t mutex; // Mutex for concurrency control
    size_t capacity; // Initial capacity of the hash table and linked list
    size_t count; // Current number of records in the collection
    Record **records; // Array to store the records
    int *hashTable; // Hash table for key-based access
    struct RecordNode {
        Record record;
        struct RecordNode *next;
    } *head, *tail; // Head and tail of the linked list
} Records;

// Function to manage a collection of 'record' structures in a multi-threaded environment
void* recordsManager(void* arg) {
    Records* records = (Records*)arg;

    // Initialize the hash table with a load factor of 0.7
    records->hashTable = (int*)calloc(records->capacity, sizeof(int));
    for (size_t i = 0; i < records->capacity; i++) {
        records->hashTable[i] = -1;
    }

    // Initialize the linked list with a dummy node
    records->head = (struct RecordNode*)malloc(sizeof(struct RecordNode));
    records->tail = records->head;
    records->records = (Record**)malloc(records->capacity * sizeof(Record*));

    while (true) {
        // Process incoming records from external source

        // Add record to hash table
        int index = records->key % records->capacity;
        if (records->hashTable[index] == -1) {
            records->hashTable[index] = 0;
        }

        // Insert record into linked list at the front
        RecordNode* newNode = (RecordNode*)malloc(sizeof(RecordNode));
        newNode->record = record;
        newNode->next = records->head->next;
        records->head->next = newNode;
        if (records->tail == records->head) {
            records->tail = newNode;
        }

        // Update the hash table and linked list sizes
        records->count++;
    }

    return NULL;
}

// Function to insert a record into the collection
void recordsInsert(Records* records, Record* record) {
    pthread_mutex_lock(&records->mutex);

    int index = record->key % records->capacity;
    if (records->hashTable[index] == -1) {
        records->hashTable[index] = 0;
    }

    // Insert the record into the linked list at the front
    RecordNode* newNode = (RecordNode*)malloc(sizeof(RecordNode));
    newNode->record = *record;
    newNode->next = records->head->next;
    records->head->next = newNode;
    if (records->tail == records->head) {
        records->tail = newNode;
    }

    // Update the hash table and linked list sizes
    records->count++;
    pthread_mutex_unlock(&records->mutex);
}

// Function to delete a record from the collection by its key
void recordsDelete(Records* records, int key) {
    pthread_mutex_lock(&records->mutex);

    // Find the record in the hash table and linked list
    int index = key % records->capacity;
    RecordNode* current = records->head->next;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&records->mutex);
        return; // Record not found
    }

    // Remove the record from the linked list and update the hash table
    records->head->next = current->next;
    if (records->tail == current) {
        records->tail = records->head;
    }
    free(current);

    // Update the hash table and linked list sizes
    records->count--;

    pthread_mutex_unlock(&records->mutex);
}

// Function to find a record in the collection by its key
Record* recordsFind(Records* records, int key) {
    pthread_mutex_lock(&records->mutex);

    // Find the record in the hash table and linked list
    int index = key % records->capacity;
    RecordNode* current = records->head->next;
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }

    pthread_mutex_unlock(&records->mutex);

    return current == NULL ? NULL : &current->record;
}

// Function to resize the hash table and linked list
void recordsResize(Records* records, size_t newCapacity) {
    // Resize the hash table
    int* newHashTable = (int*)calloc(newCapacity, sizeof(int));
    for (size_t i = 0; i < newCapacity; i++) {
        newHashTable[i] = -1;
    }

    // Resize the linked list
    RecordNode* newHead = NULL;
    RecordNode* current = records->head;
    while (current != NULL) {
        RecordNode* newNode = (RecordNode*)malloc(sizeof(RecordNode));
        newNode->record = current->record;
        newNode->next = newHead;
        newHead = newNode;
        free(current);
        current = current->next;
    }

    // Update the record pointers and sizes
    records->capacity = newCapacity;
    records->hashTable = newHashTable;
    records->head = newHead;
    records->tail = newHead;
}

// Function to initialize the collection with an initial capacity
Records* recordsInit(size_t capacity) {
    Records* records = (Records*)malloc(sizeof(Records));
    records->mutex = PTHREAD_MUTEX_INITIALIZER;
    records->capacity = capacity;
    records->count = 0;

    // Initialize the hash table and linked list
    records->records = (Record**)calloc(capacity, sizeof(Record*));
    for (size_t i = 0; i < capacity; i++) {
        records->hashTable[i] = -1;
    }

    return records;
}

// Function to free the collection's memory
void recordsFree(Records* records) {
    // Free the hash table and linked list
    for (size_t i = 0; i < records->capacity; i++) {
        if (records->hashTable[i] != -1) {
            free((void*)records->hashTable[i]);
        }
    }

    RecordNode* current = records->head;
    while (current != NULL) {
        RecordNode* next = current->next;
        free(current);
        current = next;
    }

    // Free the record pointers
    for (size_t i = 0; i < records->capacity; i++) {
        if (records->records[i] != NULL) {
            free(records->records[i]);
        }
    }

    // Free the mutex and other metadata
    pthread_mutex_destroy(&records->mutex);
    free(records);
}
