#include <string.h>
#include <time.h>

typedef struct {
    int key;
    char* data;
    int value;
    time_t timestamp;
} record;

record* createRecord(int key, int minValue, int maxValue) {
    record* newRecord = (record*)malloc(sizeof(record));
    newRecord->key = key;
    newRecord->data = (char*)malloc(100);
    sprintf(newRecord->data, "Data for record %d", key);
    newRecord->value = rand() % (maxValue - minValue) + minValue;
    newRecord->timestamp = time(NULL);
    return newRecord;
}

void freeRecord(record* recordToFree) {
    if (recordToFree != NULL) {
        if (recordToFree->data != NULL)
            free(recordToFree->data);
        free(recordToFree);
    }
}

typedef struct {
    int capacity;
    int count;
    record** records;
} LRUcache;

LRUcache* createCache(int capacity) {
    LRUcache* newCache = (LRUcache*)malloc(sizeof(LRUcache));
    newCache->capacity = capacity;
    newCache->count = 0;
    newCache->records = (record**)malloc(capacity * sizeof(record*));
    for (int i = 0; i < capacity; i++)
        newCache->records[i] = NULL;
    return newCache;
}

void cacheInsert(LRUcache* cache, record* recordToInsert) {
    if (cache->count == cache->capacity) {
        // Evict the least recently used item
        int lruIndex = 0;
        time_t earliestTimestamp = cache->records[0]->timestamp;
        for (int i = 1; i < cache->capacity; i++) {
            if (cache->records[i]->timestamp < earliestTimestamp) {
                lruIndex = i;
                earliestTimestamp = cache->records[i]->timestamp;
            }
        }
        recordToInsert->data = cache->records[lruIndex]->data;
        freeRecord(cache->records[lruIndex]);
        cache->records[lruIndex] = NULL;
    }
    int index = 0;
    while (index < cache->capacity && cache->records[index] != NULL)
        index++;
    if (index == cache->capacity) {
        // Cache is full, so add the new record
        for (int i = 1; i < cache->count; i++) {
            cache->records[i - 1] = cache->records[i];
        }
        cache->records[cache->count++] = recordToInsert;
    } else {
        // Cache has a free slot, so add the new record
        for (int i = cache->capacity - 1; i > index; i--)
            cache->records[i] = cache->records[i - 1];
        cache->records[index] = recordToInsert;
        cache->count++;
    }
}

record* cacheGet(LRUcache* cache, int key) {
    for (int i = 0; i < cache->count; i++) {
        if (cache->records[i]->key == key)
            return cache->records[i];
    }
    return NULL;
}

void cacheDelete(LRUcache* cache, record* recordToDelete) {
    for (int i = 0; i < cache->count; i++) {
        if (cache->records[i] == recordToDelete) {
            for (int j = i + 1; j < cache->count; j++)
                cache->records[j - 1] = cache->records[j];
            cache->count--;
            return;
        }
    }
}

void printStatistics(LRUcache* cache) {
    printf("Cache Hits: %d\n", cache->count);
    printf("Cache Misses: %d\n", 0); // Assuming all records are unique
}

int main() {
    // Initialize the metadata service (not shown)

    return 0;
}
