#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* str;
    int key;
    int value;
} record_t;

record_t** hash_table;
int hash_size = 128;

record_t** skip_list;
int skip_level = 5;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* buffer_queue[1024];
int buffer_head = 0, buffer_tail = 0;
int buffer_capacity = 1024;

void insert(record_t* record) {
    int index = record->key % hash_size;
    pthread_mutex_lock(&mutex);
    if (hash_table[index] == NULL || hash_table[index]->str != record->str) {
        if (hash_table[index] != NULL) free(hash_table[index]);
        hash_table[index] = record;
    }
    pthread_mutex_unlock(&mutex);

    index = 0;
    while (1 << index <= skip_level && skip_list[index] == NULL) index++;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < index; i++) {
        if (skip_list[i] != NULL) free(skip_list[i]);
    }
    record->key += index;
    skip_list[index - 1] = record;
    pthread_mutex_unlock(&mutex);

    pthread_cond_signal(&cond);
}

void delete(record_t* record) {
    int index = record->key % hash_size;
    pthread_mutex_lock(&mutex);
    if (hash_table[index] == record) hash_table[index] = NULL;
    else {
        for (int i = 0; i < skip_level && skip_list[i] != NULL; i++) {
            if (skip_list[i] == record) skip_list[i] = NULL;
        }
    }
    pthread_mutex_unlock(&mutex);

    if (buffer_head != buffer_tail) {
        int pos = (buffer_tail + 1) % buffer_capacity;
        while (pos != buffer_head && buffer_queue[pos] != NULL) pos = (pos + 1) % buffer_capacity;
        if (pos == buffer_tail) {
            buffer_head = pos;
            buffer_tail = 0;
        } else {
            buffer_tail = pos;
        }
    }
}

record_t* lookup(int key) {
    int index = key % hash_size;
    pthread_mutex_lock(&mutex);
    record_t* record = hash_table[index];
    if (record != NULL && record->key == key) return record;
    pthread_mutex_unlock(&mutex);

    for (int i = 0; i < skip_level && skip_list[i] != NULL; i++) {
        if (skip_list[i]->key == key) return skip_list[i];
    }

    return NULL;
}

void* worker(void* arg) {
    while (1) {
        record_t* record = buffer_queue[buffer_head++];
        if (record == NULL) break;

        pthread_mutex_lock(&mutex);
        insert(record);
        pthread_mutex_unlock(&mutex);

        pthread_cond_wait(&cond, &mutex);
    }

    return NULL;
}

int main() {
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) pthread_create(&threads[i], NULL, worker, NULL);

    // simulate workload
    for (int i = 0; i < 10000; i++) {
        record_t* record = malloc(sizeof(record_t));
        // generate random string and key-value pair
        // ...
        insert(record);
        free(record);
    }

    // wait for threads to finish
    for (int i = 0; i < 4; i++) pthread_join(threads[i], NULL);

    return 0;
}

