typedef struct {
    long int timestamp;
    double value;
    char metadata[1024];
} dataPoint;

dataPoint* head = NULL;

void updateNode(int index, long int timestamp, double value) {
    if (head == NULL || index >= 5000) return; // Ensure valid node and index

    for (dataPoint* current = head; current != NULL; current = current->next) {
        if (current->timestamp == timestamp) {
            current->value = value;
            return;
        }
    }
}

void insertNode(long int timestamp, double value, char metadata[]) {
    dataPoint* newNode = (dataPoint*)malloc(sizeof(dataPoint));
    newNode->timestamp = timestamp;
    newNode->value = value;
    strcpy(newNode->metadata, metadata);

    if (head == NULL) head = newNode; // Initialize list with new node
    else {
        dataPoint* current = head;
        while (current->next != NULL) current = current->next;
        current->next = newNode;
        newNode->prev = current;
    }
}

void deleteNode(long int timestamp) {
    if (head == NULL) return; // Check for empty list

    for (dataPoint* current = head; current != NULL; current = current->next) {
        if (current->timestamp == timestamp) {
            dataPoint* temp = current;
            if (current->prev != NULL) current->prev->next = current->next;
            else head = current->next;

            if (current->next != NULL) current->next->prev = current->prev;
            free(temp);
            return;
        }
    }
}

double getMaxValue() {
    double max = 0.0;
    for (dataPoint* current = head; current != NULL; current = current->next) {
        if (current->value > max) max = current->value;
    }
    return max;
}

void freeMemory() {
    dataPoint* current = head;
    while (current != NULL) {
        dataPoint* temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}

int main() {
