        scanf("%ld %lf %s", &(timestamps[i]), &(values[i]), metadata);
    }

    // Initialize nodes with random values
    srand(time(NULL));
    for (i = 0; i < recordCount; i++) {
        insertNode(timestamps[i], (double)rand() / RAND_MAX, metadata);
    }

    // Find and print max measurement value
    double maxValue = getMaxValue();
    printf("Maximum measurement value: %lf\n", maxValue);

    // Free allocated memory
    freeMemory();

    return 0;
}
