#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000
#define HASH_TABLE_SIZE 1024

typedef struct {
    char* key;
    void* value;
} KVPair;

typedef struct {
    KVPair** entries;
    int size;
    pthread_mutex_t mutex;
} ConfigManager;

void* hash_table[HASH_TABLE_SIZE];

ConfigManager* config_manager_create() {
    ConfigManager* cm = (ConfigManager*)malloc(sizeof(ConfigManager));
    cm->entries = (KVPair**)malloc(HASH_TABLE_SIZE * sizeof(KVPair*));
    for(int i = 0; i < HASH_TABLE_SIZE; i++) {
        hash_table[i] = NULL;
    }
    cm->size = 0;
    pthread_mutex_init(&cm->mutex, NULL);
    return cm;
}

void config_manager_destroy(ConfigManager* cm) {
    for(int i = 0; i < HASH_TABLE_SIZE; i++) {
        if(hash_table[i]) {
            free(hash_table[i]);
        }
    }
    free(cm->entries);
    pthread_mutex_destroy(&cm->mutex);
    free(cm);
}

int config_manager_hash(const char* key) {
    unsigned int hash = 0;
    while(*key) {
        hash = (hash * 31 + *key++) % HASH_TABLE_SIZE;
    }
    return hash;
}

void config_manager_insert(ConfigManager* cm, const char* key, void* value) {
    pthread_mutex_lock(&cm->mutex);
    int index = config_manager_hash(key) % HASH_TABLE_SIZE;
    KVPair* entry = (KVPair*)malloc(sizeof(KVPair));
    entry->key = strdup(key);
    entry->value = value;
    if(hash_table[index]) {
        KVPair** entries = (KVPair**)realloc(cm->entries, sizeof(KVPair*) * ++cm->size);
        entries[cm->size - 1] = entry;
        cm->entries = entries;
    } else {
        hash_table[index] = entry;
    }
    pthread_mutex_unlock(&cm->mutex);
}

void* config_manager_get(ConfigManager* cm, const char* key) {
    pthread_mutex_lock(&cm->mutex);
    int index = config_manager_hash(key) % HASH_TABLE_SIZE;
    for(int i = 0; i < cm->size; i++) {
        if(strcmp(cm->entries[i]->key, key) == 0) {
            void* value = cm->entries[i]->value;
            pthread_mutex_unlock(&cm->mutex);
            return value;
        }
    }
    pthread_mutex_unlock(&cm->mutex);
    return NULL;
}

void config_manager_remove(ConfigManager* cm, const char* key) {
    pthread_mutex_lock(&cm->mutex);
    int index = config_manager_hash(key) % HASH_TABLE_SIZE;
    for(int i = 0; i < cm->size; i++) {
        if(strcmp(cm->entries[i]->key, key) == 0) {
            free(cm->entries[i]->key);
            free(cm->entries[i]->value);
            free(cm->entries[i]);
            memmove(cm->entries + i, cm->entries + i + 1, sizeof(KVPair*) * (cm->size - i));
            cm->size--;
            break;
        }
    }
    pthread_mutex_unlock(&cm->mutex);
}

void config_manager_print(ConfigManager* cm) {
    for(int i = 0; i < HASH_TABLE_SIZE; i++) {
        if(hash_table[i]) {
            KVPair* entry = hash_table[i];
            printf("%s: %p\n", entry->key, entry->value);
            free(entry->key);
            free(entry->value);
            free(entry);
        }
    }
}
