    for (int i = 0; i < n; i++) {
        free(arr[i]);
    }
    free(arr);
}

file_record* read_files(int max_records) {
    file_record* records = NULL;
    char path[256];
    time_t modified;
    double size;

    int i = 0;
    while (i < max_records && fgets(path, sizeof(path), stdin)) {
        struct stat sb;
        if (stat(path, &sb) == -1) {
            continue; // skip non-existent files
        }
        modified = sb.st_mtime;
        size = ((double)(rand() % 1024 * 1024)); // random file size within range

        records = realloc(records, (i + 1) * sizeof(file_record));
        records[i].path[0] = '\0';
        strcpy(records[i].path, path);
        records[i].modified = modified;
        records[i].size = size;

        i++;
    }
    return records;
}

void free_records(file_record** arr, int n) {
    for (int i = 0; i < n; i++) {
        free(arr[i]);
    }
    free(arr);
}
