#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_TRANS_RECORDS 1000
#define TRANSACTION_MAX_ID_LENGTH 256
#define TRANSACTION_PRIORITY_RANGE 10

typedef struct {
    char id[TRANSACTION_MAX_ID_LENGTH];
    int timestamp;
    char account[50];
    double amount;
    int status; // 0: debit, 1: credit
} Transaction;

typedef struct node {
    Transaction transaction;
    int priority;
    pthread_mutex_t lock;
} Node;

Node* transactions[MAX_TRANS_RECORDS];
int total_transactions = 0;

void add_transaction(Node** head) {
    if (total_transactions >= MAX_TRANS_RECORDS) return; // Handle memory overflow
    Node* new_node = (Node*)malloc(sizeof(Node));
    pthread_mutex_init(&new_node->lock, NULL);
    // Initialize transaction data
    strcpy(new_node->transaction.id, alloca_random_string());
    new_node->transaction.timestamp = time(NULL);
    sprintf(new_node->account, "Account-%d", total_transactions);
    new_node->transaction.amount = (double)rand() / RAND_MAX;
    if (rand() % 2 == 0)
        new_node->transaction.status = 1; // Credit
    else
        new_node->transaction.status = 0; // Debit
    new_node->priority = rand() % TRANSACTION_PRIORITY_RANGE;
    transactions[total_transactions++] = new_node;
}

void update_transaction(Node** head, char* id) {
    for (int i = 0; i < total_transactions; i++) {
        pthread_mutex_lock(&transactions[i]->lock);
        if (!strcmp(transactions[i]->transaction.id, id)) {
            // Update transaction data
            transactions[i]->transaction.amount += (double)rand() / RAND_MAX;
            if (rand() % 2 == 0)
                transactions[i]->transaction.status = 1; // Credit
            else
                transactions[i]->transaction.status = 0; // Debit
            pthread_mutex_unlock(&transactions[i]->lock);
            return;
        }
        pthread_mutex_unlock(&transactions[i]->lock);
    }
}

Transaction* find_transaction(Node** head, char* id) {
    for (int i = 0; i < total_transactions; i++) {
        if (!strcmp(transactions[i]->transaction.id, id)) {
            return &transactions[i]->transaction;
        }
    }
    return NULL;
}

void print_transactions(Node** head) {
    for (int i = 0; i < total_transactions; i++) {
        printf("Transaction ID: %s\n", transactions[i]->transaction.id);
        printf("Timestamp: %d\n", transactions[i]->transaction.timestamp);
        printf("Account: %s\n", transactions[i]->account);
        printf("Amount: %.2f\n", transactions[i]->transaction.amount);
        printf("Status: %d (0: Debit, 1: Credit)\n", transactions[i]->transaction.status);
        printf("Priority: %d\n", transactions[i]->priority);
    }
}

void* thread_func(void* arg) {
    Node** head = (Node**)arg;
    for (int i = 0; i < 10000; i++) { // Process thousands of transactions per second
        add_transaction(head);
        Transaction* t = find_transaction(head, alloca_random_string());
        if (t) update_transaction(head, t->id);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        Node** head = transactions;
        pthread_create(&threads[i], NULL, thread_func, (void*)head);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }
    print_transactions(transactions);
    return 0;
