// Function to manage events and records
void* manage_events_and_records(void* data) {
    // Initialize variables
    srand(time(NULL));
    int event_index = 0;
    int record_id = 0;
    int event_count = 0;
    int record_count = 0;
    pthread_mutex_t lock;

    // Allocate memory for events and records
    Event* events = (Event*)malloc(sizeof(Event) * 10000);
    Record* records = (Record*)malloc(sizeof(Record) * 50000);

    // Initialize event and record arrays
    for (int i = 0; i < 10000; i++) {
        events[i].timestamp = time(NULL);
        strcpy(events[i].type, "Event");
        strcpy(events[i].metadata, "Metadata");
        events[i].value = rand() % 100;
    }

    for (int j = 0; j < 50000; j++) {
        records[j].id = record_id++;
        records[j].random_value = rand() % 100;
        pthread_mutex_init(&records[j].lock, NULL);
        records[j].access_count = 0;
    }

    // Serialize events and records to disk
    int fd_events = open("events.bin", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    int fd_records = open("records.bin", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);

    for (int k = 0; k < event_count; k++) {
        write(fd_events, &events[k], sizeof(Event));
    }

    for (int l = 0; l < record_count; l++) {
        write(fd_records, &records[l], sizeof(Record));
    }

    close(fd_events);
    close(fd_records);

    // Verify integrity of data upon deserialization
    int fd_events_verify = open("events.bin", O_RDONLY);
    int fd_records_verify = open("records.bin", O_RDONLY);

    Event event;
    Record record;

    while (read(fd_events_verify, &event, sizeof(Event)) > 0) {
        // Verify event integrity
        printf("Event %d: Timestamp - %ld, Type - %s, Metadata - %s, Value - %d\n",
               event_index++, (long)event.timestamp, event.type, event.metadata, event.value);
    }

    while (read(fd_records_verify, &record, sizeof(Record)) > 0) {
        // Verify record integrity
        printf("Record %d: ID - %d, Random Value - %d, Access Count - %d\n",
               record_id++, record.id, record.random_value, record.access_count);
    }

    close(fd_events_verify);
    close(fd_records_verify);

    return NULL;
}
