    char category[32];
    double latency;
    double throughput;
    double error_rate;
} Metric;

// Define the list of dynamic metrics
typedef struct {
    Metric* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MetricList;

// Function to initialize and manage a dynamic list of custom data structures representing resource usage metrics
MetricList* init_metric_list(size_t initial_capacity) {
    MetricList* list = (MetricList*)malloc(sizeof(MetricList));
    if (!list) return NULL;
    list->data = (Metric*)calloc(initial_capacity, sizeof(Metric));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new metric to the list
int add_metric(MetricList* list, Metric* metric) {
    if (!list || !metric) return -1;
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Metric* newData = (Metric*)realloc(list->data, new_capacity * sizeof(Metric));
        if (!newData) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = newData;
        list->capacity = new_capacity;
    }
    list->data[list->size] = *metric;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to update an existing metric
int update_metric(MetricList* list, int id, Metric* updatedMetric) {
    if (!list || !updatedMetric) return -1;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].id == id) {
            list->data[i] = *updatedMetric;
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1;
}

// Function to retrieve a metric based on its identifier
Metric* get_metric(MetricList* list, int id) {
    if (!list) return NULL;
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].id == id) {
            Metric* metric = (Metric*)malloc(sizeof(Metric));
            *metric = list->data[i];
            pthread_mutex_unlock(&list->lock);
            return metric;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

