    void* ptr = malloc(size);
    if (!ptr) {
        // handle memory allocation failure
        return NULL;
    }
    return ptr;
}

int initialize_records(int max_size, int min_value, int max_value) {
    records = (Record*) allocate_memory(max_size * RECORD_SIZE);
    if (!records) {
        return -1; // failed to allocate memory
    }

    for (int i = 0; i < max_size; i++) {
        Record* record = &records[i];
        record->key = i;
        record->record = (struct record*) allocate_memory(sizeof(struct record));
        if (!record->record) {
            return -1; // failed to allocate memory
        }
        record->record->value = rand() % (max_value - min_value + 1) + min_value;
    }

    num_records = max_size;
    return 0; // successful initialization
}

void free_records() {
    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        if (record->record) {
            free(record->record);
            record->record = NULL;
        }
    }
    free(records);
    records = NULL;
}

void update_record(int key, int new_value) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            records[i].record->value = new_value;
            break;
        }
    }

    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            free(records[i].record);
            records[i].record = NULL;
            // shift remaining records down
            for (int j = i + 1; j < num_records; j++) {
                Record* record = &records[j];
                record->offset -= RECORD_SIZE;
            }
            num_records--;
        }
    }

    pthread_mutex_unlock(&lock);
}

void print_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            printf("Record %d: Key=%d, Value=%d\n", i, records[i].key, records[i].record->value);
        }
    }

    pthread_mutex_unlock(&lock);
