#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int key;
    int value;
} Record;

// Linked list structure to manage records
typedef struct node {
    Record* data;
    struct node* next;
} Node;

Node* create_node(Record* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_record(Node** head_ref, Record* new_data) {
    Node* new_node = create_node(new_data);
    if (*head_ref == NULL || (*head_ref)->data->key > new_data->key) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->next->data->key <= new_data->key)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_record(Node** head_ref, int key) {
    Node* temp = *head_ref;
    if (temp != NULL && temp->data->key == key) {
        *head_ref = temp->next;
        free(temp);
        return;
    }
    while (temp != NULL && temp->next != NULL && temp->next->data->key > key)
        temp = temp->next;
    if (temp->next != NULL && temp->next->data->key == key) {
        Node* next_node = temp->next;
        temp->next = temp->next->next;
        free(next_node);
    }
}

void init_records(Node** head_ref, int num_records, int max_value, size_t limit) {
    srand(time(NULL));
    *head_ref = NULL;
    for (int i = 0; i < num_records && limit > 0; i++) {
        Record* new_data = (Record*)malloc(sizeof(Record));
        new_data->key = rand() % max_value;
        new_data->value = rand() % max_value;
        insert_record(head_ref, new_data);
        limit -= sizeof(Record) + sizeof(Node);
    }
}

void update_records(Node** head_ref, int num_updates, size_t limit) {
    Node* current = *head_ref;
    while (current != NULL && limit > 0) {
        Record* data = current->data;
        // Update logic here
        current = current->next;
        limit -= sizeof(Record);
    }
}

void compact_records(Node** head_ref, size_t limit) {
    Node* prev = *head_ref;
    Node* curr = (*head_ref)->next;
    while (curr != NULL) {
        prev->next = curr->next;
        free(curr);
        curr = prev->next;
    }
    *head_ref = curr;
}

int main() {
    // Example usage
    Node* head = NULL;
    size_t limit = 1024; // Adjust the memory limit as needed
    init_records(&head, 100, 1000, limit);

    // Perform updates
    update_records(&head, 10, limit);

    // Periodically compact records to minimize fragmentation and improve cache performance
    while (limit > sizeof(Node)) {
        compact_records(&head, limit - sizeof(Node));
        limit = sizeof(Node);
    }

    return 0;
}

