#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure for a group
typedef struct {
    int size; // Number of records in this group
    struct record* records; // Pointer to linked list of records
} group;

// Structure for a record
typedef struct {
    int value;
    struct record* next;
} record;

// Custom memory pool structure
typedef struct {
    void* block; // Pointer to allocated block
    size_t size; // Size of the block
} mem_pool;

// Initialize the memory pool with an initial size and maximum capacity
mem_pool init_memory_pool(size_t initial_size, size_t max_capacity) {
    mem_pool pool;
    pool.block = malloc(initial_size);
    if (!pool.block) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    pool.size = initial_size;
    return pool;
}

// Allocate memory from the custom pool
void* allocate_from_pool(mem_pool* pool, size_t size) {
    void* ptr = NULL;
    if (pool->block && pool->size >= size) {
        ptr = pool->block;
        pool->block += size;
        pool->size -= size;
    } else {
        printf("Error: Memory allocation failed.\n");
    }
    return ptr;
}

// Deallocate memory from the custom pool
void deallocate_from_pool(mem_pool* pool, void* ptr) {
    if (ptr && pool->block == ptr) {
        free(ptr);
        pool->block = NULL;
        pool->size = 0;
    }
}

// Function to manage and add records to a group dynamically
group* add_records_to_group(group* group_ptr, int record_count) {
    // Allocate memory for the new records from the custom pool
    mem_pool pool = init_memory_pool(record_count * sizeof(record), record_count);
    void* ptr = allocate_from_pool(&pool, record_count * sizeof(record));

    if (ptr) {
        record* new_records = ptr;
        for (int i = 0; i < record_count; i++) {
            new_records[i].value = rand(); // Initialize with random value
            new_records[i].next = group_ptr->records;
            group_ptr->records = &new_records[i];
        }
        deallocate_from_pool(&pool, ptr);
        return group_ptr;
    } else {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to update records in a group
void update_records_in_group(group* group_ptr, int record_index) {
    // Access and modify the desired record's value
    record* target_record = NULL;
    for (record* ptr = group_ptr->records; ptr; ptr = ptr->next) {
        if (ptr - group_ptr->records == record_index) {
            target_record = ptr;
            break;
        }
    }
    if (target_record) {
        target_record->value += 1; // Update the value
    } else {
        printf("Error: Record not found.\n");
    }
}

// Function to batch process groups concurrently with multiple threads
void* batch_process_groups(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = 0; i < record_count; i++) {
        group_ptr[i].size++;
        update_records_in_group(&group_ptr[i], thread_id);
    }
    return NULL;
}

// Function to initialize and manage the system
void init_system(int num_groups, int record_per_group) {
    // Initialize memory pool and groups
    mem_pool* pool = init_memory_pool(num_groups * sizeof(group), num_groups);

    group* group_ptr[num_groups];
    for (int i = 0; i < num_groups; i++) {
        group_ptr[i] = allocate_from_pool(pool, sizeof(group));
        if (!group_ptr[i]) {
            printf("Error: Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        add_records_to_group(group_ptr[i], record_per_group);
    }

    // Initialize threads and batch processing
    pthread_t threads[num_groups];
    for (int i = 0; i < num_groups; i++) {
        int* arg = &i;
        pthread_create(&threads[i], NULL, batch_process_groups, arg);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_groups; i++) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate memory and finalize the system
    for (int i = 0; i < num_groups; i++) {
        deallocate_from_pool(pool, group_ptr[i]);
    }
}

int main() {
    int num_groups = 5;
    int record_per_group = 10;
    init_system(num_groups, record_per_group);
    return 0;
}
