// Create a thread-safe linked list structure
typedef struct node {
    record_t* record;
    struct node* next;
} node_t;

node_t* init_list(record_t* head) {
    node_t* current = (node_t*)malloc(sizeof(node_t));
    current->record = head;
    current->next = NULL;
    return current;
}

// Insert a new record into the linked list
void insert_record(node_t** head, record_t* record) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->record = record;
    new_node->next = *head;
    *head = new_node;
}

// Delete a record from the linked list
void delete_record(node_t** head, int key) {
    if (*head == NULL || (*head)->record->value != key) {
        return;
    }
    node_t* current = *head;
    *head = (*head)->next;
    free(current);
}

// Update a record in the linked list
void update_record(node_t** head, int key, int value) {
    node_t* current = *head;
    while (current != NULL && current->record->value != key) {
        current = current->next;
    }
    if (current == NULL) return;
    current->record->value = value;
}

// Implement garbage collection mechanism
void gc(node_t** head, int memory_budget) {
    node_t* current = *head;
    while (current != NULL && memory_usage() > memory_budget) {
        delete_record(&current, current->record->value);
        current = current->next;
    }
}

