// Define the event structure
typedef struct {
    time_t timestamp;
    unsigned int id;
    bool status;
} Event;

// Define the collection data type
typedef struct {
    size_t capacity;
    size_t count;
    Event **events;
    pthread_mutex_t lock;
} EventCollection;

// Function to create a new event collection
EventCollection* create_event_collection(size_t initial_capacity) {
    EventCollection *collection = (EventCollection*)malloc(sizeof(EventCollection));
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->events = (Event**)malloc(initial_capacity * sizeof(Event*));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

// Function to add a new event to the collection
void add_event(EventCollection *collection, time_t timestamp, unsigned int id, bool status) {
    Event *new_event = (Event*)malloc(sizeof(Event));
    new_event->timestamp = timestamp;
    new_event->id = id;
    new_event->status = status;

    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        // Resize the collection when it reaches capacity
        size_t new_capacity = collection->capacity * 2;
        Event **new_events = (Event**)realloc(collection->events, new_capacity * sizeof(Event*));
        for (size_t i = 0; i < collection->count; i++) {
            new_events[i] = collection->events[i];
        }
        free(collection->events);
        collection->events = new_events;
        collection->capacity = new_capacity;
    }

    // Add the new event to the end of the collection
    collection->events[collection->count++] = new_event;
    pthread_mutex_unlock(&collection->lock);
}

// Function to iterate over events and print their details
void print_events(EventCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; i++) {
        Event *event = collection->events[i];
        printf("Timestamp: %ld, ID: %u, Status: %s\n", event->timestamp, event->id, event->status ? "True" : "False");
    }
    pthread_mutex_unlock(&collection->lock);
}

// Function to set the value of each record's integer field to a random value within a specified range
void initialize_events(EventCollection *collection) {
    srand(time(NULL));
    for (size_t i = 0; i < collection->count; i++) {
        Event *event = collection->events[i];
        event->id = rand() % 100 + 1;
    }
}

int main() {
    // Create a new event collection
    EventCollection *collection = create_event_collection(10);

    // Add some events to the collection
    add_event(collection, time(NULL), 1, true);
    add_event(collection, time(NULL) + 1, 2, false);
    add_event(collection, time(NULL) + 2, 3, true);

    // Initialize event IDs with random values
    initialize_events(collection);

    // Print the events
    print_events(collection);

    return 0;
}
