    Collection* col = (Collection*)malloc(sizeof(Collection));
    col->records = (Record*)malloc(capacity * sizeof(Record));
    col->count = 0;
    pthread_mutex_init(&col->lock, NULL);
    pthread_cond_init(&col->cond, NULL);
    col->capacity = capacity;
    return col;
}

void collection_insert(Collection* col, Record record) {
    pthread_mutex_lock(&col->lock);

    if (col->count == col->capacity) {
        // Handle full collection
        int oldCount = col->count;
        Record* oldRecords = (Record*)realloc(col->records, 2 * col->capacity * sizeof(Record));
        if (!oldRecords) {
            pthread_mutex_unlock(&col->lock);
            return;
        }
        col->records = oldRecords;
        col->capacity *= 2;
    }

    int i = 0;
    for (i = 0; i < col->count; i++) {
        if (record.timestamp > col->records[i].timestamp) {
            break;
        }
    }

    memmove(&col->records[i], &record, sizeof(Record));

    col->count++;

    pthread_cond_signal(&col->cond);

    pthread_mutex_unlock(&col->lock);
}

void collection_remove_stale(Collection* col) {
    pthread_mutex_lock(&col->lock);

    int i = 0;
    for (i = 0; i < col->count; i++) {
        if ((time(NULL) - col->records[i].timestamp) / 1000 > 7) {
            break;
        }
    }

    memmove(&col->records[i], &col->records[i+1], sizeof(Record));
    col->count--;

    pthread_mutex_unlock(&col->lock);
}

void collection_compact(Collection* col) {
    int newCapacity = 2 * col->capacity / 3;
    if (newCapacity < 1) {
        newCapacity = 1;
    }

    Record* newRecords = (Record*)malloc(newCapacity * sizeof(Record));
    int i = 0;
    for (i = 0; i < col->count; i++) {
        if ((time(NULL) - col->records[i].timestamp) / 1000 <= 7) {
            break;
        }
    }

    memmove(newRecords, &col->records[i], sizeof(Record));
    col->count = i;

    free(col->records);
    col->records = newRecords;
    col->capacity = newCapacity;
}

void* thread_func(void* arg) {
    Collection* col = (Collection*)arg;
    for (int i = 0; i < 10000; i++) {
        Record record;
        // Generate fake data
        record.timestamp = time(NULL);
        record.priority = i % 10;
        collection_insert(col, record);
    }

    return NULL;
}

int main() {
    Collection* col = collection_create(1000);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, col);
    }

    // Do some operations to test the function
    record timestamp;
    int priority;

    return 0;
}

