#include <iostream>
#include <list>
#include <map>
#include <random>
#include <chrono>

struct Event {
    time_t timestamp;
    unsigned int id;
    bool status;
};

class EventManager {
public:
    EventManager() : events_(std::make_shared<std::forward_list<Event>>()), memoryPool_(new MemPool()) {}

    void addEvent(Event e) {
        if (events_->size() >= capacityThreshold_) {
            resize();
        }
        *events_ += e;
        logInsertion(e);
    }

    void printEvents() const {
        for (const auto& event : *events_) {
            std::cout << "Timestamp: " << event.timestamp << ", ID: " << event.id << ", Status: " << (event.status ? "Enabled" : "Disabled") << std::endl;
        }
    }

private:
    void resize() {
        capacityThreshold_ *= 2;
        events_ = std::make_shared<std::forward_list<Event>>(std::move(*events_));
    }

    void logInsertion(const Event& e) const {
        // Log the insertion operation
        std::cout << "Event inserted at time: " << e.timestamp << ", ID: " << e.id << std::endl;
    }

    std::shared_ptr<std::forward_list<Event>> events_;
    MemPool* memoryPool_;

    unsigned int capacityThreshold_ = 1024; // Initial capacity threshold
};

class MemPool {
public:
    void* allocate(size_t size) {
        return ::operator new(size);
    }

    void deallocate(void* ptr, size_t size) {
        delete[] static_cast<char*>(ptr);
    }
};

int main() {
    EventManager manager;

    // Add events with random IDs
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);
    for (size_t i = 0; i < 10; ++i) {
        auto event = Event{std::chrono::system_clock::now().time_since_epoch().count(), dis(gen), false};
        manager.addEvent(event);
    }

    // Print the events
    manager.printEvents();

    return 0;
}
