    unsigned long id;
    double value;
    bool quality;
} measurement;

measurement* create_measurement(time_t timestamp, unsigned long id) {
    measurement* m = (measurement*)malloc(sizeof(measurement));
    m->timestamp = timestamp;
    m->id = id;
    m->value = (double)rand() / RAND_MAX; // initialize with random value
    m->quality = true; // default quality flag to true
    return m;
}

// Hash table implementation for efficient storage and retrieval of measurements
typedef struct {
    measurement* data;
    size_t capacity;
    size_t size;
} measurement_hash;

measurement_hash* init_measurement_hash(size_t initial_capacity) {
    measurement_hash* hash = (measurement_hash*)malloc(sizeof(measurement_hash));
    hash->data = (measurement*)malloc(initial_capacity * sizeof(measurement));
    hash->capacity = initial_capacity;
    hash->size = 0;
    return hash;
}

void add_measurement(measurement_hash* hash, time_t timestamp, unsigned long id) {
    measurement* new_m = create_measurement(timestamp, id);
    if(hash->size >= hash->capacity/2) { // resize when half full
        measurement* temp_data = (measurement*)malloc(2 * hash->capacity * sizeof(measurement));
        for(int i=0; i<hash->size; i++) {
            temp_data[i] = hash->data[i];
        }
        free(hash->data);
        hash->data = temp_data;
        hash->capacity *= 2;
    }
    int index = (int)id % hash->capacity;
    if(index >= hash->size) { // add to the end
        for(int i=hash->size; i<=index; i++) {
            hash->data[i] = hash->data[i-1];
        }
        hash->size++;
    } else { // overwrite existing record with same id
        measurement* old_m = &hash->data[index];
        free(old_m);
        hash->data[index] = new_m;
    }
}

// Iterate over measurements and print their details
void print_measurements(measurement_hash* hash) {
    for(int i=0; i[hash]->size; i++) {
        measurement* m = &hash->data[i];
        printf("Timestamp: %ld, ID: %lu, Value: %f, Quality: %s\n", (long)m->timestamp, m->id, m->value, m->quality ? "true" : "false");
    }
}

int main() {
    measurement_hash* hash = init_measurement_hash(10);

    // Add measurements
    add_measurement(hash, 1643723400, 1);
    add_measurement(hash, 1643723410, 2);
    add_measurement(hash, 1643723420, 3);

    print_measurements(hash);

    return 0;
}
