// Function to initialize records based on input string and offset array
record* initRecords(long* offsets, int n, char* input_str, const char* init_pattern) {
    // Check for valid n
    if (n <= 0) return NULL;

    // Pad input string with zeros if it's shorter than 10 characters
    size_t len = strlen(input_str);
    char padded_input_str[11];
    memcpy(padded_input_str, input_str, len >= 10 ? 10 : len);
    padded_input_str[len < 10 ? len : 10] = '\0';

    // Initialize records
    record* records = (record*)calloc(n, sizeof(record));
    for (int i = 0; i < n; i++) {
        int key = (init_pattern && strlen(init_pattern) <= 10)
            ? ((padded_input_str[i % len] * 256 + padded_input_str[(i+1) % len]) & 0xFF)
            : 0;

        records[i].value_ptr = &key;
        records[i].dynamic_int_ptr = (int*)malloc(sizeof(int));
        *records[i].dynamic_int_ptr = offsets[i] % 100; // Random value within range
    }

    return records;
}

// Function to free memory allocated for records and keys array
void freeMemory(record* records, int n) {
    if (!records) return;

    for (int i = 0; i < n; i++) {
        if (records[i].dynamic_int_ptr)
            free(records[i].dynamic_int_ptr);
    }

    free(records);
}
