    if (numEntries >= 1000) {  // Threshold for expanding the collection dynamically
        numEntries *= 2;  // Double the size of the collection

        // Reallocate memory and update the collection pointer
        Entry** newCollection = (Entry**)realloc(collection, numEntries * sizeof(Entry*));

