typedef struct {
    char* key;
    double value;
} entry;

// Function to generate a unique key from a user-provided string template and a random value within a specified range
entry* generate_entry(const char* template_str, int min_value, int max_value) {
    // Initialize entry with default values
    entry* new_entry = (entry*)malloc(sizeof(entry));
    new_entry->key = strdup(template_str);
    new_entry->value = (double)(rand() % (max_value - min_value + 1)) + min_value;

    return new_entry;
}

// Function to load initial entries from an external JSON configuration file
void load_entries_from_json(const char* json_file, entry** entry_array, int* num_entries) {
    // Initialize JSON parser
    json_object* json_obj = json_load_file(json_file, 0);

    if (json_obj == NULL) {
        printf("Failed to parse JSON file.\n");
        return;
    }

    // Parse JSON object and extract entries
    *num_entries = json_object_array_length(json_obj);
    *entry_array = (entry*)malloc(*num_entries * sizeof(entry));
    for (int i = 0; i < *num_entries; i++) {
        json_object* entry_json = json_object_array_get_idx(json_obj, i);
        const char* key = json_object_get_string(entry_json, "key");
        double value = json_object_get_double(entry_json, "value");

        // Generate an error message if the JSON data is malformed
        if (key == NULL || json_object_object_get_ex(entry_json, "key", NULL) != NULL) {
            printf("Malformed JSON entry %d.\n", i);
            return;
        }

        *entry_array[i] = (entry){strdup(key), value};
    }

    // Free JSON object
    json_free_memory(json_obj);
}

// Function to filter entries based on a minimum value threshold
void filter_entries(entry** entry_array, int* num_entries, double min_value) {
    // Iterate through the entries and remove those with values below the threshold
    for (int i = 0; i < *num_entries; i++) {
        if (*entry_array[i]->value < min_value) {
            free(*entry_array[i]->key);
            free(*entry_array[i]);
            *num_entries -= 1;
            entry** new_entry_array = (entry**)realloc(*entry_array, --*num_entries * sizeof(entry));
            for (int j = i; j < *num_entries; j++) {
                *new_entry_array[j] = *entry_array[j + 1];
            }
            free(*entry_array);
            *entry_array = new_entry_array;
        }
    }
}

// Function to handle memory allocation failures
void handle_memory_allocation_failure() {
    // Handle memory allocation failure by dynamically resizing the array and retrying
    while (1) {
        // Dynamically resize the array to accommodate more entries
        entry** new_entry_array = (entry**)realloc(entry_array, ++num_entries * sizeof(entry));
        if (new_entry_array != NULL) {
            entry_array = new_entry_array;
            break;
        }
    }
}

int main() {
    int num_entries = 0;
    entry* entry_array = NULL;

    // Initialize `OffsetArray` with a given number of elements, each initialized to zero
    int offset_array_size = 100;
    int* offset_array = (int*)calloc(offset_array_size, sizeof(int));
    for (int i = 0; i < offset_array_size; i++) {
        offset_array[i] = 0;
    }

    // Initialize `KeyArray` with a given number of elements, each initialized to a unique integer starting from 1
    int key_array_size = 100;
    int* key_array = (int*)calloc(key_array_size, sizeof(int));
    for (int i = 0; i < key_array_size; i++) {
        key_array[i] = i + 1;
