#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 10000000 // 10 MB
#define OFFSET_COUNT 10000
#define KEY_COUNT 5000
#define RECORD_COUNT 2000
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int key;
} record;

void* allocate_memory(int offset_count, int key_count, int timestamp_count) {
    void* offsets = malloc(offset_count * sizeof(long));
    void* keys = malloc(key_count * sizeof(int));
    void* records = malloc(RECORD_COUNT * sizeof(record));
    void* timestamps = malloc(timestamp_count * sizeof(double));

    if (!offsets || !keys || !records || !timestamps) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        free(timestamps);
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < RECORD_COUNT; i++) {
        record* rec = &records[i];
        rec->key = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    // Sort keys and timestamps
    qsort(keys, key_count, sizeof(int), compare_int);
    qsort(timestamps, timestamp_count, sizeof(double), compare_double);

    return records;
}

int compare_int(const void* a, const void* b) {
    int key1 = *(const int*)a;
    int key2 = *(const int*)b;

    if (key1 < key2) return -1;
    else if (key1 > key2) return 1;
    else return 0;
}

int compare_double(const void* a, const void* b) {
    double timestamp1 = *(const double*)a;
    double timestamp2 = *(const double*)b;

    if (timestamp1 < timestamp2) return -1;
    else if (timestamp1 > timestamp2) return 1;
    else return 0;
}
