#define RECORD_SIZE (sizeof(record_t) + sizeof(long) * 2)

typedef struct {
    int key;
    long* offset;
    int* key_ptr;
} record_t;

record_t* allocateRecords(int numRecords) {
    int recordSize = RECORD_SIZE;
    void* memBlock = NULL;
    int allocAttempts = 0;

    while (1) {
        memBlock = malloc(recordSize * numRecords);
        if (!memBlock) break;

        // Check if the memory allocation was successful
        for (int i = 0; i < numRecords; i++) {
            record_t* rec = (record_t*) ((char*) memBlock + i * recordSize);
            rec->key = rand() % 100;
            rec->offset = (long*) (((char*) memBlock) + (i * recordSize) + sizeof(record_t));
            rec->key_ptr = (int*) (((char*) memBlock) + (i * recordSize) + sizeof(record_t) + sizeof(long));

            // Initialize offset and key pointers
            *rec->offset = i;
            *(rec->key_ptr) = rec->key;

            // Check for potential memory reallocations if the initial allocation proves insufficient
            if (i >= numRecords - 10 && !memBlock) {
                free(memBlock);
                memBlock = NULL;
                allocAttempts++;
                break;
            }
        }

        // If the memory allocation was successful, return the allocated records
        if (!memBlock) continue;

        return (record_t*) memBlock;
    }

    // Handle concurrent access from multiple threads without causing data corruption or race conditions
    pthread_mutex_lock();
    free(memBlock);
    pthread_mutex_unlock();

    return NULL;
}

void deallocateRecords(record_t* recs, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        record_t* rec = &recs[i];
        free(rec->offset);
        free(rec->key_ptr);
    }

    free(recs);
}
