    data = (sensor_data_t*)malloc(count * sizeof(sensor_data_t));

    if (!data) {
        return NULL;  // Memory allocation failed, return null
    }

    long* timestamps = (long*)malloc(count * sizeof(long));
    double* measurements = (double*)malloc(count * sizeof(double));
    status_t* statuses = (status_t*)malloc(count * sizeof(status_t));

    if (!timestamps || !measurements || !statuses) {
        free(data);
        return NULL;  // Memory allocation failed, return null
    }

    // Initialize the high-resolution timer for timestamp generation
    struct timespec start;
    clock_gettime(CLOCK_REALTIME, &start);

    // Initialize the reliable random number generator for measurement calculation and status selection
    srand(start.tv_nsec);

    for (int i = 0; i < count; i++) {
        // Generate a unique timestamp from the high-resolution timer
        timestamps[i] = start.tv_sec * 1000000 + start.tv_nsec / 1000;

        // Calculate a measurement using the reliable random number generator
        measurements[i] = (double)rand() / RAND_MAX;

        // Randomly select a status from predefined enum values
        statuses[i] = (status_t)(rand() % 3);
    }

    free(timestamps);
    free(measurements);
    free(statuses);

    return data;
}
