#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BASE_NAME_LENGTH 64
#define MAX_EXTENSION_LENGTH 8
#define DEFAULT_EXTENSION ".new"
#define MAX_TOTAL_FILENAME_LENGTH 255
#define MAX_DIR_LENGTH 128
#define LOG_LEVEL_ERROR 1
#define LOG_LEVEL_WARNING 2

typedef struct {
    int base_name_length;
    char* filename;
    char* original_extension;
    char* new_extension;
    char* prefix;
} filename_data;

filename_data generate_filename(char* filename) {
    filename_data data = {0};

    // Step 1: Extract the base name and extension
    char* token = strtok(filename, ".");
    if (!token) return data; // No extension

    char* original_extension = token;
    char* base_name = token;

    // Step 2: Handle multiple periods and determine the number of digits in the new extension
    int num_periods = 0;
    while (*base_name && *base_name != '.') {
        ++num_periods;
        ++base_name;
    }
    data.base_name_length = strlen(base_name);

    if (data.base_name_length > MAX_BASE_NAME_LENGTH) {
        // Step 3: Ignore invalid characters and log warnings
        for (int i = 0; i < num_periods; ++i) {
            base_name = strstr(base_name, ".");
            if (!base_name) break;
            ++num_periods;
        }
        while (*base_name && !isalnum(*base_name)) {
            ++base_name;
        }
    }

    // Step 4: Generate the new extension
    char* new_extension = malloc(MAX_EXTENSION_LENGTH + 1);
    sprintf(new_extension, "%d", data.base_name_length);

    // Step 5: Handle filenames with no extension gracefully and provide a default extension option
    if (!original_extension) {
        original_extension = DEFAULT_EXTENSION;
    }

    // Step 6: Ensure the total length of the new filename does not exceed 255 characters
    int max_total_filename_length = MAX_TOTAL_FILENAME_LENGTH;
    if (data.prefix) {
        int prefix_len = strlen(data.prefix);
        max_total_filename_length -= prefix_len;
    }
    if (strlen(original_extension) > max_total_filename_length - strlen(base_name)) {
        // Adjust the new extension length to fit within the threshold
        char* temp_extension = malloc(MAX_EXTENSION_LENGTH + 1);
        sprintf(temp_extension, "%d", data.base_name_length / 2);
        free(new_extension);
        new_extension = temp_extension;
    }

    // Step 7: Construct the new filename and handle filenames with multiple parts
    char* new_filename = malloc(max_total_filename_length + 1);
    if (data.prefix) {
        sprintf(new_filename, "%s%s.%s", data.prefix, base_name, new_extension);
    } else {
        sprintf(new_filename, "%s.%s", base_name, new_extension);
    }
    free(original_extension);
    free(new_extension);

    data.filename = new_filename;
    return data;
}

int main() {
    // Example usage
    filename_data result = generate_filename("file with spaces/file name.txt");
    printf("%s\n", result.filename);
    return 0;
}
