import json
from datetime import datetime
import time
import os
import threading
import mmap
import ctypes

class UserSessionManager:
    def __init__(self):
        self.session_data = {}
        self.cache = {}
        self.lock = threading.Lock()
        self.memory_pool = []

    def create_session(self, request_json):
        if 'username' not in request_json or 'email' not in request_json or 'role' not in request_json:
            return {'error': 'Invalid request'}

        session_id = str(int(time.time())) if 'session_id' not in request_json else request_json['session_id']
        self.session_data[session_id] = {
            'username': request_json['username'],
            'email': request_json['email'],
            'role': request_json['role'],
            'expiration': datetime.now() + datetime.timedelta(minutes=int(request_json.get('session_expiration', 30)))
        }

        preferences_memory = self.allocate_memory()
        if not preferences_memory:
            return {'error': 'Memory allocation failed'}

        try:
            with open('user_preferences.txt', 'r') as f:
                user_prefs = json.load(f)
            for pref, value in user_prefs.items():
                ctypes.c_char_p(preferences_memory).value = str.encode(value + '\n')
        except FileNotFoundError:
            pass

        return {'session_id': session_id}

    def update_session(self, request_json):
        if 'username' not in request_json or 'email' not in request_json or 'role' not in request_json:
            return {'error': 'Invalid request'}

        if 'session_id' not in request_json:
            return {'error': 'No session ID provided'}

        session_id = request_json['session_id']
        if session_id not in self.session_data:
            return {'error': 'Session not found'}

        self.session_data[session_id]['username'] = request_json.get('username', self.session_data[session_id]['username'])
        self.session_data[session_id]['email'] = request_json.get('email', self.session_data[session_id]['email'])
        self.session_data[session_id]['role'] = request_json.get('role', self.session_data[session_id]['role'])

        return {'message': 'Session updated successfully'}

    def delete_session(self, request_json):
        if 'session_id' not in request_json:
            return {'error': 'No session ID provided'}

        session_id = request_json['session_id']
        if session_id not in self.session_data:
            return {'error': 'Session not found'}

        del self.session_data[session_id]

        return {'message': 'Session deleted successfully'}

    def get_session(self, request_json):
        if 'session_id' not in request_json:
            return {'error': 'No session ID provided'}

        session_id = request_json['session_id']
        if session_id not in self.session_data:
            return {'error': 'Session not found'}

        return self.session_data[session_id]

    def allocate_memory(self):
        memory_size = 1024 * 1000  # Allocate 1MB of memory
        try:
            preferences_memory = mmap.mmap(os.open('/dev/zero', os.O_RDWR | os.O_CREAT), memory_size)
        except FileNotFoundError:
            return None

        self.memory_pool.append((preferences_memory, memory_size))

        return preferences_memory

    def free_memory(self, preferences_memory):
        if preferences_memory in [mem[0] for mem in self.memory_pool]:
            offset = self.memory_pool[[mem[0] for mem in self.memory_pool].index(preferences_memory)].index(preferences_memory)
            mmap.close(preferences_memory)
            os.ftruncate(os.open('/dev/zero', os.O_RDWR), 0)

        return None

    def log_session_operation(self, request_json):
        with open('session_log.txt', 'a') as f:
            f.write(f'[{datetime.now()}] - Session operation: {request_json.get("sub_action", "unknown")} - Session ID: {request_json.get("session_id", "unknown")}\n')

        return None

    def handle_request(self, request_json):
        if 'sub_action' not in request_json:
            return {'error': 'Invalid request'}

        sub_action = request_json['sub_action']
        if sub_action == 'create':
            response = self.create_session(request_json)
        elif sub_action == 'update':
            response = self.update_session(request_json)
        elif sub_action == 'delete':
            response = self.delete_session(request_json)
        elif sub_action == 'get':
            response = self.get_session(request_json)

        if not isinstance(response, dict):
            return {'error': 'Invalid response'}

        return response

    def start(self):
        while True:
            request_json = json.load(sys.stdin)
            response = self.handle_request(request_json)
            print(json.dumps(response))
            time.sleep(0.1)

if __name__ == '__main__':
    session_manager = UserSessionManager()
    session_manager.start()

```

Note: The above code assumes that you are using Python 3.x and have the `mmap` module available, which is used to manage user preferences in memory.']

