void init_data_structures(long** offsets, int** keys, Record** records, Event** events, Node*** nodes, int max_nodes, size_t limit) {
    // Initialize arrays
    *offsets = (long*)malloc(max_nodes * sizeof(long));
    *keys = (int*)malloc(max_nodes * sizeof(int));
    *records = (Record*)malloc(max_nodes * sizeof(Record));
    *events = (Event*)malloc(max_nodes * sizeof(Event));

    // Initialize node list and its size
    *nodes = (Node**)malloc(max_nodes * sizeof(Node*));
    int num_nodes = 0;

    // Loop to set values for each node's record's int field to a random value within a specified range
    for (int i = 0; i < max_nodes; i++) {
        if ((num_nodes + 1) * sizeof(Node) > limit) break;
        Node* node = (Node*)malloc(sizeof(Node));
        node->prev = NULL;
        node->next = NULL;
        node->offset = rand() % 1000000; // Random offset value
        node->key = i; // Set key as the index of the node
        node->record_key = rand() % 10000; // Random record key value
        time_t timestamp = time(NULL); // Current timestamp
        node->timestamp = timestamp;
        if (num_nodes > 0) {
            Node* prev_node = (*nodes)[num_nodes - 1];
            prev_node->next = node;
            node->prev = prev_node;
        } else {
            *nodes = &node;
        }
        num_nodes++;
    }

    // Free unused memory
    for (int i = 0; i < max_nodes; i++) {
        if ((i + 1) * sizeof(Node) > limit) break;
        free((*nodes)[i]);
    }
}

