    void startPipeline(std::vector<std::string> sources, std::vector<int> nodeCounts) {
        // Initialize nodes and threads for each source
        for (int i = 0; i < sources.size(); ++i) {
            std::vector<Node*> nodes;
            for (int j = 0; j < nodeCounts[i]; ++j) {
                Node* node = new Node();
                nodes.push_back(node);
                std::thread([node]() { node->start(); }).detach();
            }
        }
    }

