#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    ConfigType_String,
    ConfigType_Integer,
    ConfigType_Float
} ConfigType;

typedef struct ConfigSetting {
    const char* name;
    ConfigType type;
    union {
        char* stringVal;
        int intVal;
        float floatVal;
    } value;
} ConfigSetting;

typedef struct ConfigList {
    ConfigSetting* settings;
    int size;
    int capacity;
} ConfigList;

ConfigList* configListInit(int initialCapacity) {
    ConfigList* list = malloc(sizeof(ConfigList));
    list->settings = malloc(initialCapacity * sizeof(ConfigSetting));
    list->size = 0;
    list->capacity = initialCapacity;
    return list;
}

void configListAdd(ConfigList* list, const char* name, ConfigType type, union {
    char* stringVal;
    int intVal;
    float floatVal;
} value) {
    if (list->size >= list->capacity) {
        list->settings = realloc(list->settings, (list->capacity * 2 + 1) * sizeof(ConfigSetting));
        list->capacity *= 2;
    }
    ConfigSetting* setting = &list->settings[list->size++];
    setting->name = name;
    setting->type = type;
    switch (type) {
        case ConfigType_String:
            setting->value.stringVal = value.stringVal;
            break;
        case ConfigType_Integer:
            setting->value.intVal = value.intVal;
            break;
        case ConfigType_Float:
            setting->value.floatVal = value.floatVal;
            break;
    }
}

void configListUpdate(ConfigList* list, const char* name, ConfigType type, union {
    char* stringVal;
    int intVal;
    float floatVal;
} value) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->settings[i].name, name) == 0) {
            switch (type) {
                case ConfigType_String:
                    list->settings[i].value.stringVal = value.stringVal;
                    break;
                case ConfigType_Integer:
                    list->settings[i].value.intVal = value.intVal;
                    break;
                case ConfigType_Float:
                    list->settings[i].value.floatVal = value.floatVal;
                    break;
            }
            return;
        }
    }
}

void configListDelete(ConfigList* list, const char* name) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->settings[i].name, name) == 0) {
            memmove(&list->settings[i], &list->settings[i + 1], (list->size - i - 1) * sizeof(ConfigSetting));
            list->size--;
            return;
        }
    }
}

void configListSerialize(ConfigList* list, char** buffer, int* bufferSize) {
    *bufferSize = list->size * sizeof(ConfigSetting);
    *buffer = malloc(*bufferSize);
    memcpy(*buffer, &list->settings[0], *bufferSize);
}

int configListValidate(ConfigList* list) {
    for (int i = 0; i < list->size; i++) {
        if (!strcmp(list->settings[i].name, "conflictingName")) {
            return -1;
        }
    }
    return 0;
}

void configListReportSizeAndMemoryUsage(ConfigList* list) {
    printf("Config List Size: %d\n", list->size);
    printf("Memory Usage: %d bytes\n", (list->capacity * sizeof(ConfigSetting)));
}
