#include <sys/wait.h>

// Define an enum for transaction status
enum {
    PENDING,
    PROCESSED,
    FAILED
};

// Define a struct to represent transactions
typedef struct {
    time_t timestamp;
    double amount;
    int status;
} Transaction;

// Function to manage flexible transaction processing
void* process_transactions(int max_transactions) {
    // Allocate memory for an array of Transactions
    Transaction* transactions = (Transaction*)malloc(max_transactions * sizeof(Transaction));

    if (!transactions) {
        return NULL;
    }

    double total_amount = 0.0;
    int i;

    for (i = 0; i < max_transactions; i++) {
        // Set timestamp to current time
        transactions[i].timestamp = time(NULL);

        // Generate a random amount within a specified range
        transactions[i].amount = (double)rand() / RAND_MAX * 100.0;

        // Randomly select transaction status
        int status = rand() % 3;
        transactions[i].status = (status == 0) ? PENDING :
                                    ((status == 1) ? PROCESSED : FAILED);

        // Simulate processing of each transaction
        sleep(1);  // Simulate time spent on processing

        // Update the running total of transaction amounts
        total_amount += transactions[i].amount;
    }

    // Log transactions to an external database or file for auditing purposes
    FILE* log_file = fopen("transactions.log", "a");
    if (log_file) {
        for (i = 0; i < max_transactions; i++) {
            fprintf(log_file, "%ld %f %d\n",
                    transactions[i].timestamp, transactions[i].amount, transactions[i].status);
        }
        fclose(log_file);
    }

    // Free dynamically allocated memory
    free(transactions);

    return NULL;
}
