        for(j = 0; j < CHAR_SET_SIZE; j++)
            char_arrays[i][j] = (char)(rand() % 256);
    }

    element_t** element_arrays = (element_t**)malloc(NUM_ELEMENTS * sizeof(element_t*));
    for(i = 0; i < NUM_ELEMENTS; i++) {
        element_arrays[i] = (element_t*)malloc(sizeof(element_t));
        element_arrays[i]->value = float_arrays[i][rand() % FLOAT_RANGE];
        element_arrays[i]->identifier = char_arrays[i][rand() % CHAR_SET_SIZE];
    }

    // manage memory here...
    for(i = 0; i < NUM_ELEMENTS; i++) {
        free(float_arrays[i]);
        free(char_arrays[i]);
        free(element_arrays[i]);
    }
    free(float_arrays);
    free(char_arrays);
    free(element_arrays);

    pthread_exit(NULL);
}

int main() {
    int i;
    pthread_t threads[NUM_THREADS];

    for(i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, manage_memory, NULL);
    }

    // wait for all threads to finish...
    for(i = 0; i < NUM_THREADS; i++)
        pthread_join(threads[i]);

    return 0;
}
