typedef struct Node {
    ConfigurationSetting setting;
    struct Node* next;
} Node;

Node* head = NULL; // Initialize head of the linked list

void init_configuration() {
    pthread_mutex_init(&mutex, NULL);
}

void add_configuration_setting(ConfigurationSetting* setting) {
    pthread_mutex_lock(&mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->setting = *setting;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&mutex);
}

ConfigurationSetting get_next_config() {
    pthread_mutex_lock(&mutex);
    ConfigurationSetting setting = head->setting;
    Node* temp = head;
    head = head->next;
    free(temp);
    pthread_mutex_unlock(&mutex);
    return setting;
}

// Dynamic memory allocation function
