    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        // Handle file open failure
        printf("Failed to open configuration file!\n");
        return;
    }
    ConfigurationSetting setting;
    while (fscanf(file, "%d %s", &setting.threshold, setting.file_rotation_policy) != 2) {
        // Parse and update linked list of settings
        add_configuration_setting(&setting);
    }
    fclose(file);
}

