namespace NetworkClient {
    class Message {
        public:
            string data;
            string protocol;
    };

    class Caching Mechanism {
        private:
            unordered_map<string, Message> inMemoryCache;
            map<string, Message> diskCache;

        public:
            void cacheMessage(Message message) {
                // Cache frequently accessed messages in memory
                if (message.data.size() < 1024 * 1024) {
                    inMemoryCache[message.protocol] = message;
                } else {
                    // Store less frequently used messages on disk
                    diskCache[message.protocol] = message;
                }
            }

            Message getMessage(string protocol) {
                // Check in-memory cache first
                if (inMemoryCache.find(protocol) != inMemoryCache.end()) {
                    return inMemoryCache[protocol];
                } else {
                    // If not found, check disk cache
                    if (diskCache.find(protocol) != diskCache.end()) {
                        return diskCache[protocol];
                    } else {
                        // Message not found in either cache; retrieve from source
                        // or throw error
                    }
                }
            }
    };

    class FilteringSystem {
        private:
            unordered_map<string, vector<Message>> contentFilters;
            unordered_map<string, vector<Message>> sourceFilters;

        public:
            void setContentFilter(string protocol, Message message) {
                if (contentFilters.find(protocol) == contentFilters.end()) {
                    contentFilters[protocol] = {};
                }
                contentFilters[protocol].push_back(message);
            }

            void setSourceFilter(string protocol, Message message) {
                if (sourceFilters.find(protocol) == sourceFilters.end()) {
                    sourceFilters[protocol] = {};
                }
                sourceFilters[protocol].push_back(message);
            }

            vector<Message> extractMessages(Message message) {
                // Apply content filters
                for (const auto& filter : contentFilters) {
                    if (filter.second.size() > 0 && contains(filter.second, message)) {
                        return filter.second;
                    }
                }

                // Apply source filters
                for (const auto& filter : sourceFilters) {
                    if (filter.second.size() > 0 && contains(filter.second, message)) {
                        return filter.second;
                    }
                }

                // If no filters match, return an empty vector
                return {};
            }

            bool contains(vector<Message> messages, Message message) {
                for (const auto& msg : messages) {
                    if (msg.data == message.data && msg.protocol == message.protocol) {
                        return true;
                    }
                }
                return false;
            }
    };

    class AlertingSystem {
        private:
            unordered_map<string, vector<Message>> alertThresholds;

        public:
            void setAlertThreshold(string protocol, Message message, int threshold) {
                if (alertThresholds.find(protocol) == alertThresholds.end()) {
                    alertThresholds[protocol] = {};
                }
                alertThresholds[protocol].push_back({threshold, message});
            }

            void processMessage(Message message) {
                for (const auto& threshold : alertThresholds) {
                    for (const auto& alert : threshold.second) {
                        if (alert.first <= 0) {
                            // Alert triggered; notify client
                            // or perform other actions
                        }
                    }
                }
            }
    };

    class ProtocolHandler {
        private:
            io_context ctx;
            CachingMechanism cachingMechanism;
            FilteringSystem filteringSystem;
            AlertingSystem alertingSystem;

        public:
            void handleMessage(Message message) {
                // Cache the message
                cachingMechanism.cacheMessage(message);

                // Filter the message based on content and source filters
                vector<Message> filteredMessages = filteringSystem.extractMessages(message);

                // Process the filtered messages
                for (const auto& filteredMessage : filteredMessages) {
                    if (filteredMessage.data.size() > 1024 * 1024) {
                        // Handle large messages by streaming them to disk or cloud storage
                    } else {
