    }
    head = create_node(rand(), rand());
    if (!head) return -3;

    // simulate concurrent insertion and deletion
    for (int i = 0; i < num_nodes; i++) {
        Node* new_node = create_node(rand(), rand());
        if (!new_node) break;
        if (!head) {
            head = new_node;
            tail = new_node;
        } else {
            new_node->next = NULL;
            if (rand() % 2) { // insert at the end
                tail->next = new_node;
                tail = new_node;
            } else { // insert in the middle
                Node* temp = head;
                while (temp && rand() % 2) temp = temp->next;
                new_node->prev = temp;
                new_node->next = temp->next;
                if (!new_node->next) tail = new_node;
                else temp->next = new_node;
            }
        }
    }

    free_nodes(&head, &tail);

    return 0;
}
