typedef struct {
    int key;
    long offset;
    int* value;
} record;

record* createRecord(int key);
void updateRecord(record** array, int capacity, int index, int newKey, long newOffset);

record* allocateArray(int capacity) {
    record* array = (record*) malloc(capacity * sizeof(record));
    if (!array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < capacity; i++) {
        array[i].key = -1;
        array[i].offset = -1;
    }
    return array;
}

void resizeArray(record** array, int* capacity) {
    int newCapacity = *capacity * 2 + 1;
    record* newArray = (record*) realloc(*array, newCapacity * sizeof(record));
    if (!newArray) {
        printf("Memory reallocation failed.\n");
        return;
    }
    *array = newArray;
    *capacity = newCapacity;
}

record* createRecord(int key) {
    record* newRecord = (record*) malloc(sizeof(record));
    if (!newRecord) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    newRecord->key = key;
    newRecord->offset = -1;
    newRecord->value = (int*) malloc(sizeof(int));
    *newRecord->value = 0;
    return newRecord;
}

void updateRecord(record** array, int capacity, int index, int newKey, long newOffset) {
    if (array[index].key == -1) {
        array[index].key = newKey;
        array[index].offset = newOffset;
    } else {
        record* oldRecord = &array[index];
        for (int i = 0; i < capacity; i++) {
            if (array[i].key == newKey && array[i].key != -1) {
                *oldRecord->value = *array[i].value;
                oldRecord->offset = array[i].offset;
                return;
            }
        }
    }
}
