        products[i].price = (float)json_real_value(json_object_get(product, "price"));
        products[i].quantity = json_integer_value(json_object_get(product, "quantity"));

        product_ids[i] = products[i].id;
        strcpy(product_names[i], products[i].name);
        product_prices[i] = products[i].price;
        product_quantities[i] = products[i].quantity;

        int j=0;
        for(json_t *review=json_object_get(product, "reviews"); review; review=json_object_next(review)) {
            if(j>=MAX_REVIEWS) break;

            products[i].reviews[j]->customer_name = json_string_value(json_object_get(review, "customer_name"));
            products[i].reviews[j]->rating = json_integer_value(json_object_get(review, "rating"));

