            for(json_t *comment=json_object_get(review, "comments"); comment; comment=json_object_next(comment)) {
                if(k>=MAX_COMMENTS) break;

                strcpy(products[i].reviews[j]->comments[k], json_string_value(json_object_get(comment, "comment")));
                k++;
            }
            j++;
        }
        i++;
    }

    // Free JSON API endpoint
    json_decref(root);

    // Free arrays for IDs, names, prices, quantities, and reviews
    free(product_ids);
    int n=0;
    while(n<MAX_PRODUCTS) {
        free((void*)product_names[n]);
        n++;
    }
    free(product_names);
    free(product_prices);
    free(product_quantities);

    // Free arrays for customer names, ratings, and comments
    free(customer_names);
    free(ratings);
    int m=0;
    while(m<MAX_REVIEWS) {
        review* r = product_reviews[m];
        while(m<n) {
            if(n>=MAX_PRODUCTS) break;
            free((void*)r->customer_name);
            n++;
            r->customer_name = json_string_value(json_object_get(r, "customer_name"));
            strcpy(product_names[n-1], r->customer_name);
            m++;
        }
    }

    // Free arrays for reviews
    int o=0;
    while(o<MAX_PRODUCTS) {
        review* r = product_reviews[o];
        if(o>=n) break;
        free((void*)r);
        o++;
    }
    free(product_reviews);

    return 0;
}
